/**
 * 画像のない選手・スタッフの顔（SVG のフラットイラスト）。
 * seed（選手 id など）から決定的に特徴を選び、face で個別に寄せられる。
 * 表情は mood、ユニフォームはクラブカラー。写真の顔と同じ丸枠に入れて使う。
 */
import type { ReactNode } from 'react'
import type { BeardStyle, FaceSpec, Mood } from '../../engine/models/face'

/** seed から独立した整数を n 個取り出す（xorshift） */
function hashInts(seed: number, n: number): number[] {
  let a = (Math.imul(seed + 0x9e37, 2654435761) ^ 0x5bd1e995) >>> 0
  const out: number[] = []
  for (let i = 0; i < n; i++) {
    a ^= a << 13
    a >>>= 0
    a ^= a >>> 17
    a ^= a << 5
    a >>>= 0
    out.push(a)
  }
  return out
}

const SKIN_LIGHT = ['#ffe3c8', '#f9d6b6', '#f3c9a3', '#ecbc92']
const SKIN_MID = ['#e6b088', '#d9a077', '#c98d63', '#b97c55']
const SKIN_DARK = ['#9c6640', '#87562f', '#6e4426', '#5a3720']
const HAIR_DARK = ['#1d1612', '#2b2018', '#3a2a1c', '#241b16']
const HAIR_MIXED = ['#2b2018', '#4a3322', '#6b4626', '#8a5b2e', '#b9874a', '#d9b56c', '#e2c98e', '#7a3a1e']
const BEARDS: BeardStyle[] = ['none', 'none', 'none', 'stubble', 'stubble', 'goatee', 'full', 'mustache']

type Region = 'east' | 'latin' | 'europe' | 'africa' | 'mideast'
const REGION: Record<string, Region> = {
  JP: 'east',
  KR: 'east',
  CN: 'east',
  BR: 'latin',
  AR: 'latin',
  UY: 'latin',
  CO: 'latin',
  MX: 'latin',
  ES: 'europe',
  PT: 'europe',
  IT: 'europe',
  FR: 'europe',
  EN: 'europe',
  DE: 'europe',
  NL: 'europe',
  HR: 'europe',
  BE: 'europe',
  NG: 'africa',
  GH: 'africa',
  CI: 'africa',
  SN: 'africa',
  SA: 'mideast',
  IR: 'mideast',
  QA: 'mideast',
}

function palettes(nation: string, roll: number): { skin: string[]; hair: string[] } {
  const r = REGION[nation] ?? 'europe'
  if (r === 'east') return { skin: SKIN_LIGHT, hair: HAIR_DARK }
  if (r === 'africa') return { skin: SKIN_DARK, hair: HAIR_DARK }
  if (r === 'mideast') return { skin: SKIN_MID, hair: HAIR_DARK }
  if (r === 'latin') {
    const t = roll % 3
    return { skin: t === 0 ? SKIN_DARK : t === 1 ? SKIN_MID : SKIN_LIGHT, hair: HAIR_DARK.concat(HAIR_MIXED.slice(1, 4)) }
  }
  return { skin: roll % 5 === 0 ? SKIN_MID : SKIN_LIGHT, hair: HAIR_MIXED }
}

const HAIR_STYLES = 11

/** 髪（顔の上に描く部分）。顔は cx50 cy52 rx25 ry27 */
function hairFront(style: number, c: string): ReactNode {
  switch (style) {
    case 0: // 短髪
      return <path d="M24 50 q-3 -31 26 -31 q29 0 26 31 q-3 -13 -9 -16 q-17 5 -34 0 q-6 3 -9 16Z" fill={c} />
    case 1: // ツンツン
      return <path d="M24 48 q-2 -18 6 -24 l2 -9 5 6 4 -10 5 8 5 -9 4 9 6 -7 2 9 q8 7 7 27 q-4 -12 -10 -15 q-17 4 -32 0 q-6 3 -9 15Z" fill={c} />
    case 2: // 横分け
      return <path d="M24 50 q-3 -32 27 -32 q28 0 25 32 q-2 -12 -6 -16 q-14 -3 -24 4 l-2 -6 q-8 4 -11 4 q-6 4 -9 14Z" fill={c} />
    case 3: // 坊主
      return <path d="M25.5 46 q1 -24 24.5 -24 q23.5 0 24.5 24 q-4 -11 -24.5 -12 q-20.5 1 -24.5 12Z" fill={c} opacity="0.85" />
    case 4: // くせ毛・アフロ
      return (
        <g fill={c}>
          <circle cx="30" cy="32" r="9" />
          <circle cx="41" cy="24" r="10" />
          <circle cx="55" cy="23" r="10" />
          <circle cx="68" cy="30" r="9" />
          <circle cx="74" cy="41" r="6" />
          <circle cx="26" cy="42" r="6" />
          <path d="M26 46 q24 -16 48 0 q-2 -10 -10 -12 q-14 3 -28 0 q-8 2 -10 12Z" />
        </g>
      )
    case 5: // 長めの真ん中分け
      return <path d="M22 62 q-4 -42 28 -42 q32 0 28 42 q-3 -20 -8 -25 q-10 -1 -18 -9 q-6 8 -20 9 q-6 6 -10 25Z" fill={c} />
    case 6: // オールバック
      return <path d="M25 44 q0 -26 25 -26 q25 0 25 26 q-5 -8 -12 -10 q-13 -3 -26 0 q-7 2 -12 10Z" fill={c} />
    case 7: // ソフトモヒカン
      return (
        <g fill={c}>
          <path d="M25.5 46 q1 -24 24.5 -24 q23.5 0 24.5 24 q-4 -11 -24.5 -12 q-20.5 1 -24.5 12Z" opacity="0.5" />
          <path d="M40 30 q2 -14 10 -16 q8 2 10 16 q-10 -3 -20 0Z" />
        </g>
      )
    case 8: // マッシュ
      return <path d="M23 50 q-2 -32 27 -32 q29 0 27 32 q-6 -5 -12 -6 q-15 -2 -30 0 q-6 1 -12 6Z" fill={c} />
    case 9: // お団子（マンバン）
      return (
        <g fill={c}>
          <circle cx="50" cy="16" r="7" />
          <path d="M25 46 q0 -26 25 -26 q25 0 25 26 q-5 -9 -12 -11 q-13 -2 -26 0 q-7 2 -12 11Z" />
        </g>
      )
    default: // スキンヘッド
      return null
  }
}

function eyesOf(mood: Mood): ReactNode {
  const ink = '#2a1d15'
  if (mood === 'happy')
    return (
      <>
        <path d="M36 53 q4 -5 8 0" fill="none" stroke={ink} strokeWidth="2.4" strokeLinecap="round" />
        <path d="M56 53 q4 -5 8 0" fill="none" stroke={ink} strokeWidth="2.4" strokeLinecap="round" />
      </>
    )
  if (mood === 'sad' || mood === 'hurt')
    return (
      <>
        <path d="M36 51 q4 4 8 0" fill="none" stroke={ink} strokeWidth="2.4" strokeLinecap="round" />
        <path d="M56 51 q4 4 8 0" fill="none" stroke={ink} strokeWidth="2.4" strokeLinecap="round" />
      </>
    )
  return (
    <>
      <ellipse cx="40" cy="53" rx="3" ry="3.4" fill={ink} />
      <ellipse cx="60" cy="53" rx="3" ry="3.4" fill={ink} />
      <circle cx="41" cy="51.8" r="1" fill="#fff" />
      <circle cx="61" cy="51.8" r="1" fill="#fff" />
    </>
  )
}

function mouthOf(mood: Mood): ReactNode {
  const c = '#9a3b2c'
  if (mood === 'happy') return <path d="M43 65 q7 8 14 0 q-7 2.5 -14 0Z" fill="#b8473a" stroke={c} strokeWidth="1.2" strokeLinejoin="round" />
  if (mood === 'normal') return <path d="M44.5 65.5 q5.5 4 11 0" fill="none" stroke={c} strokeWidth="2" strokeLinecap="round" />
  if (mood === 'flat') return <line x1="45" y1="66" x2="55" y2="66" stroke={c} strokeWidth="2" strokeLinecap="round" />
  return <path d="M45 68 q5 -4 10 0" fill="none" stroke={c} strokeWidth="2" strokeLinecap="round" />
}

function beardOf(beard: BeardStyle, c: string): ReactNode {
  if (beard === 'stubble') return <path d="M27 58 q3 22 23 24 q20 -2 23 -24 q-6 12 -23 13 q-17 -1 -23 -13Z" fill={c} opacity="0.28" />
  if (beard === 'goatee') return <path d="M44 70 q6 6 12 0 q-1 9 -6 10 q-5 -1 -6 -10Z" fill={c} />
  if (beard === 'full') return <path d="M26 54 q2 28 24 30 q22 -2 24 -30 q-6 16 -24 16 q-18 0 -24 -16Z" fill={c} />
  if (beard === 'mustache') return <path d="M42 62.5 q8 -3 16 0 q-3 3.5 -8 3.5 q-5 0 -8 -3.5Z" fill={c} />
  return null
}

export function PlayerAvatar({
  seed,
  nation = 'JP',
  mood = 'normal',
  face = {},
  kit = { primary: '#1d4ed8', secondary: '#ffffff' },
  size = '3rem',
  female = false,
  suit = false,
}: {
  seed: number
  nation?: string
  mood?: Mood
  face?: FaceSpec
  kit?: { primary: string; secondary: string }
  /** CSS の長さ（'3rem' など）か px の数値 */
  size?: number | string
  female?: boolean
  /** スーツ姿（スタッフ用） */
  suit?: boolean
}) {
  const [hSkin, hHair, hStyle, hBeard, hExtra, hRegion] = hashInts(seed, 6)
  const pal = palettes(nation, hRegion)
  const skin = pal.skin[(face.skin ?? hSkin) % pal.skin.length]
  const hair = face.hairColor ?? pal.hair[hHair % pal.hair.length]
  const style = female ? 5 : (face.hair ?? hStyle) % HAIR_STYLES
  const beard: BeardStyle = female ? 'none' : (face.beard ?? (REGION[nation] === 'east' ? (hBeard % 7 === 0 ? 'stubble' : 'none') : BEARDS[hBeard % BEARDS.length]))
  const glasses = face.glasses ?? hExtra % 11 === 0
  const headband = face.headband ?? (!suit && hExtra % 13 === 5)
  const blush = hExtra % 3 === 0

  return (
    <svg viewBox="0 0 100 100" width={size} height={size} style={{ display: 'block' }} aria-hidden>
      <defs>
        <radialGradient id={`bg${seed}`} cx="50%" cy="35%" r="70%">
          <stop offset="0%" stopColor="#f3f7fb" />
          <stop offset="100%" stopColor="#b9c9da" />
        </radialGradient>
      </defs>
      <rect width="100" height="100" fill={`url(#bg${seed})`} />
      {/* 後ろ髪（長髪） */}
      {style === 5 && <path d="M22 60 q-2 -34 28 -36 q30 2 28 36 l2 18 q-30 6 -60 0Z" fill={hair} />}
      {/* 体 */}
      {suit ? (
        <g>
          <path d="M10 100 q3 -21 40 -23 q37 2 40 23Z" fill="#1d2633" />
          <path d="M42 78 l8 14 l8 -14 q-8 -2 -16 0Z" fill="#f4f6f8" />
          <path d="M48.5 81 l1.5 -2 l1.5 2 l-1 11 l-0.5 1 l-0.5 -1Z" fill={kit.primary} />
        </g>
      ) : (
        <g>
          <path d="M10 100 q3 -21 40 -23 q37 2 40 23Z" fill={kit.primary} />
          <path d="M40 78 q10 9 20 0 l1.5 3 q-11.5 9 -23 0Z" fill={kit.secondary} />
          <path d="M18 100 l4 -14 M82 100 l-4 -14" stroke={kit.secondary} strokeWidth="2.2" opacity="0.7" />
        </g>
      )}
      {/* 首・耳・顔 */}
      <path d="M43 72 h14 v9 q-7 5 -14 0Z" fill={skin} />
      <ellipse cx="25.5" cy="55" rx="4.5" ry="6" fill={skin} />
      <ellipse cx="74.5" cy="55" rx="4.5" ry="6" fill={skin} />
      <ellipse cx="50" cy="52" rx="25" ry="27" fill={skin} />
      <path d="M33 68 q17 14 34 0 q-4 9 -17 11 q-13 -2 -17 -11Z" fill="#000" opacity="0.06" />
      {beardOf(beard, hair)}
      {blush && !female && <ellipse cx="34" cy="62" rx="4.5" ry="2.6" fill="#f08a7e" opacity="0.28" />}
      {blush && !female && <ellipse cx="66" cy="62" rx="4.5" ry="2.6" fill="#f08a7e" opacity="0.28" />}
      {female && <ellipse cx="35" cy="62" rx="4.5" ry="2.6" fill="#f59a9a" opacity="0.45" />}
      {female && <ellipse cx="65" cy="62" rx="4.5" ry="2.6" fill="#f59a9a" opacity="0.45" />}
      {/* 眉 */}
      <path d="M34.5 44.5 q5 -2.5 10 -0.5" fill="none" stroke={hair} strokeWidth="2.3" strokeLinecap="round" />
      <path d="M55.5 44 q5 -2 10 0.5" fill="none" stroke={hair} strokeWidth="2.3" strokeLinecap="round" />
      {eyesOf(mood)}
      <path d="M49 56 q-2 5 1 6.5" fill="none" stroke="#000" strokeWidth="1.2" opacity="0.18" strokeLinecap="round" />
      {mouthOf(mood)}
      {glasses && (
        <g stroke="#2b2f36" strokeWidth="1.7" fill="#fff" fillOpacity="0.12">
          <rect x="32.5" y="47.5" width="15" height="11" rx="4.5" />
          <rect x="52.5" y="47.5" width="15" height="11" rx="4.5" />
          <line x1="47.5" y1="52" x2="52.5" y2="52" />
        </g>
      )}
      {hairFront(style, hair)}
      {headband && <path d="M25.5 40 q24.5 -9 49 0 l-0.5 4.5 q-24 -8.5 -48 0Z" fill={kit.secondary === '#ffffff' ? kit.primary : kit.secondary} />}
      {mood === 'hurt' && <rect x="58" y="38" width="12" height="5" rx="1.5" fill="#fff" stroke="#d9d9d9" transform="rotate(-20 64 40)" />}
    </svg>
  )
}
