/**
 * 交渉シート（M20）。獲得は ① 移籍金（所属クラブ）→ ② 条件（選手）→ 代理人・メディカル（出たときだけ）、更改は ② だけ。
 * 見込みのメーターと乗り気の決め手を見ながら提示する。判定は「考え中…」→ 針が止まる → スタンプ。
 * 交渉は state.talks に残るので、閉じても続きから（engine/transfer/talks.ts）。
 */
import { useEffect, useRef, useState } from 'react'
import { SQUAD_ROLE_LABEL, ageOf, currentAbsWeek, ovr, type GameState, type Player, type SquadRole } from '../../engine'
import { estimate } from '../../engine/scout/knowledge'
import { willFactors } from '../../engine/transfer/market'
import { upgradeOf, weakSpots } from '../../engine/transfer/recommend'
import {
  MEDICAL_DISCOUNT_CHANCE,
  PLAYER_ATTEMPTS,
  agentRefuseChance,
  answerAgent,
  answerMedical,
  clubRounds,
  closeTalk,
  feeChance,
  feeNeed,
  findTalk,
  offerFee,
  offerTerms,
  openTalk,
  talkBlocker,
  termsChance,
  wageNeed,
  type Talk,
  type TalkLine,
  type TalkResult,
} from '../../engine/transfer/talks'
import { SideSheet } from '../layout/SideSheet'
import { PlayerFace } from '../components/PersonFace'
import { PosBadge } from '../components/common'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { rosterInfo } from '../../engine/club/roster'
import { formatMoney } from '../format'
import { sound } from '../audio/sound'
import { ChanceGauge, DiceBar, FactorList, UpgradeChip } from './TalkParts'
import { chanceColor } from './talkColor'

function Stepper({ value, onChange, steps }: { value: number; onChange: (v: number) => void; steps: number[] }) {
  const label = (s: number) => (s >= 10000 ? `${s / 10000}億` : s.toLocaleString())
  return (
    <div className="flex items-center gap-1">
      {steps
        .slice()
        .reverse()
        .map((s) => (
          <button key={-s} className="btn btn-ghost btn-sm !min-h-[2.4rem] !px-1.5 !text-[0.72rem]" onClick={() => onChange(Math.max(0, value - s))}>
            -{label(s)}
          </button>
        ))}
      <div className="num min-w-0 flex-1 rounded-lg bg-black/40 px-1 py-1.5 text-center text-[0.9rem] font-black text-gold">{formatMoney(value)}</div>
      {steps.map((s) => (
        <button key={s} className="btn btn-ghost btn-sm !min-h-[2.4rem] !px-1.5 !text-[0.72rem]" onClick={() => onChange(value + s)}>
          +{label(s)}
        </button>
      ))}
    </div>
  )
}

const ROLES: SquadRole[] = ['star', 'regular', 'rotation', 'backup', 'prospect']

const STAMP: Record<TalkResult['kind'], { text: string; color: string } | null> = {
  accept: { text: '合意！', color: '#3ddc84' },
  counter: { text: '逆提案', color: '#7dd3fc' },
  reject: { text: '拒否', color: '#f59e42' },
  event: { text: '待った！', color: '#f5c542' },
  signed: { text: '契約成立！', color: '#f5c542' },
  fail: { text: '交渉決裂', color: '#ef5350' },
  lost: { text: '競り負け', color: '#ef5350' },
  none: null,
}
const SOUND: Partial<Record<TalkResult['kind'], Parameters<typeof sound.play>[0]>> = { accept: 'notify', counter: 'click', reject: 'ooh', event: 'whistle', signed: 'fanfare', fail: 'ooh', lost: 'ooh' }

export function NegotiationSheet({ player, mode, open, onClose }: { player: Player | null; mode: 'buy' | 'renew'; open: boolean; onClose: () => void }) {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const pid = player?.id
  // 開いたら交渉を始める（続きがあればそれを）
  useEffect(() => {
    if (!open || pid === undefined) return
    mutate((st) => {
      const q = st.players[pid]
      if (q) openTalk(st, q, mode)
    })
  }, [open, pid, mode, mutate])
  if (!player) return null
  const p = player
  const talk = findTalk(state, p.id, mode)
  const close = () => {
    mutate((st) => closeTalk(st, p.id))
    onClose()
  }
  return (
    <SideSheet open={open} onClose={close} title={`${mode === 'renew' ? '契約更改' : '獲得交渉'}・${p.name}`} width="78%">
      {talk ? <TalkBody key={talk.startAbsWeek} state={state} p={p} talk={talk} onClose={close} /> : <NoTalk state={state} p={p} mode={mode} onClose={close} />}
    </SideSheet>
  )
}

/** 左上の選手の札（弱点補強なら大きく） */
function PlayerCard({ state, p, renew }: { state: GameState; p: Player; renew: boolean }) {
  const club = p.clubId >= 0 ? state.clubs[p.clubId] : null
  const now = currentAbsWeek(state)
  const e = estimate(state, p)
  const up = renew ? null : upgradeOf(state, p, weakSpots(state), e)
  return (
    <div className={`shrink-0 rounded-xl p-2 ${up ? 'upgrade-row' : 'bg-white/[0.05]'}`}>
      <div className="flex items-center gap-2">
        <PlayerFace p={p} kit={club?.colors} className="h-14 w-14 shrink-0" />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1">
            <PosBadge pos={p.pos} />
            <span className="truncate text-[0.95rem] font-black">{p.name}</span>
          </div>
          <div className="truncate text-[0.74rem] text-ink-dim">
            {ageOf(p, now)}歳・{club ? club.name : 'フリー'}・{renew ? `総合 ${ovr(p)}・やる気 ${Math.round(p.morale)}` : `総合 ${e.ovrLo === e.ovrHi ? e.ovrLo : `${e.ovrLo}〜${e.ovrHi}`}`}
          </div>
          <div className="truncate text-[0.72rem] text-ink-dim">今の年俸 {formatMoney(p.contract.wage)}</div>
        </div>
      </div>
      {up && (
        <div className="mt-1.5 flex items-center gap-1.5">
          <UpgradeChip up={up} big />
          <span className="min-w-0 truncate text-[0.7rem] text-gold">先発の {up.pos} より +{Math.round(up.gain)}</span>
        </div>
      )}
    </div>
  )
}

/** 交渉を始められないとき（決裂・来る気なし・期間外） */
function NoTalk({ state, p, mode, onClose }: { state: GameState; p: Player; mode: 'buy' | 'renew'; onClose: () => void }) {
  const reason = talkBlocker(state, p, mode)
  const me = state.clubs[state.playerClubId]
  const { will, factors } = willFactors(state, p, me, 'star')
  return (
    <div className="flex h-full min-h-0 gap-3 p-3">
      <div className="flex w-[40%] shrink-0 flex-col gap-2">
        <PlayerCard state={state} p={p} renew={mode === 'renew'} />
      </div>
      <div className="flex min-w-0 flex-1 flex-col gap-2">
        <div className="rounded-xl bg-bad/15 p-3 text-[0.85rem] font-bold">{reason ?? '交渉を準備しています…'}</div>
        {mode === 'buy' && state.mode === 'club' && rosterInfo(state).full && <RosterFix onClose={onClose} />}
        {mode === 'buy' && p.clubId !== me.id && (
          <div className="scroll-y min-h-0 flex-1 rounded-xl bg-black/25 p-2.5">
            <div className="mb-1 flex items-center justify-between">
              <span className="panel-head">乗り気の決め手（主力として約束しても）</span>
              <span className="num text-[0.85rem] font-black" style={{ color: chanceColor(will) }}>
                {Math.round(will * 100)}%
              </span>
            </div>
            <FactorList factors={factors} />
          </div>
        )}
        <button className="btn btn-ghost mt-auto w-full shrink-0" onClick={onClose}>
          閉じる
        </button>
      </div>
    </div>
  )
}

/** 選手枠がいっぱいのとき: 整理の画面へ（交渉は続きから再開できる） */
function RosterFix({ onClose }: { onClose: () => void }) {
  const push = useUi((s) => s.push)
  return (
    <button
      className="btn btn-sm w-full shrink-0 bg-bad !text-[0.76rem] text-white"
      onClick={() => {
        onClose()
        push({ id: 'squad', params: { release: 1 } })
      }}
    >
      選手枠がいっぱい。選手を整理する（交渉はあとで続きから）
    </button>
  )
}

function LogLine({ l }: { l: TalkLine }) {
  if (l.who === 'event')
    return <div className={`rounded-lg px-2 py-1 text-center text-[0.74rem] font-bold ${l.tone === 'bad' ? 'bg-bad/20 text-[#ff9a97]' : l.tone === 'good' ? 'bg-good/15 text-good' : 'bg-gold/15 text-gold'}`}>{l.text}</div>
  if (l.who === 'me') return <div className="ml-6 rounded-lg bg-accent/15 px-2 py-1 text-[0.74rem]">{l.text}</div>
  return <div className={`mr-6 rounded-lg px-2 py-1 text-[0.76rem] ${l.tone === 'good' ? 'bg-good/10' : l.tone === 'bad' ? 'bg-bad/10' : 'bg-white/[0.07]'}`}>{l.text}</div>
}

function RoundPips({ used, total }: { used: number; total: number }) {
  return (
    <span className="flex items-center gap-1 text-[0.7rem] text-ink-dim">
      残り {Math.max(0, total - used)} 回
      {Array.from({ length: total }, (_, i) => (
        <span key={i} className={`h-2 w-2 rounded-full ${i < used ? 'bg-white/15' : 'bg-gold'}`} />
      ))}
    </span>
  )
}

function TalkBody({ state, p, talk, onClose }: { state: GameState; p: Player; talk: Talk; onClose: () => void }) {
  const mutate = useGame((s) => s.mutate)
  const renew = talk.mode === 'renew'
  const me = state.clubs[state.playerClubId]
  const club = !renew && talk.fromClubId >= 0 ? state.clubs[talk.fromClubId] : null
  const [fee, setFee] = useState(() => talk.counterFee ?? (talk.stage === 'club' ? feeNeed(state, talk, p) : 0))
  const [years, setYears] = useState(() => talk.counter?.years ?? 2)
  // 起用の約束: 更改は今のまま。獲得は「レギュラー」、それでは来ない選手（主力の約束が条件）は「中心選手」から
  const firstRole: SquadRole | undefined = talk.counter ? talk.counter.role : renew ? p.contract.role : willFactors(state, p, me, 'regular').will < 0.12 ? 'star' : 'regular'
  const [role, setRole] = useState<SquadRole | undefined>(firstRole)
  const [wage, setWage] = useState(() => talk.counter?.wage ?? wageNeed(state, p, 2, firstRole, renew, talk).need)
  const [phase, setPhase] = useState<'idle' | 'spin' | 'land' | 'stamp'>('idle')
  const [shown, setShown] = useState<{ chance: number; result?: TalkResult } | null>(null)
  const [note, setNote] = useState<string | null>(null)
  const timers = useRef<number[]>([])
  const logRef = useRef<HTMLDivElement>(null)
  useEffect(() => {
    const ts = timers.current
    return () => ts.forEach((t) => clearTimeout(t))
  }, [])
  useEffect(() => {
    const el = logRef.current
    if (el) el.scrollTop = el.scrollHeight
  }, [talk.log.length])

  const busy = phase === 'spin' || phase === 'land'
  const need = wageNeed(state, p, years, role, renew, talk)
  const will = renew ? need.will : willFactors(state, p, me, role).will
  const feeC = talk.stage === 'club' ? feeChance(state, talk, p, fee) : 0
  const termsC = talk.stage === 'player' ? termsChance(state, talk, p, wage, years, role) : 0

  /** 提示して、考え中 → 針 → スタンプの順に見せる */
  const run = (chance: number, act: (st: GameState, t: Talk) => TalkResult, withDice = true) => {
    if (busy) return
    sound.play('click')
    setNote(null)
    setShown({ chance })
    setPhase(withDice ? 'spin' : 'land')
    const t1 = window.setTimeout(
      () => {
        let res: TalkResult = { kind: 'none', chance: 0, text: '' }
        mutate((st) => {
          const t = findTalk(st, p.id, talk.mode)
          if (t) res = act(st, t)
        })
        if (res.kind === 'none') {
          setPhase('idle')
          setShown(null)
          setNote(res.text || null)
          return
        }
        // 逆提案はその額を入れておく（そのまま出せば必ずまとまる）
        if (talk.counterFee !== undefined) setFee(talk.counterFee)
        if (talk.counter) {
          setWage(talk.counter.wage)
          setYears(talk.counter.years)
          setRole(talk.counter.role)
        }
        if (res.kind === 'accept' && talk.stage === 'player' && !renew) setWage(wageNeed(state, p, years, role, false, talk).need)
        setShown({ chance, result: res })
        setPhase('land')
        const t2 = window.setTimeout(
          () => {
            setPhase('stamp')
            const se = SOUND[res.kind]
            if (se) sound.play(se)
            timers.current.push(window.setTimeout(() => setPhase('idle'), 1800))
          },
          withDice && res.roll !== undefined ? 750 : 80,
        )
        timers.current.push(t2)
      },
      withDice ? 950 : 60,
    )
    timers.current.push(t1)
  }

  const stamp = phase === 'stamp' && shown?.result ? STAMP[shown.result.kind] : null
  const stampText = shown?.result?.kind === 'signed' && renew ? '契約更新！' : stamp?.text
  const rival = talk.twists.find((t) => t.kind === 'rival')
  const eager = talk.twists.find((t) => t.kind === 'eager')
  const agent = talk.twists.find((t) => t.kind === 'agent')
  const med = talk.twists.find((t) => t.kind === 'medical')
  const steps = renew ? ['条件', '更新'] : club ? ['① 移籍金', '② 条件', '契約'] : ['条件', '契約']
  const stepIdx = renew ? (talk.stage === 'done' ? 1 : 0) : (club ? 0 : -1) + (talk.stage === 'club' ? 0 : talk.stage === 'player' ? 1 : 2)
  const diceChance = shown?.chance ?? (talk.stage === 'club' ? feeC : termsC)
  const diceRoll = shown?.result?.roll

  return (
    <div className="flex h-full min-h-0 gap-3 p-3">
      {/* 左: 選手・乗り気の決め手・やりとり */}
      <div className="flex w-[38%] shrink-0 flex-col gap-2">
        <PlayerCard state={state} p={p} renew={renew} />
        <div className="scroll-y max-h-[42%] shrink-0 rounded-xl bg-black/25 p-2">
          <div className="mb-1 flex items-center justify-between">
            <span className="panel-head">{renew ? '更新への気持ち' : '乗り気の決め手'}</span>
            <span className="num text-[0.9rem] font-black" style={{ color: chanceColor(will) }}>
              乗り気 {Math.round(will * 100)}%
            </span>
          </div>
          <FactorList factors={need.factors} />
        </div>
        <div ref={logRef} className="scroll-y min-h-0 flex-1 space-y-1 rounded-xl bg-black/20 p-1.5">
          {talk.log.length === 0 && <div className="p-1 text-[0.74rem] text-ink-mute">ここに、やりとりが残ります。</div>}
          {talk.log.map((l, i) => (
            <LogLine key={i} l={l} />
          ))}
        </div>
      </div>

      {/* 右: 段階ごとの提示 */}
      <div className="relative flex min-w-0 flex-1 flex-col gap-2">
        <div className="flex shrink-0 items-center gap-1 text-[0.74rem] font-bold">
          {steps.map((s, i) => (
            <span key={s} className="flex items-center gap-1">
              {i > 0 && <span className="text-ink-mute">›</span>}
              <span className={`rounded-full px-2 py-0.5 ${i === stepIdx ? 'bg-gold text-[#2a1a00]' : i < stepIdx ? 'bg-good/20 text-good' : 'bg-white/[0.06] text-ink-dim'}`}>{s}</span>
            </span>
          ))}
        </div>
        {rival && talk.stage !== 'done' && (
          <div className="shrink-0 rounded-lg border border-bad/50 bg-bad/15 px-2 py-1 text-[0.74rem] font-bold text-[#ffb3b0]">
            ⚔ ライバル: {state.clubs[rival.clubId!]?.name}も狙っている。決裂すれば取られる
            {club ? `（移籍金の交渉は ${clubRounds(talk)} 回まで）` : ''}
          </div>
        )}
        {!renew && talk.stage !== 'done' && state.mode === 'club' && rosterInfo(state).full && <RosterFix onClose={onClose} />}
        {eager && talk.stage === 'club' && <div className="shrink-0 rounded-lg border border-good/40 bg-good/10 px-2 py-1 text-[0.74rem] font-bold text-good">本人が移籍を強く希望している（相手の希望額 −10%）</div>}

        <div className="relative flex min-h-0 flex-1 flex-col rounded-xl bg-black/25 p-2.5">
          <div className="scroll-y min-h-0 flex-1 space-y-2">
            {talk.stage === 'club' && club && (
              <>
                <div className="flex items-center justify-between">
                  <span className="panel-head">移籍金・{club.name}</span>
                  <RoundPips used={talk.round} total={clubRounds(talk)} />
                </div>
                <ChanceGauge value={phase === 'idle' ? feeC : diceChance} title="クラブが受け入れる見込み" thinking={phase === 'spin'} />
                <DiceBar chance={diceChance} roll={diceRoll} phase={phase === 'spin' ? 'spin' : phase === 'idle' ? 'idle' : 'land'} />
                <Stepper value={fee} onChange={setFee} steps={[100, 1000, 10000]} />
                <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-[0.72rem] text-ink-dim">
                  <span>相手の希望額の目安 {formatMoney(feeNeed(state, talk, p))}</span>
                  <span>資金 {formatMoney(me.budget)}</span>
                  {talk.counterFee !== undefined && (
                    <button className="rounded bg-accent/20 px-1.5 py-0.5 font-bold text-accent" onClick={() => setFee(talk.counterFee!)}>
                      逆提案 {formatMoney(talk.counterFee)}（この額なら確実）
                    </button>
                  )}
                </div>
                {feeC === 0 && <div className="text-[0.74rem] font-bold text-bad">安すぎて相手にされません。</div>}
              </>
            )}

            {talk.stage === 'player' && (
              <>
                <div className="flex items-center justify-between">
                  <span className="panel-head">{renew ? '条件' : `条件・${p.short}`}</span>
                  <RoundPips used={talk.attempts} total={PLAYER_ATTEMPTS} />
                </div>
                <ChanceGauge value={phase === 'idle' ? termsC : diceChance} title={renew ? '更新してくれる見込み' : '契約してくれる見込み'} thinking={phase === 'spin'} />
                <DiceBar chance={diceChance} roll={diceRoll} phase={phase === 'spin' ? 'spin' : phase === 'idle' ? 'idle' : 'land'} />
                <div>
                  <div className="mb-0.5 text-[0.72rem] text-ink-dim">年俸</div>
                  <Stepper value={wage} onChange={setWage} steps={[10, 100, 1000]} />
                </div>
                <div className="flex items-center gap-2">
                  <span className="text-[0.74rem] text-ink-dim">年数</span>
                  <div className="seg">
                    {[1, 2, 3, 4, 5].map((y) => (
                      <button key={y} aria-selected={years === y} onClick={() => setYears(y)}>
                        {y}年
                      </button>
                    ))}
                  </div>
                </div>
                <div className="flex flex-wrap items-center gap-1">
                  <span className="mr-1 text-[0.74rem] text-ink-dim">起用の約束</span>
                  {ROLES.map((r) => (
                    <button key={r} onClick={() => setRole(role === r ? undefined : r)} className={`rounded-md border px-2 py-1 text-[0.74rem] font-bold ${role === r ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      {SQUAD_ROLE_LABEL[r]}
                    </button>
                  ))}
                </div>
                <div className="flex flex-wrap items-center gap-x-2 gap-y-1 text-[0.72rem] text-ink-dim">
                  <span>求める年俸の目安 およそ {formatMoney(Math.round(need.need / 100) * 100)}</span>
                  {talk.counter && (
                    <button
                      className="rounded bg-accent/20 px-1.5 py-0.5 font-bold text-accent"
                      onClick={() => {
                        setWage(talk.counter!.wage)
                        setYears(talk.counter!.years)
                        setRole(talk.counter!.role)
                      }}
                    >
                      逆提案 {formatMoney(talk.counter.wage)}・{talk.counter.years} 年（このままなら確実）
                    </button>
                  )}
                </div>
                {termsC === 0 && <div className="text-[0.74rem] font-bold text-bad">このままでは来る気がありません。主力として約束すれば、話を聞いてくれるかもしれません。</div>}
                {!need.yearsOk && <div className="text-[0.74rem] font-bold text-[#f8b26a]">ベテランなので 2 年以上の契約を望んでいます。</div>}
              </>
            )}

            {talk.stage === 'agent' && agent && (
              <div className="space-y-2">
                <div className="panel-head">代理人の要求</div>
                <div className="rounded-lg bg-gold/10 p-2.5 text-[0.85rem]">
                  合意の直前、{p.short}の代理人が口を開いた。
                  <br />
                  <b>「最後に 1 つだけ。契約金として {formatMoney(agent.amount!)} をお願いしたい。」</b>
                </div>
                <div className="text-[0.74rem] text-ink-dim">断ると、本人が折れて契約してくれる見込みは {Math.round(agentRefuseChance(state, talk) * 100)}%。折れなければ決裂です。</div>
              </div>
            )}

            {talk.stage === 'medical' && (
              <div className="space-y-2">
                <div className="panel-head">メディカルチェック</div>
                <div className="rounded-lg bg-bad/10 p-2.5 text-[0.85rem]">
                  {p.short}のひざに古傷が見つかった。
                  <br />
                  入団すれば、2 週ほど別メニューになりそうだ。
                </div>
                {club && med && !med.asked && <div className="text-[0.74rem] text-ink-dim">古傷を理由に、移籍金の値下げ（15%）を頼めます（見込み {Math.round(MEDICAL_DISCOUNT_CHANCE * 100)}%・1 回だけ）。</div>}
                {talk.agreed && club && <div className="num text-[0.78rem]">いまの移籍金 {formatMoney(talk.agreed.fee)}</div>}
              </div>
            )}

            {talk.stage === 'done' && (
              <div className="flex flex-col items-center gap-2 pt-2 text-center">
                <div className="text-[1.5rem] font-black" style={{ color: talk.outcome === 'signed' ? '#f5c542' : '#ef5350' }}>
                  {talk.outcome === 'signed' ? (renew ? '契約更新！' : '獲得決定！') : talk.outcome === 'lost' ? '競り負け' : talk.outcome === 'walked' ? '見送り' : '交渉決裂'}
                </div>
                <div className="text-[0.82rem] text-ink-dim">
                  {talk.outcome === 'signed' && talk.agreed
                    ? `年俸 ${formatMoney(talk.agreed.wage)}・${talk.agreed.years} 年${talk.agreed.role ? `・${SQUAD_ROLE_LABEL[talk.agreed.role]}` : ''}${talk.agreed.fee > 0 && !renew ? `・移籍金 ${formatMoney(talk.agreed.fee)}` : ''}${talk.agreed.bonus ? `・契約金 ${formatMoney(talk.agreed.bonus)}` : ''}`
                    : talk.outcome === 'lost'
                      ? `${p.name}は${p.clubId >= 0 ? state.clubs[p.clubId].name : 'ほかのクラブ'}へ移籍した。`
                      : talk.outcome === 'failed'
                        ? `しばらくは話を聞いてもらえません（${renew ? 2 : 6} 週）。`
                        : '今回は縁がなかった。'}
                </div>
              </div>
            )}
            {note && <div className="rounded-lg bg-bad/15 px-2 py-1 text-[0.78rem] font-bold">{note}</div>}
          </div>

          {/* 右下: 操作（右手の親指） */}
          <div className="mt-2 flex shrink-0 gap-1.5">
            {talk.stage === 'club' && (
              <button className="btn btn-gold w-full" disabled={busy || feeC === 0 || fee > me.budget} onClick={() => run(feeC, (st, t) => offerFee(st, t, fee))}>
                {fee > me.budget ? '資金が足りません' : 'この額で提示する'}
              </button>
            )}
            {talk.stage === 'player' && (
              <button className="btn btn-gold w-full" disabled={busy || termsC === 0} onClick={() => run(termsC, (st, t) => offerTerms(st, t, wage, years, role))}>
                この条件で提示する
              </button>
            )}
            {talk.stage === 'agent' && agent && (
              <>
                <button className="btn btn-ghost flex-1" disabled={busy} onClick={() => run(agentRefuseChance(state, talk), (st, t) => answerAgent(st, t, false))}>
                  断る
                </button>
                <button className="btn btn-gold flex-[1.4]" disabled={busy || me.budget < (talk.agreed?.fee ?? 0) + agent.amount!} onClick={() => run(1, (st, t) => answerAgent(st, t, true), false)}>
                  払う（{formatMoney(agent.amount!)}）
                </button>
              </>
            )}
            {talk.stage === 'medical' && (
              <>
                <button className="btn btn-ghost flex-1" disabled={busy} onClick={() => run(0, (st, t) => answerMedical(st, t, 'walk'), false)}>
                  見送る
                </button>
                {club && med && !med.asked && (
                  <button className="btn btn-blue flex-1" disabled={busy} onClick={() => run(MEDICAL_DISCOUNT_CHANCE, (st, t) => answerMedical(st, t, 'discount'))}>
                    値下げを頼む
                  </button>
                )}
                <button className="btn btn-gold flex-1" disabled={busy} onClick={() => run(1, (st, t) => answerMedical(st, t, 'sign'), false)}>
                  このまま獲得
                </button>
              </>
            )}
            {talk.stage === 'done' && (
              <button className={`btn w-full ${talk.outcome === 'signed' ? 'btn-gold' : 'btn-ghost'}`} disabled={busy} onClick={onClose}>
                閉じる
              </button>
            )}
          </div>

          {/* 考え中・判定のスタンプ */}
          {stamp && (
            <button className="absolute inset-0 rounded-xl bg-black/35" onClick={() => setPhase('idle')} aria-label="閉じる">
              <span
                className="anim-stamp absolute left-1/2 top-[42%] whitespace-nowrap rounded-xl border-[0.3rem] px-4 py-1 text-[2.1rem] font-black"
                style={{ color: stamp.color, borderColor: stamp.color, background: 'rgba(6,19,31,0.85)', textShadow: `0 0 1rem ${stamp.color}66` }}
              >
                {stampText}
              </span>
              {shown?.result?.text && <span className="absolute inset-x-3 bottom-3 whitespace-pre-line rounded-lg bg-[#06131f]/90 px-2 py-1.5 text-[0.8rem] font-bold text-ink">{shown.result.text}</span>}
            </button>
          )}
        </div>
      </div>
    </div>
  )
}
