/** くらしの写真（家・車・旅行先）。写真がなければアイコンを出す。 */
import { useState } from 'react'
import { lifePhotoUrl } from './portraits'
import { Icon, type IconName } from './Icon'

export function LifePhoto({ id, icon = 'life', className = '' }: { id: string; icon?: IconName; className?: string }) {
  const url = lifePhotoUrl(id)
  const [failed, setFailed] = useState(false)
  return (
    <div className={`relative shrink-0 overflow-hidden rounded-lg bg-black/30 ${className}`}>
      {url && !failed ? (
        <img src={url} alt="" draggable={false} loading="lazy" decoding="async" className="h-full w-full object-cover" onError={() => setFailed(true)} />
      ) : (
        <div className="flex h-full w-full items-center justify-center text-ink-mute">
          <Icon name={icon} className="h-5 w-5" />
        </div>
      )}
    </div>
  )
}
