/** 移籍: 探す・注目・売る（オファー）・スカウト・履歴。 */
import { useMemo, useState } from 'react'
import { NATION_NAME, POSITIONS, ageOf, currentAbsWeek, marketValue, playerClub, squadOf, type GameState, type Nation, type Player, type Position, type ScoutRegion } from '../../engine'
import { REGION_LABEL, estimate, regionOf } from '../../engine/scout/knowledge'
import { reportsOf } from '../../engine/scout/reports'
import { rosterInfo } from '../../engine/club/roster'
import { weeksToNextWindow, windowWeeksLeft } from '../../engine/core/calendar'
import { squadRanks, windowOpen } from '../../engine/transfer/market'
import { acceptBid, rejectOffer } from '../../engine/transfer/ai'
import { recommendSignings, upgradeOf, weakSpots, type Recommendation, type Upgrade, type WeakSpots } from '../../engine/transfer/recommend'
import { outOfReach, signability, type Signability } from '../../engine/transfer/talks'
import { ForeignQuota, SignChip, UpgradeChip } from '../transfer/TalkParts'
import { isForeign } from '../../engine/match/lineup'
import { useStageWide } from '../stage/useStage'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { PlayerFace } from '../components/PersonFace'
import { EstOvr, Flag, PosBadge, Stars } from '../components/common'
import { ConfirmDialog } from '../components/ConfirmDialog'
import { NegotiationSheet } from '../transfer/NegotiationSheet'
import { useGame, useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { formatMoney, formatMoneyShort } from '../format'
import { ProspectsTab } from '../club/ProspectsTab'
import { ScoutTab } from '../transfer/ScoutTab'
import { useScreenState, useScrollMemo } from '../hooks/useScreenState'

type Tab = 'recommend' | 'search' | 'watch' | 'sell' | 'prospects' | 'scout' | 'history'
type NatFilter = 'ALL' | 'JP' | 'FOREIGN' | Nation
type SortBy = 'ovr' | 'nation' | 'age'
type Area = ScoutRegion | 'FREE'

/**
 * 選手の行。弱点を埋める選手は金の枠と「弱点補強」の札で目立たせ、獲れない選手（来る気なし・資金不足・決裂）は薄くする。
 * 右に獲得の見込みの札（乗り気・狙える・難しい・主力の約束が条件・来る気なし・資金不足・移籍期間に交渉・交渉中・決裂）。
 */
function PlayerRow({ state, p, onOpen, right, sign, up, extra }: { state: GameState; p: Player; onOpen: () => void; right?: React.ReactNode; sign?: Signability; up?: Upgrade | null; extra?: React.ReactNode }) {
  const est = estimate(state, p)
  const club = p.clubId >= 0 ? state.clubs[p.clubId] : null
  const now = currentAbsWeek(state)
  const dim = sign && outOfReach(sign)
  // 狭い画面では将来性の★を省き、札を短く（名前が隠れないように）
  const wide = useStageWide(760)
  return (
    <div className={`cv-row relative flex items-center gap-2 rounded-lg px-1.5 py-1 ${up ? 'upgrade-row' : 'bg-white/[0.04]'} ${dim ? 'opacity-50' : ''}`}>
      {up && <span className="absolute inset-y-1 left-0 w-1 rounded-r bg-gold" />}
      <button className="flex min-w-0 flex-1 items-center gap-2 text-left" onClick={onOpen}>
        <PlayerFace p={p} kit={club?.colors} className="h-8 w-8 shrink-0" />
        <PosBadge pos={p.pos} />
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-1">
            <span className="truncate text-[0.8rem] font-bold">{p.name}</span>
            {isForeign(p, state.clubs[state.playerClubId]) && <Flag nation={p.nation} className="h-[0.7rem] w-[1.05rem]" />}
          </span>
          <span className="block truncate text-[0.7rem] text-ink-dim">
            {ageOf(p, now)}歳・{club ? club.short : 'フリー'}・{sign ? `${sign.fee > 0 ? `移籍金 ${formatMoneyShort(sign.fee)}` : '移籍金なし'}・年俸 ${formatMoneyShort(sign.wage)}` : `価値 ${formatMoneyShort(marketValue(p, now, state.season))}`}
          </span>
        </span>
        <EstOvr lo={est.ovrLo} hi={est.ovrHi} />
        {wide && <Stars value={(est.potLo + est.potHi) / 2} className="text-[0.72rem]" />}
      </button>
      {(up || sign || extra) && (
        <span className={`flex shrink-0 flex-col items-end gap-0.5 ${wide ? 'w-[7.6rem]' : 'w-[5.6rem]'}`}>
          {up && <UpgradeChip up={up} compact={!wide} />}
          {extra}
          {sign && <SignChip s={sign} />}
        </span>
      )}
      {right}
    </div>
  )
}

/** 弱点の一覧（いちばん弱いところから。押すとそのポジションでしぼる） */
function WeakList({ state, spots, focus, onFocus, counts }: { state: GameState; spots: WeakSpots; focus: Position | null; onFocus: (p: Position | null) => void; counts?: Map<Position, number> }) {
  const list = [...spots.weak.entries()].sort((a, b) => a[1] - b[1])
  return (
    <div className="space-y-1">
      {list.map(([pos, rating], i) => {
        const p = state.players[spots.starter.get(pos) ?? -1]
        const n = counts?.get(pos)
        return (
          <button key={pos} onClick={() => onFocus(focus === pos ? null : pos)} className={`flex w-full items-center gap-1.5 rounded-lg px-1.5 py-1 text-left text-[0.74rem] ${focus === pos ? 'bg-gold/20 ring-1 ring-gold' : i === 0 ? 'bg-bad/15' : 'bg-white/[0.04]'}`}>
            <PosBadge pos={pos} />
            <span className="min-w-0 flex-1">
              <span className="block truncate">{p ? p.short : '（空き）'}</span>
              {i === 0 && <span className="block text-[0.66rem] font-bold text-[#ff9a97]">最大の弱点</span>}
            </span>
            <span className="num font-black text-ink-dim">{Math.round(rating)}</span>
            {n !== undefined && <span className={`num rounded px-1 text-[0.66rem] font-bold ${n > 0 ? 'bg-gold text-[#2a1a00]' : 'bg-white/10 text-ink-mute'}`}>候補 {n}</span>}
          </button>
        )
      })}
    </div>
  )
}

const KIND_LABEL: Record<Recommendation['kind'], string> = { upgrade: '即戦力', free: 'フリー', prospect: '将来性' }
const KIND_CLASS: Record<Recommendation['kind'], string> = { upgrade: 'bg-good/20 text-good', free: 'bg-accent/20 text-accent', prospect: 'bg-gold/20 text-gold' }

/** おすすめ: 弱点と、弱点を埋める候補（金の枠）・将来性の候補 */
function RecommendTab({ state, onOpen, negoBtn, watchBtn }: { state: GameState; onOpen: (p: Player) => void; negoBtn: (p: Player, s?: Signability) => React.ReactNode; watchBtn: (p: Player) => React.ReactNode }) {
  const me = playerClub(state)
  const [focus, setFocus] = useScreenState<Position | null>('rec:focus', null)
  const recScroll = useScrollMemo('rec')
  // 毎回計算する（30ms ほど）。GameState は書き換え型なので、参照でのメモ化だと更新を取りこぼす
  const spots = weakSpots(state)
  const ranks = squadRanks(state)
  const all = recommendSignings(state).map((r) => ({ r, up: r.kind === 'prospect' ? null : upgradeOf(state, r.player, spots), sign: signability(state, r.player, ranks) }))
  const counts = new Map<Position, number>()
  for (const x of all) if (x.up) counts.set(x.up.pos, (counts.get(x.up.pos) ?? 0) + 1)
  for (const pos of spots.weak.keys()) if (!counts.has(pos)) counts.set(pos, 0)
  const list = focus ? all.filter((x) => x.up?.pos === focus) : all
  const nUp = all.filter((x) => x.up).length
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[30%] shrink-0 p-2.5">
        <div className="panel-head mb-1">チームの弱点</div>
        <p className="mb-1.5 text-[0.7rem] text-ink-dim">先発の弱いポジション。押すと、そこを埋める候補だけに。</p>
        <WeakList state={state} spots={spots} focus={focus} onFocus={setFocus} counts={counts} />
        <div className="panel-head mb-1 mt-2">使えるお金</div>
        <div className="num text-[0.9rem] font-black text-gold">{formatMoney(me.budget)}</div>
        <ForeignQuota state={state} className="mt-2" />
        <p className="mt-2 text-[0.7rem] leading-relaxed text-ink-mute">能力はスカウトの推定です。スカウトを派遣するほど正確になります。</p>
      </div>
      <div ref={recScroll} className="panel scroll-y min-w-0 flex-1 space-y-1 p-2">
        {nUp > 0 && !focus && (
          <div className="rounded-lg bg-gold/10 px-2 py-1 text-[0.76rem] font-bold text-gold">
            弱点を埋める候補が {nUp} 人。金の枠の選手が、先発より上回る選手です。
          </div>
        )}
        {list.length === 0 && <div className="p-2 text-[0.8rem] text-ink-dim">{focus ? `いまの予算で ${focus} を埋められる選手は見つかりませんでした。` : 'いまの予算で取れる、おすすめの選手は見つかりませんでした。'}</div>}
        {list.map(({ r, up, sign }) => (
          <PlayerRow
            key={r.player.id}
            state={state}
            p={r.player}
            onOpen={() => onOpen(r.player)}
            up={up}
            sign={sign}
            extra={!up ? <span className={`rounded px-1.5 text-[0.7rem] font-bold ${KIND_CLASS[r.kind]}`}>{KIND_LABEL[r.kind]}</span> : undefined}
            right={
              <>
                {watchBtn(r.player)}
                {negoBtn(r.player, sign)}
              </>
            }
          />
        ))}
      </div>
    </div>
  )
}

export function TransferScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const me = playerClub(state)
  const paramTab = useCurrentScreen().params?.tab as Tab | undefined
  // 選手の詳細などから戻ったとき・ナビから開き直したときは、タブ・しぼり込み・並び・スクロールを元のまま（useScreenState）
  const [tab, setTab] = useScreenState<Tab>('tab', 'recommend', paramTab)
  const [area, setArea] = useScreenState<Area>('area', 'JP')
  const [pos, setPos] = useScreenState<Position | 'ALL'>('pos', 'ALL')
  const [maxAge, setMaxAge] = useScreenState('maxAge', 40)
  const [nego, setNego] = useState<Player | null>(null)
  // しぼり込み: 獲得の見込みがある選手だけ・弱点を埋める選手だけ
  const [reachOnly, setReachOnly] = useScreenState('reachOnly', false)
  const [upOnly, setUpOnly] = useScreenState('upOnly', false)
  // 国籍（すべて・日本・外国籍・国を選ぶ）と並び（能力・国籍・若い順）
  const [nat, setNat] = useScreenState<NatFilter>('nat', 'ALL')
  const [sortBy, setSortBy] = useScreenState<SortBy>('sortBy', 'ovr')
  const [clearAsk, setClearAsk] = useState(false)
  const searchScroll = useScrollMemo('search')
  const searchLeftScroll = useScrollMemo('searchLeft')
  const watchScroll = useScrollMemo('watch')
  const version = useGame((s) => s.version)
  const now = currentAbsWeek(state)
  const open = windowOpen(state)
  const spots = weakSpots(state)
  // 注目の一覧の札（選手枠とクラブ内順位を 1 回だけ数える）
  const watchRanks = tab === 'watch' ? squadRanks(state) : undefined

  const results = useMemo(() => {
    void version
    const list = Object.values(state.players).filter((p) => {
      if (p.retired || p.isYouth || p.clubId === me.id || p.loan) return false
      if (area === 'FREE' ? p.clubId >= 0 : p.clubId < 0 || regionOf(state, p) !== area) return false
      if (pos !== 'ALL' && p.pos !== pos) return false
      return ageOf(p, now) <= maxAge
    })
    // 国ごとの人数（国籍でしぼる前の数）
    const counts = new Map<Nation, number>()
    for (const p of list) counts.set(p.nation, (counts.get(p.nation) ?? 0) + 1)
    const natCounts = [...counts.entries()].sort((a, b) => Number(b[0] === 'JP') - Number(a[0] === 'JP') || b[1] - a[1])
    const natOk = (p: Player) => (nat === 'ALL' ? true : nat === 'JP' ? p.nation === 'JP' : nat === 'FOREIGN' ? p.nation !== 'JP' : p.nation === nat)
    const sp = weakSpots(state)
    const ranks = squadRanks(state)
    let rows = list.filter(natOk).map((p) => {
      const e = estimate(state, p)
      return { p, e, up: upgradeOf(state, p, sp, e), sign: signability(state, p, ranks) }
    })
    if (upOnly) rows = rows.filter((x) => x.up)
    if (reachOnly) rows = rows.filter((x) => !outOfReach(x.sign))
    // 並び: 能力順は獲れる見込みのある選手を先に（弱点でしぼったときは、上回る幅の大きい順）。国籍順は日本 → 国の名前の順。若い順は年齢
    const natKey = (p: Player) => (p.nation === 'JP' ? '' : NATION_NAME[p.nation])
    const reach = (a: (typeof rows)[number], b: (typeof rows)[number]) => Number(outOfReach(a.sign)) - Number(outOfReach(b.sign))
    const ability = (a: (typeof rows)[number], b: (typeof rows)[number]) => b.e.ovrHi + b.e.ovrLo - (a.e.ovrHi + a.e.ovrLo)
    rows.sort((a, b) =>
      sortBy === 'nation'
        ? natKey(a.p).localeCompare(natKey(b.p), 'ja') || reach(a, b) || ability(a, b)
        : sortBy === 'age'
          ? ageOf(a.p, now) - ageOf(b.p, now) || reach(a, b) || ability(a, b)
          : reach(a, b) || (upOnly ? b.up!.gain - a.up!.gain : 0) || ability(a, b),
    )
    return { rows: rows.slice(0, 120), total: rows.length, natCounts }
  }, [state, version, area, pos, maxAge, me.id, now, upOnly, reachOnly, nat, sortBy])

  const openPlayer = (p: Player) => push({ id: 'player', params: { id: p.id } })
  const watchBtn = (p: Player) => {
    const on = state.scout.watch.includes(p.id)
    return (
      <button
        className={`h-8 w-8 shrink-0 rounded-md text-[0.9rem] ${on ? 'text-gold' : 'text-ink-mute'}`}
        aria-label="注目"
        onClick={() =>
          mutate((st) => {
            st.scout.watch = on ? st.scout.watch.filter((x) => x !== p.id) : [...st.scout.watch, p.id]
          })
        }
      >
        ★
      </button>
    )
  }
  const negoBtn = (p: Player, s?: Signability) => {
    const can = s ? s.canTalk : open || p.clubId < 0
    return (
      <button className={`btn btn-sm !min-h-[2.2rem] !px-2 !text-[0.72rem] ${s?.status === 'talking' ? 'btn-gold' : 'btn-blue'}`} disabled={!can} onClick={() => setNego(p)}>
        {s?.status === 'talking' ? '続き' : '交渉'}
      </button>
    )
  }

  const bids = state.offers.filter((o) => o.kind === 'bid')
  const listed = squadOf(state, me.id).filter((p) => p.id in state.forSale)
  return (
    <AppShell title="移籍" current="transfer" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className="flex shrink-0 items-center gap-2">
          <div className="seg scroll-x">
            {(
              [
                ['recommend', 'おすすめ'],
                ['search', '探す'],
                ['watch', `注目（${state.scout.watch.length}）`],
                ['sell', `売る・オファー（${bids.length}）`],
                ['prospects', `有望株${state.prospects ? `（${state.prospects.list.length}）` : ''}`],
                ['scout', `スカウト${reportsOf(state).length ? `（報告 ${reportsOf(state).length}）` : ''}`],
                ['history', '履歴'],
              ] as [Tab, string][]
            ).map(([id, label]) => (
              <button key={id} aria-selected={tab === id} onClick={() => setTab(id)}>
                {label}
              </button>
            ))}
          </div>
          <span className={`ml-auto rounded-full px-2.5 py-1 text-[0.74rem] font-bold ${open ? 'bg-good/20 text-good' : 'bg-white/10 text-ink-dim'}`}>{open ? `移籍期間中（あと ${windowWeeksLeft(state.week)} 週）` : `期間外・あと ${weeksToNextWindow(state.week)} 週で開く（フリーは獲得可）`}</span>
        </div>

        {rosterInfo(state).full && (
          <div className="flex shrink-0 items-center gap-2 rounded-xl border border-bad/50 bg-bad/10 px-3 py-1.5 text-[0.78rem] font-bold text-[#ffb3b0]">
            選手枠がいっぱいです（{rosterInfo(state).count}/{rosterInfo(state).limit}）。獲得するには、先に選手を整理してください。
            <button className="btn btn-sm ml-auto !min-h-[2.1rem] bg-bad !text-[0.74rem] text-white" onClick={() => push({ id: 'squad', params: { release: 1 } })}>
              選手を整理する
            </button>
          </div>
        )}
        {tab === 'prospects' && <ProspectsTab state={state} />}
        {tab === 'recommend' && <RecommendTab state={state} onOpen={openPlayer} negoBtn={negoBtn} watchBtn={watchBtn} />}

        {tab === 'search' && (
          <div className="flex min-h-0 flex-1 gap-3">
            <div ref={searchLeftScroll} className="panel scroll-y w-[30%] shrink-0 space-y-2 p-2.5">
              <div>
                <div className="panel-head mb-1">地域</div>
                <div className="grid grid-cols-2 gap-1">
                  {(['JP', 'AS', 'EU', 'SA', 'FREE'] as Area[]).map((a) => (
                    <button key={a} onClick={() => setArea(a)} className={`rounded-md border py-1.5 text-[0.78rem] font-bold ${area === a ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      {a === 'FREE' ? 'フリー' : REGION_LABEL[a]}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <div className="panel-head mb-1">ポジション</div>
                <div className="grid grid-cols-4 gap-1">
                  {(['ALL', ...POSITIONS] as (Position | 'ALL')[]).map((x) => (
                    <button key={x} onClick={() => setPos(x)} className={`rounded-md border py-1 text-[0.72rem] font-bold ${pos === x ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      {x === 'ALL' ? '全' : x}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <div className="panel-head mb-1">年齢</div>
                <div className="grid grid-cols-4 gap-1">
                  {[21, 24, 28, 40].map((a) => (
                    <button key={a} onClick={() => setMaxAge(a)} className={`rounded-md border py-1 text-[0.72rem] font-bold ${maxAge === a ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      {a === 40 ? '全' : `${a}以下`}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <div className="panel-head mb-1">国籍</div>
                <div className="grid grid-cols-3 gap-1">
                  {(
                    [
                      ['ALL', '全'],
                      ['JP', '日本'],
                      ['FOREIGN', '外国籍'],
                    ] as const
                  ).map(([id, label]) => (
                    <button key={id} onClick={() => setNat(id)} className={`rounded-md border py-1 text-[0.72rem] font-bold ${nat === id ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      {label}
                    </button>
                  ))}
                </div>
                {results.natCounts.length > 1 && (
                  <div className="mt-1 flex flex-wrap gap-1">
                    {results.natCounts.map(([n, c]) => (
                      <button key={n} onClick={() => setNat(nat === n ? 'ALL' : n)} className={`flex items-center gap-1 rounded-md border px-1.5 py-1 text-[0.68rem] font-bold ${nat === n ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                        <Flag nation={n} className="h-[0.7rem] w-[1.05rem]" />
                        {NATION_NAME[n]}
                        <span className="num font-normal text-ink-dim">{c}</span>
                      </button>
                    ))}
                  </div>
                )}
              </div>
              <div>
                <div className="panel-head mb-1">並び</div>
                <div className="grid grid-cols-3 gap-1">
                  {(
                    [
                      ['ovr', '能力順'],
                      ['nation', '国籍順'],
                      ['age', '若い順'],
                    ] as const
                  ).map(([id, label]) => (
                    <button key={id} onClick={() => setSortBy(id)} className={`rounded-md border py-1 text-[0.72rem] font-bold ${sortBy === id ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      {label}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <div className="panel-head mb-1">しぼり込み</div>
                <div className="space-y-1">
                  <button onClick={() => setUpOnly(!upOnly)} className={`w-full rounded-md border px-2 py-1.5 text-left text-[0.74rem] font-bold ${upOnly ? 'border-gold bg-gold/20 text-gold' : 'border-line/60 bg-black/20'}`}>
                    {upOnly ? '✓ ' : ''}弱点を埋める選手だけ
                  </button>
                  <button onClick={() => setReachOnly(!reachOnly)} className={`w-full rounded-md border px-2 py-1.5 text-left text-[0.74rem] font-bold ${reachOnly ? 'border-gold bg-gold/20 text-gold' : 'border-line/60 bg-black/20'}`}>
                    {reachOnly ? '✓ ' : ''}獲得の見込みがある選手だけ
                  </button>
                </div>
              </div>
              <div>
                <div className="panel-head mb-1">チームの弱点</div>
                <WeakList
                  state={state}
                  spots={spots}
                  focus={pos === 'ALL' || !upOnly ? null : pos}
                  onFocus={(x) => {
                    setPos(x ?? 'ALL')
                    setUpOnly(!!x)
                  }}
                />
              </div>
              <p className="text-[0.7rem] text-ink-mute">能力はスカウトの知識に応じた推定値です。スカウトを派遣すると正確になります。金の枠は、先発の弱いポジションを上回る選手です。</p>
            </div>
            <div ref={searchScroll} className="panel scroll-y min-w-0 flex-1 space-y-1 p-2">
              {results.rows.length === 0 && <div className="p-2 text-[0.8rem] text-ink-dim">条件に合う選手がいません。しぼり込みを外すか、地域を変えてみてください。</div>}
              {results.total > results.rows.length && <div className="px-1 text-[0.68rem] text-ink-mute">{results.total} 人のうち {results.rows.length} 人を表示しています。国籍やポジションでしぼると、ほかの選手も見られます。</div>}
              {results.rows.map(({ p, up, sign }, i) => (
                <div key={p.id}>
                  {sortBy === 'nation' && (i === 0 || results.rows[i - 1].p.nation !== p.nation) && (
                    <div className="mb-1 mt-1.5 flex items-center gap-1.5 px-1 text-[0.74rem] font-bold text-ink-dim">
                      <Flag nation={p.nation} className="h-[0.8rem] w-[1.2rem]" />
                      {NATION_NAME[p.nation]}
                    </div>
                  )}
                  <PlayerRow state={state} p={p} up={up} sign={sign} onOpen={() => openPlayer(p)} right={<>{watchBtn(p)}{negoBtn(p, sign)}</>} />
                </div>
              ))}
            </div>
          </div>
        )}

        {tab === 'watch' && (
          <div ref={watchScroll} className="panel scroll-y min-h-0 flex-1 space-y-1 p-2">
            <div className="flex items-center gap-2 px-0.5">
              <span className="text-[0.72rem] text-ink-dim">★ を付けた選手が並びます（期限なし）。スカウトの報告は「スカウト」タブに 8 週だけ載ります。</span>
              {state.scout.watch.length > 0 && (
                <button className="btn btn-ghost btn-sm ml-auto shrink-0 !min-h-[2rem] !text-[0.72rem]" onClick={() => setClearAsk(true)}>
                  すべて外す
                </button>
              )}
            </div>
            {state.scout.watch.length === 0 && <div className="p-3 text-[0.8rem] text-ink-dim">まだいません。選手の行の ★ で入れられます。</div>}
            {state.scout.watch
              .map((id) => state.players[id])
              .filter((p) => p && !p.retired && p.clubId !== me.id)
              .map((p) => {
                const sign = signability(state, p, watchRanks)
                return <PlayerRow key={p.id} state={state} p={p} up={upgradeOf(state, p, spots)} sign={sign} onOpen={() => openPlayer(p)} right={<>{watchBtn(p)}{negoBtn(p, sign)}</>} />
              })}
          </div>
        )}

        {tab === 'sell' && (
          <div className="flex min-h-0 flex-1 gap-3">
            <div className="panel scroll-y w-[50%] shrink-0 space-y-1.5 p-2.5">
              <div className="panel-head mb-1">届いたオファー</div>
              {bids.length === 0 && <div className="text-[0.78rem] text-ink-dim">いまはオファーがありません。移籍期間中に、売りに出した選手へ声がかかります。</div>}
              {bids.map((o) => {
                if (o.kind !== 'bid') return null
                const p = state.players[o.playerId]
                const c = state.clubs[o.clubId]
                if (!p) return null
                return (
                  <div key={o.id} className="rounded-xl bg-white/[0.05] p-2">
                    <div className="flex items-center gap-2">
                      <PlayerFace p={p} kit={me.colors} className="h-8 w-8" />
                      <div className="min-w-0 flex-1">
                        <div className="truncate text-[0.82rem] font-bold">{p.name}</div>
                        <div className="truncate text-[0.72rem] text-ink-dim">
                          {c.name}から {formatMoney(o.fee)}
                        </div>
                      </div>
                    </div>
                    <div className="mt-1.5 flex gap-1.5">
                      <button className="btn btn-gold btn-sm flex-1" onClick={() => mutate((st) => void acceptBid(st, o.id))}>
                        受ける
                      </button>
                      <button className="btn btn-ghost btn-sm flex-1" onClick={() => mutate((st) => rejectOffer(st, o.id))}>
                        断る
                      </button>
                    </div>
                  </div>
                )
              })}
            </div>
            <div className="panel scroll-y min-w-0 flex-1 space-y-1 p-2.5">
              <div className="panel-head mb-1">売りに出している選手</div>
              {listed.length === 0 && <div className="text-[0.78rem] text-ink-dim">選手の詳細画面から売りに出せます。</div>}
              {listed.map((p) => (
                <div key={p.id} className="flex items-center gap-2 rounded-lg bg-white/[0.04] px-1.5 py-1">
                  <PlayerFace p={p} kit={me.colors} className="h-8 w-8" />
                  <span className="min-w-0 flex-1 truncate text-[0.8rem] font-bold">{p.name}</span>
                  <span className="num text-[0.75rem]">{formatMoneyShort(state.forSale[p.id])}</span>
                  <button className="btn btn-ghost btn-sm !min-h-[2rem] !text-[0.7rem]" onClick={() => mutate((st) => void delete st.forSale[p.id])}>
                    取り下げ
                  </button>
                </div>
              ))}
            </div>
          </div>
        )}

        {tab === 'scout' && <ScoutTab state={state} spots={spots} negoBtn={negoBtn} onOpen={openPlayer} />}

        {tab === 'history' && (
          <div className="panel scroll-y min-h-0 flex-1 space-y-0.5 p-2.5 text-[0.75rem]">
            {[...state.transfers]
              .reverse()
              .filter((t) => t.from === me.id || t.to === me.id || t.fee >= 10000)
              .slice(0, 120)
              .map((t, i) => (
                <div key={i} className={`flex gap-2 rounded px-1.5 py-0.5 ${t.from === me.id || t.to === me.id ? 'bg-gold/10' : ''}`}>
                  <span className="min-w-0 flex-1 truncate font-bold">{t.name}</span>
                  <span className="min-w-0 flex-1 truncate text-ink-dim">
                    {t.from >= 0 ? state.clubs[t.from].short : 'フリー'} → {t.to >= 0 ? state.clubs[t.to].short : '退団'}
                  </span>
                  <span className="num w-[4.6rem] text-right">{t.kind === 'loan' ? 'レンタル' : t.kind === 'loanEnd' ? '復帰' : t.kind === 'release' ? '契約解除' : t.fee ? formatMoneyShort(t.fee) : 'フリー'}</span>
                </div>
              ))}
          </div>
        )}
      </div>
      <NegotiationSheet key={nego?.id ?? 'none'} player={nego} mode="buy" open={!!nego} onClose={() => setNego(null)} />
      <ConfirmDialog
        open={clearAsk}
        title="注目をすべて外しますか？"
        text={`★ を付けた ${state.scout.watch.length} 人を外します。`}
        ok="すべて外す"
        onOk={() => {
          mutate((st) => void (st.scout.watch = []))
          setClearAsk(false)
        }}
        onCancel={() => setClearAsk(false)}
      />
    </AppShell>
  )
}
