/**
 * チュートリアル: 画面を初めて開いたとき、秘書が使い方をひとこと説明する（クラブモード）。
 * 見たものは端末に覚える（settingsStore の tipsSeen）。設定でオフにしたり、もう一度見たりできる。
 */
import { createPortal } from 'react-dom'
import { Portrait } from '../components/Portrait'
import { useSettings } from '../../stores/settingsStore'
import { useOverlayRoot } from '../stage/overlayRoot'

const TIPS: Record<string, { title: string; lines: string[] }> = {
  home: {
    title: 'ホーム',
    lines: [
      '右下の「次へ進む」で 1 週間進みます。試合の週は「試合へ」になり、観戦か結果だけを選べます。',
      '上の日付の横にある「1か月オート」なら、試合も自動で 4 週間進め、月間レポートでまとめて振り返れます。',
      'まずは「選手」で顔ぶれを、「戦術」でフォーメーションを確認しましょう。',
    ],
  },
  squad: {
    title: '選手',
    lines: ['選手をタップすると能力や契約が見られます。', '「契約」のタブで、今季で契約が切れる選手を確認できます。更新しないとシーズン末に退団します。'],
  },
  training: {
    title: '練習',
    lines: ['練習メニューの配分と強度を決めます。強いほど伸びますが、ケガも増えます。', '若手は個別練習やコンバートで伸ばせます。合宿に行くと一気に成長します。'],
  },
  tactics: {
    title: '戦術',
    lines: ['フォーメーションと作戦を決めます。監督の得意なフォーメーションほど力を出せます。', '先発を「おまかせ」にしておくと、調子やケガを見て毎週組み直します。'],
  },
  schedule: {
    title: '日程',
    lines: ['リーグの順位表と日程です。カップ戦や大陸大会もここから見られます。', '「代表」で日本代表と W 杯、「記録」でクラブの歴史が見られます。'],
  },
  club: {
    title: 'クラブ',
    lines: ['施設・スタジアム・スタッフ・スポンサー・事業・財務をまとめて管理します。', 'スポンサーの申し出はプレシーズンに届きます。資金に余裕ができたら施設と事業に投資しましょう。'],
  },
  transfer: {
    title: '移籍',
    lines: ['「おすすめ」は、足りないポジションに合う選手です。移籍期間は 8 月と 1 月です。', '格の高い選手ほど、小さいクラブには来たがりません。スカウトを派遣すると、選手の本当の力が分かります。'],
  },
}

export function Tip({ id }: { id: string }) {
  const show = useSettings((s) => s.showTips)
  const seen = useSettings((s) => s.tipsSeen)
  const set = useSettings((s) => s.set)
  const root = useOverlayRoot()
  const tip = TIPS[id]
  if (!tip || !show || seen.includes(id) || !root) return null
  const close = () => set({ tipsSeen: [...seen, id] })
  return createPortal(
    <div className="anim-rise pointer-events-none absolute left-[5.4rem] right-3 top-[3.4rem] z-40 flex items-start gap-2">
      <Portrait id="kato_misaki" kind="face" className="face-round pointer-events-auto h-12 w-12 shrink-0 border-2 border-gold/70" />
      <div className="panel pointer-events-auto max-w-[34rem] flex-1 rounded-tl-none p-3 shadow-2xl">
        <div className="mb-0.5 text-[0.78rem] font-black text-gold">秘書の加藤より ── {tip.title}</div>
        {tip.lines.map((l, i) => (
          <p key={i} className="text-[0.8rem] leading-snug">
            {l}
          </p>
        ))}
        <div className="mt-2 flex gap-2">
          <button className="btn btn-gold btn-sm flex-1" onClick={close}>
            わかった
          </button>
          <button className="btn btn-ghost btn-sm" onClick={() => set({ showTips: false })}>
            説明はもういい
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}
