/**
 * 選手との面談（M19）: 選手詳細から開く。話す内容を選ぶと、選手が返事をして、やる気が動く。
 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { MEETING_ROLES, MEETINGS, holdMeeting, meetingWait, type MeetingKind, type MeetingResult } from '../../engine/club/meeting'
import { PERSONALITY_DEFS } from '../../engine/data/personality'
import { PlayerFace } from '../components/PersonFace'
import { SideSheet } from '../layout/SideSheet'
import { useGame } from '../../stores/gameStore'

export function MeetingSheet({ state, playerId, open, onClose }: { state: GameState; playerId: number; open: boolean; onClose: () => void }) {
  const mutate = useGame((s) => s.mutate)
  const [roleOpen, setRoleOpen] = useState(false)
  const [result, setResult] = useState<MeetingResult | null>(null)
  const p = state.players[playerId]
  if (!p) return null
  const wait = meetingWait(state, p)
  const me = state.clubs[state.playerClubId]
  const request = state.offers.some((o) => o.kind === 'request' && o.playerId === p.id)
  const talk = (kind: MeetingKind, role?: (typeof MEETING_ROLES)[number]['id']) => {
    let r: MeetingResult | null = null
    mutate((st) => void (r = holdMeeting(st, p.id, kind, role)))
    setResult(r)
    setRoleOpen(false)
  }
  const close = () => {
    setResult(null)
    setRoleOpen(false)
    onClose()
  }
  return (
    <SideSheet open={open} onClose={close} title={`${p.short}と面談`} width="56%">
      <div className="space-y-2 p-3 text-[0.8rem]">
        <div className="flex items-center gap-3">
          <PlayerFace p={p} kit={me.colors} className="h-14 w-14 shrink-0" />
          <div className="min-w-0">
            <div className="text-[1rem] font-black">{p.name}</div>
            <div className="text-[0.74rem] text-ink-dim">
              性格: {PERSONALITY_DEFS[p.personality].name}・やる気 <b className="num text-ink">{Math.round(p.morale)}</b>
              {request && <span className="ml-1 font-bold text-bad">移籍を志願中</span>}
            </div>
          </div>
        </div>
        {result ? (
          <div className="anim-rise space-y-2">
            <div className="rounded-xl rounded-tl-none bg-white/10 px-3 py-2 text-[0.88rem] leading-relaxed">「{result.line}」</div>
            <div className={`text-[0.82rem] font-bold ${result.morale > 0 ? 'text-good' : result.morale < 0 ? 'text-bad' : 'text-ink-dim'}`}>
              やる気 {result.morale > 0 ? '+' : ''}
              {result.morale}
              {result.withdrew && '・移籍の志願を取り下げた'}
            </div>
            <button className="btn btn-gold w-full" onClick={close}>
              終える
            </button>
          </div>
        ) : wait > 0 ? (
          <div className="rounded-lg bg-black/25 px-3 py-2 text-ink-dim">次に面談できるのは {wait} 週後です（4 週に 1 回）。</div>
        ) : roleOpen ? (
          <div className="space-y-1.5">
            <div className="text-[0.76rem] text-ink-dim">どんな役割を伝えますか？</div>
            {MEETING_ROLES.map((r) => (
              <button key={r.id} className="menu-tile w-full !min-h-[2.9rem]" onClick={() => talk('role', r.id)}>
                <span className="font-bold">{r.name}</span>
              </button>
            ))}
            <button className="btn btn-ghost btn-sm w-full" onClick={() => setRoleOpen(false)}>
              もどる
            </button>
          </div>
        ) : (
          <div className="space-y-1.5">
            {MEETINGS.map((m) => (
              <button key={m.id} className="menu-tile w-full" onClick={() => (m.id === 'role' ? setRoleOpen(true) : talk(m.id))}>
                <span className="min-w-0">
                  <span className="block font-black">{m.name}</span>
                  <span className="block text-[0.72rem] text-ink-dim">{m.desc}</span>
                </span>
              </button>
            ))}
          </div>
        )}
      </div>
    </SideSheet>
  )
}
