/** シーズン終了のまとめ（順位・昇降格・各リーグの優勝・得点王）。 */
import { createPortal } from 'react-dom'
import { useEffect } from 'react'
import { sound } from '../audio/sound'
import { useGameState } from '../../stores/gameStore'
import { Emblem } from '../components/ClubArt'
import { formatMoney } from '../format'
import { AWARD_LABEL } from '../../engine/competition/awards'
import { Icon } from '../components/Icon'
import { useUi } from '../../stores/uiStore'
import { NATION_NAME } from '../../engine'
import { OwnerResult } from '../club/OwnerGoals'

const COMP_LABEL: Record<string, string> = { CUP: 'カップ', ACC: 'アジア', EUC: '欧州', WCC: '世界' }
const CONT_NAME: Record<string, string> = { ACC: 'アジアクラブカップ', WCC: '世界クラブ選手権' }

export function SeasonEndModal({ onClose }: { onClose: () => void }) {
  const state = useGameState()
  const push = useUi((st) => st.push)
  useEffect(() => sound.play('fanfare'), [])
  const s = state.seasons[state.seasons.length - 1]
  const root = document.getElementById('overlay-root')
  if (!s || !root) return null
  const me = state.clubs[state.playerClubId]
  const comp = state.competitions.find((c) => c.id === s.leagueId)
  const up = s.promoted.includes(me.id)
  const down = s.relegated.includes(me.id)
  const year = state.startYear + s.season
  const titles = (state.trophies ?? []).filter((t) => t.season === s.season)
  const nextAcc = state.qualified?.acc.includes(me.id)
  const bizTotal = (s.business ?? []).reduce((sum, b) => sum + b.profit, 0)
  const wc = state.national?.worldCups.find((w) => w.year === state.startYear + s.season + 1)
  return createPortal(
    <div className="anim-fade absolute inset-0 z-50 flex items-center justify-center bg-black/65 p-4">
      <div className="panel panel-solid anim-rise relative flex max-h-full w-[40rem] max-w-full flex-col p-3">
        {/* 閉じる（中身が長くても、右上と下のボタンはいつも見える） */}
        <button className="absolute right-1.5 top-1.5 z-10 flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-white/5" onClick={onClose} aria-label="閉じる">
          <Icon name="close" className="h-5 w-5" />
        </button>
        <div className="text-center text-[0.8rem] font-bold text-ink-dim">
          {year}-{String((year + 1) % 100).padStart(2, '0')} シーズン終了
        </div>
        <div className="mt-1 flex items-center justify-center gap-3">
          <Emblem id={`se-${me.id}`} emblem={me.emblem} colors={me.colors} size="3rem" />
          <div>
            <div className="text-[1.1rem] font-black">{me.name}</div>
            <div className="text-[0.85rem]">
              {comp?.name ?? s.leagueId} <span className="num text-[1.5rem] font-black text-gold">{s.rank}</span> 位（勝点 {s.points}）
            </div>
          </div>
        </div>
        <div className="scroll-y -mx-1 mt-1 min-h-0 flex-1 px-1">
          {(up || down) && <div className={`mx-auto mt-2 rounded-full px-4 py-1 text-[0.95rem] font-black ${up ? 'bg-gold text-[#2a1a00]' : 'bg-bad/80 text-white'}`}>{up ? '昇格決定！' : '降格…'}</div>}
          {titles.length > 0 && (
            <div className="mt-2 flex flex-wrap justify-center gap-2">
              {titles.map((t) => (
                <div key={t.compId} className="flex items-center gap-1.5 rounded-full bg-gold px-3 py-1 text-[0.85rem] font-black text-[#2a1a00]">
                  <Icon name="trophy" className="h-4 w-4" />
                  {t.name}
                </div>
              ))}
            </div>
          )}
          {nextAcc && <div className="mt-1 text-center text-[0.8rem] font-bold text-accent">来季はアジアクラブカップに出場します</div>}
          {wc && (
            <div className="mt-1 text-center text-[0.8rem]">
              <span className="font-bold text-gold">W杯 {wc.year}</span> 優勝 {NATION_NAME[wc.champion]}・日本は<span className="font-bold">{wc.japan}</span>
              {wc.mine.length > 0 && <span className="text-ink-dim">（{me.short}から {wc.mine.length} 人が出場）</span>}
            </div>
          )}
          <OwnerResult state={state} season={s.season} />
          <div className="mt-3 grid grid-cols-2 gap-3 text-[0.78rem]">
            <div>
              <div className="panel-head mb-1">優勝</div>
              {s.champions.filter((c) => ['NPL1', 'NPL2', 'NPL3', 'CUP', 'ACC', 'WCC', 'EUC'].includes(c.compId)).map((c) => {
                const club = state.clubs[c.clubId]
                const cn = state.competitions.find((x) => x.id === c.compId)
                return (
                  <div key={c.compId} className="flex items-center gap-1.5 py-0.5">
                    <span className="w-12 shrink-0 text-ink-dim">{COMP_LABEL[c.compId] ?? cn?.short ?? c.compId}</span>
                    <Emblem id={`sec-${c.compId}`} emblem={club.emblem} colors={club.colors} size="1.2rem" />
                    <span className={`truncate font-bold ${club.isPlayer ? 'text-gold' : ''}`}>{club.name}</span>
                  </div>
                )
              })}
            </div>
            <div>
              <div className="panel-head mb-1">得点王</div>
              {s.topScorers.map((t) => {
                const p = state.players[t.playerId]
                const cn = state.competitions.find((x) => x.id === t.compId)
                return (
                  <div key={t.compId} className="flex items-center gap-1.5 py-0.5">
                    <span className="w-12 shrink-0 text-ink-dim">{cn?.short ?? t.compId}</span>
                    <span className="truncate font-bold">{p?.name ?? '―'}</span>
                    <span className="num ml-auto shrink-0">{t.goals}点</span>
                  </div>
                )
              })}
              {s.cup && (
                <>
                  <div className="panel-head mb-1 mt-2">ナショナルカップ</div>
                  <div className="font-bold">
                    {s.cup.stage}
                    {s.cup.champion >= 0 && <span className="ml-1 font-normal text-ink-dim">（優勝 {state.clubs[s.cup.champion].short}）</span>}
                  </div>
                </>
              )}
              {(s.continental ?? []).map((c) => (
                <div key={c.compId}>
                  <div className="panel-head mb-1 mt-2">{CONT_NAME[c.compId] ?? c.compId}</div>
                  <div className={`font-bold ${c.stage === '優勝' ? 'text-gold' : ''}`}>
                    {c.stage}
                    {c.champion >= 0 && c.stage !== '優勝' && <span className="ml-1 font-normal text-ink-dim">（優勝 {state.clubs[c.champion].short}）</span>}
                  </div>
                </div>
              ))}
              {s.hallOfFame && s.hallOfFame.length > 0 && (
                <>
                  <div className="panel-head mb-1 mt-2">殿堂入り</div>
                  <div className="font-bold text-gold">{s.hallOfFame.map((id) => state.players[id]?.name ?? '').join('、')}</div>
                </>
              )}
              <div className="panel-head mb-1 mt-2">資金</div>
              <div className="num font-bold">{formatMoney(s.budgetEnd)}</div>
              {s.business && s.business.length > 0 && (
                <>
                  <div className="panel-head mb-1 mt-2">事業の決算（{s.business.length} 事業）</div>
                  <div className={`num font-bold ${bizTotal < 0 ? 'text-bad' : 'text-good'}`}>
                    {bizTotal > 0 ? '+' : ''}
                    {formatMoney(bizTotal)}
                  </div>
                </>
              )}
              {s.rival && (
                <>
                  <div className="panel-head mb-1 mt-2">ライバル</div>
                  <div className={`font-bold ${s.rival.above ? 'text-gold' : 'text-ink-dim'}`}>
                    {state.clubs[s.rival.clubId].short}（{s.rival.rank} 位）{s.rival.above ? 'より上の順位！' : 'に順位で負けた…'}
                  </div>
                </>
              )}
            </div>
          </div>
          {s.awards && s.awards.some((a) => a.compId === s.leagueId) && (
            <div className="mt-2">
              <div className="panel-head mb-1">{comp?.short} の表彰</div>
              <div className="grid grid-cols-3 gap-1 text-[0.78rem]">
                {s.awards
                  .filter((a) => a.compId === s.leagueId)
                  .map((a) => {
                    const name = a.playerId !== undefined ? (state.players[a.playerId]?.name ?? a.name) : a.staffId !== undefined ? state.staff[a.staffId]?.name : ''
                    const mine = a.clubId === me.id
                    return (
                      <div key={a.key} className={`rounded-lg px-2 py-1 ${mine ? 'bg-gold/15' : 'bg-black/25'}`}>
                        <div className="text-[0.7rem] text-ink-dim">{AWARD_LABEL[a.key]}</div>
                        <div className={`truncate font-bold ${mine ? 'text-gold' : ''}`}>{name ?? '―'}</div>
                      </div>
                    )
                  })}
              </div>
            </div>
          )}
          {(() => {
            const w = s.awards?.find((a) => a.key === 'world')
            if (!w) return null
            const mine = w.clubId === me.id
            return (
              <div className={`mt-2 flex items-center gap-2 rounded-lg px-2.5 py-1.5 text-[0.74rem] ${mine ? 'bg-gold/15' : 'bg-black/25'}`}>
                <span className="font-black text-gold">ピッチクラウン賞</span>
                <span className="text-ink-dim">世界の年間最優秀選手</span>
                <span className={`ml-auto truncate font-bold ${mine ? 'text-gold' : ''}`}>
                  {(w.playerId !== undefined ? state.players[w.playerId]?.name : undefined) ?? w.name}（{state.clubs[w.clubId]?.short}）
                </span>
              </div>
            )
          })()}
        </div>
        <div className="mt-2 flex shrink-0 gap-2">
          <button
            className="btn btn-ghost flex-1"
            onClick={() => {
              onClose()
              push({ id: 'records' })
            }}
          >
            クラブの記録
          </button>
          <button className="btn btn-gold flex-[2]" onClick={onClose}>
            新しいシーズンへ
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}
