/**
 * キャリアから書き出したレジェンドを端末に保存する（localStorage）。セーブをまたいでクラブモードから呼べる。
 * 読めない・書けないときは空のまま（ゲームは続けられる）。
 */
import type { GameState } from '../../engine'
import { legendFromCareer, type Legend } from '../../engine/career/export'

const KEY = 'pitchcrown-legends-v1'

export function loadLegends(): Legend[] {
  try {
    const raw = localStorage.getItem(KEY)
    return raw ? (JSON.parse(raw) as Legend[]) : []
  } catch {
    return []
  }
}

function saveLegends(list: Legend[]) {
  try {
    localStorage.setItem(KEY, JSON.stringify(list))
  } catch {
    // 保存できなくてもゲームは続ける
  }
}

/** キャリアの主人公を書き出す（同じ主人公なら上書き）。書き出した内容を返す */
export function exportLegend(state: GameState): Legend {
  const c = state.career!
  const key = `${state.seed}-${c.playerId}`
  const l = legendFromCareer(state, key)
  saveLegends([...loadLegends().filter((x) => x.key !== key), l])
  return l
}

export function removeLegend(key: string) {
  saveLegends(loadLegends().filter((x) => x.key !== key))
}
