/**
 * リプレイ: 試合の位置を 1 歩ごとに記録しておき（直近の数秒だけ）、ゴールや惜しい場面を切り出して再生する。
 * 試合の結果には触れない（見るだけ）。切り出した場面は試合のあとのハイライトにも使う。
 */
import type { LiveMatch } from '../../engine/match/live/sim'
import type { DrawableMatch, DrawBody } from './renderer'

/** 記録しておく歩数（10 歩 = 試合の 1 秒） */
const KEEP = 90
/** 切り出す長さ: 出来事の前と後 */
export const CLIP_BEFORE = 45
export const CLIP_AFTER = 12

interface Frame {
  /** 選手の x, y を順に（m.bodies の並び） */
  pos: Float32Array
  on: Uint8Array
  ball: [number, number, number]
  owner: number
}

/** 選手の変わらない情報（背番号・名前・チーム）とチームの色。試合が終わったあとも再生できるように場面に持たせる */
type Roster = Pick<DrawBody, 'idx' | 'team' | 'gk' | 's'>[]

export interface Clip {
  kind: 'goal' | 'post' | 'save'
  team: 0 | 1
  minute: number
  /** 見出し（得点者・「ポスト直撃」など） */
  label: string
  frames: Frame[]
  roster: Roster
  teams: DrawableMatch['teams']
}

export class Recorder {
  private buf: Frame[] = []
  private pending: { at: number; clip: Omit<Clip, 'frames' | 'roster' | 'teams'> }[] = []
  private steps = 0
  private roster: Roster = []
  private teams: DrawableMatch['teams'] = []
  readonly clips: Clip[] = []

  /** 1 歩進めたあとに呼ぶ */
  record(m: LiveMatch) {
    if (!this.roster.length) {
      this.roster = m.bodies.map((b) => ({ idx: b.idx, team: b.team, gk: b.gk, s: { id: b.s.id, number: b.s.number, short: b.s.short } }))
      this.teams = m.teams.map((t) => ({ setup: { gkColor: t.setup.gkColor, colors: { ...t.setup.colors } } }))
    }
    const n = m.bodies.length
    const pos = new Float32Array(n * 2)
    const on = new Uint8Array(n)
    for (let i = 0; i < n; i++) {
      const b = m.bodies[i]
      pos[i * 2] = b.x
      pos[i * 2 + 1] = b.y
      on[i] = b.onPitch ? 1 : 0
    }
    this.buf.push({ pos, on, ball: [m.ball.x, m.ball.y, m.ball.z], owner: m.ball.owner })
    if (this.buf.length > KEEP) this.buf.shift()
    this.steps++
    // 出来事のあと少し待ってから切り出す（ボールがネットに入るところまで）
    while (this.pending.length && this.pending[0].at <= this.steps) {
      const p = this.pending.shift()!
      this.clips.push({ ...p.clip, frames: this.buf.slice(-(CLIP_BEFORE + CLIP_AFTER)), roster: this.roster, teams: this.teams })
    }
  }

  /** 出来事が起きた（このあと CLIP_AFTER 歩で切り出す） */
  mark(clip: Omit<Clip, 'frames' | 'roster' | 'teams'>) {
    this.pending.push({ at: this.steps + CLIP_AFTER, clip })
  }

  /** 試合が終わったとき: 待っている場面を、ある分だけで切り出す */
  flush() {
    for (const p of this.pending.splice(0)) this.clips.push({ ...p.clip, frames: this.buf.slice(-(CLIP_BEFORE + CLIP_AFTER)), roster: this.roster, teams: this.teams })
  }
}

/** 記録した場面を、描画が読める形（DrawableMatch）にする */
export class ReplaySource implements DrawableMatch {
  bodies: DrawBody[]
  ball = { x: 0, y: 0, z: 0, px: 0, py: 0, pz: 0, owner: -1 }
  teams: DrawableMatch['teams']
  private clip: Clip
  constructor(clip: Clip) {
    this.clip = clip
    this.teams = clip.teams
    this.bodies = clip.roster.map((b) => ({ ...b, x: 0, y: 0, px: 0, py: 0, tx: 0, ty: 0, stun: 0, onPitch: false }))
    this.seek(0)
  }

  get length(): number {
    return this.clip.frames.length
  }

  /** i 歩目から i+1 歩目へ（描画は alpha で補間する） */
  seek(i: number) {
    const fs = this.clip.frames
    const a = fs[Math.max(0, Math.min(fs.length - 1, i))]
    const b = fs[Math.max(0, Math.min(fs.length - 1, i + 1))]
    for (let k = 0; k < this.bodies.length; k++) {
      const p = this.bodies[k]
      if (k * 2 + 1 >= a.pos.length) {
        p.onPitch = false
        continue
      }
      p.px = a.pos[k * 2]
      p.py = a.pos[k * 2 + 1]
      p.x = b.pos[k * 2]
      p.y = b.pos[k * 2 + 1]
      p.tx = p.x
      p.ty = p.y
      p.onPitch = b.on[k] === 1
    }
    this.ball.px = a.ball[0]
    this.ball.py = a.ball[1]
    this.ball.pz = a.ball[2]
    this.ball.x = b.ball[0]
    this.ball.y = b.ball[1]
    this.ball.z = b.ball[2]
    this.ball.owner = b.owner
  }
}
