/**
 * スタッフの雇用と解雇。
 * 雇うと契約金（年俸の半年分）がかかり、役割が重なるときは今のスタッフを解雇する（残りの年俸の半分を払う）。
 */
import { absWeekOf } from '../core/calendar'
import type { Club } from '../models/club'
import type { GameState } from '../models/game'
import { STAFF_ROLE_LABEL, type Staff, type StaffRole } from '../models/staff'
import { staffWage } from '../gen/staffGen'
import { inWorld, scoutLimit } from '../club/worldClass'

/** 1 クラブに 1 人までの役割（スカウトは 3 人まで。ワールドリーグは 4 人） */
export function roleLimit(club: Club, role: StaffRole): number {
  return role === 'scout' ? scoutLimit(club) : 1
}

export function signingFee(s: Staff): number {
  return Math.round(s.wage * 0.5)
}

export function severance(state: GameState, s: Staff): number {
  const years = Math.max(0, s.until - state.season) + 0.5
  return Math.round(s.wage * years * 0.5)
}

/** 雇える人（フリーのスタッフ） */
export function staffMarket(state: GameState): Staff[] {
  return Object.values(state.staff)
    .filter((s) => s.clubId < 0 && s.role !== 'owner')
    .sort((a, b) => b.ability - a.ability)
}

export function canHire(state: GameState, club: Club, s: Staff): { ok: boolean; reason?: string } {
  if (s.clubId >= 0) return { ok: false, reason: 'ほかのクラブと契約中' }
  if (s.world && !inWorld(club)) return { ok: false, reason: 'ワールドリーグのクラブとだけ契約する' }
  const fee = signingFee(s)
  const limit = roleLimit(club, s.role)
  const same = club.staff.map((id) => state.staff[id]).filter((x) => x?.role === s.role)
  const replace = same.length >= limit ? same.sort((a, b) => a.ability - b.ability)[0] : undefined
  const cost = fee + (replace ? severance(state, replace) : 0)
  if (club.budget < cost) return { ok: false, reason: '資金が足りない' }
  return { ok: true }
}

export function hire(state: GameState, club: Club, s: Staff, years = 2): Staff | undefined {
  if (!canHire(state, club, s).ok) return undefined
  const limit = roleLimit(club, s.role)
  const same = club.staff.map((id) => state.staff[id]).filter((x) => x?.role === s.role)
  let replaced: Staff | undefined
  if (same.length >= limit) {
    replaced = same.sort((a, b) => a.ability - b.ability)[0]
    fire(state, club, replaced)
  }
  club.budget -= signingFee(s)
  s.clubId = club.id
  s.until = state.season + years - 1
  s.wage = Math.max(s.wage, staffWage(s.role, s.ability, club.country))
  club.staff.push(s.id)
  if (club.isPlayer)
    state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'staff', mine: true, text: `${STAFF_ROLE_LABEL[s.role]}に ${s.name} を迎えました${replaced ? `（${replaced.name} は退団）` : ''}。` })
  return replaced
}

export function fire(state: GameState, club: Club, s: Staff) {
  if (s.role === 'owner' || s.role === 'secretary') return
  club.budget -= severance(state, s)
  club.staff = club.staff.filter((id) => id !== s.id)
  s.clubId = -1
}
