/** 試合後のハイライト: 切り出した場面（ゴール・ポスト・ビッグセーブ）を順に再生する。#overlay-root に描く。 */
import { useState } from 'react'
import { createPortal } from 'react-dom'
import { ReplayCanvas } from './ReplayCanvas'
import type { Clip } from './replay'
import { useOverlayRoot } from '../stage/overlayRoot'
import { Icon } from '../components/Icon'

const KIND_ICON: Record<Clip['kind'], string> = { goal: '⚽', post: '🥅', save: '🧤' }

export function HighlightModal({ clips, onClose, focusId }: { clips: Clip[]; onClose: () => void; focusId?: number }) {
  const root = useOverlayRoot()
  const [i, setI] = useState(0)
  // 同じ場面をもう一度流すときは key を変える
  const [round, setRound] = useState(0)
  if (!root || !clips.length) return null
  const clip = clips[i]
  const next = () => (i + 1 < clips.length ? setI(i + 1) : undefined)
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[60] flex bg-black/80">
      <div className="relative min-w-0 flex-1">
        <ReplayCanvas key={`${i}-${round}`} clip={clip} rate={0.9} focusId={focusId} onEnd={() => setTimeout(next, 900)} className="absolute inset-0" />
        <div className="safe-l absolute left-2 top-2 rounded-md bg-[#06121f]/85 px-2.5 py-1 text-[0.85rem] font-black text-white">
          {KIND_ICON[clip.kind]} {clip.minute}' {clip.label}
        </div>
        <button className="absolute bottom-3 left-1/2 -translate-x-1/2 rounded-lg bg-black/55 px-3 py-1.5 text-[0.75rem] font-bold text-white" onClick={() => setRound((r) => r + 1)}>
          もう一度
        </button>
      </div>
      <div className="safe-r flex w-[15rem] shrink-0 flex-col gap-1 bg-[#0b1320] p-2">
        <div className="flex items-center">
          <span className="panel-head">ハイライト（{clips.length}）</span>
          <button className="ml-auto flex h-9 w-9 items-center justify-center rounded-lg text-ink-dim hover:bg-white/5" onClick={onClose} aria-label="閉じる">
            <Icon name="close" className="h-5 w-5" />
          </button>
        </div>
        <div className="scroll-y min-h-0 flex-1 space-y-1">
          {clips.map((c, k) => (
            <button key={k} className={`flex w-full items-start gap-1.5 rounded-lg px-2 py-1.5 text-left text-[0.78rem] ${k === i ? 'bg-gold/15 ring-1 ring-gold/50' : 'bg-white/[0.04]'}`} onClick={() => (setI(k), setRound((r) => r + 1))}>
              <span className="num shrink-0 font-black text-gold">{c.minute}'</span>
              <span className="shrink-0">{KIND_ICON[c.kind]}</span>
              <span className="min-w-0">{c.label}</span>
            </button>
          ))}
        </div>
      </div>
    </div>,
    root,
  )
}
