/** 選手一覧の追加タブ: ユース・契約・連携。 */
import { useState } from 'react'
import { ageOf, currentAbsWeek, ovr, playerClub, squadOf, type Player } from '../../engine'
import { expiringPlayers, quickRenew, renewAllExpiring, renewalDemand } from '../../engine/transfer/contracts'
import { chemOf, combosOf } from '../../engine/club/chemistry'
import { estimate } from '../../engine/scout/knowledge'
import { rosterInfo } from '../../engine/club/roster'
import { PlayerFace } from '../components/PersonFace'
import { Flag, OvrBadge, PosBadge, Stars } from '../components/common'
import { NegotiationSheet } from '../transfer/NegotiationSheet'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { formatMoneyShort } from '../format'
import { promoteYouth } from '../../engine/club/youthStory'
import { canStudy, findAcademy, sendStudy, studyCost, studying, STUDY_MAX, STUDY_WEEKS } from '../../engine/club/academy'
import { ACADEMY_DEFS } from '../../engine/data/academies'
import { NATION_NAME } from '../../engine/data/nations'

export function YouthTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const me = playerClub(state)
  const now = currentAbsWeek(state)
  const [studyFor, setStudyFor] = useState<number | null>(null)
  const youth = Object.values(state.players)
    .filter((p) => p.isYouth && p.clubId === me.id && !p.retired)
    .sort((a, b) => ovr(b) - ovr(a))
  const abroad = studying(state, me).length
  // 留学先: アカデミーのある国を先に
  const nations = [...ACADEMY_DEFS].sort((a, b) => Number(!!findAcademy(me, b.nation)) - Number(!!findAcademy(me, a.nation)))
  return (
    <div className="scroll-y min-h-0 flex-1 space-y-1 px-3 pb-3">
      <p className="py-1 text-[0.78rem] text-ink-dim">
        ユースアカデミーの選手 <b className="num text-ink">{youth.length}</b> 人（留学 {abroad}/{STUDY_MAX}）。毎年夏に入団し、19 歳までにトップへ上げないと退団します。ユース施設・ユースコーチ・海外アカデミーで質と人数が上がります。
      </p>
      {youth.length === 0 && <div className="text-[0.8rem] text-ink-mute">いまユースの選手はいません。</div>}
      {youth.map((p) => {
        const est = estimate(state, p)
        const st = p.study && now < p.study.untilAbsWeek ? p.study : null
        return (
          <div key={p.id} className="rounded-lg bg-white/[0.04] px-1.5 py-1">
            <div className="flex items-center gap-2">
              <button className="flex min-w-0 flex-1 items-center gap-2 text-left" onClick={() => push({ id: 'player', params: { id: p.id } })}>
                <PlayerFace p={p} kit={me.colors} className="h-8 w-8 shrink-0" />
                <PosBadge pos={p.pos} />
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-1">
                    <span className="truncate text-[0.82rem] font-bold">{p.name}</span>
                    {p.nation !== 'JP' && <Flag nation={p.nation} className="h-[0.75rem] w-[1.1rem] shrink-0" />}
                  </span>
                  <span className="block truncate text-[0.68rem] text-ink-dim">
                    {st ? <span className="font-bold text-accent">留学中（{NATION_NAME[st.nation]}・あと {st.untilAbsWeek - now} 週）</span> : (p.origin ?? 'ユースアカデミー')}
                  </span>
                </span>
                <span className="num text-[0.75rem]">{ageOf(p, now)}歳</span>
                <OvrBadge value={ovr(p)} size="sm" />
                <Stars value={(est.potLo + est.potHi) / 2} className="text-[0.72rem]" />
              </button>
              <button className="btn btn-ghost btn-sm !min-h-[2.2rem] !text-[0.72rem]" disabled={!!st} onClick={() => setStudyFor(studyFor === p.id ? null : p.id)}>
                留学
              </button>
              <button className="btn btn-gold btn-sm !min-h-[2.2rem] !text-[0.72rem]" disabled={rosterInfo(state).full || !!st} onClick={() => mutate((st) => void promoteYouth(st, st.players[p.id]))}>
                {rosterInfo(state).full ? '枠いっぱい' : 'トップへ'}
              </button>
              <button
                className="btn btn-ghost btn-sm !min-h-[2.2rem] !text-[0.72rem]"
                onClick={() =>
                  mutate((st) => {
                    const q = st.players[p.id]
                    q.isYouth = false
                    q.study = undefined
                    q.clubId = -1
                  })
                }
              >
                放出
              </button>
            </div>
            {studyFor === p.id && (
              <div className="anim-rise mt-1.5 border-t border-white/10 pt-1.5">
                <div className="mb-1 text-[0.72rem] text-ink-dim">留学先（{STUDY_WEEKS} 週。その国の得意の能力が伸びやすい。海外アカデミーのある国は安く、もっと伸びる）</div>
                <div className="grid grid-cols-3 gap-1">
                  {nations.map((d) => {
                    const chk = canStudy(state, p, d.nation)
                    const own = !!findAcademy(me, d.nation)
                    return (
                      <button
                        key={d.nation}
                        className={`flex items-center gap-1.5 rounded-lg px-1.5 py-1 text-left text-[0.7rem] disabled:opacity-40 ${own ? 'bg-gold/10 ring-1 ring-gold/40' : 'bg-black/25'}`}
                        disabled={!chk.ok}
                        onClick={() => {
                          mutate((st) => void sendStudy(st, p.id, d.nation))
                          setStudyFor(null)
                        }}
                      >
                        <Flag nation={d.nation} className="h-[0.8rem] w-[1.2rem] shrink-0" />
                        <span className="min-w-0 flex-1">
                          <span className="block truncate font-bold">{d.city}</span>
                          <span className="block truncate text-[0.64rem] text-ink-dim">{d.spec}</span>
                        </span>
                        <span className="num shrink-0 text-[0.66rem]">{formatMoneyShort(studyCost(me, d.nation))}</span>
                      </button>
                    )
                  })}
                </div>
                {!canStudy(state, p, 'BR').ok && canStudy(state, p, 'BR').reason?.includes('人まで') && <div className="mt-1 text-[0.7rem] text-bad">留学は {STUDY_MAX} 人までです</div>}
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}

export function ContractTab() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const me = playerClub(state)
  const [nego, setNego] = useState<Player | null>(null)
  const list = expiringPlayers(state).sort((a, b) => ovr(b) - ovr(a))
  return (
    <div className="flex min-h-0 flex-1 flex-col px-3 pb-3">
      <div className="flex items-center gap-2 py-1">
        <p className="min-w-0 flex-1 text-[0.78rem] text-ink-dim">今季で契約が切れる選手。シーズン末までに更新しないと、フリーになって退団します。</p>
        <button className="btn btn-gold btn-sm" disabled={!list.length} onClick={() => mutate((st) => renewAllExpiring(st))}>
          全員を希望額で更新
        </button>
      </div>
      <div className="scroll-y min-h-0 flex-1 space-y-1">
        {list.length === 0 && <div className="text-[0.8rem] text-ink-mute">今季で契約が切れる選手はいません。</div>}
        {list.map((p) => (
          <div key={p.id} className="flex items-center gap-2 rounded-lg bg-white/[0.04] px-1.5 py-1">
            <PlayerFace p={p} kit={me.colors} className="h-8 w-8 shrink-0" />
            <PosBadge pos={p.pos} />
            <span className="min-w-0 flex-1 truncate text-[0.82rem] font-bold">{p.name}</span>
            <span className="num w-[2.6rem] text-right text-[0.78rem] text-ink-dim">{ageOf(p, currentAbsWeek(state))}歳</span>
            <OvrBadge value={ovr(p)} size="sm" />
            <span className="num w-[7rem] text-right text-[0.76rem] text-ink-dim">
              {formatMoneyShort(p.contract.wage)} → <span className="font-bold text-ink">{formatMoneyShort(renewalDemand(state, p))}</span>
            </span>
            <button className="btn btn-blue btn-sm !min-h-[2.2rem] !text-[0.72rem]" onClick={() => mutate((st) => quickRenew(st, st.players[p.id]))}>
              2年更新
            </button>
            <button className="btn btn-ghost btn-sm !min-h-[2.2rem] !text-[0.72rem]" onClick={() => setNego(p)}>
              交渉
            </button>
          </div>
        ))}
      </div>
      <NegotiationSheet key={nego?.id ?? 'none'} player={nego} mode="renew" open={!!nego} onClose={() => setNego(null)} />
    </div>
  )
}

export function ChemistryTab() {
  const state = useGameState()
  const me = playerClub(state)
  const squad = squadOf(state, me.id)
  const pairs: { a: Player; b: Player; v: number }[] = []
  for (let i = 0; i < squad.length; i++)
    for (let j = i + 1; j < squad.length; j++) {
      const v = chemOf(state, squad[i].id, squad[j].id)
      if (v >= 5) pairs.push({ a: squad[i], b: squad[j], v })
    }
  pairs.sort((x, y) => y.v - x.v)
  const combos = combosOf(state, squad)
  return (
    <div className="flex min-h-0 flex-1 gap-3 px-3 pb-3">
      <div className="scroll-y min-w-0 flex-1 space-y-1">
        <p className="py-1 text-[0.78rem] text-ink-dim">一緒に試合に出るほど連携が深まり、パスがつながりやすくなります。戦術理解の練習と合宿でも育ちます。</p>
        {pairs.length === 0 && <div className="text-[0.8rem] text-ink-mute">まだ連携の育ったコンビはいません。</div>}
        {pairs.slice(0, 40).map(({ a, b, v }) => (
          <div key={`${a.id}-${b.id}`} className="flex items-center gap-2 rounded-lg bg-white/[0.04] px-1.5 py-1">
            <PlayerFace p={a} kit={me.colors} className="h-7 w-7" />
            <span className="w-[5rem] truncate text-[0.75rem] font-bold">{a.short}</span>
            <PlayerFace p={b} kit={me.colors} className="h-7 w-7" />
            <span className="w-[5rem] truncate text-[0.75rem] font-bold">{b.short}</span>
            <div className="h-2 flex-1 overflow-hidden rounded-full bg-black/40">
              <div className="h-full rounded-full" style={{ width: `${v}%`, background: v >= 80 ? '#f5c542' : v >= 50 ? '#3ddc84' : '#7dd3fc' }} />
            </div>
            <span className="num w-7 text-right text-[0.75rem] font-bold">{Math.round(v)}</span>
          </div>
        ))}
      </div>
      <div className="panel scroll-y w-[34%] shrink-0 p-2.5">
        <div className="panel-head mb-1">連携技</div>
        {combos.length === 0 && <div className="text-[0.75rem] text-ink-mute">連携が 60 を超えると、組み合わせによって連携技が生まれます。</div>}
        {combos.map((c, i) => (
          <div key={i} className="mb-1 rounded-lg bg-gold/10 px-2 py-1 text-[0.75rem]">
            <span className="font-black text-gold">{c.name}</span>
            <span className="ml-1 text-ink-dim">
              {state.players[c.a]?.short} × {state.players[c.b]?.short}
            </span>
          </div>
        ))}
      </div>
    </div>
  )
}
