/** 海外遠征（M19）: 練習画面の合宿の下。プレシーズン（第 0〜2 週）に 1 回 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { TOURS, canTour, goOnTour, type TourResult } from '../../engine/club/tour'
import { useGame } from '../../stores/gameStore'
import { formatMoney } from '../format'

export function TourPanel({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const [result, setResult] = useState<TourResult | null>(null)
  const me = state.clubs[state.playerClubId]
  const ok = canTour(state)
  const done = me.tour?.season === state.season ? TOURS.find((t) => t.id === me.tour?.id) : undefined
  return (
    <div className="panel p-3">
      <div className="panel-head mb-1.5">海外遠征（プレシーズン）</div>
      {result ? (
        <div className="space-y-1 text-[0.8rem]">
          {result.games.map((g, i) => (
            <div key={i} className="flex items-center gap-2 rounded-lg bg-black/25 px-2.5 py-1">
              <span className="min-w-0 flex-1 truncate font-bold">vs {state.clubs[g.opp].name}</span>
              <span className={`num font-black ${g.gf > g.ga ? 'text-good' : g.gf < g.ga ? 'text-bad' : 'text-ink'}`}>
                {g.gf}-{g.ga}
              </span>
            </div>
          ))}
          <div className="text-[0.72rem] text-ink-dim">人気・サポーター・連携が上がり、選手は少し疲れました。</div>
        </div>
      ) : done ? (
        <div className="text-[0.8rem] text-ink-dim">今季は{done.name}に行きました。</div>
      ) : ok ? (
        <div className="grid grid-cols-3 gap-1.5">
          {TOURS.map((t) => (
            <button
              key={t.id}
              className="menu-tile !block !min-h-0 !p-2"
              disabled={me.budget < t.cost}
              onClick={() => {
                let r: TourResult | null = null
                mutate((st) => void (r = goOnTour(st, t.id)))
                setResult(r)
              }}
            >
              <div className="text-[0.84rem] font-black">{t.name}</div>
              <div className="text-[0.66rem] leading-snug text-ink-dim">{t.desc}</div>
              <div className="num mt-0.5 text-[0.7rem]">
                費用 {formatMoney(t.cost)}・出場料 {formatMoney(t.fee)}
              </div>
            </button>
          ))}
        </div>
      ) : (
        <div className="text-[0.75rem] text-ink-dim">海外遠征はプレシーズン（第 1〜3 週）に 1 回行けます（合宿の最中は行けません）。</div>
      )}
    </div>
  )
}
