/** 1か月オートのあとのまとめ: 試合・順位・成長・ケガ・お金・出来事。 */
import { createPortal } from 'react-dom'
import { clubRank, dateLabel, ovr, playerClub, squadOf, type GameState } from '../../engine'
import type { MonthSnap } from './monthSnap'
import { weekNet } from '../../engine/economy/finance'
import { DerbyBadge } from '../club/RivalPanel'
import { formatMoneyShort } from '../format'

function Signed({ v, unit = '', digits = 0 }: { v: number; unit?: string; digits?: number }) {
  const r = Math.round(v * 10 ** digits) / 10 ** digits
  return <span className={`num font-bold ${r > 0 ? 'text-good' : r < 0 ? 'text-bad' : 'text-ink-dim'}`}>{r > 0 ? '+' : ''}{digits ? r.toFixed(digits) : r.toLocaleString()}{unit}</span>
}

export function MonthReport({ state, snap, weeks, stopText, onClose }: { state: GameState; snap: MonthSnap; weeks: number[]; stopText?: string; onClose: () => void }) {
  const root = document.getElementById('overlay-root')
  if (!root || !weeks.length) return null
  const me = playerClub(state)
  const set = new Set(weeks)
  const first = weeks[0]
  const last = weeks[weeks.length - 1]
  const label = (w: number) => dateLabel(state.startYear, Math.floor(w / 48), w % 48)
  // 試合
  const matches = state.competitions
    .flatMap((c) => c.fixtures.filter((f) => set.has(f.absWeek) && f.result && (f.home === me.id || f.away === me.id)).map((f) => ({ f, c })))
    .sort((a, b) => a.f.absWeek - b.f.absWeek || (a.f.slot === 'midweek' ? -1 : 1))
  const row = state.competitions.find((c) => c.id === me.leagueId)?.table.find((r) => r.clubId === me.id)
  const rank = clubRank(state, me)
  // 成長・ケガ
  const sq = squadOf(state, me.id)
  const growth = sq
    .filter((p) => snap.ovr[p.id] !== undefined)
    .map((p) => ({ p, d: ovr(p) - snap.ovr[p.id] }))
    .filter((x) => x.d !== 0)
    .sort((a, b) => b.d - a.d)
  const up = growth.filter((x) => x.d > 0).slice(0, 5)
  const down = growth.filter((x) => x.d < 0).slice(-2)
  const injuries = sq.filter((p) => p.injury && !snap.injured.includes(p.id))
  // お金
  const fin = state.finance.filter((w) => set.has(w.absWeek))
  const income = fin.reduce((s, w) => s + w.ticket + w.tv + w.sponsor + w.goods + w.prize + w.transferIn + Math.max(0, w.other) + Math.max(0, w.business ?? 0), 0)
  const net = fin.reduce((s, w) => s + weekNet(w), 0)
  const biz = fin.reduce((s, w) => s + (w.business ?? 0), 0)
  // 出来事（試合の結果とケガ以外）
  const events = state.news.filter((n) => n.mine && set.has(n.absWeek) && n.category !== 'match' && n.category !== 'injury').slice(-6)

  return createPortal(
    <div className="anim-fade absolute inset-0 z-50 flex items-center justify-center bg-black/65 p-3">
      <div className="panel anim-rise flex max-h-full w-[46rem] max-w-full flex-col p-3">
        <div className="flex items-baseline gap-2">
          <span className="text-[1.05rem] font-black">月間レポート</span>
          <span className="num text-[0.78rem] text-ink-dim">
            {label(first)} 〜 {label(last).replace(/^\d+年/, '')}（{weeks.length} 週）
          </span>
        </div>
        <div className="scroll-y mt-2 grid min-h-0 flex-1 grid-cols-2 gap-3 text-[0.76rem]">
          <div className="space-y-2">
            <div>
              <div className="panel-head mb-1">試合（{matches.length}）</div>
              {matches.length === 0 && <div className="text-ink-dim">試合はありませんでした</div>}
              {matches.map(({ f, c }) => {
                const home = f.home === me.id
                const opp = state.clubs[home ? f.away : f.home]
                const r = f.result!
                const [gf, ga] = home ? [r.hg, r.ag] : [r.ag, r.hg]
                const pk = r.pens ? (home ? r.pens[0] - r.pens[1] : r.pens[1] - r.pens[0]) : 0
                const res = gf > ga || (gf === ga && pk > 0) ? 'W' : gf < ga || (gf === ga && pk < 0) ? 'L' : 'D'
                return (
                  <div key={f.id} className="flex items-center gap-1.5 py-0.5">
                    <span className={`flex h-4 w-4 shrink-0 items-center justify-center rounded text-[0.68rem] font-black ${res === 'W' ? 'bg-good text-[#06210f]' : res === 'L' ? 'bg-bad text-white' : 'bg-white/20'}`}>{res === 'W' ? '勝' : res === 'L' ? '負' : '分'}</span>
                    <span className="w-9 shrink-0 truncate text-[0.7rem] text-ink-dim">{c.short}</span>
                    <span className={`w-3 shrink-0 text-center text-[0.7rem] font-bold ${home ? 'text-good' : 'text-accent'}`}>{home ? 'H' : 'A'}</span>
                    <span className="min-w-0 flex-1 truncate">{opp.name}</span>
                    <DerbyBadge state={state} home={f.home} away={f.away} className="shrink-0 !text-[0.66rem]" />
                    <span className="num shrink-0 font-bold">
                      {gf}-{ga}
                      {r.pens && <span className="text-[0.68rem] text-ink-dim">（PK）</span>}
                    </span>
                  </div>
                )
              })}
            </div>
            <div>
              <div className="panel-head mb-1">順位</div>
              <div className="flex items-baseline gap-2">
                <span className="num text-ink-dim">{snap.rank} 位</span>
                <span className="text-ink-dim">→</span>
                <span className="num text-[1.1rem] font-black text-gold">{rank} 位</span>
                <span className="text-[0.76rem] text-ink-dim">
                  勝点 {row?.points ?? 0}（<Signed v={(row?.points ?? 0) - snap.points} />）
                </span>
              </div>
            </div>
            <div className="grid grid-cols-2 gap-x-2">
              <span className="text-ink-dim">サポーター</span>
              <span className="text-right">
                <Signed v={me.fans - snap.fans} unit="人" />
              </span>
              <span className="text-ink-dim">人気</span>
              <span className="text-right">
                <Signed v={me.popularity - snap.popularity} />
              </span>
            </div>
          </div>
          <div className="space-y-2">
            <div>
              <div className="panel-head mb-1">伸びた選手</div>
              {up.length === 0 && down.length === 0 && <div className="text-ink-dim">大きな変化はありません</div>}
              {[...up, ...down].map(({ p, d }) => (
                <div key={p.id} className="flex items-center gap-1.5 py-0.5">
                  <span className="w-7 shrink-0 text-[0.7rem] text-ink-dim">{p.pos}</span>
                  <span className="min-w-0 flex-1 truncate">{p.name}</span>
                  <span className="num shrink-0 text-ink-dim">{snap.ovr[p.id]} →</span>
                  <span className="num w-6 shrink-0 text-right font-bold">{ovr(p)}</span>
                  <span className="w-8 shrink-0 text-right">
                    <Signed v={d} />
                  </span>
                </div>
              ))}
            </div>
            {injuries.length > 0 && (
              <div>
                <div className="panel-head mb-1">ケガ</div>
                {injuries.map((p) => (
                  <div key={p.id} className="flex items-center gap-1.5 py-0.5">
                    <span className="min-w-0 flex-1 truncate">{p.name}</span>
                    <span className="shrink-0 text-bad">
                      {p.injury!.name}（あと {p.injury!.weeks} 週）
                    </span>
                  </div>
                ))}
              </div>
            )}
            <div>
              <div className="panel-head mb-1">お金</div>
              <div className="grid grid-cols-2 gap-x-2">
                <span className="text-ink-dim">収入</span>
                <span className="num text-right">{formatMoneyShort(income)}円</span>
                {biz !== 0 && (
                  <>
                    <span className="text-ink-dim">うち事業</span>
                    <span className={`num text-right ${biz < 0 ? 'text-bad' : ''}`}>{formatMoneyShort(biz)}円</span>
                  </>
                )}
                <span className="text-ink-dim">支出</span>
                <span className="num text-right">{formatMoneyShort(income - net)}円</span>
                <span className="font-bold">収支</span>
                <span className={`num text-right font-black ${net < 0 ? 'text-bad' : 'text-gold'}`}>
                  {net > 0 ? '+' : ''}
                  {formatMoneyShort(net)}円
                </span>
              </div>
            </div>
            {events.length > 0 && (
              <div>
                <div className="panel-head mb-1">出来事</div>
                {events.map((n, i) => (
                  <div key={i} className="py-0.5 leading-snug text-ink-dim">
                    ・{n.text}
                  </div>
                ))}
              </div>
            )}
          </div>
        </div>
        {stopText && <div className="mt-2 rounded-lg bg-accent/15 px-3 py-1.5 text-[0.78rem] font-bold text-accent">止まった理由: {stopText}</div>}
        <button className="btn btn-gold mt-2 w-full" onClick={onClose}>
          閉じる
        </button>
      </div>
    </div>,
    root,
  )
}
