/**
 * ワールドリーグ（M24）: クラブの概要の右の欄。参入の条件と申請、入ったあとはいまの順位と入れ替えの決まり。
 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { APPLY_LAST_WEEK, APPLY_REP, APPLY_TITLES, WL_DOWN, WL_NAME, applyWorldLeague, npl1Titles, withdrawWorldLeague, worldEligibility, worldLeague } from '../../engine/competition/worldLeague'
import { sortTable } from '../../engine/competition/league'
import { useGame } from '../../stores/gameStore'
import { WL_PRIZE, WL_TV } from '../../engine/club/worldClass'
import { useUi } from '../../stores/uiStore'
import { ConfirmDialog } from '../components/ConfirmDialog'

function Cond({ ok, label, value }: { ok: boolean; label: string; value: string }) {
  return (
    <div className="flex items-center gap-2 text-[0.78rem]">
      <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[0.7rem] font-black ${ok ? 'bg-good text-[#0b1320]' : 'bg-white/10 text-ink-mute'}`}>{ok ? '✓' : '・'}</span>
      <span className="min-w-0 flex-1">{label}</span>
      <span className={`num font-bold ${ok ? 'text-good' : 'text-ink-dim'}`}>{value}</span>
    </div>
  )
}

/** ワールドリーグで開くもの（M24 の 2 回目） */
const UNLOCKS: [string, string][] = [
  ['分配金', `年 ${WL_TV / 10000} 億円（1 部は 3.5 億）・優勝賞金 ${WL_PRIZE[0] / 10000} 億円`],
  ['スポンサー', '世界の企業から（1 部の約 1.8 倍）・4 つ目の枠「グローバルパートナー」'],
  ['施設', '世界水準の Lv6〜8'],
  ['スタジアム', '客席 10 万人・グレード 7 まで'],
  ['海外のファン', '海外向けオンラインストアと、海外からの観戦'],
  ['スタッフ', '世界の名伯楽（シーズンのはじめに 6 人）・スカウト 4 人まで'],
]

function Unlocks() {
  return (
    <div className="mt-1.5 grid grid-cols-[auto_1fr] gap-x-2 gap-y-0.5 rounded-lg bg-black/20 px-2 py-1.5 text-[0.68rem]">
      <span className="col-span-2 text-[0.68rem] font-bold text-gold">ワールドリーグで開くもの</span>
      {UNLOCKS.map(([k, v]) => (
        <span key={k} className="contents">
          <span className="font-bold text-ink-dim">{k}</span>
          <span>{v}</span>
        </span>
      ))}
    </div>
  )
}

export function WorldLeaguePanel({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const [ask, setAsk] = useState(false)
  const wl = worldLeague(state)
  // 古いセーブ: 次のシーズンのはじめに発足する
  if (!wl)
    return state.mode === 'club' ? (
      <div className="rounded-xl border border-gold/40 bg-gold/10 p-2.5">
        <div className="panel-head">{WL_NAME}（来季から）</div>
        <p className="mt-1 text-[0.76rem]">
          日本・欧州・南米の 18 クラブが世界一を争う、国内 1 部の上のリーグが来季のはじめに発足します（外国人枠なし）。NPL1 の上位 4 クラブが移り、NPL は 2 部・3 部から繰り上がります。
        </p>
        <p className="mt-1 text-[0.7rem] text-ink-dim">
          参入の申請の条件: NPL1 に所属・NPL1 の通算優勝 {APPLY_TITLES} 回以上・クラブの格 {APPLY_REP} 以上（いま {npl1Titles(state)} 回・格 {Math.floor(state.clubs[state.playerClubId].rep)}）
        </p>
      </div>
    ) : null
  const e = worldEligibility(state)
  if (e.member) {
    sortTable(wl)
    const rank = wl.table.findIndex((r) => r.clubId === state.playerClubId) + 1
    return (
      <div className="rounded-xl border border-gold/40 bg-gold/10 p-2.5">
        <div className="flex items-center gap-2">
          <span className="panel-head">{WL_NAME}</span>
          <span className="ml-auto rounded bg-gold px-1.5 text-[0.7rem] font-black text-[#2a1a00]">所属</span>
        </div>
        <div className="mt-1 text-[0.8rem]">
          いま <b className="num text-gold">{rank} 位</b> / {wl.clubIds.length}。外国人枠はありません。
        </div>
        <div className="mt-0.5 text-[0.7rem] text-ink-dim">下位 {WL_DOWN} クラブは自分の国のリーグへ戻り、その国のリーグの上位と入れ替わります。</div>
        <Unlocks />
        <button className="btn btn-ghost btn-sm mt-1.5 w-full !text-[0.74rem]" onClick={() => push({ id: 'schedule', params: { comp: wl.id } })}>
          順位表を見る
        </button>
      </div>
    )
  }
  return (
    <div className={`rounded-xl border p-2.5 ${e.applied ? 'border-good/50 bg-good/10' : e.ok ? 'border-gold/50 bg-gold/10' : 'border-white/10 bg-black/20'}`}>
      <div className="flex items-center gap-2">
        <span className="panel-head">{WL_NAME}への参入</span>
        {e.applied && <span className="ml-auto rounded bg-good px-1.5 text-[0.7rem] font-black text-[#0b1320]">申請済み</span>}
      </div>
      <p className="mt-0.5 text-[0.7rem] text-ink-dim">日本・欧州・南米の 18 クラブが世界一を争う、国内 1 部の上のリーグ。外国人枠なし。</p>
      <Unlocks />
      <div className="mt-1.5 space-y-1">
        <Cond ok={e.inNpl1} label="NPL1 に所属している" value={e.inNpl1 ? 'NPL1' : '—'} />
        <Cond ok={e.titles >= APPLY_TITLES} label={`NPL1 の通算優勝 ${APPLY_TITLES} 回以上`} value={`${e.titles} / ${APPLY_TITLES} 回`} />
        <Cond ok={e.rep >= APPLY_REP} label={`クラブの格 ${APPLY_REP} 以上`} value={`${Math.floor(e.rep)} / ${APPLY_REP}`} />
        <Cond ok={e.open} label={`申請は第 ${APPLY_LAST_WEEK} 週まで`} value={e.open ? '受付中' : '来季から'} />
      </div>
      {e.applied ? (
        <div className="mt-1.5 flex items-center gap-2">
          <span className="min-w-0 flex-1 text-[0.74rem] text-good">シーズン末に参入します（NPL1 から降格しなければ）。</span>
          <button className="btn btn-ghost btn-sm shrink-0 !min-h-[2.1rem] !text-[0.72rem]" onClick={() => mutate((st) => withdrawWorldLeague(st))}>
            取り下げ
          </button>
        </div>
      ) : (
        <button className="btn btn-gold btn-sm mt-1.5 w-full" disabled={!e.ok} onClick={() => setAsk(true)}>
          {e.ok ? `${WL_NAME}に申請する` : '条件を満たすと申請できます'}
        </button>
      )}
      <ConfirmDialog
        open={ask}
        title={`${WL_NAME}に申請しますか？`}
        text="シーズン末に参入します。ワールドリーグの日本勢の最下位と入れ替わります（NPL1 から降格したら取り消し）。"
        ok="申請する"
        onOk={() => {
          mutate((st) => void applyWorldLeague(st))
          setAsk(false)
        }}
        onCancel={() => setAsk(false)}
      />
    </div>
  )
}
