/**
 * 海外の有望株（M25）: 夏と冬に 6 人。左は一覧、右は選んだ子（見込みのメーター・決め手・契約金・申し込み）。
 */
import { ageOf, currentAbsWeek, playerClub, type GameState } from '../../engine'
import { OY_BONUSES, OY_ROUNDS, YOUTH_LIMIT, applyOverseas, cancelOverseas, overseasBlocker, overseasChance, overseasEstimate, overseasFactors, youthCount, type OverseasProspect } from '../../engine/club/overseasYouth'
import { findAcademy } from '../../engine/club/academy'
import { strengthsOf } from '../../engine/player/profile'
import { NATION_NAME } from '../../engine/data/nations'
import { Emblem } from '../components/ClubArt'
import { PlayerFace } from '../components/PersonFace'
import { Flag, PosBadge } from '../components/common'
import { ChanceGauge, FactorList } from '../transfer/TalkParts'
import { useGame } from '../../stores/gameStore'
import { useScreenState } from '../hooks/useScreenState'
import { formatMoney, formatMoneyShort } from '../format'

/** 次の発表の週（画面の第 N 週） */
function nextAnnounce(week: number): { week: number; label: string } {
  const r = OY_ROUNDS.find((x) => x.announce >= week) ?? OY_ROUNDS[0]
  return { week: r.announce + 1, label: r.label }
}

export function OverseasTab({ state }: { state: GameState }) {
  const oy = state.overseasYouth
  const [sel, setSel] = useScreenState('oy', 0)
  const [bonus, setBonus] = useScreenState('oyBonus', 0)
  if (!oy) return <Empty state={state} />
  const op = oy.list[Math.min(sel, oy.list.length - 1)]
  const now = currentAbsWeek(state)
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[46%] shrink-0 space-y-1 p-2">
        <div className="px-1 text-[0.72rem] text-ink-dim">
          申し込みは第 {oy.deadline + 1} 週まで（あと {Math.max(0, oy.deadline - state.week + 1)} 週）。ユース {youthCount(state)}/{YOUTH_LIMIT} 人
        </div>
        {oy.list.map((x, i) => {
          const est = overseasEstimate(state, x)
          return (
            <button key={x.player.id} className={`flex w-full items-center gap-2 rounded-lg px-1.5 py-1 text-left ${sel === i ? 'bg-gold/15 ring-1 ring-gold/50' : x.applied ? 'bg-good/10' : 'bg-black/25'}`} onClick={() => setSel(i)}>
              <PlayerFace p={x.player} className="h-9 w-9 shrink-0" />
              <span className="min-w-0 flex-1">
                <span className="flex items-center gap-1">
                  <PosBadge pos={x.player.pos} />
                  <span className="truncate text-[0.8rem] font-bold">{x.player.name}</span>
                  <Flag nation={x.player.nation} className="h-[0.75rem] w-[1.1rem] shrink-0" />
                </span>
                <span className="block truncate text-[0.66rem] text-ink-dim">
                  {ageOf(x.player, now)}歳・{x.team}
                </span>
              </span>
              <span className="shrink-0 text-right">
                <span className="block text-[0.72rem] text-gold">{'★'.repeat(est.stars)}</span>
                {x.applied ? <span className="text-[0.66rem] font-bold text-good">申し込み済み</span> : x.met ? <span className="text-[0.66rem] font-bold text-accent">大会で対戦</span> : null}
              </span>
            </button>
          )
        })}
      </div>
      {op && <Detail key={op.player.id} state={state} op={op} idx={oy.list.indexOf(op)} bonus={bonus} setBonus={setBonus} />}
    </div>
  )
}

function Detail({ state, op, idx, bonus, setBonus }: { state: GameState; op: OverseasProspect; idx: number; bonus: number; setBonus: (v: number) => void }) {
  const mutate = useGame((s) => s.mutate)
  const me = playerClub(state)
  const p = op.player
  const now = currentAbsWeek(state)
  const est = overseasEstimate(state, op)
  const b = op.applied?.bonus ?? bonus
  const chance = overseasChance(state, op, b)
  const factors = overseasFactors(state, op, b)
    .slice(1)
    .map((f) => ({ key: f.label, label: f.label, value: f.v }))
  const block = op.applied ? null : overseasBlocker(state, op, bonus)
  const strong = strengthsOf(p.attr, p.pos).strong
  const academy = findAcademy(me, p.nation)
  return (
    <div className="panel scroll-y min-w-0 flex-1 space-y-2 p-3 text-[0.8rem]">
      <div className="flex items-center gap-3">
        <PlayerFace p={p} className="h-14 w-14 shrink-0" />
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-1.5">
            <span className="truncate text-[1rem] font-black">{p.name}</span>
            <Flag nation={p.nation} />
          </div>
          <div className="text-[0.74rem] text-ink-dim">
            {NATION_NAME[p.nation]}・{ageOf(p, now)}歳・{op.team}
          </div>
          <div className="mt-0.5 flex flex-wrap items-center gap-1 text-[0.72rem]">
            <PosBadge pos={p.pos} />
            <span className="num">
              総合 {est.lo}〜{est.hi}
            </span>
            <span className="text-gold">{'★'.repeat(est.stars)}</span>
            {est.sure && <span className="rounded bg-good/20 px-1 text-[0.66rem] font-bold text-good">アカデミーの情報で正確</span>}
          </div>
        </div>
      </div>
      <div className="flex flex-wrap items-center gap-1 text-[0.7rem]">
        <span className="text-ink-dim">得意</span>
        {strong.map((s) => (
          <span key={s.key} className="rounded bg-white/10 px-1.5">
            {s.name}
          </span>
        ))}
        {op.met && <span className="rounded bg-accent/20 px-1.5 font-bold text-accent">国際ユースカップで対戦（{op.met}）</span>}
        {academy && <span className="rounded bg-gold/20 px-1.5 font-bold text-gold">{NATION_NAME[p.nation]}にアカデミー</span>}
      </div>
      <div className="flex items-center gap-1.5 text-[0.72rem]">
        {op.interest.length ? (
          <>
            {op.interest.map((id) => {
              const c = state.clubs[id]
              return <Emblem key={id} id={`oy-${p.id}-${id}`} emblem={c.emblem} colors={c.colors} size="1.3rem" />
            })}
            <span className="text-ink-dim">{op.interest.map((id) => state.clubs[id].short).join('・')} も狙っている</span>
          </>
        ) : (
          <span className="text-ink-dim">ほかに狙っているクラブはない</span>
        )}
      </div>
      <div className="rounded-lg bg-black/25 p-2">
        <ChanceGauge value={chance} title="来てくれる見込み" />
        <div className="mt-1.5">
          <FactorList factors={factors} />
        </div>
      </div>
      <div className="flex items-center gap-2">
        <span className="w-20 shrink-0 text-[0.74rem] text-ink-dim">契約金</span>
        <div className="seg">
          {OY_BONUSES.map((x) => (
            <button key={x} aria-selected={b === x} disabled={!!op.applied} onClick={() => setBonus(x)}>
              {x ? formatMoneyShort(x) : 'なし'}
            </button>
          ))}
        </div>
      </div>
      <div className="text-[0.74rem]">
        育成補償金 <b className="num">{formatMoney(op.fee)}</b>
        {b > 0 && (
          <>
            {' '}
            ＋ 契約金 <b className="num">{formatMoney(b)}</b>
          </>
        )}
        <span className="text-ink-dim">（入団が決まったら払う）</span>
      </div>
      {op.applied ? (
        <div className="flex items-center gap-2">
          <span className="min-w-0 flex-1 text-[0.76rem] font-bold text-good">申し込み済み。第 {state.overseasYouth!.deadline + 1} 週の終わりに本人が決めます。</span>
          <button className="btn btn-ghost btn-sm shrink-0" onClick={() => mutate((st) => cancelOverseas(st, idx))}>
            取り消す
          </button>
        </div>
      ) : (
        <button className="btn btn-gold w-full" disabled={!!block} onClick={() => mutate((st) => void applyOverseas(st, idx, bonus))}>
          {block ?? 'ユース契約を申し込む'}
        </button>
      )}
    </div>
  )
}

function Empty({ state }: { state: GameState }) {
  const next = nextAnnounce(state.week)
  const last = state.overseasYouthLast
  return (
    <div className="panel scroll-y min-h-0 flex-1 space-y-2 p-3 text-[0.8rem]">
      <div className="panel-head">海外の有望株</div>
      <p className="text-ink-dim">
        夏（第 {OY_ROUNDS[0].announce + 1} 週）と冬（第 {OY_ROUNDS[1].announce + 1} 週）に、海外の 15〜17 歳の有望株 6 人の情報が届きます。ユース契約（育成補償金 ＋ 契約金）で、選手枠を使わずにユースへ迎えられます。
      </p>
      <p className="text-ink-dim">
        海外アカデミーのある国の子は情報が正確で、来てくれやすくなります。冬は、国際ユースカップで目立った相手の選手も並びます。欧州の強豪が狙っている子は難しくなります。
      </p>
      <div className="rounded-lg bg-black/25 px-2.5 py-2 text-[0.78rem]">
        次の発表: <b>第 {next.week} 週（{next.label}）</b>
      </div>
      {last && (
        <div>
          <div className="mb-1 text-[0.74rem] font-bold text-ink-dim">前回の結果（{OY_ROUNDS[last.round].label}）</div>
          <div className="space-y-1">
            {last.list.map((r) => (
              <div key={r.playerId} className="flex items-center gap-2 rounded-lg bg-white/[0.04] px-2 py-1 text-[0.76rem]">
                <Flag nation={r.nation} className="h-[0.75rem] w-[1.1rem] shrink-0" />
                <span className="min-w-0 flex-1 truncate font-bold">{r.name}</span>
                <span className="truncate text-[0.68rem] text-ink-dim">{r.team}</span>
                <span className={`shrink-0 rounded px-1.5 text-[0.68rem] font-bold ${r.joined ? 'bg-good/20 text-good' : 'bg-white/10 text-ink-dim'}`}>{r.note}</span>
              </div>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}
