/**
 * キャリアの年間表彰式（シーズン末）: 開幕 → 所属リーグの表彰 → ベストイレブン → ピッチクラウン賞（世界の年間最優秀選手、10 位から発表）→ あなたの受賞。
 * career.ceremony があるとき、キャリアのホームの会話より前に出す。見終わったら消す。
 */
import { useEffect, useState } from 'react'
import { createPortal } from 'react-dom'
import { seasonLabel, type GameState } from '../../engine'
import { AWARD_LABEL } from '../../engine/competition/awards'
import { POSITION_DEFS } from '../../engine/data/positions'
import { PlayerFace } from '../components/PersonFace'
import { useGame } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { sound } from '../audio/sound'

const LEAGUE_AWARDS = ['mvp', 'scorer', 'assist', 'young', 'keeper'] as const

export function Ceremony({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const [step, setStep] = useState(0)
  const [revealed, setRevealed] = useState(0)
  const c = state.career!
  const cer = c.ceremony
  const summary = cer ? state.seasons.find((s) => s.season === cer.season) : undefined
  const log = cer ? c.log.find((l) => l.season === cer.season) : undefined
  const leagueId = log?.leagueId ?? ''
  const league = state.competitions.find((x) => x.id === leagueId)
  const ranking = summary?.worldRanking ?? []
  const total = ranking.length
  const winnerIsMe = ranking[0]?.playerId === c.playerId
  // ピッチクラウン賞: 10 位から順に出す
  useEffect(() => {
    if (step !== 3 || revealed >= total) return
    const t = setTimeout(
      () => {
        setRevealed((n) => n + 1)
        if (revealed + 1 === total) sound.play(winnerIsMe ? 'fanfare' : 'notify')
      },
      revealed === total - 1 ? 1300 : 550,
    )
    return () => clearTimeout(t)
  }, [step, revealed, total, winnerIsMe])
  if (!root || !cer || !summary) return null
  const me = c.playerId
  const awards = (summary.awards ?? []).filter((a) => a.compId === leagueId && a.playerId !== undefined && (LEAGUE_AWARDS as readonly string[]).includes(a.key))
  const eleven = summary.bestEleven?.[leagueId] ?? []
  const myTitles = log?.titles ?? []
  const steps = ['open', 'league', 'eleven', 'world', 'mine'] as const
  const close = () => mutate((st) => void (st.career!.ceremony = undefined))
  const next = () => {
    if (step >= steps.length - 1) return close()
    const n = step + 1
    setStep(n)
    if (n === 3) setRevealed(0)
    if ((n === 1 && awards.some((a) => a.playerId === me)) || (n === 2 && eleven.some((e) => e.playerId === me))) sound.play('fanfare')
  }
  const player = (id: number) => state.players[id]
  const clubShort = (id: number) => state.clubs[id]?.short ?? ''
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[60] flex flex-col overflow-hidden bg-[#05080f]" onClick={next}>
      <div className="spotlight pointer-events-none absolute inset-0" style={{ background: 'radial-gradient(45% 70% at 50% -10%, rgba(255,214,120,0.35), transparent 70%), radial-gradient(30% 50% at 15% 0%, rgba(120,170,255,0.18), transparent 70%), radial-gradient(30% 50% at 85% 0%, rgba(120,170,255,0.18), transparent 70%)' }} />
      <div className="relative flex items-center gap-2 px-4 pt-3">
        <span className="rounded-full bg-gold/90 px-3 py-0.5 text-[0.75rem] font-black text-[#2a1a00]">{seasonLabel(state.startYear, cer.season)} 年間表彰式</span>
        <button
          className="btn btn-ghost btn-sm ml-auto !min-h-[2rem]"
          onClick={(e) => {
            e.stopPropagation()
            close()
          }}
        >
          スキップ
        </button>
      </div>

      {steps[step] === 'open' && (
        <div className="relative flex flex-1 flex-col items-center justify-center gap-2 text-center">
          <div className="crown-pop text-[2.6rem] font-black tracking-wider text-gold" style={{ textShadow: '0 0 24px rgba(255,200,80,0.6)' }}>
            AWARDS {seasonLabel(state.startYear, cer.season)}
          </div>
          <div className="anim-rise text-[1rem] font-bold text-white/90" style={{ animationDelay: '0.4s' }}>
            今シーズンを彩った選手たちを表彰します
          </div>
          <div className="anim-rise text-[0.8rem] text-ink-dim" style={{ animationDelay: '0.7s' }}>
            {league?.name ?? ''} の表彰 ・ ベストイレブン ・ ピッチクラウン賞
          </div>
        </div>
      )}

      {steps[step] === 'league' && (
        <div className="relative flex flex-1 flex-col px-5 pb-3 pt-2">
          <div className="mb-2 text-center text-[1.1rem] font-black text-white">{league?.name} 年間表彰</div>
          <div className="grid grid-cols-5 items-start gap-2">
            {LEAGUE_AWARDS.map((key, i) => {
              const a = awards.find((x) => x.key === key)
              const p = a?.playerId !== undefined ? player(a.playerId) : undefined
              const mine = a?.playerId === me
              return (
                <div key={key} className={`anim-rise flex flex-col items-center rounded-xl p-2 text-center ${mine ? 'shine-sweep bg-gold/20 ring-2 ring-gold' : 'bg-white/[0.06]'}`} style={{ animationDelay: `${i * 0.25}s` }}>
                  <div className={`text-[0.78rem] font-black ${mine ? 'text-gold' : 'text-ink-dim'}`}>{AWARD_LABEL[key]}</div>
                  {a ? (
                    <>
                      {p ? <PlayerFace p={p} className="my-1.5 h-16 w-16" /> : <div className="face-round my-1.5 h-16 w-16 bg-white/10" />}
                      <div className="w-full truncate text-[0.82rem] font-black">{p?.name ?? a.name ?? '―'}</div>
                      <div className="text-[0.7rem] text-ink-dim">{clubShort(a!.clubId)}</div>
                      {a?.value !== undefined && <div className="num text-[0.72rem] text-ink-dim">{key === 'scorer' ? `${a.value} 得点` : key === 'assist' ? `${a.value} アシスト` : key === 'keeper' ? `完封 ${a.value}` : `評価点 ${a.value}`}</div>}
                      {mine && <div className="crown-pop mt-1 rounded-full bg-gold px-2 text-[0.76rem] font-black text-[#2a1a00]">受賞！</div>}
                    </>
                  ) : (
                    <div className="mt-6 text-[0.76rem] text-ink-mute">該当なし</div>
                  )}
                </div>
              )
            })}
          </div>
        </div>
      )}

      {steps[step] === 'eleven' && (
        <div className="relative flex flex-1 flex-col px-5 pb-3 pt-2">
          <div className="mb-1 text-center text-[1.1rem] font-black text-white">{league?.name} ベストイレブン</div>
          <div className="relative mx-auto flex w-full max-w-[44rem] flex-1 flex-col justify-around rounded-2xl border border-white/10 py-1" style={{ background: 'linear-gradient(180deg, #1f5a32, #17472a)' }}>
            {[eleven.slice(8, 11), eleven.slice(5, 8), eleven.slice(1, 5), eleven.slice(0, 1)].map((row, ri) => (
              <div key={ri} className="flex justify-center gap-6">
                {row.map((e, i) => {
                  const p = player(e.playerId)
                  const mine = e.playerId === me
                  return (
                    <div key={e.playerId} className="anim-rise flex w-[5.4rem] flex-col items-center" style={{ animationDelay: `${(ri * 4 + i) * 0.08}s` }}>
                      {p ? <PlayerFace p={p} className={`h-10 w-10 ${mine ? 'ring-2 ring-gold' : ''}`} /> : <div className="face-round h-10 w-10 bg-white/15" />}
                      <div className={`w-full truncate text-center text-[0.72rem] font-black ${mine ? 'text-gold' : 'text-white'}`}>{e.short}</div>
                      <div className="text-[0.66rem] text-white/70">
                        {POSITION_DEFS[e.pos as keyof typeof POSITION_DEFS]?.name ?? e.pos}・{clubShort(e.clubId)}
                      </div>
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
          {eleven.some((e) => e.playerId === me) && <div className="crown-pop mt-1 text-center text-[0.9rem] font-black text-gold">ベストイレブンに選ばれた！</div>}
        </div>
      )}

      {steps[step] === 'world' && (
        <div className="relative flex flex-1 gap-4 px-5 pb-3 pt-2">
          <div className="flex w-[40%] flex-col">
            <div className="text-[1.1rem] font-black text-gold">ピッチクラウン賞</div>
            <div className="mb-1 text-[0.76rem] text-ink-dim">世界の記者が選ぶ、年間最優秀選手</div>
            <div className="flex-1 space-y-0.5 overflow-hidden">
              {ranking
                .map((r, i) => ({ ...r, rank: i + 1 }))
                .slice(1)
                .reverse()
                .slice(0, Math.max(0, revealed))
                .map((r) => {
                  const p = player(r.playerId)
                  const mine = r.playerId === me
                  return (
                    <div key={r.playerId} className={`anim-rise flex items-center gap-2 rounded-lg px-2 py-0.5 ${mine ? 'bg-gold/20 ring-1 ring-gold' : 'bg-white/[0.05]'}`}>
                      <span className="num w-6 text-right text-[0.8rem] font-black text-ink-dim">{r.rank}</span>
                      {p && <PlayerFace p={p} className="h-6 w-6" />}
                      <span className={`min-w-0 flex-1 truncate text-[0.74rem] font-bold ${mine ? 'text-gold' : ''}`}>{p?.name ?? r.name}</span>
                      <span className="shrink-0 text-[0.68rem] text-ink-dim">{clubShort(r.clubId)}</span>
                    </div>
                  )
                })}
            </div>
          </div>
          <div className="flex flex-1 flex-col items-center justify-center">
            {revealed >= ranking.length && ranking[0] ? (
              (() => {
                const w = ranking[0]
                const p = player(w.playerId)
                const mine = w.playerId === me
                return (
                  <div className="crown-pop flex flex-col items-center text-center">
                    <div className="text-[2.4rem]">👑</div>
                    {p && (p.starId || p.face?.photo ? <PlayerFace p={p} photo className={`h-[9rem] w-[13.5rem] rounded-2xl ${mine ? 'ring-4 ring-gold' : 'ring-2 ring-white/30'}`} /> : <PlayerFace p={p} className={`h-[8rem] w-[8rem] ${mine ? 'ring-4 ring-gold' : 'ring-2 ring-white/30'}`} />)}
                    <div className="mt-2 text-[1.5rem] font-black text-white" style={{ textShadow: '0 0 18px rgba(255,200,80,0.6)' }}>
                      {p?.name ?? w.name}
                    </div>
                    <div className="text-[0.8rem] text-ink-dim">{state.clubs[w.clubId]?.name}</div>
                    {mine && <div className="mt-1 rounded-full bg-gold px-3 py-0.5 text-[0.9rem] font-black text-[#2a1a00]">あなたが世界一の選手に！</div>}
                  </div>
                )
              })()
            ) : (
              <div className="text-[1rem] font-bold text-white/70">そして、今年の受賞者は……</div>
            )}
          </div>
        </div>
      )}

      {steps[step] === 'mine' && (
        <div className="relative flex flex-1 flex-col items-center justify-center gap-2 px-6 text-center">
          <div className="text-[1.15rem] font-black text-white">あなたの今シーズン</div>
          {log && (
            <div className="num text-[0.85rem] text-ink-dim">
              {log.apps} 試合 {log.goals} 得点 {log.assists} アシスト・平均評価点 {log.rating.toFixed(2)}
              {log.worldRank ? `・ピッチクラウン賞 ${log.worldRank} 位` : ''}
            </div>
          )}
          {myTitles.length ? (
            <div className="mt-1 flex max-w-[40rem] flex-wrap justify-center gap-1.5">
              {myTitles.map((t, i) => (
                <span key={i} className="crown-pop rounded-full bg-gold/20 px-3 py-1 text-[0.82rem] font-black text-gold ring-1 ring-gold/60" style={{ animationDelay: `${i * 0.15}s` }}>
                  ★ {t}
                </span>
              ))}
            </div>
          ) : (
            <div className="text-[0.85rem] text-ink-dim">今年は受賞なし。来シーズンこそ、この舞台へ。</div>
          )}
        </div>
      )}

      <div className="relative pb-3 text-center text-[0.76rem] text-ink-mute">タップして次へ（{step + 1} / {steps.length}）</div>
    </div>,
    root,
  )
}
