/**
 * オーナーの目標（M19）: 今季の目標と今の状況、信頼。
 *   full: クラブの概要（信頼のゲージつき）、compact: ホームの小さな帯、result: シーズン末の評価
 */
import type { GameState } from '../../engine'
import { goalProgress } from '../../engine/club/owner'
import { Icon } from '../components/Icon'

function trustLabel(t: number): string {
  return t >= 85 ? '厚い信頼' : t >= 65 ? '信頼している' : t >= 45 ? 'ふつう' : t >= 25 ? '不満がある' : '強い不満'
}

export function OwnerGoals({ state, compact = false }: { state: GameState; compact?: boolean }) {
  const o = state.owner
  if (!o || o.season !== state.season) return null
  const list = o.goals.map((g) => ({ g, p: goalProgress(state, g) }))
  if (compact)
    return (
      <div className="flex items-center gap-1.5 overflow-hidden">
        <span className="shrink-0 text-[0.74rem] font-bold text-ink-dim">今季の目標</span>
        {list.map(({ g, p }) => (
          <span key={g.kind} className={`flex min-w-0 items-center gap-1 rounded-full px-2 py-0.5 text-[0.72rem] font-bold ${p.ok ? 'bg-good/15 text-good' : 'bg-white/[0.06] text-ink-dim'}`}>
            <span className="shrink-0">{p.ok ? '✓' : '・'}</span>
            <span className="truncate">{g.short ?? g.label}</span>
          </span>
        ))}
      </div>
    )
  return (
    <div>
      <div className="flex items-baseline gap-2">
        <span className="panel-head">オーナーの目標（今季）</span>
        <span className="ml-auto text-[0.74rem] text-ink-dim">
          信頼 <b className="num text-ink">{Math.round(o.trust)}</b>・{trustLabel(o.trust)}
        </span>
      </div>
      <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-black/40">
        <div className="h-full rounded-full" style={{ width: `${o.trust}%`, background: o.trust >= 45 ? 'linear-gradient(90deg,#3ddc84,#f5c542)' : '#ff6b6b' }} />
      </div>
      <div className="mt-1.5 space-y-1">
        {list.map(({ g, p }) => (
          <div key={g.kind} className={`flex items-center gap-2 rounded-lg px-2.5 py-1.5 text-[0.8rem] ${p.ok ? 'bg-good/10' : 'bg-black/25'}`}>
            <Icon name={p.ok ? 'trophy' : 'forward'} className={`h-4 w-4 shrink-0 ${p.ok ? 'text-good' : 'text-ink-mute'}`} />
            <span className="min-w-0 flex-1 font-bold">{g.label}</span>
            <span className={`num shrink-0 text-[0.74rem] ${p.ok ? 'text-good' : 'text-ink-dim'}`}>{p.value}</span>
          </div>
        ))}
      </div>
      <div className="mt-1 text-[0.7rem] leading-snug text-ink-mute">シーズン末に評価され、達成した目標の数で追加の予算が出ます。信頼が低いと予算を削られます。</div>
    </div>
  )
}

/** シーズン末の評価（SeasonEndModal） */
export function OwnerResult({ state, season }: { state: GameState; season: number }) {
  const last = state.owner?.last
  if (!last || last.season !== season) return null
  const ok = last.results.filter((r) => r.ok).length
  return (
    <div className="mt-2 rounded-lg bg-black/25 px-3 py-2">
      <div className="flex items-baseline gap-2">
        <span className="text-[0.82rem] font-black text-gold">オーナーの評価</span>
        <span className="text-[0.74rem] text-ink-dim">
          {last.results.length} つのうち {ok} つ達成・信頼 {Math.round(last.trustBefore)} → <b className={last.trustAfter >= last.trustBefore ? 'text-good' : 'text-bad'}>{Math.round(last.trustAfter)}</b>
        </span>
      </div>
      <div className="mt-1 flex flex-wrap gap-1">
        {last.results.map((r) => (
          <span key={r.label} className={`rounded px-1.5 py-0.5 text-[0.72rem] font-bold ${r.ok ? 'bg-good/15 text-good' : 'bg-bad/15 text-bad'}`}>
            {r.ok ? '✓' : '✗'} {r.label}（{r.value}）
          </span>
        ))}
      </div>
      {(last.bonus > 0 || last.cut > 0) && (
        <div className="mt-1 text-[0.76rem]">
          {last.bonus > 0 && <span className="text-good">追加の予算 +{last.bonus.toLocaleString()} 万円</span>}
          {last.cut > 0 && <span className="ml-2 text-bad">予算の削減 −{last.cut.toLocaleString()} 万円</span>}
        </div>
      )}
    </div>
  )
}
