/** キャリアの育成: 経験点で能力を上げる・特殊能力を覚える（サクセス風）。練習の予定と、育成のしかた（かんたん・じっくり）。 */
import { useState } from 'react'
import { ovr, type GameState } from '../../engine'
import { ATTR_BY_KEY, ATTRS, type AttrGroup, type AttrKey } from '../../engine/data/attributes'
import { SHARED_MENUS, TRAIN_MENUS, TRAIN_MENU_BY_ID } from '../../engine/data/career'
import { trainPlanOf } from '../../engine/career/week'
import { GROWTH_DEFS } from '../../engine/data/growth'
import { convertExp, CONVERT_RATE, expMul } from '../../engine/career/growth'
import { SKILLS, type SkillDef } from '../../engine/data/skills'
import { EXP_KINDS, EXP_LABEL, type ExpKind, type TrainMenu } from '../../engine/models/career'
import { attrCost, autoSpendForPosition, canAfford, learnSkill, raiseAttr, skillCost, skillLearnable, type ExpCost } from '../../engine/career/growth'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { OvrBadge } from '../components/common'
import { useStageRem } from '../stage/useStage'
import { useGame, useGameState } from '../../stores/gameStore'
import { useCurrentScreen } from '../../stores/uiStore'
import { attrColor } from '../format'
import { GrowthChart } from '../career/GrowthChart'
import { projectGrowth } from '../../engine/career/projection'
import { careerAge } from '../../engine/career/core'

/** 成長タイプが変わる出来事（どれも一度きり。条件は career/season.ts・week.ts） */
const GT_EVENTS: { id: string; name: string; when: string }[] = [
  { id: 'gt_bloom', name: '早咲きの予感', when: '19〜21 歳・標準より遅いタイプ・15 試合以上で評価 6.8 以上 → 早熟のほうへ' },
  { id: 'gt_awaken', name: '遅咲きの覚醒', when: '24〜27 歳・標準より早いか標準・監督の評価 60 以上か評価 7.0 以上 → 晩成のほうへ' },
  { id: 'gt_care', name: '体のメンテナンス', when: '27〜31 歳・トレーナー／フィジオ／シェフ／サウナ／ヨガ部屋のどれか → 晩成のほうへ' },
  { id: 'gt_injury', name: '大ケガからの再起', when: '21 歳から・全治 12 週以上のケガ → 晩成か早熟を選ぶ' },
]

/** 成長の見込み（予想成長曲線） */
function CurveTab({ state }: { state: GameState }) {
  const c = state.career!
  const p = state.players[c.playerId]
  const proj = projectGrowth(state)
  const gdef = GROWTH_DEFS[p.growth]
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel min-w-0 flex-1 p-2.5">
        <div className="flex items-baseline gap-2">
          <span className="panel-head">成長の見込み</span>
          <span className="ml-auto text-[0.72rem] text-ink-dim">目安です。練習・出場・投資で変わります</span>
        </div>
        <GrowthChart proj={proj} type={p.growth} className="mt-1" />
      </div>
      <div className="panel scroll-y w-[32%] shrink-0 space-y-1.5 p-2.5 text-[0.74rem]">
        <div className="panel-head">成長タイプ</div>
        <div className="rounded-lg bg-white/[0.04] px-2.5 py-1.5">
          <span className="font-black text-gold">{gdef.name}</span>
          <span className="ml-1.5 text-ink-dim">ピーク {gdef.peak}</span>
          <div className="text-[0.72rem] text-ink-dim">
            いま {careerAge(state)} 歳・OVR {proj.now.ovr}。見込みのピークは {proj.peak.age} 歳ごろ OVR {proj.peak.ovr}
          </div>
          <div className="text-[0.72rem] text-ink-dim">
            いまの経験点の入り方 ×{expMul(state).toFixed(2)}
          </div>
        </div>
        <div className="panel-head pt-1">タイプが変わる出来事（どれも一度きり）</div>
        {GT_EVENTS.map((e) => {
          const done = c.done[e.id] !== undefined
          return (
            <div key={e.id} className={`rounded-lg px-2 py-1 ${done ? 'bg-good/10' : 'bg-white/[0.04]'}`}>
              <div className="font-bold">
                {e.name}
                {done && <span className="ml-1.5 text-[0.68rem] text-good">済み</span>}
              </div>
              <div className="text-[0.68rem] text-ink-dim">{e.when}</div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

const GROUPS: [AttrGroup, string][] = [
  ['tech', '技術'],
  ['body', 'フィジカル'],
  ['mind', 'メンタル'],
  ['def', '守備'],
  ['gk', 'GK'],
]

function Cost({ cost, state }: { cost: ExpCost; state: GameState }) {
  const c = state.career!
  return (
    <span className="flex gap-1">
      {(Object.entries(cost) as [ExpKind, number][]).map(([k, v]) => (
        <span key={k} className={`num rounded px-1 text-[0.68rem] ${c.exp[k] >= v ? 'bg-white/[0.07] text-ink-dim' : 'bg-bad/15 text-bad'}`}>
          {EXP_LABEL[k]}
          {v}
        </span>
      ))}
    </span>
  )
}

function AttrRow({ state, k }: { state: GameState; k: AttrKey }) {
  const mutate = useGame((s) => s.mutate)
  const p = state.players[state.career!.playerId]
  const def = ATTRS.find((a) => a.key === k)!
  const v = Math.floor(p.attr[k])
  const cost = attrCost(k, v)
  const ok = v < 99 && canAfford(state, cost)
  return (
    <div className="flex items-center gap-2 py-[0.15rem]">
      <span className="w-[4.6rem] shrink-0 truncate text-[0.75rem]">{def.name}</span>
      <span className="num w-6 shrink-0 text-right text-[0.85rem] font-black" style={{ color: attrColor(v) }}>
        {v}
      </span>
      <div className="h-1.5 w-[3.5rem] shrink-0 overflow-hidden rounded-full bg-black/40">
        <div className="h-full rounded-full" style={{ width: `${v}%`, background: attrColor(v) }} />
      </div>
      <span className="min-w-0 flex-1">
        <Cost cost={cost} state={state} />
      </span>
      <button className="btn btn-blue btn-sm !min-h-[1.9rem] !px-2.5" disabled={!ok} onClick={() => mutate((st) => void raiseAttr(st, k))} aria-label={`${def.name}を上げる`}>
        ＋
      </button>
    </div>
  )
}

function SkillRow({ state, s }: { state: GameState; s: SkillDef }) {
  const mutate = useGame((st) => st.mutate)
  const c = state.career!
  const can = skillLearnable(state, s)
  const cost = skillCost(state, s)
  const kotsu = c.kotsu[s.id] ?? 0
  const ok = can && canAfford(state, cost)
  return (
    <div className={`flex items-center gap-2 rounded-lg px-2 py-1 ${can ? 'bg-white/[0.04]' : 'opacity-50'}`}>
      <span className={`shrink-0 rounded border px-1.5 text-[0.7rem] font-bold ${s.tier === 'gold' ? 'border-gold/60 bg-gold/15 text-gold' : 'border-accent/50 bg-accent/15 text-accent'}`}>{s.tier === 'gold' ? '金' : '青'}</span>
      <span className="min-w-0 flex-1">
        <span className="flex items-center gap-1 text-[0.78rem] font-bold">
          {s.name}
          {kotsu > 0 && <span className="text-[0.7rem] text-gold">コツ{'★'.repeat(kotsu)}</span>}
        </span>
        <span className="block truncate text-[0.7rem] text-ink-dim">{s.desc}</span>
      </span>
      <Cost cost={cost} state={state} />
      <button className="btn btn-gold btn-sm !min-h-[1.9rem]" disabled={!ok} onClick={() => mutate((st) => void learnSkill(st, s.id))}>
        覚える
      </button>
    </div>
  )
}

/** 余った経験点の振り替え（3 → 2）。かんたん育成では自動で行う */
function ConvertBox({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const c = state.career!
  const [from, setFrom] = useState<ExpKind>(() => [...EXP_KINDS].sort((a, b) => c.exp[b] - c.exp[a])[0])
  const [to, setTo] = useState<ExpKind>(() => [...EXP_KINDS].sort((a, b) => c.exp[a] - c.exp[b])[0])
  const amount = Math.min(30, Math.floor(c.exp[from]))
  return (
    <div className="space-y-1">
      <div className="panel-head pt-1">経験点の振り替え（3 → 2）</div>
      {(
        [
          ['から', from, setFrom],
          ['へ', to, setTo],
        ] as [string, ExpKind, (k: ExpKind) => void][]
      ).map(([label, v, set]) => (
        <div key={label} className="flex items-center gap-1 text-[0.7rem] text-ink-dim">
          <span className="w-6 shrink-0">{label}</span>
          <div className="seg min-w-0 flex-1">
            {EXP_KINDS.map((k) => (
              <button key={k} className="min-w-0 flex-1 !px-1" aria-selected={v === k} onClick={() => set(k)}>
                {EXP_LABEL[k]}
              </button>
            ))}
          </div>
        </div>
      ))}
      <button className="btn btn-blue btn-sm w-full" disabled={from === to || amount < 3} onClick={() => mutate((st) => void convertExp(st, from, to, amount))}>
        {EXP_LABEL[from]} {amount} → {EXP_LABEL[to]} {Math.floor(amount * CONVERT_RATE)}
      </button>
    </div>
  )
}

/** 練習の予定（おまかせのときに順に回す練習）と、育成のしかた */
function TrainTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const c = state.career!
  const p = state.players[c.playerId]
  const gk = p.pos === 'GK'
  const easy = c.growthMode === 'easy'
  const plan = trainPlanOf(state)
  const menus = TRAIN_MENUS.filter((m) => (gk ? m.gk || SHARED_MENUS.includes(m.id) : !m.gk))
  const toggle = (id: TrainMenu) =>
    mutate((st) => {
      const cur = trainPlanOf(st)
      const next = cur.includes(id) ? cur.filter((x) => x !== id) : [...cur, id].slice(-3)
      st.career!.trainPlan = next.length ? next : undefined
    })
  const focus = (Object.entries(c.focus ?? {}) as [AttrKey, number][]).sort((a, b) => b[1] - a[1]).slice(0, 6)
  const gdef = GROWTH_DEFS[p.growth]
  const mul = expMul(state)
  const maxF = Math.max(1, ...focus.map(([, v]) => v))
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[38%] shrink-0 space-y-2 p-2.5">
        <div className="panel-head">成長タイプ</div>
        <div className="rounded-lg bg-white/[0.04] px-2.5 py-1.5 text-[0.74rem]">
          <span className="font-black text-gold">{gdef.name}</span>
          <span className="ml-1.5 text-ink-dim">ピーク {gdef.peak}</span>
          <div className="text-[0.72rem] text-ink-dim">
            いまの経験点の入り方 <b className={mul >= 1.3 ? 'text-good' : mul < 0.9 ? 'text-bad' : 'text-ink'}>×{mul.toFixed(2)}</b>（ピーク年齢のタイプと年齢で変わる）
          </div>
        </div>
        <div className="panel-head pt-1">育成のしかた</div>
        <div className="seg">
          <button aria-selected={easy} onClick={() => mutate((st) => void (st.career!.growthMode = 'easy'))}>
            かんたん
          </button>
          <button aria-selected={!easy} onClick={() => mutate((st) => void (st.career!.growthMode = 'normal'))}>
            じっくり
          </button>
        </div>
        <p className="text-[0.72rem] leading-snug text-ink-dim">
          {easy ? '練習した能力が、毎週と試合のあとに自動で上がります。プレースタイルの特殊能力とコツのある特殊能力も、経験点がたまると自動で覚えます。手で上げることもできます。' : '入った経験点を、自分で能力や特殊能力に振ります。'}
        </p>
        <ConvertBox state={state} />
        <div className="panel-head pt-1">いま鍛えている能力</div>
        {focus.length === 0 && <div className="text-[0.76rem] text-ink-mute">練習すると、ここに出ます</div>}
        {focus.map(([k, v]) => (
          <div key={k} className="flex items-center gap-2">
            <span className="w-[4.6rem] shrink-0 truncate text-[0.78rem]">{ATTR_BY_KEY[k].name}</span>
            <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-black/40">
              <div className="h-full rounded-full bg-accent" style={{ width: `${(v / maxF) * 100}%` }} />
            </div>
          </div>
        ))}
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-1 p-2.5">
        <div className="panel-head">おまかせの練習（3 つまで。週ごとに順に回す）</div>
        {menus.map((m) => {
          const i = plan.indexOf(m.id)
          return (
            <button key={m.id} onClick={() => toggle(m.id)} className={`flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left ${i >= 0 ? 'bg-gold/15 ring-1 ring-gold/50' : 'bg-white/[0.04]'}`}>
              <span className={`num flex h-5 w-5 shrink-0 items-center justify-center rounded-full text-[0.72rem] font-black ${i >= 0 ? 'bg-gold text-black' : 'bg-white/10 text-ink-mute'}`}>{i >= 0 ? i + 1 : ''}</span>
              <span className="min-w-0 flex-1">
                <span className="block text-[0.8rem] font-bold">{m.name}</span>
                <span className="block truncate text-[0.7rem] text-ink-dim">上がりやすい: {m.attrs.map((a) => ATTR_BY_KEY[a].name).join('・')}</span>
              </span>
              <span className="shrink-0 text-[0.7rem] text-ink-dim">体力 -{TRAIN_MENU_BY_ID[m.id].stamina}</span>
            </button>
          )
        })}
        <p className="pt-1 text-[0.72rem] text-ink-mute">過ごし方を選ばなかった週は、ここで選んだ練習を順にします（疲れていれば休み、月に 1 回はおでかけ）。</p>
      </div>
    </div>
  )
}

export function GrowthScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const [tab, setTab] = useState<'attr' | 'skill' | 'train' | 'curve'>((useCurrentScreen().params?.tab as 'attr' | 'skill' | 'train' | 'curve' | undefined) ?? 'attr')
  const c = state.career!
  const p = state.players[c.playerId]
  const gk = p.pos === 'GK'
  const groups = GROUPS.filter(([g]) => (gk ? g === 'gk' || g === 'body' || g === 'mind' : g !== 'gk'))
  const owned = SKILLS.filter((s) => p.skills.includes(s.id))
  const learnable = SKILLS.filter((s) => s.tier !== 'red' && !p.skills.includes(s.id)).sort((a, b) => Number(skillLearnable(state, b)) - Number(skillLearnable(state, a)) || (c.kotsu[b.id] ?? 0) - (c.kotsu[a.id] ?? 0))
  // 横が狭い（iPad・画面を大きくしたとき・小さいウィンドウ）ときは、タブを 2 段目に
  const narrow = useStageRem() < 62
  return (
    <AppShell title="育成" current="growth" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className={`flex shrink-0 gap-2 ${narrow ? 'flex-col' : 'items-center'}`}>
          <div className="flex min-w-0 flex-1 items-center gap-2">
            <OvrBadge value={ovr(p)} />
            <div className="grid min-w-[19rem] flex-1 grid-cols-5 gap-1.5">
              {EXP_KINDS.map((k) => (
                <div key={k} className="min-w-0 rounded-lg bg-black/30 px-1 py-0.5 text-center">
                  <div className="whitespace-nowrap text-[0.68rem] text-ink-dim">{EXP_LABEL[k]}</div>
                  <div className="num whitespace-nowrap text-[0.95rem] font-black text-gold">{Math.floor(c.exp[k])}</div>
                </div>
              ))}
            </div>
          </div>
          <div className="flex min-w-0 shrink items-center gap-2">
          <div className="seg scroll-x min-w-0">
            <button aria-selected={tab === 'attr'} onClick={() => setTab('attr')}>
              能力
            </button>
            <button aria-selected={tab === 'skill'} onClick={() => setTab('skill')}>
              特殊能力
            </button>
            <button aria-selected={tab === 'train'} onClick={() => setTab('train')}>
              練習の予定
            </button>
            <button aria-selected={tab === 'curve'} onClick={() => setTab('curve')}>
              見込み
            </button>
          </div>
          <button className="btn btn-ghost btn-sm shrink-0" onClick={() => mutate((st) => autoSpendForPosition(st))}>
            おまかせ
          </button>
          </div>
        </div>
        {tab === 'curve' ? (
          <CurveTab state={state} />
        ) : tab === 'train' ? (
          <TrainTab state={state} />
        ) : tab === 'attr' ? (
          <div className="panel scroll-y min-h-0 flex-1 p-2.5">
            <div className="grid grid-cols-2 gap-x-5">
              {groups.map(([g, label]) => (
                <div key={g} className="mb-2">
                  <div className="panel-head mb-0.5">{label}</div>
                  {ATTRS.filter((a) => a.group === g).map((a) => (
                    <AttrRow key={a.key} state={state} k={a.key} />
                  ))}
                </div>
              ))}
            </div>
            <p className="mt-1 text-[0.72rem] text-ink-mute">能力が高いほど、1 上げるのに経験点が多く要ります。経験点は練習・試合・出来事で入り、若いほど多く入ります。</p>
          </div>
        ) : (
          <div className="flex min-h-0 flex-1 gap-3">
            <div className="panel scroll-y w-[30%] shrink-0 p-2.5">
              <div className="panel-head mb-1">持っている特殊能力（{owned.length}/6）</div>
              {owned.length === 0 && <div className="text-[0.78rem] text-ink-dim">まだありません</div>}
              {owned.map((s) => (
                <div key={s.id} className="mb-1 rounded-lg bg-gold/10 px-2 py-1">
                  <div className="text-[0.78rem] font-bold text-gold">{s.name}</div>
                  <div className="text-[0.7rem] text-ink-dim">{s.desc}</div>
                </div>
              ))}
              <p className="mt-2 text-[0.72rem] text-ink-mute">「コツ」は出来事や師匠から教わると付きます。コツがあると安く覚えられ、能力が足りなくても覚えられます。6 個までで、覚えると古いものから入れ替わります。</p>
            </div>
            <div className="panel scroll-y min-w-0 flex-1 space-y-1 p-2.5">
              {learnable.map((s) => (
                <SkillRow key={s.id} state={state} s={s} />
              ))}
            </div>
          </div>
        )}
      </div>
    </AppShell>
  )
}
