/**
 * 選手との面談（M19。クラブモードの自クラブ）。選手ごとに 4 週に 1 回。性格で効き方と返事が変わる。
 *   期待を伝える・不満を聞く（移籍の志願を取り下げることがある）・役割を伝える（主力・控え・育成）・もっとやれる（叱咤激励）
 * 全体ミーティングは 4 週に 1 回、全員のやる気が少し上がる。
 * 乱数は使わない（性格と状況で決まる）。
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { PERSONALITY_DEFS, type Personality } from '../data/personality'
import type { GameState } from '../models/game'
import type { Player } from '../models/player'
import { ovr } from '../player/overall'

export type MeetingKind = 'praise' | 'listen' | 'role' | 'push'
export type MeetingRole = 'main' | 'rotation' | 'develop'

export const MEETINGS: { id: MeetingKind; name: string; desc: string }[] = [
  { id: 'praise', name: '期待を伝える', desc: 'やる気が上がる。先発の選手ほどよく効く' },
  { id: 'listen', name: '不満を聞く', desc: '移籍の志願を取り下げることがある' },
  { id: 'role', name: '役割を伝える', desc: '主力・控え・育成。立場に合っていれば効く' },
  { id: 'push', name: 'もっとやれるはずだ', desc: '叱咤激励。熱い選手には効き、繊細な選手は落ち込む' },
]

export const MEETING_ROLES: { id: MeetingRole; name: string }[] = [
  { id: 'main', name: '主力として期待している' },
  { id: 'rotation', name: '控えから力を貸してほしい' },
  { id: 'develop', name: 'じっくり育てたい' },
]

export const MEETING_GAP = 4

const clamp = (v: number, lo: number, hi: number) => Math.max(lo, Math.min(hi, v))
const now = (state: GameState) => absWeekOf(state.season, state.week)
const ageOf = (state: GameState, p: Player) => (now(state) - p.birthAbsWeek) / WEEKS_PER_SEASON

/** あと何週で面談できるか（0 ならいま） */
export function meetingWait(state: GameState, p: Player): number {
  return p.lastMeeting === undefined ? 0 : Math.max(0, p.lastMeeting + MEETING_GAP - now(state))
}

/** 性格ごとの返事 */
