export interface MeetingResult {
  morale: number
  line: string
  /** 移籍の志願を取り下げた */
  withdrew?: boolean
}

/** 面談をする（効き目を返す） */
export function holdMeeting(state: GameState, playerId: number, kind: MeetingKind, role?: MeetingRole): MeetingResult | null {
  const p = state.players[playerId]
  const me = state.clubs[state.playerClubId]
  if (!p || p.clubId !== me.id || meetingWait(state, p) > 0) return null
  const def = PERSONALITY_DEFS[p.personality]
  const starter = me.lineup.starters.includes(p.id)
  const age = ageOf(state, p)
  // チームの中の立場（11 番目の総合と比べる）
  const level = Object.values(state.players).filter((x) => x.clubId === me.id && !x.retired).map(ovr).sort((a, b) => b - a)[10] ?? 50
  const good = ovr(p) >= level - 2
  let d: number
  let withdrew = false
  if (kind === 'praise') {
    d = (starter ? 8 : 5) * (p.personality === 'cool' ? 0.6 : p.personality === 'hot' || p.personality === 'leader' || p.personality === 'mood' ? 1.25 : 1)
    if (p.morale > 85) d = Math.min(d, 2)
  } else if (kind === 'listen') {
    const req = state.offers.find((o) => o.kind === 'request' && o.playerId === p.id && !o.abroad)
    if (req) {
      // 出場機会を求める志願: 先発でなければ半々（性格で）、先発なら取り下げる
      const keep = starter || p.personality === 'shy' || p.personality === 'mood' || p.personality === 'leader'
      if (keep) {
        state.offers = state.offers.filter((o) => o !== req)
        withdrew = true
        d = 10
      } else d = 4
    } else d = good && !starter ? 3 : 4
  } else if (kind === 'role') {
    if (role === 'main') d = starter ? 7 : good ? 3 : -3
    else if (role === 'rotation') d = starter ? -5 : good ? 1 : 4
    else d = age <= 21 ? 6 : age <= 24 ? 1 : -6
    if (p.personality === 'hot' && d > 0) d += 2
  } else {
    const k: Partial<Record<Personality, number>> = { hot: 9, effort: 8, leader: 6, genius: 4, mood: 3, cool: 2, mypace: -2, shy: -8 }
    d = k[p.personality] ?? 3
    if (d > 0) p.condition = clamp(p.condition + 4, 0, 100)
  }
  d = Math.round(d * def.moraleVar)
  p.morale = clamp(p.morale + d, 0, 100)
  p.lastMeeting = now(state)
  const r = REPLY[kind][p.personality] ?? REPLY[kind].default
  return { morale: d, line: withdrew ? '……わかりました。もう少し、このクラブでがんばってみます。' : d > 0 ? r[0] : r[1], withdrew }
}

/** 全体ミーティング（4 週に 1 回）: 全員のやる気が少し上がる */
export function teamMeetingWait(state: GameState): number {
  const last = state.clubs[state.playerClubId].lastTeamMeeting
  return last === undefined ? 0 : Math.max(0, last + MEETING_GAP - now(state))
}

export function holdTeamMeeting(state: GameState): number {
  const me = state.clubs[state.playerClubId]
  if (teamMeetingWait(state) > 0) return 0
  let n = 0
  for (const p of Object.values(state.players)) {
    if (p.clubId !== me.id || p.retired) continue
    p.morale = clamp(p.morale + 3 * PERSONALITY_DEFS[p.personality].moraleVar, 0, 100)
    n++
  }
  me.lastTeamMeeting = now(state)
  return n
}
