/**
 * キャリアからクラブモードへの書き出し（「レジェンド」）。
 *   引退した主人公 → クラブモードの監督・コーチの候補（総括のランクで能力が決まる）
 *   現役のうちに書き出した主人公 → フリーの選手（そのときの能力のまま）
 * 書き出したデータは端末に残し（画面の側で保存）、クラブモードのスタッフ画面から呼べる。
 */
import { WEEKS_PER_SEASON } from '../core/calendar'
import { createRng, hashString } from '../core/prng'
import type { Attrs } from '../data/attributes'
import type { Position } from '../data/positions'
import type { Nation } from '../data/nations'
import { generatePlayer } from '../gen/playerGen'
import { generateStaff } from '../gen/staffGen'
import type { FaceSpec } from '../models/face'
import type { Foot } from '../models/player'
import type { StaffRole } from '../models/staff'
import type { GameState } from '../models/game'
import { ovr, fairWage } from '../player/overall'
import { careerAge } from './core'
import { careerSummary } from './retire'

export interface Legend {
  /** 書き出しごとの id（同じ人を 2 回入れないため） */
  key: string
  name: string
  short: string
  nation: Nation
  pos: Position
  foot: Foot
  heightCm: number
  weightKg?: number
  face?: FaceSpec
  attr: Attrs
  skills: string[]
  /** 書き出したときの年齢 */
  age: number
  retired: boolean
  grade: string
  ovr: number
  /** 通算（表示用） */
  apps: number
  goals: number
  titles: number
}

export function legendFromCareer(state: GameState, key: string): Legend {
  const c = state.career!
  const p = state.players[c.playerId]
  const sum = c.summary ?? careerSummary(state)
  return {
    key,
    name: p.name,
    short: p.short,
    nation: p.nation,
    pos: p.pos,
    foot: p.foot,
    heightCm: p.heightCm,
    weightKg: p.weightKg,
    face: p.face,
    attr: { ...p.attr },
    skills: [...p.skills],
    age: careerAge(state),
    retired: !!c.retired,
    grade: sum.grade,
    ovr: sum.peakOvr,
    apps: sum.apps,
    goals: sum.goals,
    titles: sum.titles.length,
  }
}

/** ランクごとの、監督・コーチとしての能力 */
const GRADE_ABILITY: Record<string, number> = { S: 88, A: 80, B: 72, C: 64, D: 56, E: 50, F: 44, G: 38 }

/** このセーブに、もうそのレジェンドがいるか */
export function hasLegend(state: GameState, key: string): boolean {
  return Object.values(state.players).some((p) => p.legend === key) || Object.values(state.staff).some((s) => s.legend === key)
}

/** クラブモードのセーブにレジェンドを加える（引退していれば監督かコーチ、現役ならフリーの選手）。加えたものの種類を返す */
export function addLegend(state: GameState, l: Legend): 'staff' | 'player' | null {
  if (hasLegend(state, l.key)) return null
  const rng = createRng(hashString(l.key))
  const now = state.season * WEEKS_PER_SEASON + state.week
  if (l.retired) {
    const ability = GRADE_ABILITY[l.grade] ?? 50
    const role: StaffRole = ability >= 72 ? 'manager' : l.pos === 'GK' ? 'gkCoach' : 'headCoach'
    const s = generateStaff(state, rng, role, -1, ability, 'JP')
    Object.assign(s, { name: l.name, nation: l.nation, face: l.face, legend: l.key, birthAbsWeek: now - Math.max(l.age + 1, 35) * WEEKS_PER_SEASON })
    state.staff[s.id] = s
    return 'staff'
  }
  const p = generatePlayer(state, rng, { clubId: -1, pos: l.pos, targetOvr: l.ovr, age: l.age, nation: l.nation, country: 'JP', contractYears: -1 })
  Object.assign(p, { name: l.name, short: l.short, foot: l.foot, heightCm: l.heightCm, face: l.face, attr: { ...l.attr }, skills: [...l.skills], legend: l.key })
  for (const k of Object.keys(p.cap) as (keyof Attrs)[]) p.cap[k] = Math.max(p.cap[k], p.attr[k])
  p.contract = { ...p.contract, wage: fairWage(ovr(p), l.age, 'JP') }
  state.players[p.id] = p
  return 'player'
}
