/** キャリアの人間関係: 出会った人・絆・会える場所・出来事の進み具合。今いる地域（日本・海外の国）で会える人を先に出す。 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { BOND_STAGE, CAREER_CAST, CAST_BY_ID, GEN2_ABROAD, GEN2_CAST, DATE_SPOT_BY_ID, OVERSEAS_PLACE_NAMES, OVERSEAS_PLACES, PLACES, REGION_NAME } from '../../engine/data/career'
import { castAge, castName, canMeet, canRomance, placesFor, regionOf } from '../../engine/career/core'
import { nextEventFor } from '../../engine/career/events'
import { relationLabel, roleLabel } from '../../engine/career/family'
import { castPhotoId } from '../components/portraits'
import { ALL_EVENTS } from '../../engine/career/dialogue'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { SideSheet } from '../layout/SideSheet'
import { Portrait } from '../components/Portrait'
import { useGameState } from '../../stores/gameStore'

function Hearts({ value }: { value: number }) {
  const n = Math.min(5, Math.floor(value / 20))
  return (
    <span className="text-[0.76rem] tracking-tight text-[#f472b6]">
      {'♥'.repeat(n)}
      <span className="text-white/15">{'♥'.repeat(5 - n)}</span>
    </span>
  )
}

function stageOf(value: number, relation?: string): string {
  return relation ?? BOND_STAGE[Math.min(5, Math.floor(value / 20))]
}

/** その人との出来事の数（済んだ数 / 全部） */
function eventProgress(state: GameState, id: string): [number, number] {
  const chain = ALL_EVENTS.filter((e) => e.char === id && e.trigger === 'outing' && e.step !== undefined)
  return [chain.filter((e) => state.career!.done[e.id] !== undefined).length, chain.length]
}

/** その人に会える場所（海外の人は、その国での名前。子どもの世代の人は、今のおでかけ先） */
function placesOf(state: GameState, id: string): string[] {
  const cast = CAST_BY_ID[id]
  if (cast?.gen) return placesFor(state).filter((p) => p.people.includes(id)).map((p) => p.name)
  if (cast?.places) {
    const names = cast.region && cast.region !== 'abroad' && cast.region !== 'JP' ? OVERSEAS_PLACE_NAMES[cast.region] : {}
    return cast.places.map((pl) => names[pl] ?? OVERSEAS_PLACES.find((x) => x.id === pl)?.name ?? '')
  }
  return PLACES.filter((p) => p.people.includes(id)).map((p) => p.name)
}

/** その人がいる地域の名前 */
function regionLabel(id: string): string {
  const r = CAST_BY_ID[id]?.region ?? 'JP'
  return r === 'abroad' ? '海外' : REGION_NAME[r]
}

export function PeopleScreen() {
  const state = useGameState()
  const [sel, setSel] = useState<string | null>(null)
  const c = state.career!
  const region = regionOf(state)
  // 今いる地域の人（会ったことがなくても出す）と、ほかの地域で会ったことのある人
  const list = [...CAREER_CAST, ...GEN2_CAST, ...GEN2_ABROAD].filter((x) => x.id !== 'kato_misaki' && x.id !== 'bertrand_renoir' && (canMeet(state, x.id) || c.bonds[x.id]))
  const here = (x: { id: string }) => canMeet(state, x.id)
  const heroines = [...list.filter((x) => x.kind === 'heroine' && here(x)), ...list.filter((x) => x.kind === 'heroine' && !here(x))]
  const others = [...list.filter((x) => x.kind !== 'heroine' && here(x)), ...list.filter((x) => x.kind !== 'heroine' && !here(x))]
  const card = (id: string) => {
    const b = c.bonds[id]
    const met = !!b
    const next = met && canMeet(state, id) && nextEventFor(state, id)
    return (
      <button key={id} className={`flex items-center gap-2 rounded-xl p-2 text-left ${met ? 'bg-white/[0.05]' : 'bg-black/20'}`} onClick={() => met && setSel(id)} disabled={!met}>
        {met ? <Portrait id={castPhotoId(id, c.spouse)} kind="face" className="face-round h-11 w-11 shrink-0" /> : <span className="face-round flex h-11 w-11 shrink-0 items-center justify-center bg-white/5 text-[1.2rem] font-black text-ink-mute">？</span>}
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-1.5">
            <span className="truncate text-[0.85rem] font-black">{met ? castName(state, id) : '？？？'}</span>
            {relationLabel(state, id) && <span className="shrink-0 rounded bg-[#f472b6]/25 px-1 text-[0.66rem] font-black text-[#f9a8d4]">{relationLabel(state, id)}</span>}
          </span>
          <span className="block truncate text-[0.7rem] text-ink-dim">{met ? `${roleLabel(state, id)}・${castAge(state, id)} 歳${canMeet(state, id) ? '' : `（${regionLabel(id)}にいる）`}` : `${placesOf(state, id).slice(0, 2).join('・')}で会えるかも`}</span>
          {met && (
            <span className="flex items-center gap-1.5">
              <Hearts value={b.value} />
              <span className="text-[0.68rem] text-ink-dim">{stageOf(b.value, relationLabel(state, id))}</span>
              {next && <span className="rounded bg-accent/20 px-1 text-[0.66rem] font-bold text-accent">何か起きそう</span>}
            </span>
          )}
        </span>
      </button>
    )
  }
  const s = sel ? CAST_BY_ID[sel] : undefined
  const sb = sel ? c.bonds[sel] : undefined
  return (
    <AppShell title="人間関係" current="people" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="panel scroll-y min-w-0 flex-1 p-2.5">
          <div className="panel-head mb-1.5">出会い{region !== 'JP' && <span className="ml-2 text-[0.72rem] font-normal text-ink-dim">いまは{REGION_NAME[region]}で暮らしています</span>}</div>
          <div className="grid grid-cols-2 gap-1.5">{heroines.map((x) => card(x.id))}</div>
        </div>
        <div className="panel scroll-y w-[38%] shrink-0 p-2.5">
          <div className="panel-head mb-1.5">仲間・師匠・ライバル</div>
          <div className="grid gap-1.5">{others.map((x) => card(x.id))}</div>
          <p className="mt-2 text-[0.72rem] text-ink-mute">おでかけで人に会うと絆が深まり、出来事が進みます。会える場所は人によって違います。</p>
        </div>
      </div>
      <SideSheet open={!!sel} onClose={() => setSel(null)} title={sel ? castName(state, sel) : ''} width="62%">
        {s && sb && sel && (
          <div className="flex h-full gap-3 p-3">
            <Portrait id={castPhotoId(sel, c.spouse)} kind={s.portrait === 'bust' ? 'bust' : 'photo'} className="h-full max-h-[22rem] w-[42%] shrink-0 rounded-xl" position="50% 15%" />
            <div className="min-w-0 flex-1 space-y-2 text-[0.8rem]">
              <div>
                <div className="text-[1.05rem] font-black">{castName(state, sel!)}</div>
                <div className="text-[0.78rem] text-ink-dim">
                  {roleLabel(state, sel)}・{castAge(state, sel)} 歳
                </div>
              </div>
              <div className="flex items-center gap-2">
                <Hearts value={sb.value} />
                <span className="font-bold">{stageOf(sb.value, relationLabel(state, sel))}</span>
                <span className="num text-[0.76rem] text-ink-dim">（{Math.round(sb.value)}）</span>
              </div>
              <div>
                <span className="text-ink-dim">会える場所: </span>
                {canMeet(state, sel) ? placesOf(state, sel).join('・') || 'ふとしたときに' : `${regionLabel(sel)}にいるので、いまは会えません`}
              </div>
              {(sb.dates ?? 0) > 0 && (
                <div>
                  <span className="text-ink-dim">デート: </span>
                  {sb.dates} 回
                  {(sb.dates ?? 0) >= 2 && s.likes && <span className="ml-1 text-[0.78rem] text-pink">（好きな行き先: {s.likes.map((x) => DATE_SPOT_BY_ID[x].name).join('・')}）</span>}
                </div>
              )}
              {(() => {
                const [done, total] = eventProgress(state, sel)
                return total > 0 ? (
                  <div>
                    <span className="text-ink-dim">出来事: </span>
                    {done} / {total}
                    {canMeet(state, sel) && nextEventFor(state, sel) ? <span className="ml-1 font-bold text-accent">（次の出来事がありそう）</span> : done < total ? <span className="ml-1 text-ink-mute">（もう少し仲良くなると…）</span> : <span className="ml-1 text-gold">（すべて見た）</span>}
                  </div>
                ) : null
              })()}
              {s.kind === 'heroine' && !canRomance(state, sel) && <div className="text-[0.76rem] text-ink-mute">頼れる相談相手です。</div>}
            </div>
          </div>
        )}
      </SideSheet>
    </AppShell>
  )
}
