/** 選手一覧。並べ替えとポジション別の絞り込み。 */
import { useMemo, useState } from 'react'
import { ageOf, currentAbsWeek, gkSummaryOf, ovr, playerClub, POSITION_DEFS, POSITIONS, squadOf, summaryOf, SUMMARY_KEYS, SUMMARY_LABEL, type Player } from '../../engine'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { ConditionArrow, Flag, OvrBadge, PosBadge } from '../components/common'
import { PlayerFace } from '../components/PersonFace'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { attrColor, formatMoneyShort } from '../format'
import { useStageWide } from '../stage/useStage'
import { ChemistryTab, ContractTab, YouthTab } from '../squad/SquadExtras'
import { expiringPlayers } from '../../engine/transfer/contracts'
import { TeamMeetingButton } from '../club/TeamMeetingButton'
import { useScreenState, useScrollMemo } from '../hooks/useScreenState'
import { ReleaseSheet, RosterChip } from '../squad/ReleaseSheet'

type Line = 'ALL' | 'GK' | 'DF' | 'MF' | 'FW'
type Sort = 'pos' | 'ovr' | 'age' | 'cond'

export function SquadScreen() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const me = playerClub(state)
  // 選手の詳細から戻ったときは、表示・並び・スクロールを元のまま
  const [line, setLine] = useScreenState<Line>('line', 'ALL')
  const [sort, setSort] = useScreenState<Sort>('sort', 'pos')
  const listScroll = useScrollMemo('list')
  const screenParams = useCurrentScreen().params
  const [view, setView] = useScreenState<'top' | 'youth' | 'contract' | 'chem'>('view', 'top', screenParams?.view as 'top' | 'youth' | 'contract' | 'chem' | undefined)
  const now = currentAbsWeek(state)
  const wide = useStageWide(760)
  // 選手の整理（M22）。ホームの知らせなどから ?release=1 で開く
  const [release, setRelease] = useState(() => !!screenParams?.release)

  const players = useMemo(() => {
    const list = squadOf(state, me.id).filter((p) => line === 'ALL' || POSITION_DEFS[p.pos].line === line)
    const posIdx = (p: Player) => POSITIONS.indexOf(p.pos)
    const cmp: Record<Sort, (a: Player, b: Player) => number> = {
      pos: (a, b) => posIdx(a) - posIdx(b) || ovr(b) - ovr(a),
      ovr: (a, b) => ovr(b) - ovr(a),
      age: (a, b) => ageOf(a, now) - ageOf(b, now),
      cond: (a, b) => b.condition - a.condition,
    }
    return list.sort(cmp[sort])
  }, [state, me.id, line, sort, now])

  const starters = new Set(me.lineup.starters)

  return (
    <AppShell title={state.career ? `所属クラブ・${me.name}` : `選手（${squadOf(state, me.id).length}人）`} current="squad" right={<>{!state.career && <RosterChip state={state} onClick={() => setRelease(true)} />}{!state.career && <TeamMeetingButton state={state} />}<GameTopInfo /></>}>
      <div className="absolute inset-0 flex flex-col">
        <div className="flex shrink-0 items-center gap-2 px-3 pt-2">
          <div className={`seg ${state.career ? 'hidden' : ''}`}>
            {(
              [
                ['top', 'トップ'],
                ['youth', 'ユース'],
                ['contract', `契約${expiringPlayers(state).length ? `（${expiringPlayers(state).length}）` : ''}`],
                ['chem', '連携'],
              ] as ['top' | 'youth' | 'contract' | 'chem', string][]
            ).map(([k, label]) => (
              <button key={k} aria-selected={view === k} onClick={() => setView(k)}>
                {label}
              </button>
            ))}
          </div>
          {view === 'youth' && (
            <button className="btn btn-gold btn-sm ml-auto" onClick={() => push({ id: 'youth', params: { tab: 'academy' } })}>
              海外アカデミー・国際ユースカップ →
            </button>
          )}
          {view === 'top' && (
          <div className="seg">
            {(['ALL', 'GK', 'DF', 'MF', 'FW'] as Line[]).map((l) => (
              <button key={l} aria-selected={line === l} onClick={() => setLine(l)}>
                {l === 'ALL' ? '全' : l}
              </button>
            ))}
          </div>
          )}
          {view === 'top' && (
          <div className="seg ml-auto">
            {(
              [
                ['pos', 'ポジション'],
                ['ovr', '総合'],
                ['age', '年齢'],
                ['cond', '調子'],
              ] as [Sort, string][]
            ).map(([k, label]) => (
              <button key={k} aria-selected={sort === k} onClick={() => setSort(k)}>
                {label}
              </button>
            ))}
          </div>
          )}
        </div>
        {view === 'youth' && <YouthTab />}
        {view === 'contract' && <ContractTab />}
        {view === 'chem' && <ChemistryTab />}
        {view === 'top' && (
        <>
        <div className="flex shrink-0 items-center gap-2 px-3 pb-1 pt-2 text-[0.72rem] font-bold text-ink-mute">
          <span className="w-6 text-center">#</span>
          <span className="w-[2.1rem]">位置</span>
          <span className="w-9" />
          <span className="min-w-0 flex-1">名前</span>
          <span className="w-7 text-center">年齢</span>
          <span className="w-9 text-center">総合</span>
          <span className="w-5 text-center">調</span>
          {wide &&
            SUMMARY_KEYS.map((k) => (
              <span key={k} className="w-7 text-center">
                {SUMMARY_LABEL[k]}
              </span>
            ))}
          <span className="w-[3.6rem] text-right">年俸</span>
        </div>
        <div ref={listScroll} className="scroll-y min-h-0 flex-1 px-3 pb-3">
          {players.map((p) => {
            const sum = p.pos === 'GK' ? gkSummaryOf(p.attr) : summaryOf(p.attr)
            return (
              <button key={p.id} onClick={() => push({ id: 'player', params: { id: p.id } })} className="mb-1 flex w-full items-center gap-2 rounded-lg bg-white/[0.04] px-0 py-1 text-left hover:bg-white/[0.08]">
                <span className="num w-6 text-center text-[0.8rem] font-bold text-ink-dim">{p.number}</span>
                <PosBadge pos={p.pos} />
                <PlayerFace p={p} kit={me.colors} className="h-9 w-9 shrink-0" />
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-1.5">
                    <span className="truncate text-[0.88rem] font-bold">{p.name}</span>
                    <Flag nation={p.nation} />
                    {starters.has(p.id) && <span className="rounded bg-good/20 px-1 text-[0.68rem] font-bold text-good">先発</span>}
                    {p.injury && <span className="rounded bg-bad/20 px-1 text-[0.68rem] font-bold text-bad">負傷</span>}
                    {p.suspension > 0 && <span className="rounded bg-warn/20 px-1 text-[0.68rem] font-bold text-warn">停止</span>}
                    {p.contract.until <= state.season && <span className="rounded bg-accent/20 px-1 text-[0.68rem] font-bold text-accent">満了</span>}
                    {p.id in state.forSale && <span className="rounded bg-white/15 px-1 text-[0.68rem] font-bold">売出</span>}
                  </span>
                </span>
                <span className="num w-7 text-center text-[0.82rem]">{ageOf(p, now)}</span>
                <span className="flex w-9 justify-center">
                  <OvrBadge value={ovr(p)} size="sm" />
                </span>
                <span className="flex w-5 justify-center">
                  <ConditionArrow value={p.condition} />
                </span>
                {wide &&
                  SUMMARY_KEYS.map((k) => (
                    <span key={k} className="num w-7 text-center text-[0.8rem] font-bold" style={{ color: attrColor(sum[k]) }}>
                      {sum[k]}
                    </span>
                  ))}
                <span className="num w-[3.6rem] text-right text-[0.75rem] text-ink-dim">{formatMoneyShort(p.contract.wage)}</span>
              </button>
            )
          })}
        </div>
        </>
        )}
      </div>
      {!state.career && <ReleaseSheet key={String(release)} open={release} onClose={() => setRelease(false)} />}
    </AppShell>
  )
}
