/**
 * 成長の見込み（予想成長曲線）: 成長タイプごとの基準の曲線（data/growthRef.generated.ts。tools/growthref.ts でキャリアを
 * 自動で回して作る）を、今の年齢と OVR から先へ伸ばす。練習・出場・投資で実際は変わるので、目安として幅をつける。
 */
import { absWeekOf, WEEKS_PER_SEASON } from '../core/calendar'
import { GROWTH_REF, GROWTH_REF_AGES, GROWTH_REF_START } from '../data/growthRef.generated'
import type { GrowthType } from '../data/growth'
import type { GameState } from '../models/game'
import { ovr } from '../player/overall'

export const PROJ_MIN_AGE = 18
export const PROJ_MAX_AGE = 40

export interface ProjPoint {
  age: number
  ovr: number
  /** 見込みの幅（先の年齢だけ） */
  lo?: number
  hi?: number
}

export interface Projection {
  /** これまで（シーズンの終わりごと） */
  past: ProjPoint[]
  now: ProjPoint
  /** これから（年齢ごと） */
  future: ProjPoint[]
  peak: ProjPoint
}

/** 基準の曲線の値（18 歳との差）。年齢のあいだは直線でつなぎ、38 歳より先は最後の傾きで伸ばす */
export function refAt(type: GrowthType, age: number): number {
  const ref = GROWTH_REF[type]
  const first = GROWTH_REF_AGES[0]
  const last = GROWTH_REF_AGES[GROWTH_REF_AGES.length - 1]
  if (age <= first) return ref[0]
  if (age >= last) return ref[ref.length - 1] + (ref[ref.length - 1] - ref[ref.length - 2]) * (age - last)
  const i = Math.floor(age - first)
  const t = age - first - i
  return ref[i] + (ref[i + 1] - ref[i]) * t
}

const clampOvr = (v: number) => Math.max(30, Math.min(99, v))

/** 主人公の見込み */
export function projectGrowth(state: GameState): Projection {
  const c = state.career!
  const p = state.players[c.playerId]
  const ageAtAbs = (abs: number) => (abs - p.birthAbsWeek) / WEEKS_PER_SEASON
  const age = ageAtAbs(absWeekOf(state.season, state.week))
  const cur = ovr(p)
  const past = c.log.map((l) => ({ age: Math.round(ageAtAbs(absWeekOf(l.season, WEEKS_PER_SEASON - 1)) * 10) / 10, ovr: l.ovr }))
  const now = { age: Math.round(age * 10) / 10, ovr: cur }
  const future: ProjPoint[] = []
  for (let a = Math.floor(age) + 1; a <= PROJ_MAX_AGE; a++) {
    const v = clampOvr(Math.round(cur + refAt(p.growth, a) - refAt(p.growth, age)))
    const spread = Math.min(6, 1 + 0.6 * (a - age))
    future.push({ age: a, ovr: v, lo: clampOvr(Math.round(v - spread)), hi: clampOvr(Math.round(v + spread)) })
  }
  const peak = [now, ...future].reduce((m, x) => (x.ovr > m.ovr ? x : m), now)
  return { past, now, future, peak }
}

/** 作成画面用: 18 歳の OVR から、そのタイプの基準の曲線 */
export function typeCurve(type: GrowthType, start = GROWTH_REF_START): ProjPoint[] {
  const out: ProjPoint[] = []
  for (let a = PROJ_MIN_AGE; a <= PROJ_MAX_AGE; a++) out.push({ age: a, ovr: clampOvr(Math.round(start + refAt(type, a))) })
  return out
}
