/**
 * 海外アカデミー（M25）: 左は開いているアカデミーと開ける国、右は選んだ国のくわしい情報（開校・拡大・方針・閉校・ここから来た子）。
 */
import { useState } from 'react'
import { currentAbsWeek, ovr, playerClub, type GameState } from '../../engine'
import {
  ACADEMY_REFUND,
  ACADEMY_UPGRADE_WEEKS,
  academyIntakeCount,
  academyOpen,
  academyRunCost,
  academySlots,
  academyUpgradeCost,
  academiesOf,
  canOpenAcademy,
  canUpgradeAcademy,
  closeAcademy,
  findAcademy,
  openAcademy,
  setAcademyPolicy,
  upgradeAcademy,
} from '../../engine/club/academy'
import { ACADEMY_DEFS, ACADEMY_MAX_LEVEL, ACADEMY_OPEN_WEEKS, ACADEMY_POLICY_DESC, ACADEMY_POLICY_LABEL, ACADEMY_RUN_MUL, type AcademyNationDef, type AcademyPolicy } from '../../engine/data/academies'
import { ATTR_BY_KEY } from '../../engine/data/attributes'
import { NATION_NAME, type Nation } from '../../engine/data/nations'
import type { Academy } from '../../engine/models/club'
import { Flag, OvrBadge, PosBadge } from '../components/common'
import { ConfirmDialog } from '../components/ConfirmDialog'
import { PlayerFace } from '../components/PersonFace'
import { useGame } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { useScreenState } from '../hooks/useScreenState'
import { formatMoney, formatMoneyShort } from '../format'

function LvBar({ v, max = ACADEMY_MAX_LEVEL }: { v: number; max?: number }) {
  return (
    <span className="inline-flex gap-0.5">
      {Array.from({ length: max }, (_, i) => (
        <span key={i} className={`h-2 w-3 rounded-sm ${i < v ? 'bg-gold' : 'bg-white/10'}`} />
      ))}
    </span>
  )
}

function statusOf(state: GameState, a: Academy): { label: string; cls: string } {
  const now = currentAbsWeek(state)
  if (!academyOpen(state, a)) return { label: `開校の準備 あと ${a.openAbsWeek - now} 週`, cls: 'bg-accent/20 text-accent' }
  if (a.pending) return { label: `Lv${a.pending.level} へ工事 あと ${a.pending.doneAbsWeek - now} 週`, cls: 'bg-accent/20 text-accent' }
  return { label: '稼働中', cls: 'bg-good/20 text-good' }
}

const quality = (d: AcademyNationDef) => (d.quality >= 3 ? 'とても高い' : d.quality >= 1 ? '高い' : d.quality >= 0 ? 'ふつう' : '低め')
const gems = (d: AcademyNationDef) => (d.spread >= 8 ? '多い（当たり外れが大きい）' : d.spread >= 6 ? 'ふつう' : '少ない（安定）')

export function AcademyTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const own = academiesOf(me)
  const [sel, setSel] = useScreenState<Nation>('academy', own[0]?.nation ?? 'BR')
  const slots = academySlots(me)
  const yearCost = own.filter((a) => academyOpen(state, a)).reduce((s, a) => s + academyRunCost(a), 0)
  const produced = own.reduce((s, a) => s + a.produced, 0)
  const next = own.filter((a) => academyOpen(state, a)).reduce((s, a) => s + academyIntakeCount(a), 0)
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[44%] shrink-0 p-3">
        <div className="panel-head">海外アカデミー</div>
        <div className="mt-1.5 grid grid-cols-2 gap-x-3 gap-y-1 text-[0.78rem]">
          <span className="text-ink-dim">枠</span>
          <span className="num text-right font-bold">
            {slots.used} / {slots.slots}
          </span>
          <span className="text-ink-dim">年間の運営費</span>
          <span className="num text-right font-bold">{formatMoneyShort(yearCost)}</span>
          <span className="text-ink-dim">シーズン末に入る子</span>
          <span className="num text-right font-bold">{next} 人</span>
          <span className="text-ink-dim">これまでに入った子</span>
          <span className="num text-right font-bold">{produced} 人</span>
        </div>
        <div className="mt-1 text-[0.68rem] text-ink-mute">
          {slots.slots === 0 ? 'クラブの格 50 から開けます。' : slots.nextRep ? `クラブの格 ${slots.nextRep} で枠が 1 つ増えます。` : ''}
          {slots.world ? 'ワールドリーグに所属しているので枠 +1。' : 'ワールドリーグに上がると枠 +1。'}
        </div>
        {own.length > 0 && (
          <div className="mt-2.5 space-y-1.5">
            {own.map((a) => {
              const d = ACADEMY_DEFS.find((x) => x.nation === a.nation)!
              const st = statusOf(state, a)
              return (
                <button key={a.nation} className={`flex w-full items-center gap-2 rounded-lg px-2 py-1.5 text-left ${sel === a.nation ? 'bg-gold/15 ring-1 ring-gold/50' : 'bg-black/25'}`} onClick={() => setSel(a.nation)}>
                  <Flag nation={a.nation} className="h-[1.1rem] w-[1.65rem] shrink-0" />
                  <span className="min-w-0 flex-1">
                    <span className="flex items-center gap-1.5">
                      <span className="truncate text-[0.82rem] font-black">{d.city}校</span>
                      <LvBar v={a.level} />
                    </span>
                    <span className="flex items-center gap-1.5 text-[0.68rem]">
                      <span className={`rounded px-1 font-bold ${st.cls}`}>{st.label}</span>
                      <span className="text-ink-dim">{ACADEMY_POLICY_LABEL[a.policy]}・毎季 {academyIntakeCount(a)} 人</span>
                    </span>
                  </span>
                </button>
              )
            })}
          </div>
        )}
        <div className="mt-3 text-[0.72rem] font-bold text-ink-dim">開ける国</div>
        <div className="mt-1 grid grid-cols-3 gap-1">
          {ACADEMY_DEFS.map((d) => {
            const has = !!findAcademy(me, d.nation)
            return (
              <button key={d.nation} className={`flex items-center gap-1 rounded-lg px-1.5 py-1 text-left text-[0.7rem] ${sel === d.nation ? 'bg-gold/15 ring-1 ring-gold/50' : 'bg-white/[0.05]'}`} onClick={() => setSel(d.nation)}>
                <Flag nation={d.nation} className="h-[0.8rem] w-[1.2rem] shrink-0" />
                <span className="min-w-0 flex-1 truncate font-bold">{NATION_NAME[d.nation]}</span>
                {has && <span className="shrink-0 text-good">✓</span>}
              </button>
            )
          })}
        </div>
      </div>
      <AcademyDetail key={sel} state={state} nation={sel} />
    </div>
  )
}

function AcademyDetail({ state, nation }: { state: GameState; nation: Nation }) {
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const [ask, setAsk] = useState(false)
  const me = playerClub(state)
  const d = ACADEMY_DEFS.find((x) => x.nation === nation) ?? ACADEMY_DEFS[0]
  const a = findAcademy(me, nation)
  const open = canOpenAcademy(me, nation)
  const up = canUpgradeAcademy(state, me, nation)
  const kids = Object.values(state.players).filter((p) => p.clubId === me.id && !p.retired && p.origin === `${NATION_NAME[nation]}・${d.city}校`)
  return (
    <div className="panel scroll-y min-w-0 flex-1 space-y-2.5 p-3 text-[0.8rem]">
      <div className="flex items-center gap-3">
        <Flag nation={nation} className="h-[2rem] w-[3rem] shrink-0 rounded-sm" />
        <div className="min-w-0 flex-1">
          <div className="text-[1.05rem] font-black">
            {NATION_NAME[nation]}・{d.city}
          </div>
          <div className="mt-0.5 flex flex-wrap items-center gap-1">
            <span className="rounded bg-gold/20 px-1.5 text-[0.72rem] font-bold text-gold">得意 {d.spec}</span>
            {d.attrs.map((k) => (
              <span key={k} className="rounded bg-white/10 px-1.5 text-[0.7rem]">
                {ATTR_BY_KEY[k].name}
              </span>
            ))}
          </div>
        </div>
        {a && <LvBar v={a.level} />}
      </div>
      <div className="grid grid-cols-[auto_1fr] gap-x-3 gap-y-1 rounded-lg bg-black/25 px-2.5 py-2 text-[0.76rem]">
        <span className="text-ink-dim">育成の土台</span>
        <span className="font-bold">{quality(d)}</span>
        <span className="text-ink-dim">掘り出し物</span>
        <span className="font-bold">{gems(d)}</span>
        <span className="text-ink-dim">出てきやすい</span>
        <span className="flex flex-wrap gap-1">
          {d.pos.map((p) => (
            <PosBadge key={p} pos={p} />
          ))}
        </span>
        <span className="text-ink-dim">近くの国</span>
        <span>{d.neighbors.map((n) => NATION_NAME[n]).join('・')}（2 割はこの国の子）</span>
        <span className="text-ink-dim">運営費</span>
        <span className="num">
          {a ? `${formatMoneyShort(academyRunCost(a))}/年（Lv${a.level}）` : `${formatMoneyShort(d.run)}/年（Lv1）〜 ${formatMoneyShort(Math.round(d.run * ACADEMY_RUN_MUL[ACADEMY_MAX_LEVEL]))}/年（Lv5）`}
        </span>
      </div>

      {!a && (
        <>
          <button className="btn btn-gold w-full" disabled={!open.ok} onClick={() => mutate((st) => void openAcademy(st, nation))}>
            {open.ok || open.reason === '資金が足りない' ? `開校する（${formatMoney(d.openCost)}・準備 ${ACADEMY_OPEN_WEEKS} 週）` : open.reason}
          </button>
          {open.reason === '資金が足りない' && <div className="text-center text-[0.74rem] text-bad">資金が足りません</div>}
          <p className="text-[0.72rem] text-ink-mute">開校すると、シーズン末に毎季 1〜3 人（レベルで増える）の子どもがユースに入ります。その国の有望株の情報も正確になり、来てくれやすくなります。</p>
        </>
      )}

      {a && (
        <>
          <div>
            <div className="mb-1 text-[0.74rem] text-ink-dim">方針</div>
            <div className="seg w-full">
              {(['normal', 'elite', 'mass'] as AcademyPolicy[]).map((p) => (
                <button key={p} className="flex-1" aria-selected={a.policy === p} onClick={() => mutate((st) => setAcademyPolicy(st, nation, p))}>
                  {ACADEMY_POLICY_LABEL[p]}
                </button>
              ))}
            </div>
            <div className="mt-1 text-[0.7rem] text-ink-mute">{ACADEMY_POLICY_DESC[a.policy]}</div>
          </div>
          {a.level < ACADEMY_MAX_LEVEL && (
            <button className="btn btn-blue w-full" disabled={!up.ok} onClick={() => mutate((st) => void upgradeAcademy(st, nation))}>
              {up.ok || up.reason === '資金が足りない' ? `Lv${a.level + 1} に拡大（${formatMoney(academyUpgradeCost(nation, a.level + 1))}・${ACADEMY_UPGRADE_WEEKS} 週）` : up.reason}
            </button>
          )}
          <div>
            <div className="mb-1 flex items-center text-[0.74rem] text-ink-dim">
              <span>ここから来た子（いま在籍）</span>
              <span className="ml-auto">これまで {a.produced} 人</span>
            </div>
            {kids.length === 0 && <div className="text-[0.74rem] text-ink-mute">まだいません。シーズン末に入ってきます。</div>}
            <div className="space-y-1">
              {kids.map((p) => (
                <button key={p.id} className="flex w-full items-center gap-2 rounded-lg bg-white/[0.04] px-1.5 py-1 text-left" onClick={() => push({ id: 'player', params: { id: p.id } })}>
                  <PlayerFace p={p} kit={me.colors} className="h-7 w-7 shrink-0" />
                  <PosBadge pos={p.pos} />
                  <span className="min-w-0 flex-1 truncate text-[0.78rem] font-bold">{p.name}</span>
                  <Flag nation={p.nation} className="h-[0.75rem] w-[1.1rem] shrink-0" />
                  <span className="text-[0.68rem] text-ink-dim">{p.isYouth ? 'ユース' : 'トップ'}</span>
                  <OvrBadge value={ovr(p)} size="sm" />
                </button>
              ))}
            </div>
          </div>
          <button className="btn btn-ghost btn-sm w-full !text-[0.74rem]" onClick={() => setAsk(true)}>
            閉校する（{formatMoneyShort(Math.round(a.invested * ACADEMY_REFUND))} が戻る）
          </button>
          <ConfirmDialog
            open={ask}
            title={`${d.city}校を閉じますか？`}
            text={`つぎ込んだ額の ${Math.round(ACADEMY_REFUND * 100)}% が戻ります。ここから来た子はそのまま残ります。`}
            ok="閉校する"
            onOk={() => {
              mutate((st) => void closeAcademy(st, nation))
              setAsk(false)
            }}
            onCancel={() => setAsk(false)}
          />
        </>
      )}
    </div>
  )
}
