// ---------------------------------------------------------------- キャリアモード

const hero = (s: GameState) => (s.career ? s.players[s.career.playerId] : undefined)
const totals = (s: GameState) => {
  const c = s.career!
  const p = hero(s)
  return {
    apps: c.log.reduce((n, l) => n + l.apps, 0) + (p?.stats.apps ?? 0),
    goals: c.log.reduce((n, l) => n + l.goals, 0) + (p?.stats.goals ?? 0),
  }
}
const award = (s: GameState, key: string) => s.seasons.some((x) => x.awards?.some((a) => a.key === key && a.playerId === s.career!.playerId))

