/** キャリアモードの始まり: 主人公（名前・プレースタイル・ポジション・利き足・身長・顔）を決める。 */
import { useEffect, useState } from 'react'
import { listSlots, SLOT_COUNT, type SaveSlotMeta } from '../../persistence/db'
import { PLAY_STYLES, PLAY_STYLE_BY_ID } from '../../engine/data/career'
import { POSITION_DEFS, type Position } from '../../engine/data/positions'
import type { GrowthMode, PlayStyle } from '../../engine/models/career'
import { GROWTH_DEFS, type GrowthType } from '../../engine/data/growth'
import { jpNamePool } from '../../engine/data/nations'
import { bodyBias } from '../../engine/career/create'
import { ATTR_BY_KEY, type AttrKey } from '../../engine/data/attributes'
import type { FaceSpec } from '../../engine/models/face'
import type { Foot } from '../../engine/models/player'
import { PlayerAvatar } from '../components/PlayerAvatar'
import { Portrait } from '../components/Portrait'
import { genIds } from '../components/portraits'
import { Icon } from '../components/Icon'
import { TypeCurves } from '../career/GrowthChart'
import { useUi } from '../../stores/uiStore'
import { flushSave, useGame } from '../../stores/gameStore'

const HAIR_COLORS = ['#1d1612', '#3a2a1c', '#6b4626', '#b9874a', '#d9b56c', '#7a3a1e']
/** 主人公の顔に選べる写真（tools/gen で生成） */
const PHOTOS = genIds('protag')
const FOOT: [Foot, string][] = [
  ['R', '右'],
  ['L', '左'],
  ['B', '両足'],
]

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="mb-3">
      <div className="panel-head mb-1.5">{title}</div>
      {children}
    </section>
  )
}

export function CareerNewScreen() {
  const pop = useUi((s) => s.pop)
  const reset = useUi((s) => s.reset)
  const newCareer = useGame((s) => s.newCareer)
  const [family, setFamily] = useState('朝倉')
  const [given, setGiven] = useState('翔')
  const [style, setStyle] = useState<PlayStyle>('striker')
  const [pos, setPos] = useState<Position>('ST')
  const [foot, setFoot] = useState<Foot>('R')
  const [height, setHeight] = useState(176)
  const [weight, setWeight] = useState(68)
  const [growth, setGrowth] = useState<GrowthMode>('easy')
  const [gtype, setGtype] = useState<GrowthType | 'random'>('normal')
  const [face, setFace] = useState<FaceSpec>({ skin: 1, hair: 2, hairColor: HAIR_COLORS[0], beard: 'none', glasses: false, headband: false, photo: PHOTOS[0] })
  const [busy, setBusy] = useState(false)
  const [slots, setSlots] = useState<SaveSlotMeta[]>([])
  const [slot, setSlot] = useState(1)
  useEffect(() => {
    void flushSave()
      .then(() => listSlots())
      .then((list) => {
        setSlots(list)
        const used = new Set(list.map((x) => x.id))
        const free = Array.from({ length: SLOT_COUNT }, (_, i) => i + 1).find((i) => !used.has(i))
        setSlot(free ?? 1)
      })
      .catch(() => setSlots([]))
  }, [])

  const def = PLAY_STYLE_BY_ID[style]
  const name = `${family.trim() || '朝倉'} ${given.trim() || '翔'}`
  const pickStyle = (s: PlayStyle) => {
    setStyle(s)
    setPos(PLAY_STYLE_BY_ID[s].pos)
    if (s === 'keeper' && height < 182) setHeight(186)
  }
  const cycle = (k: 'skin' | 'hair', n: number) => setFace((f) => ({ ...f, [k]: ((f[k] ?? 0) + 1) % n }))

  const start = () => {
    setBusy(true)
    // 描画を一度返してから重い生成を行う
    setTimeout(() => {
      newCareer({ seed: (Date.now() ^ Math.floor(Math.random() * 1e9)) >>> 0, name, style, pos, foot, heightCm: height, weightKg: weight, face, growthMode: growth, growthType: gtype }, slot)
      reset({ id: 'home' })
    }, 30)
  }

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-white/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">キャリアモード</h1>
        <span className="ml-2 truncate text-[0.75rem] text-ink-dim">18 歳のルーキーから、世界の頂点へ。あなた自身を決めましょう。</span>
      </header>
      <div className="safe-px safe-pb flex min-h-0 flex-1 gap-3 pt-3">
        {/* 左: プレビュー */}
        <div className="panel scroll-y relative flex w-[34%] shrink-0 flex-col items-center p-3">
          <div className="absolute inset-x-0 top-0 h-1/2 opacity-30" style={{ background: 'radial-gradient(80% 90% at 50% 0%, #1d4ed8, transparent 70%)' }} />
          <div className="relative h-[6.5rem] w-[6.5rem] shrink-0 overflow-hidden rounded-full border-2 border-gold/60">
            {face.photo ? <Portrait id={face.photo} kind="face" className="h-full w-full" /> : <PlayerAvatar seed={7} nation="JP" face={face} size="100%" mood="happy" />}
          </div>
          <div className="relative mt-1.5 text-center text-[1.25rem] font-black leading-tight">{name}</div>
          <div className="relative text-[0.78rem] text-ink-dim">
            18 歳・{def.name}・{POSITION_DEFS[pos].name}・{FOOT.find((f) => f[0] === foot)?.[1]}利き・{height}cm・{weight}kg
          </div>
          <div className="relative mt-1 px-2 text-center text-[0.78rem] text-ink-dim">{def.desc}</div>
          <div className="relative mt-2 w-full">
            <div className="flex flex-wrap justify-center gap-1">
              {PHOTOS.map((id) => (
                <button key={id} onClick={() => setFace((f) => ({ ...f, photo: id }))} aria-label="写真の顔" className={`shrink-0 rounded-full border-2 p-0.5 ${face.photo === id ? 'border-gold' : 'border-transparent'}`}>
                  <Portrait id={id} kind="face" className="face-round h-10 w-10" />
                </button>
              ))}
              <button onClick={() => setFace((f) => ({ ...f, photo: undefined }))} className={`flex shrink-0 flex-col items-center justify-center rounded-full border-2 p-0.5 ${face.photo ? 'border-transparent' : 'border-gold'}`}>
                <span className="face-round flex h-10 w-10 items-center justify-center overflow-hidden">
                  <PlayerAvatar seed={7} nation="JP" face={{ ...face, photo: undefined }} size="100%" mood="happy" />
                </span>
              </button>
            </div>
            {!face.photo && (
              <div className="mt-1 flex flex-wrap justify-center gap-1">
                <button className="btn btn-ghost btn-sm" onClick={() => cycle('hair', 11)}>
                  髪型
                </button>
                <button className="btn btn-ghost btn-sm" onClick={() => setFace((f) => ({ ...f, hairColor: HAIR_COLORS[(HAIR_COLORS.indexOf(f.hairColor ?? '') + 1) % HAIR_COLORS.length] }))}>
                  髪の色
                </button>
                <button className="btn btn-ghost btn-sm" onClick={() => cycle('skin', 4)}>
                  肌
                </button>
                <button className={`btn btn-sm ${face.glasses ? 'btn-blue' : 'btn-ghost'}`} onClick={() => setFace((f) => ({ ...f, glasses: !f.glasses }))}>
                  めがね
                </button>
                <button className={`btn btn-sm ${face.headband ? 'btn-blue' : 'btn-ghost'}`} onClick={() => setFace((f) => ({ ...f, headband: !f.headband }))}>
                  ヘアバンド
                </button>
              </div>
            )}
          </div>
          <div className="relative mt-auto flex w-full shrink-0 items-end gap-2 pt-2">
            <Portrait id="kato_misaki" kind="face" className="face-round h-12 w-12 shrink-0" />
            <div className="rounded-xl rounded-bl-none bg-white/10 px-2.5 py-1.5 text-[0.78rem] leading-snug">代理人の加藤です。あなたの武器は何ですか？ プレースタイルで最初の能力と得意な練習が決まります。</div>
          </div>
        </div>

        {/* 右: 設定（下の帯は固定） */}
        <div className="flex min-w-0 flex-1 flex-col">
          <div className="scroll-y min-h-0 flex-1 pr-1">
            <Section title="名前">
              <div className="flex gap-2">
                <button
                  className="btn btn-ghost btn-sm h-10 shrink-0"
                  onClick={() => {
                    const pool = jpNamePool()
                    setFamily(pool.family[Math.floor(Math.random() * pool.family.length)])
                    setGiven(pool.given[Math.floor(Math.random() * pool.given.length)])
                  }}
                >
                  ランダム
                </button>
                <input value={family} onChange={(e) => setFamily(e.target.value.slice(0, 6))} placeholder="姓" aria-label="姓" className="h-10 min-w-0 flex-1 rounded-lg border border-line/60 bg-black/30 px-3 text-[0.9rem] outline-none focus:border-gold" />
                <input value={given} onChange={(e) => setGiven(e.target.value.slice(0, 6))} placeholder="名" aria-label="名" className="h-10 min-w-0 flex-1 rounded-lg border border-line/60 bg-black/30 px-3 text-[0.9rem] outline-none focus:border-gold" />
              </div>
            </Section>
            <Section title="プレースタイル">
              <div className="grid grid-cols-3 gap-1.5">
                {PLAY_STYLES.map((s) => (
                  <button key={s.id} onClick={() => pickStyle(s.id)} className={`rounded-lg border px-2 py-1.5 text-left ${s.id === style ? 'border-gold bg-gold/15' : 'border-line/60 bg-black/20'}`}>
                    <div className={`text-[0.85rem] font-black ${s.id === style ? 'text-gold' : ''}`}>{s.name}</div>
                    <div className="truncate text-[0.7rem] text-ink-dim">{s.desc}</div>
                  </button>
                ))}
              </div>
            </Section>
            <div className="grid grid-cols-2 gap-3">
              <Section title="ポジション">
                <div className="seg flex-wrap">
                  {def.positions.map((p) => (
                    <button key={p} aria-selected={pos === p} onClick={() => setPos(p)} title={POSITION_DEFS[p].name}>
                      {p}
                    </button>
                  ))}
                </div>
              </Section>
              <Section title="利き足">
                <div className="seg">
                  {FOOT.map(([f, label]) => (
                    <button key={f} aria-selected={foot === f} onClick={() => setFoot(f)}>
                      {label}
                    </button>
                  ))}
                </div>
              </Section>
              <Section title="身長">
                <div className="flex items-center gap-2">
                  <button className="btn btn-ghost btn-sm w-10" onClick={() => setHeight((h) => Math.max(160, h - 2))} aria-label="低く">
                    −
                  </button>
                  <span className="num w-16 text-center text-[1rem] font-black">{height}cm</span>
                  <button className="btn btn-ghost btn-sm w-10" onClick={() => setHeight((h) => Math.min(198, h + 2))} aria-label="高く">
                    ＋
                  </button>
                </div>
              </Section>
              <Section title="体重">
                <div className="flex items-center gap-2">
                  <button className="btn btn-ghost btn-sm w-10" onClick={() => setWeight((w) => Math.max(52, w - 2))} aria-label="軽く">
                    −
                  </button>
                  <span className="num w-16 text-center text-[1rem] font-black">{weight}kg</span>
                  <button className="btn btn-ghost btn-sm w-10" onClick={() => setWeight((w) => Math.min(100, w + 2))} aria-label="重く">
                    ＋
                  </button>
                </div>
              </Section>
              <div className="col-span-2 -mt-2 mb-2 text-[0.72rem] leading-snug text-ink-dim">
                体格で最初の能力が変わります:{' '}
                {(Object.entries(bodyBias(height, weight)) as [AttrKey, number][])
                  .filter(([, v]) => Math.abs(v) >= 0.5)
                  .map(([k, v]) => `${ATTR_BY_KEY[k].name}${v > 0 ? '+' : ''}${Math.round(v)}`)
                  .join('・') || '標準的な体格'}
              </div>
              <Section title="成長タイプ（ピーク年齢）">
                <div className="seg flex-wrap">
                  {(['early', 'normal', 'late', 'random'] as const).map((t) => (
                    <button key={t} aria-selected={gtype === t} onClick={() => setGtype(t)}>
                      {t === 'random' ? 'おまかせ' : GROWTH_DEFS[t].name}
                    </button>
                  ))}
                </div>
                <div className="mt-1 text-[0.72rem] leading-snug text-ink-dim">
                  {gtype === 'random' ? '超早熟〜超晩成のどれかになる（あとで分かる）' : gtype === 'early' ? `若いうちに大きく伸び、衰えも早い（ピーク ${GROWTH_DEFS.early.peak}）` : gtype === 'late' ? `20 代後半まで伸び続け、長く活躍できる（ピーク ${GROWTH_DEFS.late.peak}）` : `バランスよく伸びる（ピーク ${GROWTH_DEFS.normal.peak}）`}。出来事で変わることもあります
                </div>
              </Section>
              <Section title="育成のしかた">
                <div className="seg">
                  <button aria-selected={growth === 'easy'} onClick={() => setGrowth('easy')}>
                    かんたん
                  </button>
                  <button aria-selected={growth === 'normal'} onClick={() => setGrowth('normal')}>
                    じっくり
                  </button>
                </div>
                <div className="mt-1 text-[0.72rem] leading-snug text-ink-dim">{growth === 'easy' ? '練習した能力が自動で上がる。あとから変えられます' : '経験点を自分で能力に振る。あとから変えられます'}</div>
              </Section>
              <div className="col-span-2 -mt-1">
                <div className="text-[0.7rem] text-ink-dim">成長の目安（OVR。おまかせで過ごしたとき。年齢をタップすると値が出ます）</div>
                <TypeCurves types={['early', 'normal', 'late']} selected={gtype === 'random' ? undefined : gtype} />
              </div>
            </div>
          </div>
          <div className="flex shrink-0 items-center justify-end gap-2 border-t border-line/40 pt-2">
            <div className="flex items-center gap-1">
              <span className="text-[0.76rem] text-ink-dim">保存先</span>
              {Array.from({ length: SLOT_COUNT }, (_, i) => i + 1).map((n) => {
                const used = slots.find((x) => x.id === n)
                return (
                  <button key={n} onClick={() => setSlot(n)} title={used ? `${used.clubName}（上書き）` : '空き'} className={`flex h-[3.3rem] w-[3rem] flex-col items-center justify-center rounded-lg border text-[0.68rem] leading-tight ${slot === n ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/30'}`}>
                    <span className="num text-[0.95rem] font-black">{n}</span>
                    <span className="w-full truncate px-0.5">{used ? '上書き' : '空き'}</span>
                  </button>
                )
              })}
            </div>
            <button className="btn btn-gold h-[3.3rem] px-8 text-[1.05rem]" onClick={start} disabled={busy}>
              {busy ? '世界を作っています…' : 'プロへの一歩を踏み出す'}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}
