/**
 * 一般の選手の成長の見込み（クラブモードの選手詳細）。毎週の成長（growth/training.ts の growPlayer）を、
 * 乱数のゆらぎなし・平均的な練習で先へ進めて、年齢ごとの総合力を出す。上限（cap）と成長タイプで決まる目安。
 * 結果の形はキャリアの見込み（career/projection.ts）と同じで、グラフ（ui/career/GrowthChart）を使い回す。
 */
import { WEEKS_PER_SEASON } from '../core/calendar'
import type { Rng } from '../core/prng'
import { growPlayer } from '../growth/training'
import type { Player } from '../models/player'
import { ovr } from './overall'
import { PROJ_MAX_AGE, type Projection, type ProjPoint } from '../career/projection'

/** ゆらぎなし（growPlayer の noise を 1 にする） */
const STEADY: Rng = {
  next: () => 0.5,
  int: (min) => min,
  range: (min, max) => (min + max) / 2,
  pick: (arr) => arr[0],
  normal: (mean) => mean,
  shuffle: (arr) => arr,
  chance: () => false,
  weighted: () => 0,
  state: () => 0,
}

export function projectPlayer(p: Player, absWeek: number, mul = 1): Projection {
  const sim: Player = { ...p, attr: { ...p.attr }, cap: { ...p.cap }, stats: { ...p.stats, apps: 1, minutes: 90 } }
  const ageNow = (absWeek - p.birthAbsWeek) / WEEKS_PER_SEASON
  const now: ProjPoint = { age: Math.round(ageNow * 10) / 10, ovr: ovr(p) }
  const future: ProjPoint[] = []
  let w = absWeek
  for (let a = Math.floor(ageNow) + 1; a <= PROJ_MAX_AGE; a++) {
    const until = p.birthAbsWeek + a * WEEKS_PER_SEASON
    for (; w < until; w++) growPlayer(sim, w, { mul }, STEADY)
    const v = ovr(sim)
    const spread = Math.min(6, 1 + 0.5 * (a - ageNow))
    future.push({ age: a, ovr: v, lo: Math.max(30, Math.round(v - spread)), hi: Math.min(99, Math.round(v + spread)) })
  }
  const peak = [now, ...future].reduce((m, x) => (x.ovr > m.ovr ? x : m), now)
  return { past: [], now, future, peak }
}
