/**
 * 直前の試合のハイライト（ゴール・ポスト・ビッグセーブの場面）。試合の画面が書き、試合後の画面が読む。セーブはしない。
 * key は「ホーム|アウェイ」のクラブ id（観戦しなかった試合の結果に、前の試合の場面を出さないため）。
 */
import { create } from 'zustand'
import type { Clip } from '../ui/match/replay'

interface HighlightStore {
  key: string
  clips: Clip[]
  set: (key: string, clips: Clip[]) => void
}

export const useHighlights = create<HighlightStore>((set) => ({
  key: '',
  clips: [],
  set: (key, clips) => set({ key, clips }),
}))

export const highlightKey = (home: number, away: number) => `${home}|${away}`
