export function menuGroups(state: GameState): MenuGroup[] {
  return state.mode === 'career' ? CAREER_MENU : CLUB_MENU
}

/** ナビとメニューの知らせの数（返事を待っているもの） */
export function badgesOf(state: GameState): Partial<Record<string, number>> {
  const out: Partial<Record<string, number>> = {}
  const add = (key: string, n: number) => {
    if (n > 0) out[key] = (out[key] ?? 0) + n
  }
  if (state.mode === 'career') {
    const c = state.career
    if (!c) return out
    const offers = c.offers.filter((o) => o.kind !== 'rookie').length
    add('career', offers)
    add('career:offers', offers)
    add('life', (c.sponsorOffer ? 1 : 0) + (c.mediaOffer ? 1 : 0))
    add('life:sponsor', c.sponsorOffer ? 1 : 0)
    add('life:media', c.mediaOffer ? 1 : 0)
    return out
  }
  const bids = state.offers.filter((o) => o.kind === 'bid').length
  const sponsors = state.offers.filter((o) => o.kind === 'sponsor').length
  add('transfer', bids)
  add('transfer:sell', bids)
  // 有望株（M19）: 申し込んでいない子の数
  const open = state.prospects?.list.filter((p) => !p.applied).length ?? 0
  add('transfer', open)
  add('transfer:prospects', open)
  // スカウトの報告（M21）: まだ見ていない報告の数
  const reports = (state.scout.reports ?? []).filter((r) => !r.seen).length
  add('transfer', reports)
  add('transfer:scout', reports)
  add('club', sponsors)
  add('club:sponsor', sponsors)
  // 海外ユース（M25）: 申し込んでいない海外の有望株・国際ユースカップの招待と今週の試合
  const oy = state.overseasYouth?.list.filter((p) => !p.applied).length ?? 0
  const yc = state.youthCup?.season === state.season ? state.youthCup : undefined
  const cup = (yc?.status === 'invited' ? 1 : 0) + (yc?.status === 'entered' && ourCupMatch(state) ? 1 : 0)
  add('squad', oy + cup)
  add('youth:scout', oy)
  add('youth:cup', cup)
  return out
}
