/**
 * 試合の 2D 描画（Canvas）。ピッチは解像度が変わったときだけ別キャンバスに描いて使い回す。
 * 選手とボールは前後 2 ステップの位置を補間して 60fps で描く。
 */
import { BOX_DEPTH, BOX_WIDTH, GOAL_W, PITCH_H, PITCH_W, SIX_DEPTH, SIX_WIDTH } from '../../engine/match/live/types'
import type { MatchPlayerSetup } from '../../engine/match/live/types'

/** 描画に要る選手の形（LiveMatch の Body と、リプレイの ReplaySource が満たす） */
export interface DrawBody {
  idx: number
  team: 0 | 1
  gk: boolean
  s: Pick<MatchPlayerSetup, 'id' | 'number' | 'short'>
  x: number
  y: number
  px: number
  py: number
  tx: number
  ty: number
  stun: number
  onPitch: boolean
}

/** 描画に要る試合の形 */
export interface DrawableMatch {
  ball: { x: number; y: number; z: number; px: number; py: number; pz: number; owner: number }
  bodies: DrawBody[]
  teams: { setup: { gkColor: string; colors: { primary: string; secondary: string } } }[]
}

const MARGIN = 4

export interface DrawOptions {
  /** 'follow' = ボールを追う拡大表示、'full' = ピッチ全体 */
  camera: 'follow' | 'full'
  debug?: boolean
  /** 名前を出す選手（保持者など） */
  showNames?: boolean
  /** キャリア: 主人公（金の輪と名前を常に出す） */
  focusId?: number
  /** カメラの寄り（リプレイは少し寄せる） */
  zoom?: number
}

export class PitchRenderer {
  private ctx: CanvasRenderingContext2D
  private pitch: HTMLCanvasElement
  private w = 0
  private h = 0
  private dpr = 1
  /** カメラ（ワールド座標の中心と倍率） */
  private camX = PITCH_W / 2
  private camY = PITCH_H / 2
  private zoom = 1
  private pitchScale = 0
  private canvas: HTMLCanvasElement
  /** 次の描画でカメラを目標へ一気に合わせる（リプレイの始まり） */
  private snap = true

  constructor(canvas: HTMLCanvasElement) {
    this.canvas = canvas
    this.ctx = canvas.getContext('2d', { alpha: false })!
    this.pitch = document.createElement('canvas')
  }

  /** 次の描画でカメラを目標へ一気に合わせる */
  snapCamera() {
    this.snap = true
  }

  resize(cssW: number, cssH: number) {
    this.dpr = Math.min(2, window.devicePixelRatio || 1)
    this.w = Math.max(1, Math.round(cssW))
    this.h = Math.max(1, Math.round(cssH))
    this.canvas.width = Math.round(this.w * this.dpr)
    this.canvas.height = Math.round(this.h * this.dpr)
    this.pitchScale = 0
  }

  /** ピッチ全体が収まる倍率（px/m） */
  private fitScale(): number {
    return Math.min(this.w / (PITCH_W + MARGIN * 2), this.h / (PITCH_H + MARGIN * 2))
  }

  private renderPitch(scale: number) {
    const W = (PITCH_W + MARGIN * 2) * scale
    const H = (PITCH_H + MARGIN * 2) * scale
    const c = this.pitch
    c.width = Math.ceil(W * this.dpr)
    c.height = Math.ceil(H * this.dpr)
    const g = c.getContext('2d')!
    g.setTransform(this.dpr * scale, 0, 0, this.dpr * scale, MARGIN * this.dpr * scale, MARGIN * this.dpr * scale)
    // 芝
    g.fillStyle = '#17713f'
    g.fillRect(-MARGIN, -MARGIN, PITCH_W + MARGIN * 2, PITCH_H + MARGIN * 2)
    const stripes = 14
    for (let i = 0; i < stripes; i++) {
      g.fillStyle = i % 2 ? '#1c8048' : '#18773f'
      g.fillRect((PITCH_W / stripes) * i, 0, PITCH_W / stripes + 0.05, PITCH_H)
    }
    // 外周の影
    const grd = g.createRadialGradient(PITCH_W / 2, PITCH_H / 2, PITCH_H * 0.3, PITCH_W / 2, PITCH_H / 2, PITCH_W * 0.7)
    grd.addColorStop(0, 'rgba(255,255,255,0.05)')
    grd.addColorStop(1, 'rgba(0,0,0,0.22)')
    g.fillStyle = grd
    g.fillRect(-MARGIN, -MARGIN, PITCH_W + MARGIN * 2, PITCH_H + MARGIN * 2)
    // ライン
    g.strokeStyle = 'rgba(255,255,255,0.85)'
    g.lineWidth = 0.16
    g.strokeRect(0, 0, PITCH_W, PITCH_H)
    g.beginPath()
    g.moveTo(PITCH_W / 2, 0)
    g.lineTo(PITCH_W / 2, PITCH_H)
    g.stroke()
    g.beginPath()
    g.arc(PITCH_W / 2, PITCH_H / 2, 9.15, 0, Math.PI * 2)
    g.stroke()
    g.fillStyle = 'rgba(255,255,255,0.9)'
    for (const x of [PITCH_W / 2, 11, PITCH_W - 11]) {
      g.beginPath()
      g.arc(x, PITCH_H / 2, 0.25, 0, Math.PI * 2)
      g.fill()
    }
    for (const side of [0, 1]) {
      const x0 = side === 0 ? 0 : PITCH_W
      const s = side === 0 ? 1 : -1
      g.strokeRect(side === 0 ? 0 : PITCH_W - BOX_DEPTH, PITCH_H / 2 - BOX_WIDTH / 2, BOX_DEPTH, BOX_WIDTH)
      g.strokeRect(side === 0 ? 0 : PITCH_W - SIX_DEPTH, PITCH_H / 2 - SIX_WIDTH / 2, SIX_DEPTH, SIX_WIDTH)
      // ペナルティアーク
      g.beginPath()
      const a = Math.acos((BOX_DEPTH - 11) / 9.15)
      if (side === 0) g.arc(11, PITCH_H / 2, 9.15, -a, a)
      else g.arc(PITCH_W - 11, PITCH_H / 2, 9.15, Math.PI - a, Math.PI + a)
      g.stroke()
      // ゴール
      g.fillStyle = 'rgba(255,255,255,0.18)'
      g.fillRect(side === 0 ? -2 : PITCH_W, PITCH_H / 2 - GOAL_W / 2, 2, GOAL_W)
      g.strokeStyle = 'rgba(255,255,255,0.95)'
      g.lineWidth = 0.22
      g.strokeRect(side === 0 ? -2 : PITCH_W, PITCH_H / 2 - GOAL_W / 2, 2, GOAL_W)
      g.lineWidth = 0.16
      g.strokeStyle = 'rgba(255,255,255,0.85)'
      // コーナー
      for (const y of [0, PITCH_H]) {
        g.beginPath()
        g.arc(x0, y, 1, side === 0 ? (y === 0 ? 0 : -Math.PI / 2) : y === 0 ? Math.PI / 2 : Math.PI, side === 0 ? (y === 0 ? Math.PI / 2 : 0) : y === 0 ? Math.PI : (Math.PI * 3) / 2)
        g.stroke()
      }
      void s
    }
    this.pitchScale = scale
  }

  draw(m: DrawableMatch, alpha: number, opt: DrawOptions) {
    const ctx = this.ctx
    const fit = this.fitScale()
    // カメラ
    const b = m.ball
    const bx = b.px + (b.x - b.px) * alpha
    const by = b.py + (b.y - b.py) * alpha
    const targetZoom = opt.zoom ?? (opt.camera === 'follow' ? 1.75 : 1)
    this.zoom += (targetZoom - this.zoom) * (this.snap ? 1 : 0.12)
    const scale = fit * this.zoom
    const viewW = this.w / scale
    const viewH = this.h / scale
    const tx = opt.camera === 'follow' ? clampView(bx, viewW, PITCH_W) : PITCH_W / 2
    const ty = opt.camera === 'follow' ? clampView(by, viewH, PITCH_H) : PITCH_H / 2
    this.camX += (tx - this.camX) * (this.snap ? 1 : 0.1)
    this.camY += (ty - this.camY) * (this.snap ? 1 : 0.1)
    this.snap = false
    if (Math.abs(this.pitchScale - scale) > 0.02 * scale) this.renderPitch(scale)

    ctx.setTransform(this.dpr, 0, 0, this.dpr, 0, 0)
    ctx.fillStyle = '#0b3d22'
    ctx.fillRect(0, 0, this.w, this.h)
    const ox = this.w / 2 - this.camX * scale
    const oy = this.h / 2 - this.camY * scale
    ctx.drawImage(this.pitch, ox - MARGIN * scale, oy - MARGIN * scale, this.pitch.width / this.dpr, this.pitch.height / this.dpr)
    ctx.setTransform(this.dpr * scale, 0, 0, this.dpr * scale, this.dpr * ox, this.dpr * oy)

    const minR = 5.5 / scale
    const r = Math.max(0.95, minR)
    // 影
    ctx.fillStyle = 'rgba(0,0,0,0.25)'
    for (const p of m.bodies) {
      if (!p.onPitch) continue
      const x = p.px + (p.x - p.px) * alpha
      const y = p.py + (p.y - p.py) * alpha
      ctx.beginPath()
      ctx.ellipse(x + r * 0.25, y + r * 0.35, r, r * 0.8, 0, 0, Math.PI * 2)
      ctx.fill()
    }
    // デバッグ: 目標位置
    if (opt.debug) {
      ctx.lineWidth = 0.1
      for (const p of m.bodies) {
        if (!p.onPitch) continue
        ctx.strokeStyle = p.team === 0 ? 'rgba(255,255,255,0.4)' : 'rgba(255,200,0,0.4)'
        ctx.beginPath()
        ctx.moveTo(p.x, p.y)
        ctx.lineTo(p.tx, p.ty)
        ctx.stroke()
      }
    }
    const carrier = b.owner
    const fontPx = r * 1.15
    const showNum = r * scale >= 7
    for (const p of m.bodies) {
      if (!p.onPitch) continue
      const team = m.teams[p.team].setup
      const x = p.px + (p.x - p.px) * alpha
      const y = p.py + (p.y - p.py) * alpha
      const fill = p.gk ? team.gkColor : team.colors.primary
      const edge = p.gk ? '#ffffff' : team.colors.secondary
      const isFocus = opt.focusId !== undefined && p.s.id === opt.focusId
      if (isFocus) {
        ctx.strokeStyle = '#f5c542'
        ctx.lineWidth = 0.45
        ctx.beginPath()
        ctx.arc(x, y, r + 1.1, 0, Math.PI * 2)
        ctx.stroke()
      }
      if (p.idx === carrier) {
        ctx.strokeStyle = '#ffe08a'
        ctx.lineWidth = 0.28
        ctx.beginPath()
        ctx.arc(x, y, r + 0.55, 0, Math.PI * 2)
        ctx.stroke()
      }
      ctx.fillStyle = fill
      ctx.beginPath()
      ctx.arc(x, y, r, 0, Math.PI * 2)
      ctx.fill()
      ctx.lineWidth = Math.max(0.18, 1.6 / scale)
      ctx.strokeStyle = edge
      ctx.stroke()
      if (p.stun > 0.3) {
        ctx.fillStyle = 'rgba(0,0,0,0.35)'
        ctx.fill()
      }
      if (showNum) {
        ctx.fillStyle = luminance(fill) > 0.6 ? '#111827' : '#ffffff'
        ctx.font = `800 ${fontPx}px system-ui, sans-serif`
        ctx.textAlign = 'center'
        ctx.textBaseline = 'middle'
        ctx.fillText(String(p.s.number), x, y + fontPx * 0.05)
      }
      if (opt.showNames && (p.idx === carrier || isFocus)) {
        const label = p.s.short
        ctx.font = `700 ${Math.max(1.2, 11 / scale)}px system-ui, sans-serif`
        ctx.textAlign = 'center'
        ctx.textBaseline = 'top'
        const tw = ctx.measureText(label).width
        ctx.fillStyle = 'rgba(4,14,26,0.75)'
        roundRect(ctx, x - tw / 2 - 0.4, y + r + 0.35, tw + 0.8, Math.max(1.6, 15 / scale), 0.4)
        ctx.fill()
        ctx.fillStyle = '#ffffff'
        ctx.fillText(label, x, y + r + 0.45)
      }
    }
    // ボール（高さは影とのずれで表す）
    const bz = b.pz + (b.z - b.pz) * alpha
    const br = Math.max(0.42, 3 / scale) * (1 + bz * 0.08)
    ctx.fillStyle = 'rgba(0,0,0,0.35)'
    ctx.beginPath()
    ctx.ellipse(bx + bz * 0.25, by + bz * 0.35, br * 0.9, br * 0.7, 0, 0, Math.PI * 2)
    ctx.fill()
    ctx.fillStyle = '#ffffff'
    ctx.beginPath()
    ctx.arc(bx, by - bz * 0.45, br, 0, Math.PI * 2)
    ctx.fill()
    ctx.strokeStyle = '#111827'
    ctx.lineWidth = br * 0.25
    ctx.stroke()
  }
}

function clampView(c: number, view: number, size: number): number {
  const half = view / 2
  const lo = half - MARGIN
  const hi = size - half + MARGIN
  if (lo > hi) return size / 2
  return Math.max(lo, Math.min(hi, c))
}

function luminance(hex: string): number {
  const h = hex.replace('#', '')
  const n = parseInt(h.length === 3 ? h.split('').map((c) => c + c).join('') : h, 16)
  const r = (n >> 16) & 255
  const g = (n >> 8) & 255
  const b = n & 255
  return (0.299 * r + 0.587 * g + 0.114 * b) / 255
}

function roundRect(ctx: CanvasRenderingContext2D, x: number, y: number, w: number, h: number, r: number) {
  ctx.beginPath()
  ctx.moveTo(x + r, y)
  ctx.arcTo(x + w, y, x + w, y + h, r)
  ctx.arcTo(x + w, y + h, x, y + h, r)
  ctx.arcTo(x, y + h, x, y, r)
  ctx.arcTo(x, y, x + w, y, r)
  ctx.closePath()
}
