/**
 * ゲームの画面と重ね物（M17 のあとの起動の高速化）。タイトル画面と分けて、あとから読み込む（React.lazy）。
 * ゲームの処理（engine・gameStore）はここから読むので、タイトルが出るまでに読み込むコードが小さくなる。
 */
import { useGame } from './stores/gameStore'
import { TitleScreen } from './ui/screens/TitleScreen'
import { GalleryScreen } from './ui/screens/GalleryScreen'
import { AchievementsScreen } from './ui/screens/AchievementsScreen'
import { AchievementWatcher } from './ui/achievements/AchievementWatcher'
import { PressConference } from './ui/home/PressConference'
import { AutoProgress } from './ui/home/AutoProgress'
import { SettingsScreen } from './ui/screens/SettingsScreen'
import { PlaceholderScreen } from './ui/screens/PlaceholderScreen'
import { NewGameScreen } from './ui/screens/NewGameScreen'
import { LoadScreen } from './ui/screens/LoadScreen'
import { HomeScreen } from './ui/screens/HomeScreen'
import { SquadScreen } from './ui/screens/SquadScreen'
import { PlayerScreen } from './ui/screens/PlayerScreen'
import { LeagueScreen } from './ui/screens/LeagueScreen'
import { ClubScreen } from './ui/screens/ClubScreen'
import { MatchLabScreen } from './ui/screens/MatchLabScreen'
import { TacticsScreen } from './ui/screens/TacticsScreen'
import { TrainingScreen } from './ui/screens/TrainingScreen'
import { TransferScreen } from './ui/screens/TransferScreen'
import { PreMatchScreen } from './ui/screens/PreMatchScreen'
import { LiveMatchScreen } from './ui/screens/LiveMatchScreen'
import { PostMatchScreen } from './ui/screens/PostMatchScreen'
import { RecordsScreen } from './ui/screens/RecordsScreen'
import { NationalScreen } from './ui/screens/NationalScreen'
import { CareerNewScreen } from './ui/screens/CareerNewScreen'
import { CareerHomeScreen } from './ui/screens/CareerHomeScreen'
import { GrowthScreen } from './ui/screens/GrowthScreen'
import { LifeScreen } from './ui/screens/LifeScreen'
import { PeopleScreen } from './ui/screens/PeopleScreen'
import { CareerScreen } from './ui/screens/CareerScreen'
import { NationalMatchScreen } from './ui/screens/NationalMatchScreen'
import { CareerEndScreen } from './ui/screens/CareerEndScreen'
import { YouthMatchScreen } from './ui/screens/YouthMatchScreen'
import { YouthScreen } from './ui/screens/YouthScreen'
import { YouthCupScreen } from './ui/screens/YouthCupScreen'
import { ErrorDialog } from './ui/ErrorDialog'
import { useCurrentScreen } from './stores/uiStore'

/** ゲームが始まっていないと開けない画面 */
const NEEDS_GAME = new Set(['records', 'national', 'growth', 'people', 'career', 'natMatch', 'youthMatch', 'youth', 'youthCup', 'careerEnd', 'home', 'squad', 'player', 'tactics', 'schedule', 'club', 'transfer', 'matchLab', 'preMatch', 'match', 'postMatch', 'training'])

function Screens() {
  const screen = useCurrentScreen()
  const hasGame = useGame((s) => !!s.state)
  const career = useGame((s) => s.state?.mode === 'career')
  if (NEEDS_GAME.has(screen.id) && !hasGame) return <TitleScreen />
  switch (screen.id) {
    case 'title':
      return <TitleScreen />
    case 'newGame':
      return <NewGameScreen />
    case 'load':
      return <LoadScreen />
    case 'gallery':
      return <GalleryScreen />
    case 'achievements':
      return <AchievementsScreen />
    case 'settings':
      return <SettingsScreen />
    case 'home':
      return career ? <CareerHomeScreen /> : <HomeScreen />
    case 'careerNew':
      return <CareerNewScreen />
    case 'growth':
      return <GrowthScreen />
    case 'life':
      return <LifeScreen />
    case 'people':
      return <PeopleScreen />
    case 'career':
      return <CareerScreen />
    case 'natMatch':
      return <NationalMatchScreen />
    case 'youthMatch':
      return <YouthMatchScreen />
    case 'youth':
      return <YouthScreen />
    case 'youthCup':
      return <YouthCupScreen />
    case 'careerEnd':
      return <CareerEndScreen />
    case 'squad':
      return <SquadScreen />
    case 'player':
      return <PlayerScreen />
    case 'schedule':
      return <LeagueScreen />
    case 'club':
      return <ClubScreen />
    case 'matchLab':
      return <MatchLabScreen />
    case 'tactics':
      return <TacticsScreen />
    case 'training':
      return <TrainingScreen />
    case 'transfer':
      return <TransferScreen />
    case 'preMatch':
      return <PreMatchScreen />
    case 'match':
      return <LiveMatchScreen />
    case 'postMatch':
      return <PostMatchScreen />
    case 'records':
      return <RecordsScreen />
    case 'national':
      return <NationalScreen />
    default:
      return <PlaceholderScreen id={screen.id} />
  }
}

/** タイトル以外の画面（タイトルは App が直接出す）と、どの画面でも出す重ね物 */
export default function GameLayer() {
  const screen = useCurrentScreen()
  const id = screen.id
  return (
    <>
      {id !== 'title' && <Screens key={screen.uid ?? id} />}
      <ErrorDialog />
      <AchievementWatcher />
      <PressConference />
      <AutoProgress />
    </>
  )
}
