/**
 * 優勝の演出（M16、クラブモード）: まだ祝っていないタイトル（trophies の celebrated 以降）を、ホームでセレモニーにする。
 * セレモニーのあとに優勝パレード: 人気・サポーター・選手のやる気が上がり、ニュースになる。
 * 古いセーブは、開いたときに今までのタイトルを祝い済みにする（migrations の v6 のあと）。
 */
import { absWeekOf } from '../core/calendar'
import type { GameState, Trophy } from '../models/game'

/** 大会ごとのパレードの大きさ（人気の上がり幅） */
function weight(compId: string): number {
  if (compId === 'WL') return 12
  if (compId === 'WCC') return 10
  if (compId === 'ACC' || compId === 'NPL1') return 8
  if (compId === 'CUP') return 5
  if (compId.endsWith('PO')) return 3
  return 4
}

/** 沿道の人数の表示（1 万人からは「万人」） */
export function crowdLabel(n: number): string {
  return n >= 10000 ? `${(n / 10000).toFixed(1)} 万人` : `${n.toLocaleString()} 人`
}

/** まだ祝っていないタイトル */
export function unseenTrophies(state: GameState): Trophy[] {
  if (state.mode !== 'club') return []
  return state.trophies.slice(state.celebrated ?? 0)
}

export interface ParadeResult {
  crowd: number
  popularity: number
  fans: number
}

/** 優勝パレード（タイトル 1 つぶん）。人気・サポーター・選手のやる気を上げ、ニュースにする */
export function holdParade(state: GameState, t: Trophy): ParadeResult {
  const me = state.clubs[state.playerClubId]
  const w = weight(t.compId)
  const crowd = Math.max(3000, Math.round(Math.min(400000, me.fans * (0.25 + w * 0.03) + state.hometown.population * 0.002 * w) / 1000) * 1000)
  const popularity = Math.min(100 - me.popularity, Math.round(w * 0.8))
  const fans = Math.round(me.fans * (0.02 + w * 0.006))
  me.popularity += popularity
  me.fans += fans
  for (const p of Object.values(state.players)) if (p.clubId === me.id && !p.retired) p.morale = Math.min(100, p.morale + 8)
  state.news.push({ absWeek: absWeekOf(state.season, state.week), category: 'club', mine: true, text: `${t.name}の優勝パレード。沿道に ${crowdLabel(crowd)}が集まった！` })
  return { crowd, popularity, fans }
}
