/** くらし画面のタブ（M12）: 住まい（家を買う）・車・休暇（旅行と思い出）・メディア・家族。 */
import { useState } from "react";
import type { GameState } from "../../engine";
import { seasonLabel } from "../../engine";
import {
  CARS,
  CHILD_MILESTONES,
  COMPANION_NAME,
  FAMILY_EVENTS,
  HOUSING_BY_ID,
  MEDIA,
  MEDIA_BY_KIND,
  REGION_NAME,
  VACATIONS,
} from "../../engine/data/career";
import type {
  Companion,
  HousingId,
  VacationId,
} from "../../engine/models/career";
import {
  netWage,
  weeklyCost,
  weeklySponsorIncome,
  familyCost,
} from "../../engine/career/life";
import { bizEstimate } from "../../engine/career/business";
import {
  buyCar,
  buyHome,
  canBuyCar,
  canBuyHome,
  canLiveIn,
  canMoveInto,
  carsOf,
  carValue,
  garageSize,
  homeSellValue,
  HOMES_FOR_SALE,
  housingOf,
  mainCarOf,
  moveInto,
  ownedHomes,
  RENTALS,
  sellCar,
  sellHome,
  setMainCar,
  villaHomes,
} from "../../engine/career/homes";
import {
  bookVacation,
  canBookVacation,
  cancelVacation,
  companionsOf,
  placeName,
  vacationCost,
} from "../../engine/career/vacation";
import {
  acceptMedia,
  cmsOf,
  declineMedia,
  weeklyCmIncome,
} from "../../engine/career/media";
import { childAge } from "../../engine/career/children";
import { Portrait } from "../components/Portrait";
import { castPhotoId } from "../components/portraits";
import { LifePhoto } from "../components/LifePhoto";
import { useGame } from "../../stores/gameStore";
import { formatMoney, formatMoneyShort } from "../format";
import { castName } from '../../engine/career/core'

export function Row({
  title,
  sub,
  right,
  on,
  photo,
  children,
}: {
  title: React.ReactNode;
  sub?: React.ReactNode;
  right?: React.ReactNode;
  on?: boolean;
  photo?: React.ReactNode;
  children?: React.ReactNode;
}) {
  return (
    <div
      className={`flex items-center gap-2 rounded-lg px-2.5 py-1.5 ${on ? "bg-good/10" : "bg-white/[0.04]"}`}
    >
      {photo}
      <div className="min-w-0 flex-1">
        <div className="font-bold">{title}</div>
        {sub && <div className="text-[0.72rem] text-ink-dim">{sub}</div>}
      </div>
      {right && (
        <span className="num shrink-0 text-[0.72rem] text-ink-dim">
          {right}
        </span>
      )}
      {children}
    </div>
  );
}

const Btn = ({
  children,
  onClick,
  disabled,
  kind = "blue",
  title,
}: {
  children: React.ReactNode;
  onClick: () => void;
  disabled?: boolean;
  kind?: "blue" | "gold" | "ghost";
  title?: string;
}) => (
  <button
    className={`btn btn-${kind} btn-sm shrink-0 !min-h-[2rem]`}
    disabled={disabled}
    onClick={onClick}
    title={title}
  >
    {children}
  </button>
);

const homePhoto = (id: HousingId) => `home_${id.toLowerCase()}`;

// ---------------------------------------------------------------- 住まい

export function HomesTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate);
  const c = state.career!;
  const cur = housingOf(state);
  const owned = ownedHomes(state);
  const wage = state.players[c.playerId].contract.wage;
  const bizWeek = (c.businesses ?? []).reduce(
    (n, b) => n + bizEstimate(state, b.id, b.level),
    0,
  );
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[60%] shrink-0 space-y-1.5 p-3 text-[0.78rem]">
        <div className="panel-head">借りる</div>
        {RENTALS.map((h) => {
          const here = cur.id === h.id;
          const chk = canMoveInto(state, h.id);
          return (
            <Row
              key={h.id}
              on={here}
              title={
                <>
                  {h.name}
                  {here && (
                    <span className="ml-1.5 text-[0.7rem] text-good">
                      いま
                    </span>
                  )}
                </>
              }
              sub={`${h.desc}・器具 ${h.slots}・車庫 ${h.garage}`}
              right={
                h.cost > 0
                  ? `引っ越し ${formatMoneyShort(h.cost)}円・毎週 ${h.weekly}万`
                  : undefined
              }
            >
              {!here && (
                <Btn
                  disabled={!chk.ok}
                  title={chk.reason}
                  onClick={() => mutate((st) => void moveInto(st, h.id))}
                >
                  移る
                </Btn>
              )}
            </Row>
          );
        })}
        <div className="panel-head pt-1">家を買う</div>
        {HOMES_FOR_SALE.map((h) => {
          const mine = owned.includes(h.id);
          const here = cur.id === h.id;
          const livable = mine && canLiveIn(state, h.id);
          const where = h.region
            ? h.region.map((r) => REGION_NAME[r]).join("・")
            : "";
          const buy = canBuyHome(state, h.id);
          return (
            <Row
              key={h.id}
              on={here}
              photo={
                <LifePhoto
                  id={homePhoto(h.id)}
                  icon="home"
                  className="h-[3.2rem] w-[5.3rem]"
                />
              }
              title={
                <>
                  {h.name}
                  {here && (
                    <span className="ml-1.5 text-[0.7rem] text-good">
                      住んでいる
                    </span>
                  )}
                  {mine && !here && (
                    <span className="ml-1.5 text-[0.7rem] text-gold">
                      別荘
                    </span>
                  )}
                </>
              }
              sub={`${h.desc}・器具 ${h.slots}・車庫 ${h.garage}・${h.perk?.label ?? ""}${where && where !== "日本" ? `（${where}のクラブにいるとき住める）` : ""}・維持費 毎週 ${h.weekly}万`}
            >
              <div className="flex shrink-0 flex-col gap-1">
                {!mine && (
                  <Btn
                    kind="gold"
                    disabled={!buy.ok}
                    title={buy.reason}
                    onClick={() => mutate((st) => void buyHome(st, h.id))}
                  >
                    買う {formatMoneyShort(h.cost)}円
                  </Btn>
                )}
                {mine && !here && livable && (
                  <Btn onClick={() => mutate((st) => void moveInto(st, h.id))}>
                    住む
                  </Btn>
                )}
                {mine && (
                  <Btn
                    kind="ghost"
                    onClick={() => mutate((st) => void sellHome(st, h.id))}
                  >
                    売る {formatMoneyShort(homeSellValue(h.id))}円
                  </Btn>
                )}
              </div>
            </Row>
          );
        })}
        <p className="text-[0.72rem] text-ink-mute">
          広い家ほど休養と調子が良くなり、練習器具と車を多く置けます。住んでいない持ち家は別荘になり、シーズンのはじめに体力と調子がいっぱいに戻ります。売ると代金の
          8 割が戻ります。
        </p>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-2 p-3 text-[0.78rem]">
        <div className="panel-head">毎週のお金</div>
        <div className="space-y-0.5 text-[0.74rem]">
          <Money label="年俸（手取り）" v={Math.round(netWage(wage) / 48)} />
          <Money label="スポンサー（手取り）" v={weeklySponsorIncome(state)} />
          <Money label="CM（手取り）" v={weeklyCmIncome(state)} />
          <Money label="事業の見込み" v={bizWeek} />
          <Money label="家・車・サービス・家族" v={-weeklyCost(state)} />
          <div className="flex justify-between border-t border-line/40 pt-0.5 font-bold">
            <span>貯金</span>
            <span className="num text-gold">{formatMoney(c.money)}</span>
          </div>
        </div>
        <div className="text-[0.72rem] text-ink-dim">
          {cur.name}に住んでいます（休養 +{cur.rest}・調子 +{cur.condition}
          /週）。
          {villaHomes(state).length > 0 &&
            `別荘: ${villaHomes(state)
              .map((id) => HOUSING_BY_ID[id].name)
              .join("・")}`}
        </div>
      </div>
    </div>
  );
}

function Money({ label, v }: { label: string; v: number }) {
  return (
    <div className="flex justify-between">
      <span className="text-ink-dim">{label}</span>
      <span className={`num ${v < 0 ? "text-bad" : ""}`}>
        {v >= 0 ? "+" : ""}
        {v.toLocaleString()}万
      </span>
    </div>
  );
}

// ---------------------------------------------------------------- 車

export function CarsTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate);
  const cars = carsOf(state);
  const main = mainCarOf(state);
  return (
    <div className="panel scroll-y min-h-0 flex-1 space-y-1.5 p-3 text-[0.78rem]">
      <div className="flex items-baseline gap-2">
        <span className="panel-head">車</span>
        <span className="ml-auto text-[0.76rem] text-ink-dim">
          車庫 <b className="num text-ink">{cars.length}</b> /{" "}
          {garageSize(state)}（{housingOf(state).name}）
        </span>
      </div>
      {CARS.map((def) => {
        const own = cars.find((x) => x.id === def.id);
        const isMain = main === def.id;
        const chk = canBuyCar(state, def.id);
        const eff = [
          def.condition ? `調子 +${def.condition}` : "",
          def.stamina ? `体力 +${def.stamina}` : "",
          def.fame ? "知名度" : "",
        ]
          .filter(Boolean)
          .join("・");
        return (
          <Row
            key={def.id}
            on={!!own}
            photo={
              <LifePhoto
                id={`car_${def.id}`}
                icon="car"
                className="h-[3.2rem] w-[5.3rem]"
              />
            }
            title={
              <>
                {def.name}
                {isMain && (
                  <span className="ml-1.5 text-[0.7rem] text-good">
                    いつも乗る車
                  </span>
                )}
              </>
            }
            sub={`${def.desc}（乗る車にすると毎週 ${eff}）・維持費 毎週 ${def.weekly}万`}
          >
            <div className="flex shrink-0 flex-col gap-1">
              {!own && (
                <Btn
                  kind="gold"
                  disabled={!chk.ok}
                  title={chk.reason}
                  onClick={() => mutate((st) => void buyCar(st, def.id))}
                >
                  買う {formatMoneyShort(def.cost)}円
                </Btn>
              )}
              {own && !isMain && (
                <Btn onClick={() => mutate((st) => setMainCar(st, def.id))}>
                  これに乗る
                </Btn>
              )}
              {own && (
                <Btn
                  kind="ghost"
                  onClick={() => mutate((st) => void sellCar(st, def.id))}
                >
                  売る {formatMoneyShort(carValue(state, own))}円
                </Btn>
              )}
            </div>
          </Row>
        );
      })}
      <p className="text-[0.72rem] text-ink-mute">
        いつも乗る車の効果が毎週入ります。3
        台以上持つと、少しずつ知名度も上がります。車があると、デートで「ドライブ」に誘えます。売るときは年々値下がりします（クラシックカーは値上がり）。
      </p>
    </div>
  );
}

// ---------------------------------------------------------------- 休暇

export function VacationTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate);
  const c = state.career!;
  const comps = companionsOf(state);
  const [w, setW] = useState<Companion>(
    comps.includes("partner")
      ? "partner"
      : comps.includes("family")
        ? "family"
        : "solo",
  );
  const villas = villaHomes(state);
  const v = c.vacation;
  const pid = c.spouse ?? c.partner;
  const companionLabel = (x: Companion) =>
    (x === "partner" || x === "family") && pid
      ? `${x === "family" ? "家族" : (castName(state, pid) ?? "恋人")}と`
      : COMPANION_NAME[x];
  const book = (id: VacationId, home?: HousingId) =>
    mutate((st) => void bookVacation(st, id, w, home));
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[60%] shrink-0 space-y-1.5 p-3 text-[0.78rem]">
        <div className="panel-head">オフの旅行（シーズンの終わりに行く）</div>
        {v ? (
          <div className="flex items-center gap-2 rounded-lg bg-good/10 px-2.5 py-2">
            <LifePhoto
              id={v.id === "home" ? homePhoto(v.home!) : `trip_${v.id}`}
              icon="plane"
              className="h-[3.2rem] w-[5.3rem]"
            />
            <div className="min-w-0 flex-1">
              <div className="font-bold">
                予約済み: {placeName(v.id, v.home)}
              </div>
              <div className="text-[0.72rem] text-ink-dim">
                {companionLabel(v.with)}・{formatMoneyShort(v.cost)}
                円（取り消すと全額戻ります）
              </div>
            </div>
            <Btn
              kind="ghost"
              onClick={() => mutate((st) => cancelVacation(st))}
            >
              取り消す
            </Btn>
          </div>
        ) : (
          <>
            <div className="seg">
              {comps.map((x) => (
                <button key={x} aria-selected={w === x} onClick={() => setW(x)}>
                  {companionLabel(x)}
                </button>
              ))}
            </div>
            {villas.map((h) => {
              const chk = canBookVacation(state, "home", w, h);
              return (
                <Row
                  key={h}
                  photo={
                    <LifePhoto
                      id={homePhoto(h)}
                      icon="home"
                      className="h-[3rem] w-[5rem]"
                    />
                  }
                  title={`別荘（${HOUSING_BY_ID[h].name}）で過ごす`}
                  sub="交通費だけ。のんびり休める"
                >
                  <Btn
                    disabled={!chk.ok}
                    title={chk.reason}
                    onClick={() => book("home", h)}
                  >
                    {formatMoneyShort(vacationCost(state, "home", w, h))}円
                  </Btn>
                </Row>
              );
            })}
            {VACATIONS.map((d) => {
              const chk = canBookVacation(state, d.id, w);
              return (
                <Row
                  key={d.id}
                  photo={
                    <LifePhoto
                      id={`trip_${d.id}`}
                      icon="plane"
                      className="h-[3rem] w-[5rem]"
                    />
                  }
                  title={d.name}
                  sub={`${d.desc}（精神 +${d.mental}・新シーズンの調子 +${d.boost}${w === "partner" || w === "family" ? `・絆 +${d.bond}` : ""}）`}
                >
                  <Btn
                    disabled={!chk.ok}
                    title={chk.reason}
                    onClick={() => book(d.id)}
                  >
                    {formatMoneyShort(vacationCost(state, d.id, w))}円
                  </Btn>
                </Row>
              );
            })}
          </>
        )}
        <p className="text-[0.72rem] text-ink-mute">
          費用は人数ぶん。チームの仲間とは割り勘で、監督の評価も少し上がります。オフの自主トレ合宿と両方行けます。
        </p>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-1.5 p-3 text-[0.78rem]">
        <div className="panel-head">
          思い出のアルバム（{(c.memories ?? []).length}）
        </div>
        {(c.memories ?? []).length === 0 && (
          <div className="text-[0.76rem] text-ink-dim">
            まだ旅の思い出はありません。
          </div>
        )}
        <div className="grid grid-cols-2 gap-1.5">
          {[...(c.memories ?? [])].reverse().map((m, i) => (
            <div key={i} className="overflow-hidden rounded-lg bg-white/[0.04]">
              <LifePhoto
                id={m.dest === "home" ? homePhoto(m.home!) : `trip_${m.dest}`}
                icon="plane"
                className="aspect-[5/3] w-full !rounded-none"
              />
              <div className="px-2 py-1">
                <div className="font-bold">{placeName(m.dest, m.home)}</div>
                <div className="text-[0.7rem] text-ink-dim">
                  {seasonLabel(state.startYear, m.season)}のオフ・
                  {m.partner
                    ? `${castName(state, m.partner) ?? ""}と`
                    : COMPANION_NAME[m.with]}
                  {m.with === "family" ? "（家族旅行）" : ""}
                </div>
              </div>
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}

// ---------------------------------------------------------------- メディア

export function MediaTab({ state, onDone }: { state: GameState; onDone?: () => void }) {
  const mutate = useGame((s) => s.mutate);
  const c = state.career!;
  const o = c.mediaOffer;
  const cms = cmsOf(state);
  const history = [...(c.media ?? [])].reverse();
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[55%] shrink-0 space-y-2 p-3 text-[0.78rem]">
        <div className="flex items-baseline gap-2">
          <span className="panel-head">テレビ・雑誌・CM</span>
          <span className="ml-auto text-[0.76rem] text-ink-dim">
            知名度 <b className="num text-ink">{Math.floor(c.fame)}</b>
          </span>
        </div>
        {o ? (
          <div className="rounded-lg border border-gold/50 bg-gold/5 px-2.5 py-2">
            <div className="text-[0.72rem] text-ink-dim">
              依頼（{MEDIA_BY_KIND[o.kind].name}）
            </div>
            <div className="font-bold">{o.name}</div>
            <div className="num text-[0.76rem]">
              {o.kind === "cm"
                ? `年 ${formatMoney(o.pay)}（1 シーズン契約）`
                : o.kind === "book"
                  ? `印税 ${formatMoney(o.pay)}（3 シーズンに分けて）`
                  : `出演料 ${formatMoney(o.pay)}`}
              ・体力 {MEDIA_BY_KIND[o.kind].stamina}
              {MEDIA_BY_KIND[o.kind].trust
                ? `・監督の評価 ${MEDIA_BY_KIND[o.kind].trust}`
                : ""}
            </div>
            <div className="mt-1 flex gap-1.5">
              <button
                className="btn btn-ghost btn-sm flex-1"
                onClick={() => {
                  mutate((st) => declineMedia(st));
                  onDone?.();
                }}
              >
                断る
              </button>
              <button
                className="btn btn-gold btn-sm flex-1"
                onClick={() => {
                  mutate((st) => void acceptMedia(st));
                  onDone?.();
                }}
              >
                引き受ける
              </button>
            </div>
          </div>
        ) : (
          <div className="text-[0.78rem] text-ink-dim">
            いまは依頼がありません。知名度が上がると、月に 1 回ほど届きます。
          </div>
        )}
        <div className="panel-head pt-1">CM の契約（{cms.length} / 2）</div>
        {cms.length === 0 && (
          <div className="text-[0.76rem] text-ink-mute">
            なし（知名度 45 から依頼が来ます）
          </div>
        )}
        {cms.map((x) => (
          <Row
            key={x.company}
            on
            title={x.company}
            sub={`年 ${formatMoney(x.annual)}・${x.until === state.season ? "今季まで" : "来季まで"}`}
          />
        ))}
        {c.book && (
          <Row
            on
            title="自伝の印税"
            sub={`毎シーズン ${formatMoney(c.book.royalty)}・${seasonLabel(state.startYear, c.book.until)}まで`}
          />
        )}
        <div className="panel-head pt-1">依頼の種類</div>
        <div className="space-y-0.5 text-[0.72rem] text-ink-dim">
          {MEDIA.map((m) => (
            <div key={m.kind}>
              {m.name}（知名度 {m.minFame}〜
              {m.kind === "overseas"
                ? "・海外のクラブにいるとき"
                : m.kind === "documentary"
                  ? "・タイトルか欧州の強豪"
                  : m.kind === "book"
                    ? "・28 歳から一度だけ"
                    : ""}
              ）
            </div>
          ))}
        </div>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-1 p-3 text-[0.78rem]">
        <div className="panel-head">出演歴（{history.length}）</div>
        {history.length === 0 && (
          <div className="text-[0.76rem] text-ink-dim">まだありません。</div>
        )}
        {history.map((r, i) => (
          <div
            key={i}
            className="flex items-baseline gap-2 rounded-lg bg-white/[0.04] px-2 py-1"
          >
            <span className="num shrink-0 text-[0.68rem] text-ink-mute">
              {seasonLabel(state.startYear, r.season)}
            </span>
            <span className="min-w-0 flex-1 truncate font-bold">{r.name}</span>
            <span className="shrink-0 text-[0.7rem] text-ink-dim">
              {MEDIA_BY_KIND[r.kind].name}
            </span>
          </div>
        ))}
      </div>
    </div>
  );
}

// ---------------------------------------------------------------- 家族

export function FamilyTab({ state }: { state: GameState }) {
  const c = state.career!;
  const kids = c.children ?? [];
  const spouse = c.spouse;
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[55%] shrink-0 space-y-2 p-3 text-[0.78rem]">
        <div className="panel-head">家族</div>
        {spouse ? (
          <div className="flex items-center gap-2.5">
            <Portrait
              id={castPhotoId(spouse, spouse)}
              kind="face"
              className="face-round h-12 w-12 shrink-0"
            />
            <div>
              <div className="font-bold">{castName(state, spouse)}</div>
              <div className="text-[0.72rem] text-ink-dim">
                妻・絆 {Math.floor(c.bonds[spouse]?.value ?? 0)}
              </div>
            </div>
          </div>
        ) : c.partner ? (
          <div className="text-[0.78rem] text-ink-dim">
            恋人: <b className="text-ink">{castName(state, c.partner)}</b>
            {housingOf(state).grade === 0 &&
              "（ふたりで暮らすには、寮を出る必要があります）"}
          </div>
        ) : (
          <div className="text-[0.78rem] text-ink-dim">まだひとりです。</div>
        )}
        {kids.map((k) => {
          const age = childAge(state, k);
          // 過ぎた節目（2 歳以上前）は起きない（career/children.ts と同じ決まり）
          const next = CHILD_MILESTONES.find(
            (m) =>
              !(k.done ?? []).includes(m.id) &&
              (!m.soccer || k.soccer) &&
              age < m.age + 2,
          );
          return (
            <div
              key={k.name}
              className="rounded-lg bg-white/[0.04] px-2.5 py-1.5"
            >
              <div className="flex items-baseline gap-2">
                <span className="font-bold">{k.name}</span>
                <span className="num text-[0.76rem] text-ink-dim">{age} 歳</span>
                {k.soccer && (
                  <span className="ml-auto text-[0.72rem] text-gold">
                    サッカー {"★".repeat(Math.max(1, k.talent ?? 0))}
                  </span>
                )}
              </div>
              {next && (
                <div className="text-[0.7rem] text-ink-mute">
                  次の節目: {next.age} 歳
                </div>
              )}
            </div>
          );
        })}
        {spouse && (
          <div className="text-[0.72rem] text-ink-dim">
            家族の生活費 毎週 {familyCost(state)}万円
          </div>
        )}
        <p className="text-[0.72rem] text-ink-mute">
          子どもが大きくなると、はじめての一歩・入学式・サッカーを始める日などの出来事があります。庭のある家やミニバンだと、家族の出来事が少し増えます。
        </p>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-1 p-3 text-[0.78rem]">
        <div className="panel-head">家族の行事（今シーズン）</div>
        {!spouse && (
          <div className="text-[0.76rem] text-ink-dim">
            結婚すると、季節の行事を家族で過ごせます。
          </div>
        )}
        {spouse &&
          FAMILY_EVENTS.filter((e) => !e.kids || kids.length).map((e) => {
            const done = c.familyEvents?.[e.id] === state.season;
            return (
              <div
                key={e.id}
                className={`flex items-center gap-2 rounded-lg px-2 py-1 ${done ? "bg-good/10" : "bg-white/[0.04]"}`}
              >
                <span className="num w-[2.4rem] shrink-0 text-[0.72rem] text-ink-dim">
                  {e.month}月
                </span>
                <span className="flex-1 font-bold">{e.name}</span>
                <span className="text-[0.7rem] text-ink-dim">
                  {done ? "済み" : "これから"}
                </span>
              </div>
            );
          })}
      </div>
    </div>
  );
}
