/**
 * 成長の見込みのグラフ（SVG）。横軸は年齢 18〜40、縦軸は OVR。
 *   player: これまで（実線）・今・見込み（破線と幅）・ピーク年齢の帯。タップした年齢の値を出す
 *   types : 成長タイプごとの基準の曲線（選んだタイプを濃く、ほかを薄く）。作成画面用
 * 当たり判定は年齢ごとの縦の帯（回転表示でも座標の計算がいらない）。
 */
import { useState } from 'react'
import { GROWTH_DEFS, type GrowthType } from '../../engine/data/growth'
import { PROJ_MAX_AGE, PROJ_MIN_AGE, typeCurve, type ProjPoint, type Projection } from '../../engine/career/projection'

const W = 360
const H = 168
const PAD = { l: 24, r: 10, t: 8, b: 18 }
const GOLD = 'var(--color-gold)'
const ACCENT = 'var(--color-accent)'

const x = (age: number) => PAD.l + ((age - PROJ_MIN_AGE) / (PROJ_MAX_AGE - PROJ_MIN_AGE)) * (W - PAD.l - PAD.r)

function yScale(values: number[]) {
  const lo = Math.max(30, Math.floor((Math.min(...values) - 3) / 10) * 10)
  const hi = Math.min(100, Math.ceil((Math.max(...values) + 3) / 10) * 10)
  const y = (v: number) => PAD.t + (1 - (v - lo) / (hi - lo)) * (H - PAD.t - PAD.b)
  const ticks: number[] = []
  for (let v = lo; v <= hi; v += 10) ticks.push(v)
  return { y, ticks }
}

/** ピーク年齢の範囲（「26〜29歳」から） */
function peakRange(type: GrowthType): [number, number] {
  const m = GROWTH_DEFS[type].peak.match(/(\d+)\D+(\d+)/)
  return m ? [Number(m[1]), Number(m[2])] : [26, 29]
}

/** いちばん高い点（タイプの名前をそこに書く。曲線の端だと名前が重なるため） */
const top = (pts: ProjPoint[]) => pts.reduce((m, p) => (p.ovr > m.ovr ? p : m), pts[0])

const path = (pts: ProjPoint[], y: (v: number) => number) => pts.map((p, i) => `${i ? 'L' : 'M'}${x(p.age).toFixed(1)},${y(p.ovr).toFixed(1)}`).join('')

function Axes({ y, ticks }: { y: (v: number) => number; ticks: number[] }) {
  return (
    <g>
      {ticks.map((t) => (
        <g key={t}>
          <line x1={PAD.l} x2={W - PAD.r} y1={y(t)} y2={y(t)} stroke="var(--color-line)" strokeOpacity={0.55} strokeWidth={0.6} />
          <text x={PAD.l - 4} y={y(t) + 3} textAnchor="end" fontSize={8} fill="var(--color-ink-mute)">
            {t}
          </text>
        </g>
      ))}
      {Array.from({ length: (PROJ_MAX_AGE - PROJ_MIN_AGE) / 2 + 1 }, (_, i) => PROJ_MIN_AGE + i * 2).map((a) => (
        <text key={a} x={x(a)} y={H - 5} textAnchor="middle" fontSize={8} fill="var(--color-ink-mute)">
          {a}
        </text>
      ))}
    </g>
  )
}

/** 年齢ごとの縦の帯（タップでその年齢を選ぶ） */
function HitColumns({ onPick }: { onPick: (age: number | null) => void }) {
  const step = x(PROJ_MIN_AGE + 1) - x(PROJ_MIN_AGE)
  return (
    <g onPointerLeave={() => onPick(null)}>
      {Array.from({ length: PROJ_MAX_AGE - PROJ_MIN_AGE + 1 }, (_, i) => PROJ_MIN_AGE + i).map((a) => (
        <rect key={a} x={x(a) - step / 2} y={0} width={step} height={H} fill="transparent" onPointerEnter={() => onPick(a)} onPointerDown={() => onPick(a)} />
      ))}
    </g>
  )
}

function Tip({ age, lines, y0 }: { age: number; lines: string[]; y0: number }) {
  const left = x(age) > W - 110
  const bx = left ? x(age) - 96 : x(age) + 6
  return (
    <g pointerEvents="none">
      <line x1={x(age)} x2={x(age)} y1={PAD.t} y2={H - PAD.b} stroke="var(--color-ink-dim)" strokeOpacity={0.6} strokeWidth={0.8} />
      <rect x={bx} y={Math.max(PAD.t, y0 - 14)} width={90} height={12 + lines.length * 11} rx={4} fill="#0b1320" fillOpacity={0.92} stroke="var(--color-line)" />
      {lines.map((t, i) => (
        <text key={i} x={bx + 6} y={Math.max(PAD.t, y0 - 14) + 12 + i * 11} fontSize={8.5} fill={i ? 'var(--color-ink-dim)' : 'var(--color-ink)'} fontWeight={i ? 400 : 700}>
          {t}
        </text>
      ))}
    </g>
  )
}

function Legend({ items }: { items: { label: string; color: string; dash?: boolean; band?: boolean }[] }) {
  return (
    <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5 text-[0.68rem] text-ink-dim">
      {items.map((it) => (
        <span key={it.label} className="flex items-center gap-1">
          <svg width="16" height="8" aria-hidden>
            {it.band ? <rect x="0" y="0" width="16" height="8" fill={it.color} fillOpacity={0.18} /> : <line x1="0" x2="16" y1="4" y2="4" stroke={it.color} strokeWidth="2" strokeDasharray={it.dash ? '3 2' : undefined} />}
          </svg>
          {it.label}
        </span>
      ))}
    </div>
  )
}

/** 主人公の見込み */
export function GrowthChart({ proj, type, className = '' }: { proj: Projection; type: GrowthType; className?: string }) {
  const [pick, setPick] = useState<number | null>(null)
  const all = [...proj.past, proj.now, ...proj.future]
  const { y, ticks } = yScale([...all.map((p) => p.ovr), ...proj.future.map((p) => p.hi ?? p.ovr), ...proj.future.map((p) => p.lo ?? p.ovr)])
  const [p0, p1] = peakRange(type)
  const fut = [proj.now, ...proj.future]
  const band = `${fut.map((p, i) => `${i ? 'L' : 'M'}${x(p.age)},${y(p.hi ?? p.ovr)}`).join('')}${[...fut]
    .reverse()
    .map((p) => `L${x(p.age)},${y(p.lo ?? p.ovr)}`)
    .join('')}Z`
  const past = [...proj.past.filter((p) => p.age < proj.now.age), proj.now]
  const at = pick === null ? null : (all.find((p) => Math.round(p.age) === pick) ?? null)
  const fp = pick === null ? undefined : proj.future.find((p) => p.age === pick)
  return (
    <div className={className}>
      <Legend
        items={[
          { label: 'これまで', color: GOLD },
          { label: '見込み（幅は目安）', color: ACCENT, dash: true },
          { label: `ピーク ${GROWTH_DEFS[type].peak}`, color: GOLD, band: true },
        ]}
      />
      <svg viewBox={`0 0 ${W} ${H}`} className="block w-full" role="img" aria-label={`成長の見込み。いま ${proj.now.age} 歳 OVR ${proj.now.ovr}、見込みのピークは ${proj.peak.age} 歳ごろ OVR ${proj.peak.ovr}`}>
        <rect x={x(p0)} y={PAD.t} width={x(p1) - x(p0)} height={H - PAD.t - PAD.b} fill={GOLD} fillOpacity={0.08} />
        <Axes y={y} ticks={ticks} />
        <path d={band} fill={ACCENT} fillOpacity={0.15} />
        <path d={path(fut, y)} fill="none" stroke={ACCENT} strokeWidth={2} strokeDasharray="5 3" strokeLinejoin="round" />
        {past.length > 1 && <path d={path(past, y)} fill="none" stroke={GOLD} strokeWidth={2} strokeLinejoin="round" />}
        {proj.past.map((p, i) => (
          <circle key={i} cx={x(p.age)} cy={y(p.ovr)} r={2.6} fill={GOLD} />
        ))}
        <circle cx={x(proj.now.age)} cy={y(proj.now.ovr)} r={4.5} fill={GOLD} stroke="var(--color-panel)" strokeWidth={2} />
        <text x={x(proj.now.age)} y={y(proj.now.ovr) - 8} textAnchor="middle" fontSize={8.5} fontWeight={700} fill="var(--color-ink)">
          いま {proj.now.ovr}
        </text>
        {proj.peak !== proj.now && (
          <text x={x(proj.peak.age)} y={y(proj.peak.ovr) - 7} textAnchor="middle" fontSize={8} fill="var(--color-ink-dim)">
            {proj.peak.ovr}
          </text>
        )}
        {at && pick !== null && <Tip age={pick} y0={y(at.ovr)} lines={[`${pick} 歳`, fp ? `見込み ${fp.ovr}（${fp.lo}〜${fp.hi}）` : `OVR ${at.ovr}`]} />}
        <HitColumns onPick={setPick} />
      </svg>
    </div>
  )
}

/** 成長タイプごとの基準の曲線（作成画面） */
export function TypeCurves({ types, selected, className = '' }: { types: GrowthType[]; selected?: GrowthType; className?: string }) {
  const [pick, setPick] = useState<number | null>(null)
  const curves = types.map((t) => ({ t, pts: typeCurve(t) }))
  const { y, ticks } = yScale(curves.flatMap((c) => c.pts.map((p) => p.ovr)))
  const sel = curves.find((c) => c.t === selected)
  const [p0, p1] = selected ? peakRange(selected) : [0, 0]
  const at = pick !== null && sel ? sel.pts.find((p) => p.age === pick) : undefined
  return (
    <div className={className}>
      <svg viewBox={`0 0 ${W} ${H}`} className="block w-full" role="img" aria-label="成長タイプごとの成長の目安">
        {selected && <rect x={x(p0)} y={PAD.t} width={x(p1) - x(p0)} height={H - PAD.t - PAD.b} fill={GOLD} fillOpacity={0.08} />}
        <Axes y={y} ticks={ticks} />
        {curves
          .filter((c) => c.t !== selected)
          .map((c) => (
            <g key={c.t}>
              <path d={path(c.pts, y)} fill="none" stroke="var(--color-ink-mute)" strokeOpacity={0.7} strokeWidth={1.4} />
              <text x={x(top(c.pts).age)} y={y(top(c.pts).ovr) - 4} textAnchor="middle" fontSize={7.5} fill="var(--color-ink-mute)">
                {GROWTH_DEFS[c.t].name}
              </text>
            </g>
          ))}
        {sel && (
          <g>
            <path d={path(sel.pts, y)} fill="none" stroke={GOLD} strokeWidth={2.2} strokeLinejoin="round" />
            <text x={x(top(sel.pts).age)} y={y(top(sel.pts).ovr) - 5} textAnchor="middle" fontSize={8.5} fontWeight={700} fill="var(--color-ink)">
              {GROWTH_DEFS[sel.t].name}
            </text>
          </g>
        )}
        {at && pick !== null && <Tip age={pick} y0={y(at.ovr)} lines={[`${pick} 歳`, `目安 OVR ${at.ovr}`]} />}
        <HitColumns onPick={setPick} />
      </svg>
    </div>
  )
}
