/** 戦術のプリセット。 */
import type { Tactics } from '../models/club'

export interface TacticPreset {
  id: string
  name: string
  desc: string
  values: Omit<Tactics, 'formation'>
}

export const TACTIC_PRESETS: TacticPreset[] = [
  { id: 'balance', name: 'バランス', desc: '攻守の切り替えを重視する標準的な戦い方', values: { mentality: 0, tempo: 50, width: 50, lineHeight: 50, pressing: 50, focus: 'balanced', offsideTrap: false, counter: false } },
  { id: 'possession', name: 'ポゼッション', desc: 'パスをつないでボールを保持し、相手を動かす', values: { mentality: 0, tempo: 32, width: 62, lineHeight: 62, pressing: 58, focus: 'balanced', offsideTrap: false, counter: false } },
  { id: 'counter', name: 'カウンター', desc: '引いて守り、奪ったら素早く前へ', values: { mentality: -1, tempo: 75, width: 48, lineHeight: 32, pressing: 40, focus: 'balanced', offsideTrap: false, counter: true } },
  { id: 'wing', name: 'サイドアタック', desc: '幅を取ってクロスを多く入れる', values: { mentality: 0, tempo: 58, width: 85, lineHeight: 52, pressing: 52, focus: 'balanced', offsideTrap: false, counter: false } },
  { id: 'center', name: '中央突破', desc: '狭いエリアでのコンビネーションで崩す', values: { mentality: 1, tempo: 55, width: 32, lineHeight: 58, pressing: 55, focus: 'center', offsideTrap: false, counter: false } },
  { id: 'highPress', name: 'ハイプレス', desc: '前線から激しく奪いに行く。体力の消耗が大きい', values: { mentality: 1, tempo: 66, width: 55, lineHeight: 74, pressing: 88, focus: 'balanced', offsideTrap: true, counter: false } },
  { id: 'defensive', name: '堅守速攻', desc: '守備ブロックを固め、少ない人数で攻める', values: { mentality: -2, tempo: 60, width: 40, lineHeight: 28, pressing: 32, focus: 'balanced', offsideTrap: false, counter: true } },
  { id: 'longball', name: 'ロングボール', desc: '前線へ早めにボールを送る', values: { mentality: 0, tempo: 80, width: 58, lineHeight: 45, pressing: 50, focus: 'balanced', offsideTrap: false, counter: false } },
]

/** 今の戦術にいちばん近いプリセット */
export function closestPreset(t: Tactics): TacticPreset | undefined {
  return TACTIC_PRESETS.find((p) => Object.entries(p.values).every(([k, v]) => t[k as keyof Tactics] === v))
}
