/** 練習: メニューの配分・強度・個別練習とコンバート・合宿。 */
import { useState } from 'react'
import {
  CAMP_PLACES,
  INTENSITY,
  MENU_BY_ID,
  POSITIONS,
  TRAINING_MENUS,
  aptMark,
  defaultTraining,
  ovr,
  playerClub,
  squadOf,
  type Player,
  type Position,
  type TrainingIntensity,
  type TrainingPlan,
} from '../../engine'
import { campCost, canPlanCamp, planCamp } from '../../engine/growth/camp'
import { absWeekOf } from '../../engine'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { SideSheet } from '../layout/SideSheet'
import { OvrBadge, PosBadge } from '../components/common'
import { PlayerFace } from '../components/PersonFace'
import { useGame, useGameState } from '../../stores/gameStore'
import { formatMoney } from '../format'
import { TourPanel } from '../club/TourPanel'

function Pips({ value, onChange }: { value: number; onChange: (v: number) => void }) {
  return (
    <div className="flex gap-1">
      {[0, 1, 2, 3, 4, 5].map((v) => (
        <button key={v} onClick={() => onChange(v)} aria-label={`${v}`} className={`h-7 w-6 rounded-md border ${v === 0 ? 'text-[0.68rem] text-ink-mute' : ''} ${v <= value && v > 0 ? 'border-gold bg-gold/80' : 'border-line/60 bg-black/30'}`}>
          {v === 0 ? '0' : ''}
        </button>
      ))}
    </div>
  )
}

export function TrainingScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const club = playerClub(state)
  const plan: TrainingPlan = club.training ?? defaultTraining()
  const [sel, setSel] = useState<Player | null>(null)
  const [campPlace, setCampPlace] = useState(CAMP_PLACES[0].id)
  const [campWeeks, setCampWeeks] = useState(1)
  const setPlan = (fn: (p: TrainingPlan) => TrainingPlan) =>
    mutate((st) => {
      const c = st.clubs[st.playerClubId]
      c.training = fn(c.training ?? defaultTraining())
    })
  const total = Object.values(plan.weights).reduce((s, w) => s + w, 0) || 1
  const squad = squadOf(state, club.id).sort((a, b) => POSITIONS.indexOf(a.pos) - POSITIONS.indexOf(b.pos))
  const now = absWeekOf(state.season, state.week)
  const inCamp = club.camp && now >= club.camp.startAbsWeek && now < club.camp.startAbsWeek + club.camp.weeks
  const campOk = canPlanCamp(state, club)
  const place = CAMP_PLACES.find((c) => c.id === campPlace)!

  return (
    <AppShell title="練習" current="training" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="panel scroll-y flex w-[46%] shrink-0 flex-col p-3">
          <div className="panel-head mb-1.5">練習の強度</div>
          <div className="seg w-full">
            {INTENSITY.map((it, i) => (
              <button key={it.label} className="flex-1" aria-selected={plan.intensity === i} onClick={() => setPlan((p) => ({ ...p, intensity: i as TrainingIntensity }))}>
                {it.label}
              </button>
            ))}
          </div>
          <p className="mt-1 text-[0.76rem] text-ink-dim">{INTENSITY[plan.intensity].desc}</p>
          <div className="panel-head mb-1 mt-3">メニューの配分</div>
          <div className="space-y-1.5">
            {TRAINING_MENUS.map((m) => {
              const w = plan.weights[m.id] ?? 0
              return (
                <div key={m.id} className="flex items-center gap-2">
                  <div className="w-[5.6rem] shrink-0">
                    <div className="text-[0.82rem] font-bold">{m.name}</div>
                    <div className="truncate text-[0.68rem] text-ink-mute">{m.desc}</div>
                  </div>
                  <Pips value={w} onChange={(v) => setPlan((p) => ({ ...p, weights: { ...p.weights, [m.id]: v } }))} />
                  <span className="num ml-auto w-9 text-right text-[0.78rem] text-ink-dim">{Math.round((w / total) * 100)}%</span>
                </div>
              )
            })}
          </div>
        </div>

        <div className="flex min-w-0 flex-1 flex-col gap-3">
          <div className="panel p-3">
            <div className="panel-head mb-1.5">合宿</div>
            {inCamp ? (
              <div className="text-[0.82rem]">
                {club.camp!.place}で合宿中（あと {club.camp!.startAbsWeek + club.camp!.weeks - now} 週）。成長が伸び、チームのまとまりが深まります。
              </div>
            ) : campOk ? (
              <div className="space-y-1.5">
                {/* 場所は 1 行に並べ、週数と費用は次の行（狭い画面で文字が重ならないように） */}
                <div className="grid grid-cols-5 gap-1">
                  {CAMP_PLACES.map((c) => (
                    <button key={c.id} onClick={() => setCampPlace(c.id)} title={c.desc} className={`min-w-0 rounded-md border px-1 py-1 text-[0.76rem] font-bold leading-tight ${campPlace === c.id ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      <span className="block truncate">{c.name}</span>
                      <span className="block text-[0.66rem] font-normal text-ink-dim">{c.abroad ? '海外' : '国内'}</span>
                    </button>
                  ))}
                </div>
                <div className="flex items-center gap-2">
                  <span className="min-w-0 flex-1 truncate text-[0.72rem] text-ink-dim">{place.desc}</span>
                  <div className="seg shrink-0">
                    {[1, 2].map((w) => (
                      <button key={w} aria-selected={campWeeks === w} onClick={() => setCampWeeks(w)}>
                        {w}週
                      </button>
                    ))}
                  </div>
                  <button className="btn btn-gold btn-sm shrink-0" disabled={club.budget < campCost(state, club, place, campWeeks)} onClick={() => mutate((st) => void planCamp(st, st.clubs[st.playerClubId], campPlace, campWeeks))}>
                    {formatMoney(campCost(state, club, place, campWeeks))}
                  </button>
                </div>
              </div>
            ) : (
              <div className="text-[0.75rem] text-ink-dim">合宿はプレシーズン（8月）とウインターブレイク（1月）に組めます。</div>
            )}
          </div>

          {state.week <= 2 && <TourPanel state={state} />}
          <div className="panel flex min-h-0 flex-1 flex-col p-3">
            <div className="panel-head mb-1">個別練習・コンバート（選手をタップ）</div>
            <div className="scroll-y min-h-0 flex-1 space-y-1 pr-1">
              {squad.map((p) => {
                const ind = plan.individual[p.id]
                return (
                  <button key={p.id} onClick={() => setSel(p)} className="flex w-full items-center gap-2 rounded-lg bg-white/[0.04] px-1.5 py-1 text-left hover:bg-white/[0.08]">
                    <PlayerFace p={p} kit={club.colors} className="h-8 w-8 shrink-0" />
                    <PosBadge pos={p.pos} />
                    <span className="min-w-0 flex-1 truncate text-[0.8rem] font-bold">{p.name}</span>
                    {ind?.menu && <span className="rounded bg-accent/20 px-1.5 text-[0.7rem] font-bold text-accent">{MENU_BY_ID[ind.menu]?.name}</span>}
                    {ind?.convert && (
                      <span className="rounded bg-gold/20 px-1.5 text-[0.7rem] font-bold text-gold">
                        →{ind.convert} {aptMark(p.apt[ind.convert])}
                      </span>
                    )}
                    <OvrBadge value={ovr(p)} size="sm" />
                  </button>
                )
              })}
            </div>
          </div>
        </div>
      </div>

      <SideSheet open={!!sel} onClose={() => setSel(null)} title={sel ? `${sel.name} の個別練習` : ''} width="54%">
        {sel && (
          <div className="space-y-3 p-3">
            <div>
              <div className="panel-head mb-1">重点メニュー</div>
              <div className="grid grid-cols-3 gap-1">
                <button
                  onClick={() => setPlan((p) => ({ ...p, individual: { ...p.individual, [sel.id]: { ...p.individual[sel.id], menu: undefined } } }))}
                  className={`rounded-md border py-1.5 text-[0.78rem] font-bold ${!plan.individual[sel.id]?.menu ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}
                >
                  なし
                </button>
                {TRAINING_MENUS.filter((m) => !m.gkOnly || sel.pos === 'GK').map((m) => (
                  <button
                    key={m.id}
                    onClick={() => setPlan((p) => ({ ...p, individual: { ...p.individual, [sel.id]: { ...p.individual[sel.id], menu: m.id } } }))}
                    className={`rounded-md border py-1.5 text-[0.78rem] font-bold ${plan.individual[sel.id]?.menu === m.id ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}
                  >
                    {m.name}
                  </button>
                ))}
              </div>
            </div>
            {sel.pos !== 'GK' && (
              <div>
                <div className="panel-head mb-1">コンバート（適性を上げるポジション）</div>
                <div className="grid grid-cols-5 gap-1">
                  {POSITIONS.filter((p) => p !== 'GK').map((pos: Position) => {
                    const cur = plan.individual[sel.id]?.convert === pos
                    return (
                      <button
                        key={pos}
                        onClick={() => setPlan((p) => ({ ...p, individual: { ...p.individual, [sel.id]: { ...p.individual[sel.id], convert: cur || pos === sel.pos ? undefined : pos } } }))}
                        className={`flex flex-col items-center rounded-md border py-1 text-[0.78rem] font-bold ${cur ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}
                      >
                        {pos}
                        <span className="text-[0.7rem] font-normal">{aptMark(sel.apt[pos])}</span>
                      </button>
                    )
                  })}
                </div>
                <p className="mt-1 text-[0.74rem] text-ink-dim">練習場のレベルが高く、若いほど早く身につきます。</p>
              </div>
            )}
          </div>
        )}
      </SideSheet>
    </AppShell>
  )
}
