/** キャラクター図鑑（画像の確認も兼ねる）。 */
import { useState } from 'react'
import { HEROINES, NATION_NAME, STAR_PLAYERS, STAR_STAFF, type HeroineDef, type StarPlayerDef, type StarStaffDef } from '../../engine/data/cast'
import { Portrait } from '../components/Portrait'
import { genIds } from '../components/portraits'
import { PlayerAvatar } from '../components/PlayerAvatar'
import { SideSheet } from '../layout/SideSheet'
import { Icon } from '../components/Icon'
import { useUi } from '../../stores/uiStore'
import type { Mood } from '../../engine/models/face'

type Tab = 'heroine' | 'player' | 'staff' | 'mob'
type Selected = { kind: 'heroine'; d: HeroineDef } | { kind: 'player'; d: StarPlayerDef } | { kind: 'staff'; d: StarStaffDef } | null

const LINE_COLOR: Record<string, string> = { FW: '#ff5a5f', MF: '#3ddc84', DF: '#3aa0ff', GK: '#f5c542' }
const MOB_KITS = [
  { primary: '#1d4ed8', secondary: '#ffffff' },
  { primary: '#b91c1c', secondary: '#fde047' },
  { primary: '#065f46', secondary: '#ffffff' },
  { primary: '#111827', secondary: '#f5c542' },
  { primary: '#7c3aed', secondary: '#ffffff' },
  { primary: '#f97316', secondary: '#1e293b' },
]
const MOB_NATIONS = ['JP', 'BR', 'EN', 'ES', 'DE', 'NG', 'FR', 'SA', 'AR', 'IT', 'KR', 'NL']
const MOODS: Mood[] = ['happy', 'normal', 'normal', 'flat', 'sad', 'hurt']
const GEN_SETS: [string, string][] = [
  ['protag', '主人公の顔（キャリアモードで選べる）'],
  ['pool', '一般の選手・スタッフ（自クラブと同じリーグの主力に使う）'],
]

export function GalleryScreen() {
  const pop = useUi((s) => s.pop)
  const [tab, setTab] = useState<Tab>('heroine')
  const [sel, setSel] = useState<Selected>(null)

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-3" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-white/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">ギャラリー</h1>
        <div className="seg ml-auto" role="tablist">
          {(
            [
              ['heroine', `ヒロイン ${HEROINES.length}`],
              ['player', `選手 ${STAR_PLAYERS.length}`],
              ['staff', `スタッフ ${STAR_STAFF.length}`],
              ['mob', '一般'],
            ] as [Tab, string][]
          ).map(([id, label]) => (
            <button key={id} role="tab" aria-selected={tab === id} onClick={() => setTab(id)}>
              {label}
            </button>
          ))}
        </div>
      </header>

      <div className="scroll-y safe-px safe-pb min-h-0 flex-1 pt-3">
        {tab === 'heroine' && (
          <div className="grid gap-2.5" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(7.4rem, 1fr))' }}>
            {HEROINES.map((h, i) => (
              <button key={h.id} className="card-hover anim-rise overflow-hidden rounded-xl border border-pink/30 bg-panel text-left" style={{ animationDelay: `${i * 0.02}s` }} onClick={() => setSel({ kind: 'heroine', d: h })}>
                <Portrait id={h.id} kind="bust" className="aspect-[3/4] w-full" />
                <div className="px-2 py-1.5">
                  <div className="truncate text-[0.9rem] font-extrabold">{h.name}</div>
                  <div className="truncate text-[0.74rem] text-ink-dim">
                    {h.age}歳・{h.role}
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}

        {tab === 'player' && (
          <div className="grid gap-2.5" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(9.5rem, 1fr))' }}>
            {STAR_PLAYERS.map((p, i) => (
              <button key={p.id} className="card-hover anim-rise overflow-hidden rounded-xl border border-line bg-panel text-left" style={{ animationDelay: `${i * 0.015}s` }} onClick={() => setSel({ kind: 'player', d: p })}>
                <div className="relative">
                  <Portrait id={p.id} kind="photo" className="aspect-[3/2] w-full" />
                  <span className="absolute bottom-1 left-1 rounded px-1.5 text-[0.76rem] font-black text-white" style={{ background: LINE_COLOR[p.line] }}>
                    {p.line} {p.number}
                  </span>
                </div>
                <div className="px-2 py-1.5">
                  <div className="truncate text-[0.82rem] font-extrabold">{p.name}</div>
                  <div className="truncate text-[0.74rem] text-ink-dim">
                    {p.age}歳・{NATION_NAME[p.nation]}
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}

        {tab === 'staff' && (
          <div className="grid gap-2.5" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(9.5rem, 1fr))' }}>
            {STAR_STAFF.map((s, i) => (
              <button key={s.id} className="card-hover anim-rise overflow-hidden rounded-xl border border-line bg-panel text-left" style={{ animationDelay: `${i * 0.02}s` }} onClick={() => setSel({ kind: 'staff', d: s })}>
                <div className="relative">
                  <Portrait id={s.id} kind="photo" className="aspect-[3/2] w-full" />
                  <span className="absolute bottom-1 left-1 rounded bg-bg/85 px-1.5 text-[0.76rem] font-bold text-gold">{s.role}</span>
                </div>
                <div className="px-2 py-1.5">
                  <div className="truncate text-[0.82rem] font-extrabold">{s.name}</div>
                  <div className="truncate text-[0.74rem] text-ink-dim">
                    {s.age}歳・{NATION_NAME[s.nation]}
                  </div>
                </div>
              </button>
            ))}
          </div>
        )}

        {tab === 'mob' && (
          <div>
            {GEN_SETS.map(([set, title]) => {
              const ids = genIds(set)
              if (!ids.length) return null
              return (
                <section key={set} className="mb-4">
                  <div className="panel-head mb-1.5">{title}</div>
                  <div className="grid gap-2" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(4.2rem, 1fr))' }}>
                    {ids.map((id) => (
                      <Portrait key={id} id={id} kind="face" className="face-round aspect-square w-full" />
                    ))}
                  </div>
                </section>
              )
            })}
            <div className="panel-head mb-1.5">自動生成の顔</div>
            <p className="mb-2 text-[0.75rem] text-ink-dim">写真のない選手は国籍と ID から顔を自動生成します（表情は調子・ケガで変化）。</p>
            <div className="grid gap-2" style={{ gridTemplateColumns: 'repeat(auto-fill, minmax(4.2rem, 1fr))' }}>
              {Array.from({ length: 48 }, (_, i) => (
                <div key={i} className="face-round aspect-square w-full">
                  <PlayerAvatar seed={i * 7 + 3} nation={MOB_NATIONS[i % MOB_NATIONS.length]} mood={MOODS[i % MOODS.length]} kit={MOB_KITS[i % MOB_KITS.length]} size="100%" suit={i % 16 === 15} />
                </div>
              ))}
            </div>
          </div>
        )}
      </div>

      <SideSheet open={!!sel} onClose={() => setSel(null)} title={sel?.d.name}>
        {sel?.kind === 'heroine' && <HeroineDetail d={sel.d} />}
        {sel?.kind === 'player' && <MaleDetail id={sel.d.id} lines={[`${sel.d.line}・背番号 ${sel.d.number}`, `${sel.d.age}歳・${NATION_NAME[sel.d.nation]}`]} blurb={sel.d.blurb} />}
        {sel?.kind === 'staff' && <MaleDetail id={sel.d.id} lines={[sel.d.role, `${sel.d.age}歳・${NATION_NAME[sel.d.nation]}`]} blurb={sel.d.blurb} />}
      </SideSheet>
    </div>
  )
}

function HeroineDetail({ d }: { d: HeroineDef }) {
  return (
    <div className="flex gap-3 p-3">
      <Portrait id={d.id} kind="bust" className="aspect-[3/4] w-[42%] shrink-0 rounded-xl border border-pink/40" />
      <div className="min-w-0 flex-1">
        <div className="text-[0.75rem] text-ink-dim">{d.kana}</div>
        <div className="text-[1.4rem] font-black">{d.name}</div>
        <div className="mt-0.5 text-[0.85rem] font-bold text-pink">
          {d.age}歳・{d.role}
        </div>
        <div className="mt-2 inline-block rounded-full bg-pink/20 px-2.5 py-0.5 text-[0.75rem] font-bold text-pink">{d.tags}</div>
        <p className="mt-2 text-[0.85rem] leading-relaxed text-ink">{d.blurb}</p>
        <div className="mt-2 text-[0.76rem] text-ink-mute">{d.relation === 'peer' ? '高校編：同級生' : '相談相手（年上）'}</div>
      </div>
    </div>
  )
}

function MaleDetail({ id, lines, blurb }: { id: string; lines: string[]; blurb: string }) {
  return (
    <div className="flex gap-3 p-3">
      <div className="w-[46%] shrink-0">
        <Portrait id={id} kind="photo" className="aspect-[3/2] w-full rounded-xl border border-line" />
        <div className="mt-2 flex items-center gap-2">
          <Portrait id={id} kind="face" className="face-round h-16 w-16" />
          <span className="text-[0.76rem] text-ink-mute">顔アイコン</span>
        </div>
      </div>
      <div className="min-w-0 flex-1">
        {lines.map((l, i) => (
          <div key={i} className={i === 0 ? 'text-[0.95rem] font-extrabold text-gold' : 'text-[0.85rem] text-ink-dim'}>
            {l}
          </div>
        ))}
        <p className="mt-2 text-[0.85rem] leading-relaxed">{blurb}</p>
      </div>
    </div>
  )
}
