/** 試合前: 対戦カード・両チームの強さ・先発。観戦するか、結果だけ見るかを選ぶ。 */
import { useMemo } from 'react'
import { GROUP_LETTERS, isNeutral, matchOptions, roundName } from '../../engine/competition/continental'
import { DerbyBadge } from '../club/RivalPanel'
import { FOREIGN_LIMIT, foreignCount } from '../../engine/match/lineup'
import { NATION_NAME, type Nation } from '../../engine/data/nations'
import { clubRank, leagueOf, ovr, playerClub, playerFixtureThisWeek, squadOf, type GameState } from '../../engine'
import { buildMatchSetup } from '../../engine/match/setup'
import { teamRatings } from '../../engine/match/ratings'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Emblem } from '../components/ClubArt'
import { FormationPitch } from '../components/FormationPitch'
import { PlayerFace } from '../components/PersonFace'
import { OvrBadge } from '../components/common'
import { Icon } from '../components/Icon'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

function CompareBar({ label, a, b }: { label: string; a: number; b: number }) {
  const tot = a + b || 1
  return (
    <div>
      <div className="num flex justify-between text-[0.76rem]">
        <span className="font-bold">{Math.round(a)}</span>
        <span className="text-ink-dim">{label}</span>
        <span className="font-bold">{Math.round(b)}</span>
      </div>
      <div className="mt-0.5 flex h-1.5 overflow-hidden rounded-full bg-black/40">
        <div className="bg-gold" style={{ width: `${(a / tot) * 100}%` }} />
        <div className="flex-1 bg-accent" />
      </div>
    </div>
  )
}

function form(state: GameState, clubId: number): string {
  const c = state.clubs[clubId]
  const row = leagueOf(state, c).table.find((r) => r.clubId === clubId)
  return row?.form ?? ''
}

/** 順位の表示（アジアのクラブはリーグ戦をしないので国名） */
function standing(state: GameState, clubId: number): string {
  const club = state.clubs[clubId]
  const comp = state.competitions.find((c) => c.id === club.leagueId)
  if (!comp || comp.hidden) return NATION_NAME[club.country as Nation] ?? ''
  return `${comp.country === 'JP' ? '' : `${comp.short} `}${clubRank(state, club)}位`
}

export function PreMatchScreen() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const reset = useUi((s) => s.reset)
  const playWeek = useGame((s) => s.playWeek)
  const me = playerClub(state)
  const fx = playerFixtureThisWeek(state)
  const setup = useMemo(() => (fx ? buildMatchSetup(state, fx.fixture.id, fx.fixture.home, fx.fixture.away, matchOptions(fx.comp, fx.fixture)) : null), [state, fx])
  if (!fx || !setup) {
    return (
      <AppShell title="試合" current="home" right={<GameTopInfo />}>
        <div className="p-6 text-center text-ink-dim">今週は試合がありません</div>
      </AppShell>
    )
  }
  const homeSide = fx.fixture.home === me.id
  const neutral = isNeutral(fx.comp, fx.fixture)
  const foreign = foreignCount(state, me)
  const opp = state.clubs[homeSide ? fx.fixture.away : fx.fixture.home]
  const mine = homeSide ? setup.home : setup.away
  const theirs = homeSide ? setup.away : setup.home
  const rm = teamRatings(mine)
  const ro = teamRatings(theirs)
  const keyPlayers = squadOf(state, opp.id)
    .sort((a, b) => ovr(b) - ovr(a))
    .slice(0, 3)
  const title = `${fx.comp.name} ${roundName(fx.comp, fx.fixture.round)}${fx.fixture.group !== undefined ? `（${GROUP_LETTERS[fx.fixture.group]} 組）` : ''}`
  // キャリア: 主人公は先発か、ベンチか、メンバー外か（戦術やメンバーは変えられない）
  const career = state.career
  const role = career ? (me.lineup.starters.includes(career.playerId) ? '先発' : me.lineup.bench.includes(career.playerId) ? 'ベンチ' : 'メンバー外') : null

  return (
    <AppShell title={title} current="home" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="flex w-[34%] shrink-0 flex-col gap-2">
          <div className="min-h-0 flex-1">
            <FormationPitch state={state} formation={me.tactics.formation} lineup={me.lineup} kit={me.colors} compact />
          </div>
          {role ? (
            <div className={`rounded-lg px-3 py-2 text-center text-[0.85rem] font-black ${role === '先発' ? 'bg-good/20 text-good' : role === 'ベンチ' ? 'bg-accent/20 text-accent' : 'bg-white/10 text-ink-dim'}`}>
              {role === '先発' ? 'あなたは先発です！' : role === 'ベンチ' ? 'あなたはベンチスタート。出番を待とう' : '今日はメンバー外…スタンドから見守る'}
            </div>
          ) : (
            <>
              {foreign > FOREIGN_LIMIT && <div className="rounded-lg bg-bad/20 px-2 py-1 text-[0.76rem] text-bad">外国籍の選手が {foreign} 人います（{FOREIGN_LIMIT} 人まで）。試合ではおまかせで組み直します。</div>}
              <button className="btn btn-ghost btn-sm" onClick={() => push({ id: 'tactics', params: { back: true } })}>
                <Icon name="tactics" className="h-4 w-4" />
                戦術・メンバーを変える
              </button>
            </>
          )}
        </div>

        <div className="panel flex min-w-0 flex-1 flex-col p-3">
          <div className="flex items-center justify-center gap-3">
            <div className="flex w-[40%] flex-col items-center text-center">
              <Emblem id={`pm-h-${fx.fixture.home}`} emblem={state.clubs[fx.fixture.home].emblem} colors={state.clubs[fx.fixture.home].colors} size="3.4rem" />
              <div className="mt-1 w-full truncate text-[0.95rem] font-black">{state.clubs[fx.fixture.home].name}</div>
              <div className="num text-[0.76rem] text-ink-dim">
                {standing(state, fx.fixture.home)} {form(state, fx.fixture.home)}
              </div>
            </div>
            <div className="text-center">
              <div className="text-[1.4rem] font-black text-ink-dim">VS</div>
              <div className={`mt-1 rounded px-2 text-[0.72rem] font-black ${neutral ? 'bg-white/10 text-ink' : homeSide ? 'bg-good/20 text-good' : 'bg-accent/20 text-accent'}`}>{neutral ? '中立地' : homeSide ? 'HOME' : 'AWAY'}</div>
              <DerbyBadge state={state} home={fx.fixture.home} away={fx.fixture.away} className="mt-1 inline-block" />
            </div>
            <div className="flex w-[40%] flex-col items-center text-center">
              <Emblem id={`pm-a-${fx.fixture.away}`} emblem={state.clubs[fx.fixture.away].emblem} colors={state.clubs[fx.fixture.away].colors} size="3.4rem" />
              <div className="mt-1 w-full truncate text-[0.95rem] font-black">{state.clubs[fx.fixture.away].name}</div>
              <div className="num text-[0.76rem] text-ink-dim">
                {standing(state, fx.fixture.away)} {form(state, fx.fixture.away)}
              </div>
            </div>
          </div>
          <div className="mx-auto mt-3 w-full max-w-[22rem] space-y-1.5">
            <div className="flex justify-between text-[0.72rem] font-bold">
              <span className="text-gold">{me.short}</span>
              <span className="text-accent">{opp.short}</span>
            </div>
            <CompareBar label="攻撃力" a={rm.att} b={ro.att} />
            <CompareBar label="中盤" a={rm.mid} b={ro.mid} />
            <CompareBar label="守備力" a={rm.def} b={ro.def} />
          </div>
          <div className="mt-3">
            <div className="panel-head mb-1">相手の注目選手</div>
            <div className="flex gap-2">
              {keyPlayers.map((p) => (
                <div key={p.id} className="flex min-w-0 flex-1 items-center gap-1.5 rounded-lg bg-black/25 px-1.5 py-1">
                  <PlayerFace p={p} kit={opp.colors} className="h-8 w-8 shrink-0" />
                  <span className="min-w-0 flex-1 truncate text-[0.78rem] font-bold">{p.short}</span>
                  <OvrBadge value={ovr(p)} size="sm" />
                </div>
              ))}
            </div>
          </div>
        </div>

        <div className="flex w-[11rem] shrink-0 flex-col justify-end gap-2">
          <button className="btn btn-gold h-[3.6rem] text-[1.05rem]" onClick={() => push({ id: 'match' })}>
            <Icon name="play" className="h-5 w-5" />
            観戦する
          </button>
          <button
            className="btn btn-ghost"
            onClick={() => {
              playWeek()
              reset({ id: 'postMatch' })
            }}
          >
            結果だけ見る
          </button>
        </div>
      </div>
    </AppShell>
  )
}
