import { ageAt, currentAbsWeek } from '../../engine'
import { useGame } from '../../stores/gameStore'
import { photoIdOf } from './portraits'

/** 人の写真の id（固有キャラか、今の年齢に合わせた生成の写真）。なければ undefined */
export function usePhotoId(person: { starId?: string; face?: { photo?: string }; birthAbsWeek: number }): string | undefined {
  const state = useGame((s) => s.state)
  return photoIdOf(person, state ? ageAt(currentAbsWeek(state), person.birthAbsWeek) : undefined)
}
