/** キャリアのユース期（M17）: 大会の準決勝・決勝（試合前 → 観戦か結果だけ → 結果）。 */
import { useMemo, useState } from 'react'
import { playYouthWatched, youthBigMatch, youthMatchSetup } from '../../engine/career/saga'
import type { MatchSummary } from '../../engine/match/live/types'
import { MatchView } from '../match/MatchView'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Icon } from '../components/Icon'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

export function YouthMatchScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const advance = useGame((s) => s.advance)
  const reset = useUi((s) => s.reset)
  // 開いた時点の試合を固定する
  const [big] = useState(() => youthBigMatch(state))
  const [phase, setPhase] = useState<'pre' | 'live'>('pre')
  const setup = useMemo(() => (big ? youthMatchSetup(state) : null), [big, state])
  const c = state.career!
  const y = c.saga?.youth
  // 試合のあと（観戦でも結果だけでも）は週を進めてホームへ。結果は「最近の出来事」と会話で出る
  const finish = (s: MatchSummary | null) => {
    if (s) mutate((st) => playYouthWatched(st, s))
    advance('week')
    reset({ id: 'home' })
  }
  if (phase === 'live' && setup) return <MatchView setup={setup} onExit={finish} focus={c.playerId} />
  if (!big || !setup || !y) {
    return (
      <AppShell title="ユースの試合" current="home" right={<GameTopInfo />}>
        <div className="absolute inset-0 flex items-center justify-center">
          <button className="btn btn-gold" onClick={() => reset({ id: 'home' })}>
            ホームへ
          </button>
        </div>
      </AppShell>
    )
  }
  return (
    <AppShell title={big.label} current="home" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="panel flex min-w-0 flex-1 flex-col justify-center p-4">
          <div className="text-center text-[0.75rem] font-bold tracking-widest text-gold">{big.final ? '決勝' : '準決勝'}</div>
          <div className="mt-2 flex items-center justify-center gap-4">
            <div className="w-[38%] text-center text-[1.05rem] font-black">{y.team}</div>
            <div className="text-[1.4rem] font-black text-ink-dim">VS</div>
            <div className="w-[38%] text-center text-[1.05rem] font-black">{big.opp}</div>
          </div>
          <div className="mx-auto mt-4 rounded-lg bg-good/20 px-4 py-2 text-center text-[0.9rem] font-black text-good">背番号 {setup.home.starters.find((x) => x.id === c.playerId)?.number ?? 10} で先発です！</div>
          <div className="mt-2 text-center text-[0.78rem] text-ink-dim">{big.final ? '勝てば優勝。スタンドには家族も来ている。' : '勝てば決勝。ここからが本当の勝負だ。'}</div>
        </div>
        <div className="flex w-[11rem] shrink-0 flex-col justify-end gap-2">
          <button className="btn btn-gold h-[3.6rem] text-[1.05rem]" onClick={() => setPhase('live')}>
            <Icon name="play" className="h-5 w-5" />
            観戦する
          </button>
          <button className="btn btn-ghost" onClick={() => finish(null)}>
            結果だけ見る
          </button>
        </div>
      </div>
    </AppShell>
  )
}
