/**
 * クラブの総合力の推移（SVG）。横軸はシーズン、縦軸は値に合わせた幅（30 以上。0〜100 の中）。段（S〜G）の境目に薄い線と文字。
 * 1 本の線（選んだ項目）。点をタップするとその年の値を出す。当たり判定は点ごとの縦の帯。
 */
import { useState } from 'react'
import { powerGrade } from '../../engine/club/power'

export interface PowerPoint {
  /** 横軸の文字（「26」など） */
  label: string
  value: number
  /** 吹き出しの 1 行目（「2026-27・NPL3」など） */
  title: string
  /** 吹き出しの 2 行目以降 */
  lines: string[]
  now?: boolean
  /** 過去の記録から推定した点（破線・白抜き） */
  estimated?: boolean
}

const W = 360
const H = 170
const PAD = { l: 22, r: 16, t: 8, b: 18 }
const GOLD = 'var(--color-gold)'
const GRADES: [number, string][] = [
  [25, 'F'],
  [35, 'E'],
  [45, 'D'],
  [55, 'C'],
  [65, 'B'],
  [75, 'A'],
  [85, 'S'],
]
/** 縦軸の範囲: 値の上下に少し余白をとり、幅は 30 以上 */
function yRange(values: number[]): [number, number] {
  let lo = Math.max(0, Math.floor((Math.min(...values) - 8) / 5) * 5)
  let hi = Math.min(100, Math.ceil((Math.max(...values) + 8) / 5) * 5)
  while (hi - lo < 30) {
    if (lo > 0) lo = Math.max(0, lo - 5)
    if (hi - lo < 30 && hi < 100) hi = Math.min(100, hi + 5)
  }
  return [lo, hi]
}

export function PowerChart({ points, name }: { points: PowerPoint[]; name: string }) {
  const [pick, setPick] = useState<number | null>(null)
  const [lo, hi] = yRange(points.length ? points.map((p) => p.value) : [0, 100])
  const y = (v: number) => PAD.t + (1 - (v - lo) / (hi - lo)) * (H - PAD.t - PAD.b)
  const n = points.length
  const x = (i: number) => (n <= 1 ? (PAD.l + W - PAD.r) / 2 : PAD.l + 8 + (i / (n - 1)) * (W - PAD.l - PAD.r - 16))
  const step = n <= 1 ? W : x(1) - x(0)
  // 横軸の文字は多すぎないように間引く（最初・最後・いまは必ず）
  const every = Math.max(1, Math.ceil(n / 9))
  const at = pick === null ? null : points[pick]
  return (
    <svg viewBox={`0 0 ${W} ${H}`} className="block w-full" role="img" aria-label={`${name}の推移。${points.map((p) => `${p.title} ${Math.round(p.value)}`).join('、')}`}>
      {/* 段の境目（範囲の中だけ） */}
      {GRADES.filter(([v]) => v > lo && v <= hi).map(([v, g]) => (
        <g key={g}>
          <line x1={PAD.l} x2={W - PAD.r} y1={y(v)} y2={y(v)} stroke="var(--color-line)" strokeOpacity={0.5} strokeWidth={0.6} />
          <text x={PAD.l - 4} y={y(v) + 3} textAnchor="end" fontSize={7.5} fill="var(--color-ink-mute)">
            {v}
          </text>
          <text x={W - PAD.r + 3} y={y(v) - 2} fontSize={7.5} fontWeight={700} fill="var(--color-ink-dim)">
            {g}
          </text>
        </g>
      ))}
      <line x1={PAD.l} x2={W - PAD.r} y1={y(lo)} y2={y(lo)} stroke="var(--color-line)" strokeWidth={0.8} />
      <text x={PAD.l - 4} y={y(lo) + 3} textAnchor="end" fontSize={7.5} fill="var(--color-ink-mute)">
        {lo}
      </text>
      {points.map((p, i) =>
        i % every === 0 || i === n - 1 ? (
          <text key={i} x={x(i)} y={H - 5} textAnchor="middle" fontSize={8} fontWeight={p.now ? 700 : 400} fill={p.now ? 'var(--color-ink)' : 'var(--color-ink-mute)'}>
            {p.label}
          </text>
        ) : null,
      )}
      {/* 線: 推定の点にかかる区間は破線 */}
      {points.slice(1).map((p, k) => {
        const a = points[k]
        return <line key={k} x1={x(k)} y1={y(a.value)} x2={x(k + 1)} y2={y(p.value)} stroke={GOLD} strokeWidth={2} strokeLinecap="round" strokeDasharray={a.estimated || p.estimated ? '4 3' : undefined} strokeOpacity={a.estimated || p.estimated ? 0.75 : 1} />
      })}
      {points.map((p, i) => (
        <circle key={i} cx={x(i)} cy={y(p.value)} r={p.now ? 5 : 3.6} fill={p.estimated ? 'var(--color-panel)' : GOLD} stroke={p.estimated ? GOLD : 'var(--color-panel)'} strokeWidth={p.now ? 2 : 1.4} />
      ))}
      {n > 0 && (
        <text x={x(n - 1)} y={y(points[n - 1].value) - 8} textAnchor="middle" fontSize={8.5} fontWeight={700} fill="var(--color-ink)">
          {Math.round(points[n - 1].value)}（{powerGrade(points[n - 1].value)}）
        </text>
      )}
      {at && pick !== null && <Tip x0={x(pick)} y0={y(at.value)} title={at.title} lines={[`${name} ${Math.round(at.value)}（${powerGrade(at.value)}）`, ...at.lines]} />}
      {/* 当たり判定: 点ごとの縦の帯 */}
      <g onPointerLeave={() => setPick(null)}>
        {points.map((_, i) => (
          <rect key={i} x={x(i) - step / 2} y={0} width={step} height={H} fill="transparent" onPointerEnter={() => setPick(i)} onPointerDown={() => setPick(i)} />
        ))}
      </g>
    </svg>
  )
}

function Tip({ x0, y0, title, lines }: { x0: number; y0: number; title: string; lines: string[] }) {
  const w = 118
  const left = x0 > W - w - 20
  const bx = left ? x0 - w - 6 : x0 + 6
  const by = Math.min(H - PAD.b - (14 + (lines.length + 1) * 11), Math.max(PAD.t, y0 - 16))
  return (
    <g pointerEvents="none">
      <line x1={x0} x2={x0} y1={PAD.t} y2={H - PAD.b} stroke="var(--color-ink-dim)" strokeOpacity={0.6} strokeWidth={0.8} />
      <rect x={bx} y={by} width={w} height={12 + (lines.length + 1) * 11} rx={4} fill="#0b1320" fillOpacity={0.94} stroke="var(--color-line)" />
      {[title, ...lines].map((t, i) => (
        <text key={i} x={bx + 6} y={by + 12 + i * 11} fontSize={8.5} fill={i ? 'var(--color-ink-dim)' : 'var(--color-ink)'} fontWeight={i ? 400 : 700}>
          {t}
        </text>
      ))}
    </g>
  )
}
