/**
 * クラブの総合力（M23。クラブ画面の「総合力」タブ）: いまの総合力と段・リーグでの順位、5 つの内訳、シーズンごとの推移（グラフと表）。
 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { POWER_PARTS, myPower, nextGrade, powerBySeason, powerGrade, type PowerLog, type PowerPart } from '../../engine/club/power'
import { useUi } from '../../stores/uiStore'
import { PowerChart, type PowerPoint } from './PowerChart'

type Series = 'total' | PowerPart

const GRADE_COLOR: Record<string, string> = { S: '#ffcf4a', A: '#ff9a52', B: '#3ddc84', C: '#7dd3fc', D: '#c7d2de', E: '#8a97a8', F: '#8a97a8', G: '#8a97a8' }

function GradeChip({ v, big = false }: { v: number; big?: boolean }) {
  const g = powerGrade(v)
  return (
    <span className={`num inline-flex shrink-0 items-center justify-center rounded font-black text-[#0b1320] ${big ? 'h-12 w-12 rounded-xl text-[1.8rem]' : 'h-[1.15rem] w-[1.15rem] text-[0.74rem]'}`} style={{ background: GRADE_COLOR[g] }}>
      {g}
    </span>
  )
}

const leagueShort = (state: GameState, id: string) => state.competitions.find((c) => c.id === id)?.short ?? id
const seasonLabel = (state: GameState, season: number) => `${state.startYear + season}-${String((state.startYear + season + 1) % 100).padStart(2, '0')}`

/** ホームの数字のチップ（押すとクラブの総合力へ） */
export function PowerChip({ state }: { state: GameState }) {
  const push = useUi((s) => s.push)
  const p = myPower(state)
  return (
    <button className="stat-chip py-1" onClick={() => push({ id: 'club', params: { tab: 'power' } })}>
      <div className="flex items-center justify-center gap-1 text-[0.7rem] text-ink-dim">総合力</div>
      <div className="flex items-center justify-center gap-1">
        <GradeChip v={p.total} />
        <span className="num text-[0.98rem] font-black">{Math.round(p.total)}</span>
      </div>
    </button>
  )
}

export function PowerTab({ state }: { state: GameState }) {
  const p = myPower(state)
  const [series, setSeries] = useState<Series>('total')
  const [view, setView] = useState<'chart' | 'table'>('chart')
  const next = nextGrade(p.total)
  const logs = powerBySeason(state).filter((e) => e.season < state.season)
  const nowLog: PowerLog = { season: state.season, week: state.week, total: p.total, parts: p.parts, leagueId: p.leagueId, leagueRank: p.leagueRank, leagueSize: p.leagueSize }
  const rows = [...logs, nowLog]
  const valueOf = (e: PowerLog) => (series === 'total' ? e.total : e.parts[series])
  const finishOf = (season: number) => state.seasons.find((x) => x.season === season)
  const name = series === 'total' ? '総合力' : POWER_PARTS.find((x) => x.id === series)!.name
  const points: PowerPoint[] = rows.map((e) => {
    const fin = finishOf(e.season)
    const now = e.season === state.season
    return {
      label: now ? 'いま' : `'${String((state.startYear + e.season) % 100).padStart(2, '0')}`,
      value: valueOf(e),
      title: `${seasonLabel(state, e.season)}・${leagueShort(state, e.leagueId)}`,
      lines: [e.estimated ? '推定（選手と資金の記録から）' : `総合力はリーグ ${e.leagueRank} 位 / ${e.leagueSize}`, ...(fin ? [`成績 ${fin.rank} 位（勝点 ${fin.points}）`] : now ? ['今季'] : [])],
      now,
      estimated: e.estimated,
    }
  })
  // 記録より前のシーズン（成績だけ）
  const recorded = new Set(rows.map((e) => e.season))
  const older = state.seasons.filter((x) => !recorded.has(x.season))
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      {/* 左: いまの総合力と内訳 */}
      <div className="panel scroll-y w-[38%] shrink-0 space-y-2.5 p-3">
        <div className="flex items-center gap-3 rounded-xl bg-black/25 p-2.5">
          <GradeChip v={p.total} big />
          <div className="min-w-0">
            <div className="text-[0.72rem] text-ink-dim">クラブの総合力</div>
            <div className="num text-[2rem] font-black leading-none">{Math.round(p.total)}</div>
            <div className="mt-0.5 text-[0.74rem] text-ink-dim">
              {leagueShort(state, p.leagueId)} の {p.leagueSize} クラブ中 <b className="text-gold">{p.leagueRank} 位</b>
            </div>
          </div>
        </div>
        {next && (
          <div className="text-[0.72rem] text-ink-dim">
            {next.grade} まで あと <b className="num text-ink">{next.need}</b>
          </div>
        )}
        <div className="space-y-1.5">
          <div className="panel-head">内訳（押すと推移をその項目に）</div>
          {POWER_PARTS.map((part) => {
            const v = p.parts[part.id]
            const on = series === part.id
            return (
              <button key={part.id} onClick={() => setSeries(on ? 'total' : part.id)} className={`block w-full rounded-lg px-2 py-1 text-left ${on ? 'bg-gold/15 ring-1 ring-gold/60' : 'bg-white/[0.04]'}`}>
                <div className="flex items-center gap-1.5 text-[0.78rem]">
                  <span className="font-bold">{part.name}</span>
                  <span className="text-[0.66rem] text-ink-mute">{Math.round(part.weight * 100)}%</span>
                  <span className="ml-auto text-[0.68rem] text-ink-dim">リーグ {p.partRanks[part.id]} 位</span>
                  <GradeChip v={v} />
                  <b className="num w-7 text-right">{Math.round(v)}</b>
                </div>
                <div className="mt-0.5 h-1.5 overflow-hidden rounded-full bg-black/40">
                  <div className="h-full rounded-full bg-gold" style={{ width: `${v}%` }} />
                </div>
                <div className="mt-0.5 text-[0.64rem] text-ink-mute">{part.desc}</div>
              </button>
            )
          })}
        </div>
        <p className="text-[0.66rem] leading-relaxed text-ink-mute">段の目安: 3 部の平均は F、2 部は E、1 部は C、欧州の強豪は A。S は世界の頂点。どのクラブも同じ式なので、リーグの中で比べられます。</p>
      </div>

      {/* 右: 推移 */}
      <div className="panel flex min-w-0 flex-1 flex-col gap-2 p-3">
        <div className="flex shrink-0 flex-wrap items-center gap-2">
          <span className="panel-head">推移</span>
          <div className="seg !min-h-0">
            {(['total', ...POWER_PARTS.map((x) => x.id)] as Series[]).map((id) => (
              <button key={id} aria-selected={series === id} className="!min-h-[2.1rem] !px-2 !text-[0.72rem]" onClick={() => setSeries(id)}>
                {id === 'total' ? '総合力' : POWER_PARTS.find((x) => x.id === id)!.name}
              </button>
            ))}
          </div>
          <div className="seg ml-auto !min-h-0">
            <button aria-selected={view === 'chart'} className="!min-h-[2.1rem] !px-2 !text-[0.72rem]" onClick={() => setView('chart')}>
              グラフ
            </button>
            <button aria-selected={view === 'table'} className="!min-h-[2.1rem] !px-2 !text-[0.72rem]" onClick={() => setView('table')}>
              表
            </button>
          </div>
        </div>
        <div className="scroll-y min-h-0 flex-1">
          {view === 'chart' ? (
            <>
              <PowerChart points={points} name={name} />
              {rows.length < 2 && <p className="mt-1 text-[0.72rem] text-ink-dim">総合力の記録は月のはじめとシーズンの終わりに残ります。シーズンを重ねると線になります。</p>}
              {rows.some((e) => e.estimated) && <p className="mt-1 text-[0.68rem] text-ink-mute">破線・白抜きの点は推定です（この機能より前のシーズン。戦力は選手の記録、経営は資金の記録から。人気・施設・スタッフは今の値までの目安）。</p>}
              {older.length > 0 && <p className="mt-1 text-[0.68rem] text-ink-mute">この記録より前のシーズン（{older.length} シーズン）は、表に成績だけ出ます。</p>}
            </>
          ) : (
            <table className="w-full text-[0.74rem]">
              <thead>
                <tr className="text-ink-dim">
                  <th className="py-1 text-left font-normal">シーズン</th>
                  <th className="text-left font-normal">リーグ</th>
                  <th className="text-right font-normal">成績</th>
                  <th className="text-right font-normal">総合力</th>
                  {POWER_PARTS.map((x) => (
                    <th key={x.id} className="text-right font-normal">
                      {x.name}
                    </th>
                  ))}
                </tr>
              </thead>
              <tbody>
                {[...rows].reverse().map((e) => {
                  const fin = finishOf(e.season)
                  return (
                    <tr key={e.season} className="border-t border-white/[0.06]">
                      <td className="num py-1">{e.season === state.season ? `${seasonLabel(state, e.season)}（いま）` : seasonLabel(state, e.season)}</td>
                      <td>{leagueShort(state, e.leagueId)}</td>
                      <td className="num text-right">{fin ? `${fin.rank} 位` : '—'}</td>
                      <td className="num text-right font-black">
                        {Math.round(e.total)} <span className="text-[0.66rem] text-ink-dim">{e.estimated ? '推定' : powerGrade(e.total)}</span>
                      </td>
                      {POWER_PARTS.map((x) => (
                        <td key={x.id} className={`num text-right ${e.estimated && x.id !== 'team' && x.id !== 'finance' ? 'text-ink-mute' : ''}`}>
                          {e.estimated && x.id !== 'team' && x.id !== 'finance' ? '〜' : ''}
                          {Math.round(e.parts[x.id])}
                        </td>
                      ))}
                    </tr>
                  )
                })}
                {[...older].reverse().map((x) => (
                  <tr key={`o${x.season}`} className="border-t border-white/[0.06] text-ink-dim">
                    <td className="num py-1">{seasonLabel(state, x.season)}</td>
                    <td>{leagueShort(state, x.leagueId)}</td>
                    <td className="num text-right">{x.rank} 位</td>
                    <td className="text-right" colSpan={POWER_PARTS.length + 1}>
                      記録なし
                    </td>
                  </tr>
                ))}
              </tbody>
            </table>
          )}
        </div>
      </div>
    </div>
  )
}
