import { SLOT_LABEL, acceptSponsor, localSupport, sponsorBase, sponsorSlots } from '../../engine/economy/sponsors'
import { WORLD_FACILITY, inWorld, worldVisitors } from '../../engine/club/worldClass'
import type { Club } from '../../engine/models/club'
import { canHire, fire, hire, severance, signingFee, staffMarket } from '../../engine/staff/hiring'
import { maintenancePerSeason, squadWages, staffWages, weekNet } from '../../engine/economy/finance'
