import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { formatMoney, formatMoneyShort } from '../format'
import { BusinessTab } from '../club/BusinessTab'
import { loadLegends } from '../career/legends'
import { addLegend, hasLegend } from '../../engine/career/export'
import { RivalPanel } from '../club/RivalPanel'
import { Icon, type IconName } from '../components/Icon'
import { TOWN_TRAITS } from '../../engine/data/clubs'
