import { SalesTab } from '../club/SalesTab'
import { CommunityTab } from '../club/CommunityTab'

type Tab = 'info' | 'power' | 'community' | 'facility' | 'stadium' | 'sales' | 'staff' | 'sponsor' | 'business' | 'finance'
const TABS: [Tab, string, IconName][] = [
  ['info', '概要', 'club'],
  ['power', '総合力', 'growth'],
  ['community', '地域', 'story'],
  ['facility', '施設', 'whistle'],
  ['stadium', 'スタジアム', 'ball'],
  ['sales', '営業', 'trophy'],
  ['staff', 'スタッフ', 'person'],
  ['sponsor', 'スポンサー', 'trophy'],
  ['business', '事業', 'life'],
  ['finance', '財務', 'growth'],
]

/** 施設の Lv のバーの長さ（ワールドリーグにいるか、Lv6 以上なら 8） */
function levelMax(club: Club, lv: number): number {
  return inWorld(club) || lv > 5 ? WORLD_FACILITY : 5
}

function Level({ v, max = 5 }: { v: number; max?: number }) {
  return (
    <span className="inline-flex gap-0.5">
      {Array.from({ length: max }, (_, i) => (
        <span key={i} className={`h-2.5 w-3.5 rounded-sm ${i < v ? 'bg-gold' : 'bg-white/10'}`} />
      ))}
    </span>
  )
}

function Kv({ k, v }: { k: string; v: React.ReactNode }) {
  return (
    <>
      <span className="text-ink-dim">{k}</span>
      <span className="num text-right font-bold">{v}</span>
    </>
  )
}

function StaffCard({ s, now, action }: { s: Staff; now: number; action?: React.ReactNode }) {
  return (
    <div className="flex items-center gap-2 rounded-lg bg-white/[0.04] px-2 py-1.5">
      <StaffFace s={s} className="h-10 w-10 shrink-0" />
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          <span className="rounded bg-accent/20 px-1.5 text-[0.7rem] font-bold text-accent">{STAFF_ROLE_LABEL[s.role]}</span>
          <span className="truncate text-[0.82rem] font-bold">{s.name}</span>
          <Flag nation={s.nation} />
          {s.world && <span className="shrink-0 rounded bg-gold px-1 text-[0.64rem] font-black text-[#2a1a00]">世界</span>}
        </div>
        <div className="truncate text-[0.72rem] text-ink-dim">
          {ageAt(now, s.birthAbsWeek)}歳・{NATION_NAME[s.nation]}
          {s.style && `・${STYLE_LABEL[s.style]}`}
          {s.formations && `・得意 ${Object.entries(s.formations).filter(([, v]) => v >= 75).map(([k]) => k).join(' ')}`}
          ・年俸 {formatMoneyShort(s.wage)}
        </div>
      </div>
      {s.role !== 'owner' && s.role !== 'secretary' && s.role !== 'interpreter' && (
        <div className="text-center">
          <div className="text-[0.66rem] text-ink-dim">能力</div>
          <div className="num text-[0.95rem] font-black text-gold">{s.ability}</div>
        </div>
      )}
      {action}
    </div>
  )
}

function InfoTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const push = useUi((s) => s.push)
  const town = state.hometown
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[46%] shrink-0 p-3">
        <div className="flex items-center gap-3">
          <Emblem id={`cl-${me.id}`} emblem={me.emblem} colors={me.colors} size="3.4rem" />
          <Kit id={`cl-${me.id}`} pattern={me.kit} colors={me.colors} size="3rem" number={10} />
          <div className="min-w-0">
            <div className="truncate text-[1.05rem] font-black">{me.name}</div>
            <div className="text-[0.78rem] text-ink-dim">
              {town.pref}・{town.city}
            </div>
          </div>
        </div>
        <div className="mt-3 grid grid-cols-2 gap-x-3 gap-y-1.5 text-[0.8rem]">
          <Kv k="資金" v={formatMoney(me.budget)} />
          <Kv k="クラブの格" v={Math.round(me.rep)} />
          <Kv k="人気" v={Math.round(me.popularity)} />
          <Kv k="サポーター" v={`${me.fans.toLocaleString()}人`} />
          <Kv k="サポーターの上限" v={`${fansCap(state, me).toLocaleString()}人`} />
          {(me.worldFans ?? 0) > 0 && <Kv k="海外のファン" v={`${(me.worldFans ?? 0).toLocaleString()}人`} />}
          <Kv k="ホームタウン人口" v={`${town.population}万人`} />
          <Kv k="街の発展度" v={Math.round(town.development)} />
          {town.trait && <Kv k="街の特色" v={`${TOWN_TRAITS[town.trait].name}（${TOWN_TRAITS[town.trait].desc}）`} />}
          <Kv k="オーナーの救済" v={`${state.money.bailouts} / 2 回`} />
          <Kv k="タイトル" v={`${(state.trophies ?? []).length} 個`} />
        </div>
        <button className="btn btn-blue btn-sm mt-3 w-full" onClick={() => push({ id: 'records' })}>
          クラブの記録・殿堂
        </button>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 p-3">
        <WorldLeaguePanel state={state} />
        <div className="mt-3" />
        <OwnerGoals state={state} />
        <div className="mt-3" />
        <RivalPanel state={state} />
        <div className="panel-head mb-1 mt-3">工事中</div>
        {(me.construction ?? []).length === 0 && <div className="text-[0.78rem] text-ink-dim">工事はありません</div>}
        {(me.construction ?? []).map((c, i) => (
          <div key={i} className="flex items-center gap-2 py-1 text-[0.8rem]">
            <span className="min-w-0 flex-1 font-bold">{c.label}</span>
            <span className="num text-ink-dim">あと {c.doneAbsWeek - currentAbsWeek(state)} 週</span>
          </div>
        ))}
        <div className="panel-head mb-1 mt-3">施設</div>
        <div className="space-y-1.5">
          {FACILITY_IDS.map((f) => (
            <div key={f} className="flex items-center gap-2 text-[0.8rem]">
              <span className="min-w-0 flex-1 font-bold">{FACILITY_LABEL[f]}</span>
              <Level v={me.facilities[f]} max={levelMax(me, me.facilities[f])} />
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

function FacilityTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const mutate = useGame((s) => s.mutate)
  const working = busy(me, 'facility')
  const world = inWorld(me)
  return (
    <div className="panel scroll-y min-h-0 flex-1 p-3">
      {working && <div className="mb-2 rounded-lg bg-accent/15 px-3 py-1.5 text-[0.78rem] text-accent">工事中: {working.label}（あと {working.doneAbsWeek - currentAbsWeek(state)} 週）</div>}
      <div className={`mb-2 rounded-lg px-3 py-1.5 text-[0.74rem] ${world ? 'bg-gold/10 text-gold' : 'bg-black/20 text-ink-dim'}`}>
        {world ? 'ワールドリーグ: 施設は世界水準の Lv8 まで上げられます（Lv6 から費用 1.6 倍）。' : 'Lv6〜8 の世界水準の施設は、ワールドリーグに上がると建てられます。'}
      </div>
      <div className="grid grid-cols-2 gap-2">
        {FACILITY_IDS.map((f) => {
          const lv = me.facilities[f]
          const chk = canBuildFacility(me, f)
          return (
            <div key={f} className="rounded-xl bg-white/[0.04] p-2.5">
              <div className="flex items-center gap-2">
                <span className="min-w-0 flex-1 text-[0.88rem] font-black">{FACILITY_LABEL[f]}</span>
                <span className="num text-[0.75rem] text-ink-dim">Lv{lv}</span>
                <Level v={lv} max={levelMax(me, lv)} />
              </div>
              <div className="mt-0.5 text-[0.74rem] text-ink-dim">{FACILITY_EFFECT[f]}</div>
              {lv < (world || lv >= 5 ? WORLD_FACILITY : 5) && (
                <button className="btn btn-blue btn-sm mt-1.5 w-full" disabled={!chk.ok} onClick={() => mutate((st) => void startFacility(st, st.clubs[st.playerClubId], f))}>
                  {chk.ok || chk.reason === '資金が足りない' ? `Lv${lv + 1} へ（${formatMoneyShort(facilityCost(lv + 1))}円・${facilityWeeks(lv + 1)}週）` : chk.reason}
                </button>
              )}
            </div>
          )
        })}
      </div>
    </div>
  )
}

function StadiumTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const mutate = useGame((s) => s.mutate)
  const working = busy(me, 'stadium')
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel w-[40%] shrink-0 p-3">
        <div className="text-[1rem] font-black">{me.stadium.name}</div>
        <div className="mt-2 grid grid-cols-2 gap-y-1.5 text-[0.82rem]">
          <Kv k="収容人数" v={`${me.stadium.capacity.toLocaleString()}人`} />
          <Kv k="設備のグレード" v={<Level v={me.stadium.grade} max={inWorld(me) || me.stadium.grade > 5 ? 7 : 5} />} />
          <Kv k="維持費（年）" v={formatMoneyShort(maintenancePerSeason(me)) + '円'} />
          {inWorld(me) && <Kv k="海外から観戦" v={`1 試合 ${worldVisitors(me).toLocaleString()}人`} />}
        </div>
        <p className="mt-3 text-[0.76rem] text-ink-dim">客席が足りないと観客を取りこぼします。グレードを上げると観客が増え、入場料も高く取れます。</p>
        <p className="mt-1 text-[0.72rem] text-ink-mute">{inWorld(me) ? 'ワールドリーグ: 客席は 10 万人まで、グレードは 7 まで上げられます。' : '客席は 8 万人・グレード 5 まで。ワールドリーグに上がると 10 万人・グレード 7 まで。'}</p>
        {working && <div className="mt-2 rounded-lg bg-accent/15 px-3 py-1.5 text-[0.78rem] text-accent">工事中: {working.label}（あと {working.doneAbsWeek - currentAbsWeek(state)} 週）</div>}
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-2 p-3">
        {stadiumPlans(me).map((p) => (
          <div key={p.label} className="flex items-center gap-2 rounded-xl bg-white/[0.04] p-2.5">
            <div className="min-w-0 flex-1">
              <div className="text-[0.85rem] font-bold">{p.label}</div>
              <div className="num text-[0.76rem] text-ink-dim">
                {formatMoney(p.cost)}・工期 {p.weeks} 週
              </div>
            </div>
            <button className="btn btn-blue btn-sm" disabled={!!working || me.budget < p.cost} onClick={() => mutate((st) => void startStadium(st, st.clubs[st.playerClubId], p))}>
              着工
            </button>
          </div>
        ))}
      </div>
    </div>
  )
}

function StaffTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const mutate = useGame((s) => s.mutate)
  const now = currentAbsWeek(state)
  const [market, setMarket] = useState(false)
  const staff = clubStaff(state, me)
  const free = staffMarket(state)
  return (
    <div className="panel flex min-h-0 flex-1 flex-col p-3">
      <div className="mb-2 flex items-center gap-2">
        <span className="text-[0.75rem] text-ink-dim">人件費（年） {formatMoney(staffWages(state, me))}</span>
        <button className="btn btn-gold btn-sm ml-auto" onClick={() => setMarket(true)}>
          スタッフを探す（{free.length}人）
        </button>
      </div>
      <div className="scroll-y grid min-h-0 flex-1 grid-cols-2 content-start gap-2 pr-1">
        {staff.map((s) => (
          <StaffCard
            key={s.id}
            s={s}
            now={now}
            action={
              s.role !== 'owner' && s.role !== 'secretary' ? (
                <button className="btn btn-ghost btn-sm !min-h-[2.2rem] !px-2 !text-[0.72rem]" disabled={me.budget < severance(state, s)} onClick={() => mutate((st) => fire(st, st.clubs[st.playerClubId], st.staff[s.id]))} title={`違約金 ${formatMoney(severance(state, s))}`}>
                  解雇
                </button>
              ) : null
            }
          />
        ))}
      </div>
      <SideSheet open={market} onClose={() => setMarket(false)} title="スタッフを探す" width="66%">
        <div className="space-y-1.5 p-3">
          <LegendPanel state={state} />
          {free.map((s) => {
            const chk = canHire(state, me, s)
            return (
              <StaffCard
                key={s.id}
                s={s}
                now={now}
                action={
                  chk.reason && chk.reason !== '資金が足りない' ? (
                    <span className="w-[6.5rem] shrink-0 text-right text-[0.66rem] text-ink-mute">{chk.reason}</span>
                  ) : (
                    <button className="btn btn-blue btn-sm !min-h-[2.4rem] !text-[0.74rem]" disabled={!chk.ok} onClick={() => mutate((st) => void hire(st, st.clubs[st.playerClubId], st.staff[s.id]))} title={chk.reason}>
                      契約 {formatMoneyShort(signingFee(s))}
                    </button>
                  )
                }
              />
            )
          })}
        </div>
      </SideSheet>
    </div>
  )
}

/** キャリアモードから書き出した OB（引退していれば監督・コーチの候補、現役ならフリーの選手として呼べる） */
function LegendPanel({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const [list] = useState(() => loadLegends())
  if (!list.length) return null
  return (
    <div className="mb-2 rounded-xl border border-gold/40 bg-gold/5 p-2">
      <div className="mb-1 text-[0.75rem] font-black text-gold">キャリアモードの OB</div>
      {list.map((l) => {
        const here = hasLegend(state, l.key)
        return (
          <div key={l.key} className="flex items-center gap-2 py-0.5 text-[0.75rem]">
            <span className="w-6 shrink-0 text-center text-[0.9rem] font-black text-gold">{l.grade}</span>
            <span className="min-w-0 flex-1 truncate font-bold">{l.name}</span>
            <span className="shrink-0 text-[0.7rem] text-ink-dim">{l.retired ? '監督・コーチの候補' : `現役 ${l.age} 歳・${l.pos}`}</span>
            <button className="btn btn-blue btn-sm shrink-0 !min-h-[2rem]" disabled={here} onClick={() => mutate((st) => void addLegend(st, l))}>
              {here ? '呼んだ' : '呼ぶ'}
            </button>
          </div>
        )
      })}
      <div className="text-[0.68rem] text-ink-mute">呼ぶと、引退した OB はこの一覧に、現役の OB は移籍市場のフリーの選手に加わります。</div>
    </div>
  )
}

function SponsorTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const mutate = useGame((s) => s.mutate)
  const offers = state.offers.filter((o) => o.kind === 'sponsor')
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[42%] shrink-0 p-3">
        <div className="panel-head mb-1">契約中</div>
        {[...sponsorSlots(me), ...(me.sponsors ?? []).map((c) => c.slot).filter((x) => !sponsorSlots(me).includes(x))].map((slot) => {
          const c = (me.sponsors ?? []).find((x) => x.slot === slot)
          return (
            <div key={slot} className="mb-1.5 rounded-lg bg-white/[0.04] px-2.5 py-1.5">
              <div className="text-[0.74rem] text-ink-dim">{SLOT_LABEL[slot]}</div>
              {c ? (
                <div className="flex items-center gap-2 text-[0.82rem]">
                  <span className="min-w-0 flex-1 truncate font-bold">{c.company}</span>
                  <span className="num">{formatMoneyShort(c.annual)}円/年</span>
                </div>
              ) : (
                <div className="text-[0.78rem] text-ink-mute">なし（目安 {formatMoneyShort(sponsorBase(state, me, slot))}円/年）</div>
              )}
            </div>
          )
        })}
        <div className="mt-2 text-[0.78rem] text-ink-dim">地元の小口スポンサー: {formatMoneyShort(localSupport(state, me))}円/年</div>
        <p className="mt-1 text-[0.72rem] text-ink-mute">空いている枠には、プレシーズンに申し出が届きます。人気・格・リーグが上がるほど額が上がります。{inWorld(me) ? 'ワールドリーグでは世界の企業から（額は 1 部の約 1.8 倍）、4 つ目の枠「グローバルパートナー」も開きます。' : 'ワールドリーグに上がると、世界の企業と 4 つ目の枠「グローバルパートナー」が開きます。'}</p>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-1.5 p-3">
        <div className="panel-head mb-1">申し出（{offers.length}）</div>
        {offers.length === 0 && <div className="text-[0.78rem] text-ink-dim">いまは申し出がありません</div>}
        {offers.map((o) =>
          o.kind === 'sponsor' ? (
            <div key={o.id} className="flex items-center gap-2 rounded-xl bg-white/[0.05] p-2.5">
              <div className="min-w-0 flex-1">
                <div className="text-[0.72rem] text-ink-dim">{SLOT_LABEL[o.slot]}</div>
                <div className="truncate text-[0.88rem] font-black">{o.company}</div>
                <div className="num text-[0.78rem]">
                  年 {formatMoney(o.annual)}・{o.years} 年契約
                  {o.bonus && <span className="ml-1 text-gold">（{o.bonus.value} 位以内で +{formatMoneyShort(o.bonus.amount)}円）</span>}
                </div>
              </div>
              <button className="btn btn-gold btn-sm" onClick={() => mutate((st) => void acceptSponsor(st, st.clubs[st.playerClubId], o.id))}>
                契約
              </button>
            </div>
          ) : null,
        )}
      </div>
    </div>
  )
}

function FinanceTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const weeks = state.finance.filter((w) => Math.floor(w.absWeek / 48) === state.season)
  const sum = (k: keyof (typeof weeks)[number]) => weeks.reduce((s, w) => s + (w[k] as number), 0)
  const rows: [string, number][] = [
    ['入場料', sum('ticket')],
    ['分配金', sum('tv')],
    ['スポンサー', sum('sponsor')],
    ['グッズ', sum('goods')],
    ['賞金', sum('prize')],
    ['事業', weeks.reduce((s, w) => s + (w.business ?? 0), 0)],
    ['選手の年俸', -sum('wages')],
    ['スタッフの年俸', -sum('staffWages')],
    ['維持費', -sum('maintenance')],
    ['工事・出店', -sum('construction')],
    ['海外ユース', -weeks.reduce((s, w) => s + (w.youth ?? 0), 0)],
    ['その他', sum('other')],
  ]
  const net = weeks.reduce((s, w) => s + weekNet(w), 0)
  const recent = state.finance.slice(-12)
  const maxAbs = Math.max(1, ...recent.map((w) => Math.abs(weekNet(w))))
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[46%] shrink-0 p-3">
        <div className="panel-head mb-1">今シーズンの収支</div>
        <div className="space-y-0.5 text-[0.8rem]">
          {rows.map(([k, v]) => (
            <div key={k} className="flex justify-between">
              <span className="text-ink-dim">{k}</span>
              <span className={`num font-bold ${v < 0 ? 'text-bad' : v > 0 ? 'text-good' : ''}`}>{v === 0 ? '―' : formatMoneyShort(v) + '円'}</span>
            </div>
          ))}
          <div className="mt-1 flex justify-between border-t border-line/50 pt-1 text-[0.88rem]">
            <span className="font-bold">合計</span>
            <span className={`num font-black ${net < 0 ? 'text-bad' : 'text-gold'}`}>{formatMoneyShort(net)}円</span>
          </div>
        </div>
      </div>
      <div className="panel min-w-0 flex-1 p-3">
        <div className="panel-head mb-1">直近 12 週の収支</div>
        <div className="flex h-[60%] items-center gap-1">
          {recent.map((w) => {
            const v = weekNet(w)
            const h = (Math.abs(v) / maxAbs) * 50
            return (
              <div key={w.absWeek} className="relative flex h-full flex-1 flex-col justify-center" title={`${formatMoneyShort(v)}円`}>
                <div className="absolute inset-x-0 top-1/2 h-px bg-white/15" />
                <div className={`mx-auto w-full max-w-[1.4rem] rounded-sm ${v >= 0 ? 'self-end bg-good' : 'bg-bad'}`} style={{ height: `${h}%`, marginTop: v >= 0 ? `${50 - h}%` : '50%', marginBottom: v >= 0 ? '50%' : 0 }} />
              </div>
            )
          })}
        </div>
        <div className="mt-2 grid grid-cols-2 gap-y-1 text-[0.75rem]">
          <Kv k="選手の年俸（年）" v={formatMoneyShort(squadWages(state, me.id)) + '円'} />
          <Kv k="スタッフ（年）" v={formatMoneyShort(staffWages(state, me)) + '円'} />
          <Kv k="維持費（年）" v={formatMoneyShort(maintenancePerSeason(me)) + '円'} />
        </div>
      </div>
    </div>
  )
}

export function ClubScreen() {
  const state = useGameState()
  const initial = (useCurrentScreen().params?.tab as Tab | undefined) ?? 'info'
  const [tab, setTab] = useState<Tab>(initial)
  const offers = state.offers.length
  return (
    <AppShell title="クラブ" current="club" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className="seg scroll-x shrink-0 self-start">
          {TABS.map(([id, label, icon]) => (
            <button key={id} aria-selected={tab === id} onClick={() => setTab(id)} className="relative !flex items-center gap-1">
              <Icon name={icon} className="h-4 w-4 shrink-0" />
              {label}
              {id === 'sponsor' && offers > 0 && <span className="nav-badge !-right-0.5 !-top-1">{offers}</span>}
            </button>
          ))}
        </div>
        {tab === 'info' && <InfoTab state={state} />}
        {tab === 'power' && <PowerTab state={state} />}
        {tab === 'facility' && <FacilityTab state={state} />}
        {tab === 'stadium' && <StadiumTab state={state} />}
        {tab === 'sales' && <SalesTab state={state} />}
        {tab === 'community' && <CommunityTab state={state} />}
        {tab === 'staff' && <StaffTab state={state} />}
        {tab === 'sponsor' && <SponsorTab state={state} />}
        {tab === 'business' && <BusinessTab state={state} />}
        {tab === 'finance' && <FinanceTab state={state} />}
      </div>
    </AppShell>
  )
}
