/** 開発用: 2 クラブを選んで試合を観戦する（試合エンジンの確認・調整用）。 */
import { useMemo, useState } from 'react'
import { teamStrength, type GameState } from '../../engine'
import { buildMatchSetup } from '../../engine/match/setup'
import type { MatchSetup, MatchSummary } from '../../engine/match/live/types'
import { MatchView } from '../match/MatchView'
import { Emblem } from '../components/ClubArt'
import { Icon } from '../components/Icon'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'

function ClubPicker({ state, ids, value, onChange, label }: { state: GameState; ids: number[]; value: number; onChange: (id: number) => void; label: string }) {
  const i = ids.indexOf(value)
  const c = state.clubs[value]
  const step = (d: number) => onChange(ids[(i + d + ids.length) % ids.length])
  return (
    <div className="panel flex flex-1 flex-col items-center gap-2 p-3">
      <div className="text-[0.75rem] font-bold text-ink-dim">{label}</div>
      <div className="flex w-full items-center gap-2">
        <button className="btn btn-ghost btn-sm w-10 !px-0" onClick={() => step(-1)}>
          ◀
        </button>
        <div className="flex min-w-0 flex-1 flex-col items-center">
          <Emblem id={`lab-${c.id}`} emblem={c.emblem} colors={c.colors} size="3rem" />
          <div className="mt-1 w-full truncate text-center text-[0.95rem] font-black">{c.name}</div>
          <div className="num text-[0.78rem] text-ink-dim">
            {c.tactics.formation}・戦力 {Math.round(teamStrength(state, c))}
          </div>
        </div>
        <button className="btn btn-ghost btn-sm w-10 !px-0" onClick={() => step(1)}>
          ▶
        </button>
      </div>
    </div>
  )
}

export function MatchLabScreen() {
  const state = useGameState()
  const pop = useUi((s) => s.pop)
  const params = useCurrentScreen().params as { home?: number; away?: number; title?: string } | undefined
  const ids = useMemo(() => state.competitions.filter((c) => ['NPL1', 'NPL2', 'NPL3', 'ENG1', 'ESP1'].includes(c.id)).flatMap((c) => c.clubIds), [state])
  const [home, setHome] = useState(params?.home ?? ids[0])
  const [away, setAway] = useState(params?.away ?? ids[1])
  const [setup, setSetup] = useState<MatchSetup | null>(null)
  const [last, setLast] = useState<MatchSummary | null>(null)
  const [debug, setDebug] = useState(false)
  const [n, setN] = useState(1)

  if (setup) return <MatchView setup={setup} debug={debug} onExit={(s) => { setLast(s); setSetup(null) }} />

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-white/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">{params?.title ?? 'Match Lab（試合エンジンの確認）'}</h1>
      </header>
      <div className="safe-px safe-pb flex min-h-0 flex-1 flex-col gap-3 pt-3">
        <div className="flex gap-3">
          <ClubPicker state={state} ids={ids} value={home} onChange={setHome} label="ホーム" />
          <ClubPicker state={state} ids={ids} value={away} onChange={setAway} label="アウェイ" />
        </div>
        {last && (
          <div className="panel-flat px-3 py-2 text-[0.85rem]">
            前回の結果: {state.clubs[home].short} {last.score[0]} - {last.score[1]} {state.clubs[away].short}（シュート {last.stats[0].shots}-{last.stats[1].shots}、xG {last.stats[0].xg.toFixed(2)}-{last.stats[1].xg.toFixed(2)}）
          </div>
        )}
        <div className="mt-auto flex items-center justify-end gap-2">
          <button className={`btn btn-sm ${debug ? 'btn-blue' : 'btn-ghost'}`} onClick={() => setDebug((d) => !d)}>
            目標位置を表示
          </button>
          <button
            className="btn btn-gold min-w-[10rem]"
            onClick={() => {
              setN((v) => v + 1)
              setSetup(buildMatchSetup(state, 7_000_000 + n, home, away))
            }}
          >
            キックオフ
          </button>
        </div>
      </div>
    </div>
  )
}
