/**
 * 試合の観戦画面（Canvas＋HUD）。LiveMatch を一定の速さで進め、描画は補間して 60fps。
 * HUD（スコア・時計・実況）は 1 秒に数回だけ React に反映する。
 * リプレイ: 直近の位置を記録しておき（ui/match/replay.ts）、ゴール・ポスト・ビッグセーブを切り出す。
 * ゴールのあとはカットインのあとにリプレイを流し（設定でオフにできる）、場面は試合後のハイライトに渡す。
 */
import { useEffect, useMemo, useRef, useState } from 'react'
import { sound } from '../audio/sound'
import { Portrait } from '../components/Portrait'
import { photoIdOf } from '../components/portraits'
import { useGame } from '../../stores/gameStore'
import { ageAt, currentAbsWeek } from '../../engine'
import { LiveMatch, type Moment } from '../../engine/match/live/sim'
import { DT, type MatchEvent, type MatchSetup, type MatchSummary } from '../../engine/match/live/types'
import { PitchRenderer } from './renderer'
import { Icon } from '../components/Icon'
import { useSettings } from '../../stores/settingsStore'
import { InterventionSheet } from './InterventionSheet'
import { Recorder, type Clip } from './replay'
import { ReplayCanvas } from './ReplayCanvas'
import { highlightKey, useHighlights } from '../../stores/highlightStore'

interface Hud {
  score: [number, number]
  clock: string
  half: number
  events: MatchEvent[]
  poss: [number, number]
  shots: [number, number]
  over: boolean
  pens?: [number, number]
}

function hudOf(m: LiveMatch): Hud {
  const p0 = m.teams[0].stats.possession
  const p1 = m.teams[1].stats.possession
  const tot = Math.max(1, p0 + p1)
  return {
    score: [m.score[0], m.score[1]],
    clock: m.clockLabel(),
    half: m.half,
    events: m.events.filter((e) => e.text && e.type !== 'foul').slice(-3),
    poss: [Math.round((p0 / tot) * 100), Math.round((p1 / tot) * 100)],
    shots: [m.teams[0].stats.shots, m.teams[1].stats.shots],
    over: m.finished,
    pens: m.pens,
  }
}

/**
 * 再生の速さの底上げ（M14 で試合の中身を 2 倍にしたので、×1 でも 4/3 倍で進め、観戦の時間は前の 1.5 倍にする）
 */
const VIEW_RATE = 4 / 3

const EVENT_ICON: Partial<Record<string, string>> = { goal: '⚽', yellow: '🟨', red: '🟥', save: '🧤', post: '🥅', sub: '🔄', injury: '✚', penalty: '❗', corner: '⚑', offside: '🚩' }

/** 見せ場の成功の見込みを ◎○△ で（シュートは見込みが低めなので基準を下げる） */
function chanceMark(kind: string, prob: number): string {
  const [hi, mid] = kind === 'shoot' ? [0.3, 0.12] : [0.62, 0.38]
  return prob >= hi ? '◎' : prob >= mid ? '○' : '△'
}

/** 試合の出来事の音 */
function playEventSound(type: string) {
  if (type === 'goal') sound.play('goal')
  else if (type === 'kickoff' || type === 'halftime') sound.play('whistle')
  else if (type === 'fulltime') sound.play('whistleLong')
  else if (type === 'yellow' || type === 'red' || type === 'foul' || type === 'offside') sound.play('card')
  else if (type === 'post' || type === 'save' || type === 'chance') sound.play('ooh')
  else if (type === 'shot' || type === 'miss' || type === 'block') sound.play('kick')
}

export function MatchView({ setup, onExit, debug = false, userSide, focus }: { setup: MatchSetup; onExit: (s: MatchSummary | null) => void; debug?: boolean; userSide?: 0 | 1; focus?: number }) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const wrapRef = useRef<HTMLDivElement>(null)
  // 試合オブジェクト（setup ごとに 1 つ。中身はループで書き換わる）。キャリアなら主人公の見せ場で止まる
  // 試合ごとにリプレイの記録も新しくする
  const { match, recorder } = useMemo(() => ({ match: new LiveMatch(setup, focus !== undefined ? { focus, interactive: true } : {}), recorder: new Recorder() }), [setup, focus])
  // 試合中はスタジアムの歓声。出たらメニューの BGM に戻す
  useEffect(() => {
    sound.setScene('match')
    return () => sound.setScene('menu')
  }, [])
  const [moment, setMoment] = useState<Moment | null>(null)
  const defaultSpeed = useSettings((s) => s.matchSpeed)
  const [speed, setSpeed] = useState<number>(defaultSpeed)
  const [paused, setPaused] = useState(false)
  const [camera, setCamera] = useState<'follow' | 'full'>('follow')
  const [hud, setHud] = useState<Hud | null>(null)
  const [goalFlash, setGoalFlash] = useState<{ team: 0 | 1; key: number; scorer?: string; photo?: string; minute?: number; assist?: string } | null>(null)
  const [sheet, setSheet] = useState(false)
  const autoReplay = useSettings((s) => s.goalReplay)
  // 再生中のリプレイ（そのあいだ試合は止める）
  const [replay, setReplay] = useState<Clip | null>(null)
  const ctl = useRef({ speed, paused, camera, debug, replay: false, autoReplay })
  useEffect(() => {
    ctl.current = { speed, paused, camera, debug, replay: !!replay, autoReplay }
  }, [speed, paused, camera, debug, replay, autoReplay])

  useEffect(() => {
    const m = match
    const canvas = canvasRef.current!
    const wrap = wrapRef.current!
    const r = new PitchRenderer(canvas)
    const fit = () => r.resize(wrap.clientWidth, wrap.clientHeight)
    fit()
    const ro = new ResizeObserver(fit)
    ro.observe(wrap)
    let acc = 0
    let last = performance.now()
    let raf = 0
    let lastHud = 0
    let lastFlash = -1
    // 音: 新しく起きた出来事ごとに（「結果へ」で一気に進んだときは鳴らさない）
    let heard = m.events.length
    // リプレイ: 場面の印（フラッシュの時刻）・切り出した場面の数・ゴールのカットインが終わる時刻
    let marked = -1
    let clipsSeen = 0
    let flashUntil = 0
    const queue: Clip[] = []
    const all = [...m.setup.home.starters, ...m.setup.home.bench, ...m.setup.away.starters, ...m.setup.away.bench]
    const nameOf = (id?: number) => all.find((p) => p.id === id)?.short ?? ''
    const markMoment = () => {
      const f = m.flash
      if (!f || f.t === marked || (f.kind !== 'goal' && f.kind !== 'post' && f.kind !== 'save')) return
      marked = f.t
      const e = [...m.events].reverse().find((x) => x.type === f.kind)
      if (!e) return
      // セーブは決定的な場面（xG 0.2 以上）だけ
      if (f.kind === 'save' && (e.xg ?? 0) < 0.2) return
      const label = f.kind === 'goal' ? `${nameOf(e.player)}のゴール` : f.kind === 'post' ? `${nameOf(e.player)}のシュートがポスト直撃` : `${nameOf(e.other)}のビッグセーブ`
      recorder.mark({ kind: f.kind, team: e.team, minute: e.minute, label })
    }
    const frame = (now: number) => {
      const dt = Math.min(0.1, (now - last) / 1000)
      last = now
      const c = ctl.current
      if (!c.paused && !c.replay && !m.finished) {
        acc += dt * c.speed * VIEW_RATE
        let n = 0
        while (acc >= DT && n < 40) {
          m.step()
          recorder.record(m)
          markMoment()
          acc -= DT
          n++
        }
        if (n >= 40) acc = 0
      }
      // ゴールの場面が切り出せたら、カットインのあとに流す
      if (recorder.clips.length > clipsSeen) {
        for (const clip of recorder.clips.slice(clipsSeen)) if (clip.kind === 'goal' && c.autoReplay && !m.finished) queue.push(clip)
        clipsSeen = recorder.clips.length
      }
      if (queue.length && !c.replay && now > flashUntil && !m.pendingMoment) {
        const clip = queue.shift()!
        ctl.current.replay = true
        setReplay(clip)
      }
      r.draw(m, m.finished ? 1 : acc / DT, { camera: c.camera, debug: c.debug, showNames: true, focusId: focus })
      // 見せ場で止まったら選択肢を出す
      if (m.pendingMoment) {
        acc = 0
        setMoment((cur) => (cur === m.pendingMoment ? cur : m.pendingMoment))
      }
      if (m.events.length > heard) {
        const fresh = m.events.slice(heard)
        heard = m.events.length
        if (fresh.length <= 6 && !m.finished) for (const e of fresh) playEventSound(e.type)
        else if (m.finished) sound.play('whistleLong')
      }
      if (m.flash && m.flash.kind === 'goal' && m.flash.t !== lastFlash) {
        lastFlash = m.flash.t
        // 得点者（カットイン用）
        const g = [...m.events].reverse().find((e) => e.type === 'goal')
        const sc = all.find((p) => p.id === g?.player)
        const as = all.find((p) => p.id === g?.other)
        // 写真: 固有キャラか、生成した写真（主人公など。年齢に合わせる）
        const st = useGame.getState().state
        const pl = sc && st ? st.players[sc.id] : undefined
        const photo = pl && st ? photoIdOf(pl, ageAt(currentAbsWeek(st), pl.birthAbsWeek)) : sc?.starId
        setGoalFlash({ team: m.flash.team, key: m.flash.t, scorer: sc?.name, photo, minute: g?.minute, assist: as?.short })
        flashUntil = now + 2500
      }
      if (now - lastHud > 220) {
        lastHud = now
        setHud(hudOf(m))
      }
      raf = requestAnimationFrame(frame)
    }
    raf = requestAnimationFrame(frame)
    return () => {
      cancelAnimationFrame(raf)
      ro.disconnect()
    }
  }, [match, focus, recorder])

  useEffect(() => {
    if (!goalFlash) return
    const id = setTimeout(() => setGoalFlash(null), 2400)
    return () => clearTimeout(id)
  }, [goalFlash])

  const skip = () => {
    setMoment(null)
    match.runToEnd()
    setHud(hudOf(match))
  }

  const choose = (i: number) => {
    match.resolveMoment(i)
    setMoment(null)
  }

  const [confirmExit, setConfirmExit] = useState(false)
  /** 試合後のハイライトに、切り出した場面を渡す */
  const keepHighlights = () => {
    recorder.flush()
    useHighlights.getState().set(highlightKey(setup.home.clubId, setup.away.clubId), [...recorder.clips])
  }
  const exit = () => {
    // 自クラブの試合は途中でやめても、残りを自動で進めて結果にする
    if (!match.finished && userSide !== undefined) {
      setPaused(true)
      setConfirmExit(true)
      return
    }
    keepHighlights()
    onExit(match.finished ? match.summary() : null)
  }

  const home = setup.home
  const away = setup.away
  const s = hud?.score ?? [0, 0]
  return (
    <div className="absolute inset-0 flex flex-col bg-[#0b3d22]">
      <div ref={wrapRef} className="relative min-h-0 flex-1">
        <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" />

        {/* ゴールのリプレイ（タップで飛ばす） */}
        {replay && (
          <button className="absolute inset-0 block" onClick={() => setReplay(null)} aria-label="リプレイを飛ばす">
            <ReplayCanvas clip={replay} rate={0.75} focusId={focus} onEnd={() => setTimeout(() => setReplay(null), 600)} className="absolute inset-0" />
            <span className="safe-l absolute left-14 top-2 flex items-center gap-1.5 rounded-md bg-bad/90 px-2 py-0.5 text-[0.75rem] font-black tracking-widest text-white">
              <span className="h-2 w-2 animate-pulse rounded-full bg-white" />
              REPLAY
            </span>
            <span className="absolute bottom-[20%] left-1/2 -translate-x-1/2 rounded-lg bg-[#06121f]/80 px-3 py-1 text-[0.85rem] font-black text-white">
              {replay.minute}' {replay.label}
            </span>
            <span className="safe-r absolute right-3 top-2 rounded-lg bg-black/55 px-3 py-1.5 text-[0.78rem] font-bold text-white">タップで飛ばす ≫</span>
          </button>
        )}

        {/* スコアボード */}
        <div className="safe-t pointer-events-none absolute inset-x-0 top-0 flex justify-center pt-1.5">
          <div className="flex items-stretch overflow-hidden rounded-lg shadow-lg" style={{ boxShadow: '0 4px 14px rgba(0,0,0,0.45)' }}>
            <div className="flex items-center gap-1.5 px-2.5 py-1 text-[0.85rem] font-black text-white" style={{ background: home.colors.primary }}>
              <span className="h-3 w-1.5 rounded-sm" style={{ background: home.colors.secondary }} />
              <span style={{ color: lum(home.colors.primary) > 0.6 ? '#111' : '#fff' }}>{home.short}</span>
            </div>
            <div className="num flex items-center gap-1.5 bg-[#0b1320]/95 px-3 text-[1.15rem] font-black text-white">
              <span>{s[0]}</span>
              <span className="text-ink-mute">-</span>
              <span>{s[1]}</span>
            </div>
            <div className="flex items-center gap-1.5 px-2.5 py-1 text-[0.85rem] font-black" style={{ background: away.colors.primary }}>
              <span style={{ color: lum(away.colors.primary) > 0.6 ? '#111' : '#fff' }}>{away.short}</span>
              <span className="h-3 w-1.5 rounded-sm" style={{ background: away.colors.secondary }} />
            </div>
            <div className="num flex items-center bg-gold px-2 text-[0.8rem] font-black text-[#2a1a00]">{hud?.clock ?? '0:00'}</div>
          </div>
        </div>

        {/* 左上: 終了 */}
        <div className="safe-l safe-t absolute left-0 top-0 p-1.5">
          <button className="flex h-10 w-10 items-center justify-center rounded-lg bg-black/45 text-white" onClick={exit} aria-label="終了">
            <Icon name="back" className="h-5 w-5" />
          </button>
        </div>

        {/* 右: 速度・カメラ（右手の親指） */}
        <div className="safe-r absolute bottom-2 right-0 flex flex-col items-end gap-1.5 pr-2">
          <div className="flex gap-1 rounded-xl bg-black/45 p-1">
            {[1, 2, 4, 8].map((v) => (
              <button key={v} onClick={() => { setSpeed(v); setPaused(false) }} className={`num h-10 w-11 rounded-lg text-[0.85rem] font-black ${speed === v && !paused ? 'bg-gold text-[#2a1a00]' : 'text-white'}`}>
                ×{v}
              </button>
            ))}
            <button onClick={() => setPaused((p) => !p)} className={`h-10 w-11 rounded-lg text-[0.85rem] font-black ${paused ? 'bg-accent text-white' : 'text-white'}`} aria-label="一時停止">
              {paused ? '▶' : 'Ⅱ'}
            </button>
          </div>
          <div className="flex gap-1">
            {userSide !== undefined && !hud?.over && (
              <button
                onClick={() => {
                  setPaused(true)
                  setSheet(true)
                }}
                className="h-10 rounded-lg bg-accent px-3 text-[0.75rem] font-black text-white"
              >
                作戦
              </button>
            )}
            <button onClick={() => setCamera((c) => (c === 'follow' ? 'full' : 'follow'))} className="h-10 rounded-lg bg-black/45 px-3 text-[0.75rem] font-bold text-white">
              {camera === 'follow' ? '全体' : '追従'}
            </button>
            <button onClick={skip} disabled={hud?.over} className="h-10 rounded-lg bg-black/45 px-3 text-[0.75rem] font-bold text-white disabled:opacity-40">
              結果へ ≫
            </button>
          </div>
        </div>

        {/* 実況 */}
        <div className="safe-l safe-b pointer-events-none absolute bottom-2 left-0 w-[52%] space-y-1 pl-2">
          {hud?.events.map((e, i) => (
            <div key={`${e.t}-${i}`} className="anim-rise flex items-start gap-1.5 rounded-lg bg-[#06121f]/80 px-2 py-1 text-[0.78rem] leading-snug text-white" style={{ opacity: 0.55 + (i / 3) * 0.45 }}>
              <span className="num shrink-0 font-black text-gold">{e.minute}{e.added ? `+${e.added}` : ''}'</span>
              <span className="shrink-0">{EVENT_ICON[e.type] ?? ''}</span>
              <span className="min-w-0">{e.text}</span>
            </div>
          ))}
        </div>

        {/* キャリア: 見せ場の選択 */}
        {moment && (
          <div className="anim-fade absolute inset-0 z-20 flex items-end justify-center bg-black/35 pb-4">
            <div className="panel anim-rise w-[36rem] max-w-[92%] p-3">
              <div className="text-center text-[1.05rem] font-black text-gold">{moment.title}</div>
              <div className="mt-2 grid gap-2" style={{ gridTemplateColumns: `repeat(${moment.choices.length}, minmax(0, 1fr))` }}>
                {moment.choices.map((c, i) => (
                  <button key={c.label} className="btn btn-blue flex h-auto min-h-[3.4rem] flex-col gap-0.5 py-1.5" onClick={() => choose(i)}>
                    <span className="text-[0.92rem] font-black">{c.label}</span>
                    <span className="text-[0.75rem] font-bold text-[#cfe7ff]">成功 {chanceMark(c.kind, c.prob)}</span>
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}

        {/* ゴール演出 */}
        {goalFlash && (
          <div key={goalFlash.key} className="pointer-events-none absolute inset-0 flex items-center justify-center">
            <div className="goal-burst text-[4.2rem] font-black italic tracking-wider" style={{ color: '#fff', textShadow: `0 0 18px ${(goalFlash.team === 0 ? home : away).colors.primary}, 0 4px 0 rgba(0,0,0,0.5)` }}>
              GOAL!!
            </div>
            {goalFlash.scorer && (
              <div className="goal-cutin absolute bottom-[18%] left-0 flex items-center gap-3 py-2 pl-6 pr-10" style={{ background: `linear-gradient(90deg, ${(goalFlash.team === 0 ? home : away).colors.primary}ee 70%, transparent)` }}>
                {goalFlash.photo && <Portrait id={goalFlash.photo} kind="face" className="face-round h-14 w-14 shrink-0 border-2 border-white/80" />}
                <div className="text-white drop-shadow">
                  <div className="text-[0.75rem] font-bold opacity-90">
                    {(goalFlash.team === 0 ? home : away).name}
                    {goalFlash.minute !== undefined && `・${goalFlash.minute}分`}
                  </div>
                  <div className="text-[1.5rem] font-black leading-tight">{goalFlash.scorer}</div>
                  {goalFlash.assist && <div className="text-[0.78rem] opacity-90">アシスト {goalFlash.assist}</div>}
                </div>
              </div>
            )}
          </div>
        )}

        {userSide !== undefined && (
          <InterventionSheet
            m={match}
            side={userSide}
            open={sheet}
            onClose={() => {
              setSheet(false)
              setPaused(false)
            }}
          />
        )}

        {confirmExit && (
          <div className="anim-fade absolute inset-0 z-50 flex items-center justify-center bg-black/55">
            <div className="panel w-[22rem] p-4 text-center">
              <div className="text-[0.95rem] font-black">観戦をやめますか？</div>
              <p className="mt-1 text-[0.78rem] text-ink-dim">残りの時間は自動で進めて、結果を表示します。</p>
              <div className="mt-3 flex gap-2">
                <button
                  className="btn btn-ghost flex-1"
                  onClick={() => {
                    setConfirmExit(false)
                    setPaused(false)
                  }}
                >
                  観戦を続ける
                </button>
                <button
                  className="btn btn-gold flex-1"
                  onClick={() => {
                    match.runToEnd()
                    keepHighlights()
                    onExit(match.summary())
                  }}
                >
                  結果へ
                </button>
              </div>
            </div>
          </div>
        )}

        {/* 試合終了 */}
        {hud?.over && (
          <div className="anim-fade absolute inset-0 flex items-center justify-center bg-black/55">
            <div className="panel anim-rise w-[24rem] p-4 text-center">
              <div className="text-[0.85rem] font-bold text-ink-dim">試合終了</div>
              <div className="mt-1 flex items-center justify-center gap-3 text-[1rem] font-black">
                <span className="min-w-0 flex-1 truncate text-right">{home.name}</span>
                <span className="num shrink-0 whitespace-nowrap text-[2rem] text-gold">
                  {s[0]} - {s[1]}
                </span>
                <span className="min-w-0 flex-1 truncate text-left">{away.name}</span>
              </div>
              {hud.pens && (
                <div className="num text-[0.8rem] text-ink-dim">
                  PK {hud.pens[0]} - {hud.pens[1]}
                </div>
              )}
              <div className="num mt-2 grid grid-cols-3 gap-1 text-[0.78rem]">
                <span>{hud.poss[0]}%</span>
                <span className="text-ink-dim">支配率</span>
                <span>{hud.poss[1]}%</span>
                <span>{hud.shots[0]}</span>
                <span className="text-ink-dim">シュート</span>
                <span>{hud.shots[1]}</span>
              </div>
              <button className="btn btn-gold mt-3 w-full" onClick={exit}>
                閉じる
              </button>
            </div>
          </div>
        )}
      </div>
    </div>
  )
}

function lum(hex: string): number {
  const n = parseInt(hex.replace('#', ''), 16)
  return (0.299 * ((n >> 16) & 255) + 0.587 * ((n >> 8) & 255) + 0.114 * (n & 255)) / 255
}
