/** 選手・スタッフの顔。画像のある固有キャラと、生成した写真を選んだ人は写真、それ以外は自動生成の顔。 */
import { moodOf, type Player, type Staff } from '../../engine'
import { Portrait } from './Portrait'
import { PlayerAvatar } from './PlayerAvatar'
import { usePhotoId } from './usePhotoId'

export function PlayerFace({ p, kit, className = 'h-10 w-10', photo = false }: { p: Player; kit?: { primary: string; secondary: string }; className?: string; photo?: boolean }) {
  const id = usePhotoId(p)
  const avatar = <PlayerAvatar seed={p.id} nation={p.nation} mood={moodOf(p.condition, !!p.injury)} face={p.face} kit={kit} size="100%" />
  if (id) return <Portrait id={id} kind={photo ? 'photo' : 'face'} className={`${className} ${photo ? '' : 'face-round'}`} fallback={avatar} />
  return <div className={`${className} ${photo ? 'overflow-hidden rounded-lg' : 'face-round'}`}>{avatar}</div>
}

export function StaffFace({ s, className = 'h-10 w-10', photo = false }: { s: Staff; className?: string; photo?: boolean }) {
  const id = usePhotoId(s)
  const avatar = <PlayerAvatar seed={s.id + 100000} nation={s.nation} face={s.face} suit female={s.female} kit={{ primary: '#1e3a8a', secondary: '#ffffff' }} size="100%" />
  if (id) return <Portrait id={id} kind={photo ? 'photo' : 'face'} className={`${className} ${photo ? '' : 'face-round'}`} fallback={avatar} />
  return <div className={`${className} ${photo ? 'overflow-hidden rounded-lg' : 'face-round'}`}>{avatar}</div>
}
