/** 1か月オートの進み具合（週を 1 つずつ進めるあいだ、画面の上に出す。そのあいだはほかの操作を受けない）。 */
import { createPortal } from 'react-dom'
import { useGame } from '../../stores/gameStore'

export function AutoProgress() {
  const p = useGame((s) => s.progress)
  const root = document.getElementById('overlay-root')
  if (!p || !root) return null
  const pct = Math.round((p.done / p.total) * 100)
  // 「次の試合まで」は何週かかるか分からない（週の数だけ出す）
  const open = p.total > 4
  return createPortal(
    <div className="absolute inset-0 z-[70] flex items-center justify-center bg-black/45">
      <div className="panel panel-solid w-[19rem] p-4 text-center">
        <div className="text-[0.95rem] font-black text-gold">オートで進めています</div>
        <div className="num mt-1 text-[0.82rem] text-ink-dim">{open ? `${p.done + 1} 週目` : `${Math.min(p.done + 1, p.total)} / ${p.total} 週`}</div>
        <div className="mt-2.5 h-2 overflow-hidden rounded-full bg-white/10">
          <div className={`h-full rounded-full bg-gold ${open ? 'animate-pulse' : ''}`} style={{ width: open ? '100%' : `${Math.max(6, pct)}%`, transition: 'width 0.25s ease' }} />
        </div>
      </div>
    </div>,
    root,
  )
}
