/** 今週の過ごし方を選ぶシート（練習・休養・趣味・取材・おでかけ・デート・自主トレ）。 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { CAST_BY_ID, DATE_SPOTS, PLAY_STYLE_BY_ID, REGION_NAME, SHARED_MENUS, TRAIN_MENUS } from '../../engine/data/career'
import { canMeet, castName, placesFor, regionOf } from '../../engine/career/core'
import { dateCandidates, likesSpot, spotOpen } from '../../engine/career/dates'
import { partnerId } from '../../engine/career/family'
import { Portrait } from '../components/Portrait'
import { castPhotoId } from '../components/portraits'
import { ATTR_BY_KEY } from '../../engine/data/attributes'
import { EXP_LABEL, type ExpKind, type WeekAction } from '../../engine/models/career'
import { nextEventFor } from '../../engine/career/events'
import { trainingPartners } from '../../engine/career/week'
import { HOBBY_BY_ID } from '../../engine/career/life'
import { SideSheet } from '../layout/SideSheet'
import { useGame } from '../../stores/gameStore'

function ExpChips({ exp }: { exp: Partial<Record<ExpKind, number>> }) {
  return (
    <span className="flex flex-wrap gap-1">
      {(Object.entries(exp) as [ExpKind, number][]).map(([k, v]) => (
        <span key={k} className="rounded bg-white/[0.07] px-1 text-[0.68rem] text-ink-dim">
          {EXP_LABEL[k]}+{v}
        </span>
      ))}
    </span>
  )
}

function Item({ title, sub, right, onClick, on, hint }: { title: string; sub?: React.ReactNode; right?: React.ReactNode; onClick: () => void; on: boolean; hint?: string }) {
  return (
    <button className={`flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left ${on ? 'bg-gold/15 ring-1 ring-gold/50' : 'bg-white/[0.04]'}`} onClick={onClick}>
      <span className="min-w-0 flex-1">
        <span className="flex items-center gap-1.5 text-[0.82rem] font-bold">
          {title}
          {hint && <span className="rounded bg-accent/20 px-1 text-[0.66rem] font-black text-accent">{hint}</span>}
        </span>
        {sub && <span className="mt-0.5 block">{sub}</span>}
      </span>
      {right && <span className="shrink-0 text-[0.72rem] text-ink-dim">{right}</span>}
    </button>
  )
}

const same = (a: WeekAction | undefined, b: WeekAction) => JSON.stringify(a) === JSON.stringify(b)

export function ActionSheet({ state, open, onClose }: { state: GameState; open: boolean; onClose: () => void }) {
  const mutate = useGame((s) => s.mutate)
  const c = state.career!
  const p = state.players[c.playerId]
  const fav = PLAY_STYLE_BY_ID[c.style].favorite
  const gk = p.pos === 'GK'
  const menus = TRAIN_MENUS.filter((m) => (gk ? m.gk || SHARED_MENUS.includes(m.id) : !m.gk))
  const pick = (a: WeekAction) => {
    mutate((st) => void (st.career!.action = a))
    onClose()
  }
  const partners = trainingPartners(state).filter((id) => c.bonds[id])
  const [dateWho, setDateWho] = useState<string | null>(null)
  const dates = dateCandidates(state)
  const region = regionOf(state)
  const lover = partnerId(state)
  return (
    <SideSheet open={open} onClose={onClose} title="今週の過ごし方" width="64%">
      <div className="grid grid-cols-2 gap-3 p-3">
        <div className="space-y-1.5">
          <div className="panel-head">練習</div>
          {menus.map((m) => (
            <Item
              key={m.id}
              title={m.name}
              hint={m.id === fav ? '得意' : undefined}
              sub={
                <span className="flex flex-wrap items-center gap-1">
                  <span className="text-[0.68rem] text-accent">↑{m.attrs.map((a) => ATTR_BY_KEY[a].name).join('・')}</span>
                  <ExpChips exp={m.exp} />
                </span>
              }
              right={`体力 -${m.stamina}`}
              on={same(c.action, { kind: 'train', menu: m.id })}
              onClick={() => pick({ kind: 'train', menu: m.id })}
            />
          ))}
          <div className="panel-head pt-1">体を休める・名前を売る</div>
          <Item title="休養" sub={<span className="text-[0.7rem] text-ink-dim">体力が大きく戻り、調子が上がる</span>} right="体力 +35" on={same(c.action, { kind: 'rest' })} onClick={() => pick({ kind: 'rest' })} />
          {(c.hobbies ?? []).map((h) => {
            const def = HOBBY_BY_ID[h.id]
            return (
              <Item
                key={h.id}
                title={`趣味の時間（${def.name}）`}
                sub={<span className="text-[0.7rem] text-ink-dim">休みながら上達（腕前 {Math.floor(h.skill)}）・調子 +{def.condition}</span>}
                right={`体力 +${def.stamina}`}
                on={same(c.action, { kind: 'hobby', hobby: h.id })}
                onClick={() => pick({ kind: 'hobby', hobby: h.id })}
              />
            )
          })}
          <Item title="取材・ファンサービス" sub={<span className="text-[0.7rem] text-ink-dim">知名度が上がる（オファーが届きやすくなる）</span>} right="体力 -4" on={same(c.action, { kind: 'media' })} onClick={() => pick({ kind: 'media' })} />
        </div>
        <div className="space-y-1.5">
          <div className="panel-head">おでかけ（人に会える）</div>
          {region !== 'JP' && <div className="text-[0.72rem] text-ink-dim">{REGION_NAME[region]}の街</div>}
          {placesFor(state).map((pl) => {
            const people = pl.people.filter((id) => CAST_BY_ID[id] && canMeet(state, id))
            const known = people.filter((id) => c.bonds[id])
            const event = people.some((id) => c.bonds[id] && nextEventFor(state, id))
            return (
              <Item
                key={pl.id}
                title={pl.name}
                hint={event ? '何か起きそう' : undefined}
                sub={<span className="text-[0.7rem] text-ink-dim">{known.length ? `会えそう: ${known.map((id) => castName(state, id)).join('・')}` : pl.desc}</span>}
                right={pl.stamina > 0 ? `体力 +${pl.stamina}` : `体力 ${pl.stamina}`}
                on={same(c.action, { kind: 'outing', place: pl.id })}
                onClick={() => pick({ kind: 'outing', place: pl.id })}
              />
            )
          })}
          <div className="panel-head pt-1">デートに誘う</div>
          {dates.length === 0 && <div className="text-[0.76rem] text-ink-mute">{lover ? `${castName(state, lover)}は今は会えません` : 'おでかけで会って仲良くなる（絆 30）と、デートに誘えます'}</div>}
          {dates.map((who) => (
            <div key={who}>
              <button className={`flex w-full items-center gap-2 rounded-lg px-2.5 py-1.5 text-left ${dateWho === who || (c.action?.kind === 'date' && c.action.who === who) ? 'bg-pink/15 ring-1 ring-pink/50' : 'bg-white/[0.04]'}`} onClick={() => setDateWho(dateWho === who ? null : who)}>
                <Portrait id={castPhotoId(who, c.spouse)} kind="face" className="face-round h-8 w-8 shrink-0" />
                <span className="min-w-0 flex-1">
                  <span className="block text-[0.82rem] font-bold">{castName(state, who)}</span>
                  <span className="block text-[0.7rem] text-ink-dim">
                    {who === lover ? (who === c.spouse ? '妻' : '恋人') : `絆 ${Math.floor(c.bonds[who]?.value ?? 0)}`}・デート {c.bonds[who]?.dates ?? 0} 回
                  </span>
                </span>
                <span className="shrink-0 text-[0.72rem] text-pink">{dateWho === who ? '行き先を選ぶ ▾' : '誘う ▸'}</span>
              </button>
              {dateWho === who && (
                <div className="mt-1 grid grid-cols-2 gap-1 pl-2">
                  {DATE_SPOTS.filter((sp) => spotOpen(state, sp.id)).map((sp) => {
                    const known = (c.bonds[who]?.dates ?? 0) > 0 && likesSpot(who, sp.id)
                    return (
                      <Item
                        key={sp.id}
                        title={sp.name}
                        hint={known ? '好き' : undefined}
                        sub={<span className="text-[0.68rem] text-ink-dim">{sp.desc}</span>}
                        right={sp.cost ? `${sp.cost}万円` : undefined}
                        on={same(c.action, { kind: 'date', who, spot: sp.id })}
                        onClick={() => pick({ kind: 'date', who, spot: sp.id })}
                      />
                    )
                  })}
                </div>
              )}
            </div>
          ))}
          <div className="panel-head pt-1">自主トレ（仲間と）</div>
          {partners.length === 0 && <div className="text-[0.76rem] text-ink-mute">仲間と知り合うと一緒に練習できます（クラブハウスやジムで会えるかも）</div>}
          {partners.map((id) => (
            <Item key={id} title={`${castName(state, id)}と自主トレ`} sub={<span className="text-[0.7rem] text-ink-dim">仲が良いほど経験点が多く入る</span>} right="体力 -14" on={same(c.action, { kind: 'selfTrain', partner: id })} onClick={() => pick({ kind: 'selfTrain', partner: id })} />
          ))}
        </div>
      </div>
    </SideSheet>
  )
}
