/** ゲーム中の上部バー右側（日付と資金）。 */
import { dateLabel, PHASE_LABEL, phaseOfWeek, playerClub } from '../../engine'
import { useGameState } from '../../stores/gameStore'
import { formatMoneyShort } from '../format'
import { useStageWide } from '../stage/useStage'

export function GameTopInfo() {
  const state = useGameState()
  const club = playerClub(state)
  const wide = useStageWide(700)
  return (
    <>
      {wide && (
      <div className="text-right leading-tight">
        <div className="num text-[0.78rem] font-bold">{dateLabel(state.startYear, state.season, state.week)}</div>
        <div className="text-[0.7rem] text-ink-dim">{PHASE_LABEL[phaseOfWeek(state.week)]}</div>
      </div>
      )}
      <div className="num rounded-lg border border-gold/40 bg-gold/10 px-2.5 py-1 text-[0.85rem] font-extrabold text-gold">
        {state.career ? <span className="mr-1 text-[0.7rem] font-bold opacity-80">貯金</span> : null}
        {formatMoneyShort(state.career ? state.career.money : club.budget)}円
      </div>
    </>
  )
}
