/** クラブモードのホーム（クラブの状態・次の試合・ニュース・秘書のひとこと）。 */
import { useState } from 'react'
import { clubRank, dateLabel, leagueOf, playerClub, playerFixtureThisWeek, staffByRole, upcomingFixtures, type Fixture, type GameState } from '../../engine'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { MonthAutoButton } from '../home/MonthAutoButton'
import { ClubCelebration } from '../home/ClubCelebration'
import { YouthStoryCard } from '../home/YouthStoryCard'
import { Emblem } from '../components/ClubArt'
import { StaffFace } from '../components/PersonFace'
import { Icon } from '../components/Icon'
import { useGame, useGameState, type AdvanceMode } from '../../stores/gameStore'
import { SeasonEndModal } from './SeasonEndModal'
import { PowerChip } from '../club/PowerTab'
import { OfferBanners } from '../home/OfferBanners'
import { useUi } from '../../stores/uiStore'
import { formatMoneyShort } from '../format'
import { roundName } from '../../engine/competition/continental'
import { DerbyBadge } from '../club/RivalPanel'
import { MonthReport } from '../home/MonthReport'
import { takeSnap, type MonthSnap } from '../home/monthSnap'
import { OwnerGoals } from '../club/OwnerGoals'

function weekOffset(state: GameState, f: Fixture): number {
  return f.absWeek - (state.season * 48 + state.week)
}

/** 指定した週の自クラブの試合の勝敗（PK 戦は勝ち・負けに数える） */
function recordOf(state: GameState, weeks: number[]) {
  const me = state.playerClubId
  const set = new Set(weeks)
  const rec = { w: 0, d: 0, l: 0 }
  for (const c of state.competitions) {
    for (const f of c.fixtures) {
      if (!f.result || !set.has(f.absWeek) || (f.home !== me && f.away !== me)) continue
      const r = f.result
      const [my, op] = f.home === me ? [r.hg, r.ag] : [r.ag, r.hg]
      const [mp, opp] = r.pens ? (f.home === me ? r.pens : [r.pens[1], r.pens[0]]) : [0, 0]
      if (my > op || (my === op && mp > opp)) rec.w++
      else if (my < op || (my === op && mp < opp)) rec.l++
      else rec.d++
    }
  }
  return rec
}

function NextMatch({ state }: { state: GameState }) {
  const me = playerClub(state)
  const next = upcomingFixtures(state, me.id, 4)
  if (!next.length) return <div className="text-[0.8rem] text-ink-dim">予定された試合はありません</div>
  const f = next[0]
  const home = f.home === me.id
  const opp = state.clubs[home ? f.away : f.home]
  const comp = state.competitions.find((c) => c.id === f.compId)!
  const wk = weekOffset(state, f)
  return (
    <div>
      <div className="flex items-center justify-between gap-1 text-[0.78rem] text-ink-dim">
        <span className="truncate">
          {comp.name} {roundName(comp, f.round)}
        </span>
        <DerbyBadge state={state} home={f.home} away={f.away} className="shrink-0" />
        <span className="num">{wk === 0 ? '今週' : `${wk}週後`}</span>
      </div>
      <div className="vs-band mt-1.5 flex items-center justify-center gap-3 py-2">
        <div className="flex w-[40%] flex-col items-center gap-1 text-center">
          <Emblem id={`h-${me.id}`} emblem={me.emblem} colors={me.colors} size="3.3rem" />
          <span className="truncate text-[0.92rem] font-black drop-shadow">{me.short}</span>
        </div>
        <div className="text-center">
          <div className={`rounded px-2 py-0.5 text-[0.76rem] font-black ${home ? 'bg-good/30 text-good' : 'bg-accent/30 text-accent'}`}>{home ? 'HOME' : 'AWAY'}</div>
          <div className="mt-1 text-[1.3rem] font-black italic text-white drop-shadow">VS</div>
        </div>
        <div className="flex w-[40%] flex-col items-center gap-1 text-center">
          <Emblem id={`o-${opp.id}`} emblem={opp.emblem} colors={opp.colors} size="3.3rem" />
          <span className="truncate text-[0.92rem] font-black drop-shadow">{opp.short}</span>
        </div>
      </div>
      <div className="mt-2 space-y-1">
        {next.slice(1).map((g) => {
          const h = g.home === me.id
          const o = state.clubs[h ? g.away : g.home]
          return (
            <div key={g.id} className="flex items-center gap-2 text-[0.78rem]">
              <span className="num w-[4.2rem] shrink-0 whitespace-nowrap text-ink-mute">{dateLabel(state.startYear, state.season, g.absWeek % 48).replace(/^\d+年/, '')}</span>
              <span className={`w-4 shrink-0 text-center font-bold ${h ? 'text-good' : 'text-accent'}`}>{h ? 'H' : 'A'}</span>
              <span className="truncate">{o.name}</span>
            </div>
          )
        })}
      </div>
    </div>
  )
}

export function HomeScreen() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const reset = useUi((s) => s.reset)
  const me = playerClub(state)
  const comp = leagueOf(state, me)
  const rank = clubRank(state, me)
  const row = comp.table.find((r) => r.clubId === me.id)
  const secretary = staffByRole(state, me, 'secretary')
  const news = [...state.news].reverse().slice(0, 30)
  const advance = useGame((s) => s.advance)
  const advanceAsync = useGame((s) => s.advanceAsync)
  const [toast, setToast] = useState<string | null>(null)
  // 開発用: ?screen=home&weeks=48&seasonEnd=1 でシーズン終了のまとめを開いておく（見た目の確認用）
  const [seasonEnd, setSeasonEnd] = useState(() => import.meta.env.DEV && new URLSearchParams(location.search).has('seasonEnd'))
  const [report, setReport] = useState<{ snap: MonthSnap; weeks: number[]; stopText?: string } | null>(null)
  const matchWeek = !!playerFixtureThisWeek(state)
  const go = async (mode: AdvanceMode) => {
    // 1か月オートは今週の試合も自動で行う
    if (matchWeek && mode !== 'month') return push({ id: 'preMatch' })
    const snap = mode === 'month' ? takeSnap(state) : null
    // 1か月オート・次の試合までは 1 週ずつ、進み具合を出しながら（画面が止まって見えないように）
    const out = mode === 'week' ? advance(mode) : await advanceAsync(mode)
    if (out.needMatch) {
      push({ id: 'preMatch' })
      return
    }
    // 1か月オートは月間レポートでまとめて見せる（シーズンが終わったときは、シーズンのまとめを出す）
    if (snap && out.reports.length && !out.seasonEnded) {
      setReport({ snap, weeks: out.reports.map((r) => r.absWeek), stopText: out.stopText })
      return
    }
    const rec = recordOf(state, out.reports.map((r) => r.absWeek))
    const played = rec.w + rec.d + rec.l
    const msg = [`${out.reports.length}週進みました`, played ? `（${rec.w}勝${rec.d}分${rec.l}敗）` : '', out.stopText ? `・${out.stopText}` : ''].join('')
    setToast(msg)
    if (out.seasonEnded) setSeasonEnd(true)
  }

  return (
    <AppShell
      title={me.name}
      current="home"
      right={
        <>
          <MonthAutoButton onRun={() => void go('month')} />
          <GameTopInfo />
        </>
      }
    >
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="flex w-[42%] shrink-0 flex-col gap-3">
          <div className="panel panel-hero relative shrink-0 overflow-hidden p-3">
            <div className="absolute inset-0 opacity-30" style={{ background: `radial-gradient(70% 120% at 0% 0%, ${me.colors.primary}, transparent 70%)` }} />
            <div className="relative flex items-center gap-3">
              <Emblem id={`me-${me.id}`} emblem={me.emblem} colors={me.colors} size="3.6rem" />
              <div className="min-w-0">
                <div className="truncate text-[1.05rem] font-black">{me.name}</div>
                <div className="text-[0.75rem] text-ink-dim">{comp.name}</div>
                <div className="mt-0.5 flex items-baseline gap-2">
                  <span className="num text-[1.4rem] font-black text-gold">{rank}</span>
                  <span className="text-[0.78rem] text-ink-dim">位</span>
                  <span className="num text-[0.78rem] text-ink-dim">
                    勝点 {row?.points ?? 0}（{row?.won ?? 0}勝{row?.drawn ?? 0}分{row?.lost ?? 0}敗）
                  </span>
                </div>
              </div>
            </div>
            <div className="relative mt-2 grid grid-cols-4 gap-1.5 text-center">
              {(
                [
                  ['資金', `${formatMoneyShort(me.budget)}円`, 'club'],
                  ['サポーター', `${me.fans.toLocaleString()}人`, 'squad'],
                  ['人気', `${Math.round(me.popularity)}`, 'story'],
                ] as const
              ).map(([k, v, icon]) => (
                <div key={k} className="stat-chip py-1">
                  <div className="flex items-center justify-center gap-1 text-[0.7rem] text-ink-dim">
                    <Icon name={icon} className="h-3.5 w-3.5 text-gold/80" />
                    {k}
                  </div>
                  <div className="num text-[0.98rem] font-black">{v}</div>
                </div>
              ))}
              <PowerChip state={state} />
            </div>
          </div>
          <div className="panel panel-hero min-h-0 flex-1 overflow-hidden p-3">
            <div className="panel-head mb-1">次の試合</div>
            <NextMatch state={state} />
          </div>
        </div>

        <div className="flex min-w-0 flex-1 flex-col gap-3">
          {secretary && (
            <div className="flex items-end gap-2">
              <StaffFace s={secretary} className="h-12 w-12 shrink-0" />
              <div className="panel-flat rounded-bl-none px-3 py-2 text-[0.8rem] leading-snug">
                社長、{state.season === 0 && state.week === 0 ? '新しいシーズンの始まりです。まずは選手の顔ぶれを確認しましょう。' : '今週も頑張りましょう。'}
              </div>
            </div>
          )}
          <button className="panel-flat px-2.5 py-1.5 text-left" onClick={() => push({ id: 'club', params: { tab: 'info' } })}>
            <OwnerGoals state={state} compact />
          </button>
          <OfferBanners />
          <div className="panel flex min-h-0 flex-1 flex-col p-3">
            <div className="panel-head mb-1">ニュース</div>
            <div className="scroll-y min-h-0 flex-1 space-y-1.5 pr-1">
              {news.map((n, i) => (
                <div key={i} className={`rounded-lg px-2.5 py-1.5 text-[0.8rem] leading-snug ${n.mine ? 'bg-gold/10 text-ink' : 'bg-black/20 text-ink-dim'}`}>
                  {n.text}
                </div>
              ))}
            </div>
          </div>
          <div className="flex justify-end gap-2">
            <button
              className="btn btn-ghost"
              onClick={() => {
                const next = upcomingFixtures(state, me.id, 1)[0]
                const opp = next ? (next.home === me.id ? next.away : next.home) : comp.clubIds.find((id) => id !== me.id)!
                push({ id: 'matchLab', params: { home: me.id, away: opp, title: '練習試合' } })
              }}
            >
              <Icon name="ball" className="h-5 w-5" />
              練習試合
            </button>
            <button className="btn btn-ghost" onClick={() => push({ id: 'squad' })}>
              <Icon name="squad" className="h-5 w-5" />
              選手を見る
            </button>
            <div className="flex flex-col gap-1">
              <button className={`btn min-w-[11rem] text-[1.05rem] ${matchWeek ? 'btn-blue' : 'btn-gold'}`} onClick={() => go('week')}>
                <Icon name={matchWeek ? 'ball' : 'forward'} className="h-5 w-5" />
                {matchWeek ? '試合へ' : '次へ進む'}
              </button>
              <div className="flex gap-1">
                {!matchWeek && (
                  <button className="btn btn-ghost btn-sm min-w-0 flex-1 !px-1.5 !text-[0.72rem]" onClick={() => go('nextMatch')}>
                    次の試合まで
                  </button>
                )}
                <MonthAutoButton className="btn btn-ghost btn-sm min-w-0 flex-1 !px-1.5 !text-[0.72rem]" onRun={() => void go('month')} />
              </div>
            </div>
          </div>
        </div>
      </div>
      {toast && (
        <button className="anim-rise absolute left-1/2 top-2 z-30 -translate-x-1/2 rounded-full bg-[#0b1320]/90 px-4 py-1.5 text-[0.8rem] font-bold text-white shadow-lg" onClick={() => setToast(null)}>
          {toast}
        </button>
      )}
      {seasonEnd && <SeasonEndModal onClose={() => setSeasonEnd(false)} />}
      <ClubCelebration state={state} />
      <YouthStoryCard state={state} />
      {report && <MonthReport state={state} snap={report.snap} weeks={report.weeks} stopText={report.stopText} onClose={() => setReport(null)} />}
      {state.money.gameOver && (
        <div className="absolute inset-0 z-50 flex items-center justify-center bg-black/75">
          <div className="panel w-[26rem] p-5 text-center">
            <div className="text-[1.2rem] font-black text-bad">GAME OVER</div>
            <p className="mt-2 text-[0.85rem]">資金難が続き、オーナーはクラブの経営権を手放すことを決めました。</p>
            <button className="btn btn-gold mt-4 w-full" onClick={() => reset({ id: 'title' })}>
              タイトルへ
            </button>
          </div>
        </div>
      )}
    </AppShell>
  )
}
