/**
 * 営業（M19）: チケットの値段・年間シート・グッズの商品。クラブ画面のタブ。
 */
import type { GameState } from '../../engine'
import { goodsPerSeason, ticketPrice } from '../../engine/economy/finance'
import { MERCH_LINES, MERCH_MAX, TICKET_LEVELS, merchLevel, merchUpgradeCost, salesOf, seasonTicketEstimate, seasonTicketHolders, starPlayers, upgradeMerch } from '../../engine/economy/sales'
import { useGame } from '../../stores/gameStore'
import { GLOBAL_STORE_MAX, canUpgradeStore, globalStoreLevel, inWorld, upgradeStore, worldGoods, worldVisitors } from '../../engine/club/worldClass'
import { formatMoney, formatMoneyShort } from '../format'

/** 海外のファンと海外向けオンラインストア（M24 の 2 回目。ワールドリーグで開く） */
function WorldStore({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const me = state.clubs[state.playerClubId]
  const fans = me.worldFans ?? 0
  if (!inWorld(me) && !fans) return null
  const lv = globalStoreLevel(me)
  const chk = canUpgradeStore(me)
  return (
    <div className="rounded-lg border border-gold/40 bg-gold/10 px-2.5 py-2">
      <div className="flex items-center gap-2">
        <span className="font-black text-gold">海外のファン</span>
        <span className="num ml-auto font-bold">{fans.toLocaleString()} 人</span>
      </div>
      <div className="text-[0.7rem] text-ink-dim">
        {inWorld(me) ? 'ワールドリーグで戦うほど増える（順位・人気・格・目玉の選手）。' : 'ワールドリーグを離れたので少しずつ減っています。'}ホームの試合に 1 試合 {worldVisitors(me).toLocaleString()} 人が海外から観に来ます。
      </div>
      <div className="mt-1.5 flex items-center gap-2">
        <div className="min-w-0 flex-1">
          <div className="flex items-center gap-2">
            <span className="font-bold">海外向けオンラインストア</span>
            <span className="flex gap-0.5">
              {Array.from({ length: GLOBAL_STORE_MAX }, (_, i) => (
                <span key={i} className={`h-1.5 w-4 rounded-full ${i < lv ? 'bg-gold' : 'bg-white/10'}`} />
              ))}
            </span>
          </div>
          <div className="text-[0.7rem] text-ink-dim">海外のファンからのグッズ 年 {formatMoneyShort(worldGoods(me))}円</div>
        </div>
        {chk.reason === '最大' ? (
          <span className="shrink-0 text-[0.74rem] font-bold text-gold">最大</span>
        ) : (
          <button className="btn btn-blue btn-sm shrink-0" disabled={!chk.ok} onClick={() => mutate((st) => void upgradeStore(st))}>
            {chk.cost ? `${lv === 0 ? '開く' : '広げる'} ${formatMoneyShort(chk.cost)}円` : chk.reason}
          </button>
        )}
      </div>
    </div>
  )
}

export function SalesTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const me = state.clubs[state.playerClubId]
  const lv = me.sales?.ticket ?? 2
  const price = ticketPrice(me)
  const est = seasonTicketEstimate(me, price)
  const holders = seasonTicketHolders(state, me)
  const goods = goodsPerSeason(me, state)
  const stars = starPlayers(state, me)
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[46%] shrink-0 space-y-3 p-3 text-[0.8rem]">
        <div>
          <div className="panel-head mb-1">チケットの値段</div>
          <div className="grid grid-cols-5 gap-1">
            {TICKET_LEVELS.map((t, i) => (
              <button
                key={t.name}
                className={`rounded-lg px-1 py-1.5 text-center ${i === lv ? 'bg-gold/20 font-black text-gold ring-1 ring-gold/60' : 'bg-white/[0.05] text-ink-dim'}`}
                onClick={() => mutate((st) => void (salesOf(st.clubs[st.playerClubId]).ticket = i))}
              >
                <div className="text-[0.76rem]">{t.name}</div>
                <div className="num text-[0.7rem]">{Math.round(price * t.price * 10000).toLocaleString()} 円</div>
              </button>
            ))}
          </div>
          <div className="mt-1.5 text-[0.74rem] leading-snug text-ink-dim">
            観客 ×{TICKET_LEVELS[lv].att.toFixed(2)}・1 人あたり ×{TICKET_LEVELS[lv].price.toFixed(2)}
            {TICKET_LEVELS[lv].pop > 0 ? '・人気が少し上がる' : TICKET_LEVELS[lv].pop < 0 ? '・人気が少し下がる' : ''}。満員になるなら、高くしても客は減りません（収容 {me.stadium.capacity.toLocaleString()} 人）。
          </div>
        </div>
        <div>
          <div className="flex items-center gap-2">
            <span className="panel-head">年間シート</span>
            <button
              className={`ml-auto rounded-full px-3 py-1 text-[0.76rem] font-black ${me.sales?.seasonTickets ? 'bg-good/25 text-good' : 'bg-white/10 text-ink-dim'}`}
              onClick={() => mutate((st) => void (salesOf(st.clubs[st.playerClubId]).seasonTickets = !st.clubs[st.playerClubId].sales?.seasonTickets))}
            >
              {me.sales?.seasonTickets ? '売る' : '売らない'}
            </button>
          </div>
          <div className="mt-1 text-[0.74rem] leading-snug text-ink-dim">
            シーズンのはじめに前払いで売る（1 試合あたり {Math.round((1 - 0.85) * 100)}% 引き）。持っている人は毎試合来るので、観客の底になります。
          </div>
          <div className="mt-1 rounded-lg bg-black/25 px-2.5 py-1.5">
            {holders > 0 ? (
              <span>
                今季: <b className="num">{holders.toLocaleString()}</b> 席（{formatMoney(me.sales?.sold?.revenue ?? 0)}）
              </span>
            ) : (
              <span>
                来季の見込み: <b className="num">{est.count.toLocaleString()}</b> 席・{formatMoney(est.revenue)}
              </span>
            )}
          </div>
        </div>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-2 p-3 text-[0.8rem]">
        <div className="flex items-baseline gap-2">
          <span className="panel-head">グッズ</span>
          <span className="ml-auto text-[0.74rem] text-ink-dim">
            見込み 年 <b className="num text-ink">{formatMoneyShort(goods)}円</b>
          </span>
        </div>
        <WorldStore state={state} />
        {MERCH_LINES.map((d) => {
          const l = merchLevel(me, d.id)
          const cost = merchUpgradeCost(me, d.id)
          return (
            <div key={d.id} className="flex items-center gap-2 rounded-lg bg-black/25 px-2.5 py-1.5">
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-2">
                  <span className="font-bold">{d.name}</span>
                  <span className="flex gap-0.5">
                    {Array.from({ length: MERCH_MAX }, (_, i) => (
                      <span key={i} className={`h-1.5 w-4 rounded-full ${i < l ? 'bg-gold' : 'bg-white/10'}`} />
                    ))}
                  </span>
                </div>
                <div className="text-[0.7rem] text-ink-dim">
                  {d.desc}・Lv ごとにグッズ +{Math.round(d.bonus * 100)}%
                </div>
              </div>
              {cost !== null ? (
                <button className="btn btn-blue btn-sm shrink-0" disabled={me.budget < cost} onClick={() => mutate((st) => void upgradeMerch(st, d.id))}>
                  {l === 0 ? '発売' : '広げる'} {formatMoneyShort(cost)}円
                </button>
              ) : (
                <span className="shrink-0 text-[0.74rem] font-bold text-gold">最大</span>
              )}
            </div>
          )
        })}
        <div className="panel-head mb-1 mt-2">人気の選手（選手グッズ）</div>
        <div className="flex flex-wrap gap-1.5">
          {stars.map(({ p, score }) => (
            <span key={p.id} className="rounded-full bg-white/[0.06] px-2.5 py-1 text-[0.76rem]">
              <b>{p.name}</b>
              <span className="num ml-1 text-ink-dim">{Math.round(score)}</span>
            </span>
          ))}
        </div>
      </div>
    </div>
  )
}
