/**
 * 優勝のセレモニー（M16、クラブモード）: まだ祝っていないタイトルごとに、トロフィー・紙吹雪・秘書と主将の言葉。
 * 「パレードへ」で優勝パレード（人気・サポーター・やる気が上がる。engine/club/celebration.ts）。#overlay-root に描く。
 */
import { useState } from 'react'
import { createPortal } from 'react-dom'
import type { GameState } from '../../engine'
import { staffByRole } from '../../engine'
import { crowdLabel, holdParade, unseenTrophies, type ParadeResult } from '../../engine/club/celebration'
import { ovr } from '../../engine/player/overall'
import { useGame } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { PlayerFace, StaffFace } from '../components/PersonFace'
import { Emblem } from '../components/ClubArt'
import { Icon } from '../components/Icon'
import { sound } from '../audio/sound'

const COLORS = ['#f5c542', '#ffffff', '#3aa0ff', '#ff6fa5', '#3ddc84', '#ff8a3d']

function Confetti() {
  return (
    <div className="pointer-events-none absolute inset-0 overflow-hidden" aria-hidden>
      {Array.from({ length: 36 }, (_, i) => (
        <span
          key={i}
          className="confetti"
          style={{ left: `${(i * 37) % 100}%`, background: COLORS[i % COLORS.length], animationDuration: `${2.6 + ((i * 7) % 10) / 6}s`, animationDelay: `${((i * 13) % 20) / 10}s` }}
        />
      ))}
    </div>
  )
}

/** 秘書の言葉（大きな大会は特別に） */
const SECRETARY_LINE: Record<string, string> = {
  WL: '社長……世界一のリーグの頂点です！ 欧州の名門を相手に、この街のクラブが世界の頂点に立ちました！',
  WCC: '世界クラブ選手権の優勝です！ 社長、私たちのクラブが世界一になりました！',
  ACC: 'アジアの頂点です！ 社長、次は世界ですね。',
}

const CAPTAIN_LINES = [
  'みんなで掴んだタイトルです。最後まで信じてくれたサポーターのおかげです！',
  '苦しい試合もあったけど、このクラブの仲間と戦えて本当によかった。',
  'これで終わりじゃない。来季はもっと上を目指します！',
]

export function ClubCelebration({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const unseen = unseenTrophies(state)
  const [parade, setParade] = useState<ParadeResult | null>(null)
  if (!root || !unseen.length) return null
  const t = unseen[0]
  const me = state.clubs[state.playerClubId]
  const secretary = staffByRole(state, me, 'secretary')
  const squad = Object.values(state.players).filter((p) => p.clubId === me.id && !p.retired)
  const captain = (me.lineup?.captain !== undefined ? state.players[me.lineup.captain] : undefined) ?? [...squad].sort((a, b) => ovr(b) - ovr(a))[0]
  const next = () => {
    if (!parade) {
      sound.play('fanfare')
      mutate((st) => {
        const tr = unseenTrophies(st)[0]
        setParade(holdParade(st, tr))
      })
      return
    }
    setParade(null)
    // 1 つ祝い終わった（まだあれば次のタイトルへ）
    mutate((st) => void (st.celebrated = (st.celebrated ?? 0) + 1))
  }
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[55] flex items-center justify-center bg-[#050b14]/90 p-3">
      <Confetti />
      <div className="panel panel-solid anim-rise relative flex max-h-full w-[34rem] max-w-full flex-col p-4 text-center">
        {!parade ? (
          <>
            <div className="scroll-y min-h-0 flex-1">
              <div className="flex items-center justify-center gap-3">
                <Emblem id={`cel-${me.id}`} emblem={me.emblem} colors={me.colors} size="3rem" />
                <div style={{ animation: 'crown-pop 0.8s ease-out both' }}>
                  <Icon name="trophy" className="h-16 w-16 text-gold" />
                </div>
              </div>
              <div className="mt-1 text-[0.8rem] font-bold text-ink-dim">{me.name}</div>
              <div className="text-[1.5rem] font-black text-gold">{t.name}！</div>
              <div className="mt-3 space-y-2 text-left">
                {secretary && (
                  <div className="flex items-start gap-2.5">
                    <StaffFace s={secretary} className="h-11 w-11 shrink-0" photo />
                    <p className="rounded-lg bg-white/[0.06] px-2.5 py-1.5 text-[0.8rem]">{SECRETARY_LINE[t.compId] ?? '社長、おめでとうございます！ この街に、新しい歴史が刻まれました。'}</p>
                  </div>
                )}
                {captain && (
                  <div className="flex items-start gap-2.5">
                    <PlayerFace p={captain} kit={me.colors} className="h-11 w-11 shrink-0" />
                    <p className="rounded-lg bg-white/[0.06] px-2.5 py-1.5 text-[0.8rem]">
                      <span className="text-[0.72rem] text-ink-dim">主将 {captain.short}</span>
                      <br />
                      {CAPTAIN_LINES[(t.season + t.compId.length) % CAPTAIN_LINES.length]}
                    </p>
                  </div>
                )}
              </div>
            </div>
            <button className="btn btn-gold mt-3 w-full shrink-0" onClick={next}>
              優勝パレードへ
            </button>
          </>
        ) : (
          <>
            <div className="scroll-y min-h-0 flex-1">
              <div className="text-[0.8rem] font-bold text-ink-dim">{t.name}</div>
              <div className="text-[1.4rem] font-black text-gold">優勝パレード</div>
              <p className="mt-2 text-[0.85rem]">
                街の大通りを、選手たちを乗せたバスがゆっくり進む。
                <br />
                沿道には <b className="num text-gold">{crowdLabel(parade.crowd)}</b> のサポーターが集まった！
              </p>
              <div className="num mt-3 grid grid-cols-3 gap-2 text-[0.8rem]">
                <div className="rounded-lg bg-white/[0.06] py-1.5">
                  <div className="text-[0.7rem] text-ink-dim">人気</div>+{parade.popularity}
                </div>
                <div className="rounded-lg bg-white/[0.06] py-1.5">
                  <div className="text-[0.7rem] text-ink-dim">サポーター</div>+{parade.fans.toLocaleString()}人
                </div>
                <div className="rounded-lg bg-white/[0.06] py-1.5">
                  <div className="text-[0.7rem] text-ink-dim">選手のやる気</div>アップ
                </div>
              </div>
            </div>
            <button className="btn btn-gold mt-3 w-full shrink-0" onClick={next}>
              {unseen.length > 1 ? '次のタイトルへ' : '閉じる'}
            </button>
          </>
        )}
      </div>
    </div>,
    root,
  )
}
