/**
 * フォーメーションの配置図（横向き: 左が自陣、右へ攻める）。
 * スロットをタップすると選択、もう一度別のスロットをタップすると入れ替え（親が処理）。
 */
import { aptMark, formationOf, ratingAt, type GameState, type Lineup } from '../../engine'
import { PlayerFace } from './PersonFace'

export function FormationPitch({
  state,
  formation,
  lineup,
  kit,
  selected,
  onSlot,
  compact = false,
}: {
  state: GameState
  formation: string
  lineup: Lineup
  kit: { primary: string; secondary: string }
  selected?: number | null
  onSlot?: (slot: number) => void
  compact?: boolean
}) {
  const f = formationOf(formation)
  return (
    <div className="relative h-full w-full overflow-hidden rounded-xl" style={{ background: 'linear-gradient(90deg,#17713f 0%,#1c8048 25%,#18773f 50%,#1c8048 75%,#17713f 100%)' }}>
      <svg viewBox="0 0 105 68" preserveAspectRatio="none" className="absolute inset-0 h-full w-full" aria-hidden>
        <g fill="none" stroke="#ffffff" strokeOpacity="0.4" strokeWidth="0.35" vectorEffect="non-scaling-stroke">
          <rect x="1" y="1" width="103" height="66" />
          <line x1="52.5" y1="1" x2="52.5" y2="67" />
          <circle cx="52.5" cy="34" r="9.15" />
          <rect x="1" y="13.85" width="16.5" height="40.3" />
          <rect x="87.5" y="13.85" width="16.5" height="40.3" />
        </g>
      </svg>
      {f.slots.map((s, i) => {
        const p = state.players[lineup.starters[i]]
        const left = `${3 + s.u * 92}%`
        const top = `${6 + s.v * 88}%`
        const sel = selected === i
        const apt = p ? p.apt[s.pos] : 0
        const mark = aptMark(apt)
        const markColor = mark === '◎' ? '#f5c542' : mark === '○' ? '#3ddc84' : mark === '△' ? '#7dd3fc' : '#ff5a5f'
        return (
          <button
            key={i}
            onClick={() => onSlot?.(i)}
            className={`absolute flex -translate-x-1/2 -translate-y-1/2 flex-col items-center ${sel ? 'z-10 scale-110' : ''}`}
            style={{ left, top, transition: 'transform 0.12s' }}
          >
            <div className={`relative rounded-full ${sel ? 'ring-3 ring-gold' : ''}`}>
              {p ? <PlayerFace p={p} kit={kit} className={compact ? 'h-8 w-8' : 'h-10 w-10'} /> : <div className={`face-round ${compact ? 'h-8 w-8' : 'h-10 w-10'} bg-black/40`} />}
              {p && (
                <span className="num absolute -right-2 -top-1 rounded bg-[#0b1320]/90 px-1 text-[0.7rem] font-black text-white">
                  {Math.round(ratingAt(p, s.pos))}
                </span>
              )}
            </div>
            <div className="mt-0.5 flex max-w-[5.6rem] items-center gap-0.5 rounded bg-[#0b1320]/80 px-1 text-[0.68rem] font-bold leading-tight text-white">
              <span style={{ color: markColor }}>{s.label}</span>
              <span className="truncate">{p ? p.short : '―'}</span>
            </div>
          </button>
        )
      })}
    </div>
  )
}
