/** 試合後: スコアと得点者、チームの成績、自クラブの選手の評価点、順位。 */
import { clubRank, leagueOf, playerClub } from '../../engine'
import type { TeamStats } from '../../engine/match/live/types'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Emblem } from '../components/ClubArt'
import { PlayerFace } from '../components/PersonFace'
import { PosBadge } from '../components/common'
import { Icon } from '../components/Icon'
import { useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { roundName } from '../../engine/competition/continental'
import { CareerMatchPanel } from '../career/CareerMatchPanel'
import { useState } from 'react'
import { HighlightModal } from '../match/HighlightModal'
import { highlightKey, useHighlights } from '../../stores/highlightStore'

const ROWS: { key: keyof TeamStats | 'passPct'; label: string; fmt?: (v: number) => string }[] = [
  { key: 'possession', label: '支配率', fmt: (v) => `${Math.round(v)}%` },
  { key: 'shots', label: 'シュート' },
  { key: 'onTarget', label: '枠内シュート' },
  { key: 'xg', label: 'ゴール期待値', fmt: (v) => v.toFixed(2) },
  { key: 'passPct', label: 'パス成功率', fmt: (v) => `${Math.round(v)}%` },
  { key: 'corners', label: 'コーナー' },
  { key: 'fouls', label: 'ファウル' },
  { key: 'offsides', label: 'オフサイド' },
]

function ratingColor(r: number): string {
  return r >= 8 ? '#f5c542' : r >= 7 ? '#3ddc84' : r >= 6 ? '#e8eef6' : '#ff8a8a'
}

export function PostMatchScreen() {
  const state = useGameState()
  const reset = useUi((s) => s.reset)
  const hl = useHighlights()
  const [showHl, setShowHl] = useState(false)
  const lm = state.lastMatch
  const me = playerClub(state)
  if (!lm) {
    return (
      <AppShell title="試合結果" current="home" right={<GameTopInfo />}>
        <div className="p-6 text-center text-ink-dim">まだ試合がありません</div>
      </AppShell>
    )
  }
  const s = lm.summary
  const home = state.clubs[lm.home]
  const away = state.clubs[lm.away]
  const mySide: 0 | 1 = lm.home === me.id ? 0 : 1
  const totalPoss = Math.max(1, s.stats[0].possession + s.stats[1].possession)
  const value = (side: 0 | 1, key: string): number => {
    const t = s.stats[side]
    if (key === 'possession') return (t.possession / totalPoss) * 100
    if (key === 'passPct') return t.passes ? (t.passesOk / t.passes) * 100 : 0
    return t[key as keyof TeamStats] as number
  }
  const mine = s.players
    .filter((p) => p.team === mySide && p.minutes > 0.5)
    .sort((a, b) => b.rating - a.rating)
  const comp = state.competitions.find((c) => c.id === lm.compId)
  const myGoals = s.score[mySide]
  const oppGoals = s.score[mySide === 0 ? 1 : 0]
  // PK 戦は PK の勝ち負け
  const pk = s.pens ? s.pens[mySide] - s.pens[mySide === 0 ? 1 : 0] : 0
  const result = myGoals > oppGoals || (myGoals === oppGoals && pk > 0) ? 'WIN' : myGoals < oppGoals || pk < 0 ? 'LOSE' : 'DRAW'
  // 決勝で勝った（カップ戦・大陸大会・世界大会の優勝）
  const fixture = comp?.fixtures.find((f) => f.id === lm.fixtureId)
  const finalRound = comp?.roundNames ? comp.roundNames.length - 1 : comp?.id === 'CUP' ? 5 : comp?.id.endsWith('PO') ? 1 : -1
  const title = result === 'WIN' && fixture && fixture.round === finalRound ? (comp?.id === 'WCC' ? '世界クラブ王者！' : comp?.id.endsWith('PO') ? '昇格プレーオフ優勝！' : `${comp?.name} 優勝！`) : null
  const resultColor = result === 'WIN' ? 'text-gold' : result === 'LOSE' ? 'text-bad' : 'text-ink-dim'

  return (
    <AppShell title="試合結果" current="home" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="panel flex w-[38%] shrink-0 flex-col p-3">
          <div className="text-center text-[0.78rem] text-ink-dim">
            {comp?.name ?? ''} {comp && fixture ? roundName(comp, fixture.round) : ''}
          </div>
          {title ? (
            <div className="anim-rise mx-auto my-0.5 flex items-center gap-1.5 rounded-full bg-gold px-4 py-1 text-[1.05rem] font-black text-[#2a1a00] shadow-lg">
              <Icon name="trophy" className="h-5 w-5" />
              {title}
            </div>
          ) : (
            <div className={`text-center text-[1.4rem] font-black italic tracking-widest ${resultColor}`}>{result}</div>
          )}
          <div className="mt-1 flex items-center justify-center gap-2">
            <div className="flex w-[34%] flex-col items-center">
              <Emblem id={`pr-h-${home.id}`} emblem={home.emblem} colors={home.colors} size="2.8rem" />
              <span className="mt-0.5 w-full truncate text-center text-[0.78rem] font-bold">{home.short}</span>
            </div>
            <div className="num text-[2.2rem] font-black">
              {s.score[0]} - {s.score[1]}
            </div>
            <div className="flex w-[34%] flex-col items-center">
              <Emblem id={`pr-a-${away.id}`} emblem={away.emblem} colors={away.colors} size="2.8rem" />
              <span className="mt-0.5 w-full truncate text-center text-[0.78rem] font-bold">{away.short}</span>
            </div>
          </div>
          {s.pens && (
            <div className="num text-center text-[0.75rem] text-ink-dim">
              PK {s.pens[0]} - {s.pens[1]}
            </div>
          )}
          <div className="scroll-y mt-2 min-h-0 flex-1 space-y-0.5">
            {s.goals.map((g, i) => {
              const p = state.players[g.player]
              const a = g.assist !== undefined ? state.players[g.assist] : undefined
              return (
                <div key={i} className={`flex items-center gap-1.5 text-[0.75rem] ${g.team === 0 ? '' : 'flex-row-reverse text-right'}`}>
                  <span className="num font-black text-gold">{g.minute}'</span>
                  <span>⚽</span>
                  <span className="min-w-0 truncate font-bold">
                    {p?.short ?? '?'}
                    {g.ownGoal ? '（OG）' : g.penalty ? '（PK）' : ''}
                  </span>
                  {a && <span className="min-w-0 truncate text-ink-dim">← {a.short}</span>}
                </div>
              )
            })}
          </div>
          {hl.key === highlightKey(lm.home, lm.away) && hl.clips.length > 0 && (
            <button className="btn btn-blue btn-sm mt-2 w-full" onClick={() => setShowHl(true)}>
              <Icon name="play" className="h-4 w-4" />
              ハイライト（{hl.clips.length} 場面）
            </button>
          )}
          {showHl && <HighlightModal clips={hl.clips} focusId={state.career?.playerId} onClose={() => setShowHl(false)} />}
          {comp?.kind === 'league' && (
            <div className="mt-2 rounded-lg bg-black/25 px-2 py-1.5 text-center text-[0.8rem]">
              {leagueOf(state, me).name} <span className="num text-[1rem] font-black text-gold">{clubRank(state, me)}</span> 位
            </div>
          )}
        </div>

        {state.career ? (
          <CareerMatchPanel state={state} />
        ) : (
        <div className="panel w-[28%] shrink-0 p-3">
          <div className="panel-head mb-1.5">スタッツ</div>
          <div className="space-y-1.5">
            {ROWS.map((r) => {
              const a = value(0, r.key)
              const b = value(1, r.key)
              const tot = a + b || 1
              const f = r.fmt ?? ((v: number) => String(Math.round(v)))
              return (
                <div key={r.key}>
                  <div className="num flex justify-between text-[0.78rem]">
                    <span className="font-bold">{f(a)}</span>
                    <span className="text-ink-dim">{r.label}</span>
                    <span className="font-bold">{f(b)}</span>
                  </div>
                  <div className="mt-0.5 flex h-1 overflow-hidden rounded-full bg-black/40">
                    <div style={{ width: `${(a / tot) * 100}%`, background: home.colors.primary === '#ffffff' ? '#cbd5e1' : home.colors.primary }} />
                    <div className="flex-1" style={{ background: away.colors.primary === '#ffffff' ? '#cbd5e1' : away.colors.primary }} />
                  </div>
                </div>
              )
            })}
          </div>
        </div>
        )}

        <div className="flex min-w-0 flex-1 flex-col gap-2">
          <div className="panel scroll-y min-h-0 flex-1 p-2.5">
            <div className="panel-head mb-1">評価点</div>
            {mine.map((ps) => {
              const p = state.players[ps.id]
              if (!p) return null
              return (
                <div key={ps.id} className="flex items-center gap-1.5 py-[0.18rem]">
                  <PlayerFace p={p} kit={me.colors} className="h-7 w-7 shrink-0" />
                  <PosBadge pos={p.pos} />
                  <span className="min-w-0 flex-1 truncate text-[0.78rem] font-bold">
                    {p.short}
                    {ps.id === s.mom && <span className="ml-1 rounded bg-gold px-1 text-[0.66rem] font-black text-[#2a1a00]">MOM</span>}
                  </span>
                  {ps.goals > 0 && <span className="text-[0.76rem]">{'⚽'.repeat(Math.min(3, ps.goals))}</span>}
                  {ps.yellow > 0 && <span className="h-3 w-2 rounded-[1px] bg-warn" />}
                  {ps.red && <span className="h-3 w-2 rounded-[1px] bg-bad" />}
                  {ps.injured && <span className="text-[0.72rem] text-bad">負傷</span>}
                  <span className="num w-8 text-right text-[0.85rem] font-black" style={{ color: ratingColor(ps.rating) }}>
                    {ps.rating.toFixed(1)}
                  </span>
                </div>
              )
            })}
          </div>
          <button className="btn btn-gold" onClick={() => reset({ id: 'home' })}>
            <Icon name="forward" className="h-5 w-5" />
            ホームへ
          </button>
        </div>
      </div>
    </AppShell>
  )
}
