/**
 * 国際ユースカップ（M25）: 招待への返事・組み合わせ（準々決勝 → 準決勝 → 決勝）・自クラブの選手の成績・目立った相手・これまでの成績。
 */
import type { GameState } from '../../engine'
import { seasonLabel } from '../../engine/core/calendar'
import { NATION_NAME } from '../../engine/data/nations'
import {
  YC_FEE,
  YC_INVITE_WEEK,
  YC_MAX_AGE,
  YC_MIN_PLAYERS,
  YC_MIN_REP,
  YC_REPLY_WEEK,
  YC_RESULT,
  YC_ROUND,
  YC_WEEKS,
  canEnterYouthCup,
  cupSquad,
  ourCupMatch,
  ourLevel,
  replyYouthCup,
  type YouthCup,
  type YouthCupMatch,
} from '../../engine/club/youthCup'
import { Flag } from '../components/common'
import { Icon } from '../components/Icon'
import { useGame } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { formatMoney } from '../format'

function TeamName({ cup, i, win }: { cup: YouthCup; i: number; win?: boolean }) {
  const t = cup.teams[i]
  return (
    <span className={`flex min-w-0 items-center gap-1 ${i === 0 ? 'font-black text-gold' : win ? 'font-bold' : 'text-ink-dim'}`}>
      <Flag nation={t.nation} className="h-[0.7rem] w-[1rem] shrink-0" />
      <span className="truncate">{t.name}</span>
    </span>
  )
}

function MatchCard({ cup, m }: { cup: YouthCup; m: YouthCupMatch }) {
  const mine = m.a === 0 || m.b === 0
  return (
    <div className={`rounded-lg px-2 py-1 text-[0.72rem] ${mine ? 'bg-gold/10 ring-1 ring-gold/40' : 'bg-black/25'}`}>
      {[m.a, m.b].map((ti, k) => (
        <div key={ti} className="flex items-center gap-1.5">
          <TeamName cup={cup} i={ti} win={m.winner === ti} />
          <span className="num ml-auto shrink-0 font-bold">
            {m.score ? m.score[k] : ''}
            {m.pens ? <span className="text-[0.62rem] text-ink-dim">（{m.pens[k]}）</span> : null}
          </span>
        </div>
      ))}
      {m.watched && <div className="text-right text-[0.6rem] text-accent">観戦</div>}
    </div>
  )
}

export function YouthCupTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const cup = state.youthCup?.season === state.season ? state.youthCup : undefined
  const me = state.clubs[state.playerClubId]
  const eligible = cupSquad(state).length

  if (!cup || cup.status === 'declined') {
    return (
      <div className="flex min-h-0 flex-1 gap-3">
        <div className="panel scroll-y min-w-0 flex-1 space-y-2 p-3 text-[0.8rem]">
          <div className="panel-head">国際ユースカップ</div>
          <p className="text-ink-dim">
            欧州・南米・アジアの強豪の U-18 と戦う、ウインターブレイクの大会（8 クラブ・第 {YC_WEEKS[0] + 1}〜{YC_WEEKS[2] + 1} 週）。毎年第 {YC_INVITE_WEEK + 1} 週に招待が届きます。
          </p>
          <div className="grid grid-cols-[1fr_auto] gap-x-3 gap-y-1 rounded-lg bg-black/25 px-2.5 py-2 text-[0.76rem]">
            <span className="text-ink-dim">招待の条件: クラブの格 {YC_MIN_REP} 以上</span>
            <span className={`num font-bold ${me.rep >= YC_MIN_REP ? 'text-good' : 'text-ink-dim'}`}>{Math.floor(me.rep)}</span>
            <span className="text-ink-dim">
              出られる選手（ユースと {YC_MAX_AGE} 歳以下）{YC_MIN_PLAYERS} 人以上
            </span>
            <span className={`num font-bold ${eligible >= YC_MIN_PLAYERS ? 'text-good' : 'text-ink-dim'}`}>{eligible} 人</span>
          </div>
          <p className="text-[0.74rem] text-ink-mute">出た選手は大会の経験で少し伸びます。優勝・準優勝で人気とサポーターが増え、目立った相手の選手は冬の「海外の有望株」に並びます。</p>
          {cup?.status === 'declined' && <div className="text-[0.76rem] text-ink-dim">今季の大会は見送りました。</div>}
        </div>
        <History state={state} />
      </div>
    )
  }

  const ours = Object.entries(cup.ours)
    .map(([id, o]) => ({ p: state.players[Number(id)], ...o }))
    .filter((x) => x.p)
    .sort((a, b) => b.ratingSum / b.apps - a.ratingSum / a.apps)
  const now = ourCupMatch(state)
  const chk = canEnterYouthCup(state)
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y min-w-0 flex-1 space-y-2 p-3 text-[0.8rem]">
        <div className="flex items-center gap-2">
          <span className="panel-head">国際ユースカップ</span>
          <span className="flex items-center gap-1 text-[0.74rem] text-ink-dim">
            <Flag nation={cup.host.nation} className="h-[0.75rem] w-[1.1rem]" />
            {NATION_NAME[cup.host.nation]}・{cup.host.city}
          </span>
          {cup.result !== undefined && <span className={`ml-auto rounded px-1.5 text-[0.72rem] font-black ${cup.result === 3 ? 'bg-gold text-[#2a1a00]' : 'bg-white/10'}`}>{YC_RESULT[cup.result]}</span>}
        </div>
        {cup.status === 'invited' && (
          <div className="rounded-xl border border-gold/40 bg-gold/10 p-2.5">
            <div className="text-[0.82rem] font-black text-gold">招待が届いています（返事は第 {YC_REPLY_WEEK + 1} 週まで）</div>
            <div className="mt-1 text-[0.74rem]">
              うちのユースの力 <b className="num">{Math.round(ourLevel(state))}</b>（出られる選手 {eligible} 人）。相手の力 {Math.round(Math.min(...cup.teams.slice(1).map((t) => t.level)))}〜{Math.round(Math.max(...cup.teams.slice(1).map((t) => t.level)))}。
            </div>
            <div className="mt-1.5 flex gap-2">
              <button className="btn btn-gold btn-sm flex-1" disabled={!chk.ok} onClick={() => mutate((st) => void replyYouthCup(st, true))}>
                {chk.ok || chk.reason === '資金が足りない' ? `参加する（遠征費 ${formatMoney(YC_FEE)}）` : chk.reason}
              </button>
              <button className="btn btn-ghost btn-sm" onClick={() => mutate((st) => void replyYouthCup(st, false))}>
                見送る
              </button>
            </div>
          </div>
        )}
        {now && (
          <button className="btn btn-gold w-full" onClick={() => push({ id: 'youthCup' })}>
            <Icon name="play" className="h-4 w-4" />
            {YC_ROUND[now.round]} vs {now.opp.name}（観戦する・結果だけ）
          </button>
        )}
        <div className="grid grid-cols-3 gap-2">
          {YC_ROUND.map((label, r) => (
            <div key={label} className="space-y-1.5">
              <div className="text-center text-[0.7rem] font-bold text-ink-dim">
                {label}（第 {YC_WEEKS[r] + 1} 週）
              </div>
              <div className={`flex flex-col gap-1.5 ${r === 1 ? 'pt-5' : r === 2 ? 'pt-14' : ''}`}>
                {(cup.rounds[r] ?? []).map((m, i) => (
                  <MatchCard key={i} cup={cup} m={m} />
                ))}
                {!cup.rounds[r] && <div className="rounded-lg bg-black/15 px-2 py-2 text-center text-[0.68rem] text-ink-mute">前の回戦のあと</div>}
              </div>
            </div>
          ))}
        </div>
      </div>
      <div className="panel scroll-y w-[38%] shrink-0 space-y-2 p-3 text-[0.78rem]">
        {cup.status === 'invited' ? (
          <>
            <div className="text-[0.74rem] font-bold text-ink-dim">出場クラブ</div>
            {cup.teams.map((t, i) => (
              <div key={i} className="flex items-center gap-1.5 text-[0.76rem]">
                <TeamName cup={cup} i={i} />
                <span className="num ml-auto text-[0.7rem] text-ink-dim">力 {Math.round(i === 0 ? ourLevel(state) : t.level)}</span>
              </div>
            ))}
          </>
        ) : (
          <>
            <div className="text-[0.74rem] font-bold text-ink-dim">うちの選手の成績</div>
            {ours.length === 0 && <div className="text-[0.74rem] text-ink-mute">まだ試合をしていません。</div>}
            {ours.map((x) => (
              <button key={x.p.id} className="flex w-full items-center gap-1.5 text-left text-[0.74rem]" onClick={() => push({ id: 'player', params: { id: x.p.id } })}>
                <span className="min-w-0 flex-1 truncate font-bold">{x.p.name}</span>
                <span className="num text-ink-dim">{x.apps} 試合</span>
                <span className="num w-8 text-right">{x.goals ? `${x.goals}点` : ''}</span>
                <span className="num w-8 text-right font-bold text-gold">{(x.ratingSum / x.apps).toFixed(1)}</span>
              </button>
            ))}
            {cup.standouts.length > 0 && (
              <>
                <div className="pt-1 text-[0.74rem] font-bold text-ink-dim">目立った相手の選手</div>
                {cup.standouts.map((s) => (
                  <div key={s.name} className="flex items-center gap-1.5 text-[0.74rem]">
                    <Flag nation={s.nation} className="h-[0.7rem] w-[1rem] shrink-0" />
                    <span className="min-w-0 flex-1 truncate font-bold">{s.name}</span>
                    <span className="text-[0.66rem] text-ink-dim">{s.pos}</span>
                    <span className="num font-bold text-accent">{s.rating.toFixed(1)}</span>
                  </div>
                ))}
                <div className="text-[0.68rem] text-ink-mute">冬の「海外の有望株」に並びます（来てくれやすい）。</div>
              </>
            )}
          </>
        )}
        <History state={state} inline />
      </div>
    </div>
  )
}

function History({ state, inline = false }: { state: GameState; inline?: boolean }) {
  const log = state.youthCupLog ?? []
  const body = (
    <>
      <div className="text-[0.74rem] font-bold text-ink-dim">これまでの成績</div>
      {log.length === 0 && <div className="text-[0.74rem] text-ink-mute">まだ出ていません。</div>}
      {[...log].reverse().map((r) => (
        <div key={r.season} className="flex items-center gap-1.5 text-[0.74rem]">
          <span className="num w-14 shrink-0 text-ink-dim">{seasonLabel(state.startYear, r.season)}</span>
          <span className="min-w-0 flex-1 truncate">{r.host}</span>
          {r.mvp && <span className="truncate text-[0.66rem] text-ink-dim">MVP {r.mvp}</span>}
          <span className={`shrink-0 rounded px-1.5 text-[0.68rem] font-bold ${r.result === 3 ? 'bg-gold text-[#2a1a00]' : 'bg-white/10'}`}>{YC_RESULT[r.result]}</span>
        </div>
      ))}
    </>
  )
  if (inline) return <div className="space-y-1 border-t border-white/10 pt-2">{body}</div>
  return <div className="panel scroll-y w-[38%] shrink-0 space-y-1 p-3">{body}</div>
}
