/**
 * 選手の整理（M22）: 選手枠（35 人）と、放出の候補（能力が低い・年長・出番がない順）。
 * おすすめを選ぶ → まとめて解雇（違約金）か、まとめて売りに出す。先発とポジションの最低人数は守る。
 */
import { useState } from 'react'
import { POSITION_DEFS, type GameState } from '../../engine'
import { ROSTER_LIMIT, listMany, releaseCandidates, releaseMany, releaseWarnings, rosterInfo, suggestRelease, type ReleaseCandidate } from '../../engine/club/roster'
import { releaseCost } from '../../engine/transfer/market'
import { SideSheet } from '../layout/SideSheet'
import { ConfirmDialog } from '../components/ConfirmDialog'
import { PlayerFace } from '../components/PersonFace'
import { OvrBadge, PosBadge } from '../components/common'
import { useGame, useGameState } from '../../stores/gameStore'
import { formatMoney, formatMoneyShort } from '../format'

const ROLE_LABEL: Record<ReleaseCandidate['role'], string> = { starter: '先発', bench: 'ベンチ', out: '出番なし' }
const ROLE_CLASS: Record<ReleaseCandidate['role'], string> = { starter: 'bg-good/20 text-good', bench: 'bg-accent/20 text-accent', out: 'bg-white/10 text-ink-dim' }

/** 選手枠の表示（選手一覧の上部・整理の画面） */
export function RosterChip({ state, onClick }: { state: GameState; onClick: () => void }) {
  const r = rosterInfo(state)
  return (
    <button className={`btn btn-sm !min-h-[2.3rem] !text-[0.78rem] ${r.over ? 'bg-bad text-white' : r.full ? 'btn-gold' : 'btn-ghost'}`} onClick={onClick}>
      選手の整理 <span className="num font-black">{r.count}/{r.limit}</span>
    </button>
  )
}

export function ReleaseSheet({ open, onClose }: { open: boolean; onClose: () => void }) {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const r = rosterInfo(state)
  const [sel, setSel] = useState<number[]>(() => (r.over > 0 ? suggestRelease(state, r.over) : []))
  const [showStarters, setShowStarters] = useState(false)
  const [ask, setAsk] = useState<'release' | 'sell' | null>(null)
  const [done, setDone] = useState<string | null>(null)
  const cands = releaseCandidates(state)
  const list = showStarters ? cands : cands.filter((c) => c.role !== 'starter')
  const ids = sel.filter((id) => state.players[id]?.clubId === state.playerClubId)
  const cost = ids.reduce((s, id) => s + releaseCost(state, state.players[id]), 0)
  const warnings = releaseWarnings(state, ids)
  const after = r.count - ids.length
  const toggle = (id: number) => setSel((s) => (s.includes(id) ? s.filter((x) => x !== id) : [...s, id]))
  const suggestN = r.over > 0 ? r.over : 3
  return (
    <SideSheet open={open} onClose={onClose} title="選手の整理" width="82%">
      <div className="flex h-full min-h-0 flex-col gap-2 p-3">
        {/* 選手枠と、まとめて選ぶ */}
        <div className="flex shrink-0 flex-wrap items-center gap-2">
          <div className={`rounded-lg px-2.5 py-1 text-[0.82rem] font-bold ${r.over ? 'bg-bad/20 text-[#ffb3b0]' : r.full ? 'bg-gold/15 text-gold' : 'bg-black/30 text-ink'}`}>
            選手枠 <span className="num text-[1rem] font-black">{r.count}</span>/{ROSTER_LIMIT}
            <span className="ml-1 text-[0.74rem]">{r.over ? `（${r.over} 人オーバー）` : r.full ? '（いっぱい・獲得できません）' : `（あと ${r.free} 人）`}</span>
          </div>
          <button className="btn btn-gold btn-sm !min-h-[2.3rem] !text-[0.76rem]" onClick={() => setSel(suggestRelease(state, suggestN))}>
            おすすめを {suggestN} 人選ぶ
          </button>
          <button className="btn btn-ghost btn-sm !min-h-[2.3rem] !text-[0.76rem]" disabled={!sel.length} onClick={() => setSel([])}>
            選択を外す
          </button>
          <button className="ml-auto text-[0.74rem] text-ink-dim underline-offset-2 hover:underline" onClick={() => setShowStarters(!showStarters)}>
            {showStarters ? '先発を隠す' : '先発も表示'}
          </button>
        </div>
        <p className="shrink-0 text-[0.7rem] text-ink-dim">放出の候補らしい順（能力がチームの水準より低い・年長・出番がない）。今季で契約が切れる選手は、待てばシーズン末にお金をかけずに退団します。</p>

        {/* 候補の一覧 */}
        <div className="scroll-y min-h-0 flex-1 space-y-1">
          {list.map((c) => {
            const on = sel.includes(c.p.id)
            return (
              <button key={c.p.id} onClick={() => toggle(c.p.id)} className={`flex w-full items-center gap-2 rounded-lg px-2 py-1 text-left ${on ? 'bg-bad/15 ring-1 ring-bad/60' : 'bg-white/[0.04]'}`}>
                <span className={`flex h-5 w-5 shrink-0 items-center justify-center rounded border text-[0.8rem] font-black ${on ? 'border-bad bg-bad text-white' : 'border-white/30'}`}>{on ? '✓' : ''}</span>
                <PlayerFace p={c.p} className="h-8 w-8 shrink-0" />
                <PosBadge pos={c.p.pos} />
                <span className="min-w-0 flex-1">
                  <span className="flex items-center gap-1.5">
                    <span className="truncate text-[0.82rem] font-bold">{c.p.name}</span>
                    <span className={`shrink-0 rounded px-1 text-[0.64rem] font-bold ${ROLE_CLASS[c.role]}`}>{ROLE_LABEL[c.role]}</span>
                  </span>
                  <span className="block truncate text-[0.68rem] text-ink-dim">
                    {c.age}歳・{POSITION_DEFS[c.p.pos].name}・今季 {c.p.stats.apps} 試合{c.note ? `・${c.note}` : ''}
                  </span>
                </span>
                <OvrBadge value={c.ovr} size="sm" />
                <span className="w-[5.6rem] shrink-0 text-right text-[0.68rem]">
                  <span className="block text-ink-dim">年俸 {formatMoneyShort(c.p.contract.wage)}</span>
                  {c.expiring ? <span className="block font-bold text-good">今季で満了</span> : <span className="block font-bold text-[#ffb3b0]">違約金 {formatMoneyShort(c.cost)}</span>}
                </span>
              </button>
            )
          })}
        </div>

        {/* 右下: まとめて */}
        <div className="shrink-0 rounded-xl bg-black/30 p-2">
          {done && <div className="mb-1 rounded-md bg-good/15 px-2 py-1 text-[0.76rem] font-bold text-good">{done}</div>}
          {warnings.map((w) => (
            <div key={w} className="mb-1 rounded-md bg-bad/15 px-2 py-0.5 text-[0.72rem] font-bold text-[#ffb3b0]">
              {w}
            </div>
          ))}
          <div className="flex flex-wrap items-center gap-2">
            <span className="text-[0.78rem]">
              選んだ <b className="num">{ids.length}</b> 人・違約金 合計 <b className="num text-[#ffb3b0]">{formatMoney(cost)}</b>・整理後{' '}
              <b className={`num ${after > ROSTER_LIMIT ? 'text-bad' : 'text-good'}`}>
                {after}/{ROSTER_LIMIT}
              </b>
            </span>
            <button className="btn btn-ghost btn-sm ml-auto !min-h-[2.5rem]" disabled={!ids.length || ids.some((id) => state.players[id]?.loan)} onClick={() => setAsk('sell')}>
              売りに出す（{ids.length}）
            </button>
            <button className="btn btn-sm !min-h-[2.5rem] bg-bad text-white" disabled={!ids.length || warnings.length > 0} onClick={() => setAsk('release')}>
              解雇する（{ids.length}）
            </button>
          </div>
        </div>
      </div>
      <ConfirmDialog
        open={ask === 'release'}
        title={`${ids.length} 人を解雇しますか？`}
        text={`違約金 ${formatMoney(cost)} を払って契約を解除します。選手はフリーになります。`}
        ok="解雇する"
        onOk={() => {
          let res = { count: 0, cost: 0 }
          mutate((st) => void (res = releaseMany(st, ids)))
          setDone(`${res.count} 人を解雇しました（違約金 ${formatMoney(res.cost)}）。`)
          setSel([])
          setAsk(null)
        }}
        onCancel={() => setAsk(null)}
      />
      <ConfirmDialog
        open={ask === 'sell'}
        title={`${ids.length} 人を売りに出しますか？`}
        text="市場価値で売りに出します。移籍期間に、ほかのクラブから声がかかります（移籍 → 売る・オファー）。"
        ok="売りに出す"
        onOk={() => {
          let n = 0
          mutate((st) => void (n = listMany(st, ids)))
          setDone(`${n} 人を売りに出しました。移籍期間にオファーが届きます。`)
          setSel([])
          setAsk(null)
        }}
        onCancel={() => setAsk(null)}
      />
    </SideSheet>
  )
}
