/** キャリア: 主人公が招集された代表戦（試合前 → 観戦か結果だけ → 結果）。 */
import { useMemo, useState } from 'react'
import { NATION_NAME } from '../../engine'
import type { Nation } from '../../engine/data/nations'
import { careerNationalFixture, nationalMatchSetup, natRoundName } from '../../engine/national/national'
import type { MatchSummary } from '../../engine/match/live/types'
import { MatchView } from '../match/MatchView'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Flag } from '../components/common'
import { Icon } from '../components/Icon'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

function ratingColor(r: number): string {
  return r >= 8 ? '#f5c542' : r >= 7 ? '#3ddc84' : r >= 6 ? '#e8eef6' : '#ff8a8a'
}

function Team({ n }: { n: Nation }) {
  return (
    <div className="flex w-[38%] flex-col items-center gap-1.5 text-center">
      <Flag nation={n} className="h-[3rem] w-[4.5rem] rounded shadow-lg" />
      <div className="text-[1rem] font-black">{NATION_NAME[n]}代表</div>
    </div>
  )
}

export function NationalMatchScreen() {
  const state = useGameState()
  const playNational = useGame((s) => s.playNational)
  const reset = useUi((s) => s.reset)
  // 開いた時点の試合を固定する
  const [fx] = useState(() => careerNationalFixture(state))
  const [phase, setPhase] = useState<'pre' | 'live' | 'done'>(fx ? 'pre' : 'done')
  const setup = useMemo(() => (fx ? nationalMatchSetup(state, fx.f) : null), [fx, state])
  const c = state.career!
  const pid = c.playerId
  if (phase === 'live' && setup) {
    const exit = (s: MatchSummary | null) => {
      playNational(s ?? undefined)
      setPhase('done')
    }
    return <MatchView setup={setup} onExit={exit} focus={pid} />
  }
  if (phase === 'done' || !fx || !setup) {
    const r = c.lastNational
    return (
      <AppShell title="代表戦の結果" current="home" right={<GameTopInfo />}>
        <div className="absolute inset-0 flex items-center justify-center p-4">
          <div className="panel w-[30rem] max-w-full p-4 text-center">
            {r ? (
              <>
                <div className="text-[0.75rem] text-ink-dim">{r.compShort}</div>
                <div className="mt-1 text-[1.1rem] font-black">
                  {NATION_NAME[state.players[pid].nation]} <span className="num text-[2rem] text-gold">{r.gf} - {r.ga}</span> {NATION_NAME[r.opp as Nation] ?? r.opp}
                </div>
                {r.minutes > 0 ? (
                  <div className="mt-2 flex items-end justify-center gap-4">
                    <div>
                      <div className="text-[0.7rem] text-ink-dim">あなたの評価点</div>
                      <div className="num text-[2rem] font-black leading-none" style={{ color: ratingColor(r.rating) }}>
                        {r.rating.toFixed(1)}
                      </div>
                    </div>
                    <div className="num pb-1 text-[0.8rem] text-ink-dim">
                      {r.minutes} 分{r.goals > 0 && <b className="ml-1 text-ink">{r.goals} 得点</b>}
                    </div>
                  </div>
                ) : (
                  <div className="mt-2 text-[0.8rem] text-ink-dim">今日は出番がありませんでした。</div>
                )}
              </>
            ) : (
              <div className="text-ink-dim">代表戦はありません</div>
            )}
            <button className="btn btn-gold mt-4 w-full" onClick={() => reset({ id: 'home' })}>
              <Icon name="forward" className="h-5 w-5" />
              ホームへ
            </button>
          </div>
        </div>
      </AppShell>
    )
  }
  const mine = state.players[pid].nation
  const side = setup.home.starters.some((p) => p.id === pid) || setup.home.bench.some((p) => p.id === pid) ? setup.home : setup.away
  const role = side.starters.some((p) => p.id === pid) ? '先発' : side.bench.some((p) => p.id === pid) ? 'ベンチ' : 'メンバー外'
  const round = natRoundName(fx.comp, fx.f)
  return (
    <AppShell title={`${fx.comp.name}${round ? ` ${round}` : ''}`} current="home" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="panel flex min-w-0 flex-1 flex-col justify-center p-4">
          <div className="flex items-center justify-center gap-3">
            <Team n={fx.f.home} />
            <div className="text-center">
              <div className="text-[1.4rem] font-black text-ink-dim">VS</div>
              <div className="mt-1 rounded bg-white/10 px-2 text-[0.72rem] font-black">{fx.f.neutral ? '中立地' : fx.f.home === mine ? 'HOME' : 'AWAY'}</div>
            </div>
            <Team n={fx.f.away} />
          </div>
          <div className={`mx-auto mt-4 rounded-lg px-4 py-2 text-center text-[0.9rem] font-black ${role === '先発' ? 'bg-good/20 text-good' : role === 'ベンチ' ? 'bg-accent/20 text-accent' : 'bg-white/10 text-ink-dim'}`}>
            {role === '先発' ? `${NATION_NAME[mine]}代表の先発です！` : role === 'ベンチ' ? 'ベンチスタート。出番を待とう' : '今日はメンバー外…'}
          </div>
        </div>
        <div className="flex w-[11rem] shrink-0 flex-col justify-end gap-2">
          <button className="btn btn-gold h-[3.6rem] text-[1.05rem]" onClick={() => setPhase('live')}>
            <Icon name="play" className="h-5 w-5" />
            観戦する
          </button>
          <button
            className="btn btn-ghost"
            onClick={() => {
              playNational()
              setPhase('done')
            }}
          >
            結果だけ見る
          </button>
        </div>
      </div>
    </AppShell>
  )
}
