/** クラブのエンブレムとユニフォーム（EmblemSpec / KitPattern とクラブカラーから描く）。 */
import type { EmblemSpec, KitPattern } from '../../engine'

const SHIELDS = [
  'M50 4 L92 16 V52 C92 74 74 90 50 97 C26 90 8 74 8 52 V16 Z',
  'M50 4 L90 12 V58 C90 80 50 97 50 97 C50 97 10 80 10 58 V12 Z',
  'M50 3 A47 47 0 1 1 49.9 3 Z',
  'M50 4 L94 28 L82 88 L50 97 L18 88 L6 28 Z',
  'M14 6 H86 V60 C86 80 66 92 50 97 C34 92 14 80 14 60 Z',
]

function Charge({ type, color }: { type: number; color: string }) {
  switch (type % 8) {
    case 0:
      return <path d="M50 28 L56 44 L73 44 L59 54 L64 70 L50 60 L36 70 L41 54 L27 44 L44 44 Z" fill={color} />
    case 1:
      return (
        <g fill="none" stroke={color} strokeWidth="3.5">
          <circle cx="50" cy="50" r="18" />
          <path d="M50 37 L57 47 L53 59 H47 L43 47 Z" fill={color} stroke="none" />
        </g>
      )
    case 2:
      return <path d="M56 24 L38 54 H49 L43 78 L64 46 H52 Z" fill={color} />
    case 3:
      return <path d="M50 60 C38 60 26 52 22 38 C34 44 40 44 46 42 C40 38 36 32 36 26 C46 32 54 32 64 26 C64 32 60 38 54 42 C60 44 66 44 78 38 C74 52 62 60 50 60 Z" fill={color} />
    case 4:
      return <path d="M30 62 L26 36 L40 48 L50 30 L60 48 L74 36 L70 62 Z" fill={color} />
    case 5:
      return <path d="M26 66 L44 34 L52 48 L60 38 L74 66 Z" fill={color} />
    case 6:
      return <path d="M50 26 C60 36 68 42 68 54 C68 64 60 72 50 72 C40 72 32 64 32 54 C32 42 40 36 50 26 Z" fill={color} />
    default:
      return (
        <g fill={color}>
          <circle cx="50" cy="50" r="7" />
          {[0, 60, 120, 180, 240, 300].map((a) => (
            <ellipse key={a} cx="50" cy="35" rx="5" ry="10" transform={`rotate(${a} 50 50)`} />
          ))}
        </g>
      )
  }
}

export function Emblem({
  id,
  emblem,
  colors,
  size = '2.5rem',
  initials,
}: {
  id: number | string
  emblem: EmblemSpec
  colors: { primary: string; secondary: string }
  size?: number | string
  /** 中央に短い文字を入れる（略称の頭文字など） */
  initials?: string
}) {
  const { shape, charge, pattern } = emblem
  const c1 = colors.primary
  const c2 = colors.secondary
  const path = SHIELDS[shape % SHIELDS.length]
  const pid = `em-${id}`
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ display: 'block', flexShrink: 0 }} aria-hidden>
      <defs>
        <clipPath id={pid}>
          <path d={path} />
        </clipPath>
        <linearGradient id={`${pid}-g`} x1="0" y1="0" x2="0" y2="1">
          <stop offset="0" stopColor="#fff" stopOpacity="0.28" />
          <stop offset="0.5" stopColor="#fff" stopOpacity="0" />
        </linearGradient>
      </defs>
      <path d={path} fill={c1} />
      <g clipPath={`url(#${pid})`}>
        {pattern % 5 === 1 && [0, 40, 80].map((x) => <rect key={x} x={x} y="0" width="20" height="100" fill={c2} opacity="0.5" />)}
        {pattern % 5 === 2 && <path d="M0 0 H100 L0 100 Z" fill={c2} opacity="0.4" />}
        {pattern % 5 === 3 && <rect x="0" y="50" width="100" height="50" fill={c2} opacity="0.4" />}
        {pattern % 5 === 4 && <rect x="0" y="0" width="100" height="22" fill={c2} opacity="0.55" />}
        {initials ? (
          <text x="50" y="62" textAnchor="middle" fontSize="30" fontWeight="900" fill={pattern % 5 === 0 ? c2 : '#fff'} fontFamily="system-ui, sans-serif">
            {initials}
          </text>
        ) : (
          <Charge type={charge} color={pattern % 5 === 0 ? c2 : '#ffffff'} />
        )}
        <rect width="100" height="100" fill={`url(#${pid}-g)`} />
      </g>
      <path d={path} fill="none" stroke="#0b1320" strokeWidth="3.5" opacity="0.6" />
    </svg>
  )
}

export function Kit({ id, pattern, colors, size = '3rem', number }: { id: number | string; pattern: KitPattern; colors: { primary: string; secondary: string }; size?: number | string; number?: number }) {
  const c1 = colors.primary
  const c2 = colors.secondary
  const pid = `kit-${id}`
  const body = 'M30 22 L42 12 C46 16 54 16 58 12 L70 22 L82 34 L72 46 L68 40 V88 H32 V40 L28 46 L18 34 Z'
  return (
    <svg width={size} height={size} viewBox="0 0 100 100" style={{ display: 'block', flexShrink: 0 }} aria-hidden>
      <defs>
        <clipPath id={pid}>
          <path d={body} />
        </clipPath>
      </defs>
      <path d={body} fill={c1} />
      <g clipPath={`url(#${pid})`}>
        {pattern === 'stripes' && [36, 48, 60].map((x) => <rect key={x} x={x} y="0" width="7" height="100" fill={c2} />)}
        {pattern === 'hoops' && [30, 46, 62, 78].map((y) => <rect key={y} x="0" y={y} width="100" height="8" fill={c2} />)}
        {pattern === 'sash' && <path d="M22 10 L40 10 L84 90 L66 90 Z" fill={c2} />}
        {pattern === 'halves' && <rect x="50" y="0" width="50" height="100" fill={c2} />}
        <path d="M18 34 L28 46 L34 40 L30 22 Z" fill={c2} opacity="0.9" />
        <path d="M82 34 L72 46 L66 40 L70 22 Z" fill={c2} opacity="0.9" />
        <rect x="0" y="0" width="100" height="40" fill="#fff" opacity="0.08" />
      </g>
      <path d={body} fill="none" stroke="#0b1320" strokeWidth="2.5" opacity="0.5" />
      <path d="M42 12 C46 16 54 16 58 12 L54 20 H46 Z" fill={c2} stroke="#0b1320" strokeWidth="1" opacity="0.9" />
      {number !== undefined && (
        <text x="50" y="68" textAnchor="middle" fontSize="26" fontWeight="900" fill={pattern === 'solid' ? c2 : '#fff'} stroke="#0b1320" strokeWidth="1" fontFamily="system-ui, sans-serif">
          {number}
        </text>
      )}
    </svg>
  )
}
