/** キャリアモードのホーム: 主人公の状態・監督の課題・次の試合・出来事・今週の過ごし方。 */
import { useState } from 'react'
import { dateLabel, ovr, playerFixtureThisWeek, upcomingFixtures, type GameState } from '../../engine'
import { EXP_KINDS, EXP_LABEL } from '../../engine/models/career'
import { POSITION_DEFS } from '../../engine/data/positions'
import { PLAY_STYLE_BY_ID } from '../../engine/data/career'
import { careerAge } from '../../engine/career/core'
import { STATUS_LABEL, careerStatus, objectiveLabel } from '../../engine/career/manager'
import { actionLabel, autoAction } from '../../engine/career/week'
import { roundName } from '../../engine/competition/continental'
import { careerNationalFixture } from '../../engine/national/national'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { MonthAutoButton } from '../home/MonthAutoButton'
import { Emblem } from '../components/ClubArt'
import { PlayerFace } from '../components/PersonFace'
import { OvrBadge } from '../components/common'
import { Icon } from '../components/Icon'
import { Portrait } from '../components/Portrait'
import { TalkScene } from '../career/TalkScene'
import { Ceremony } from '../career/Ceremony'
import { ActionSheet } from '../career/ActionSheet'
import { OfferCard } from '../career/OfferCard'
import { SeasonEndModal } from './SeasonEndModal'
import { useGame, useGameState, type AdvanceMode } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { RankBadge } from '../career/RankBadge'
import { clubRank } from '../../engine/career/rank'
import { youthBigMatch, youthNextLabel } from '../../engine/career/saga'
import { WatchHome } from '../career/WatchHome'

function Meter({ label, value, color = '#f5c542', warn }: { label: string; value: number; color?: string; warn?: boolean }) {
  return (
    <div className="flex items-center gap-2 text-[0.76rem]">
      <span className="w-[4.2rem] shrink-0 text-ink-dim">{label}</span>
      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-black/40">
        <div className="h-full rounded-full" style={{ width: `${Math.max(2, Math.min(100, value))}%`, background: warn ? '#ff6b6b' : color }} />
      </div>
      <span className="num w-7 shrink-0 text-right font-bold">{Math.round(value)}</span>
    </div>
  )
}

/** 主人公の次の試合での見込み */
function lineupStatus(state: GameState): string {
  const c = state.career!
  const club = state.clubs[state.playerClubId]
  if (state.players[c.playerId].injury) return 'ケガで欠場'
  if (club.lineup.starters.includes(c.playerId)) return '先発の予定'
  if (club.lineup.bench.includes(c.playerId)) return 'ベンチ入りの予定'
  return 'メンバー外の見込み'
}

export function CareerHomeScreen() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const advance = useGame((s) => s.advance)
  const advanceAsync = useGame((s) => s.advanceAsync)
  const [sheet, setSheet] = useState(false)
  const [toast, setToast] = useState<string | null>(null)
  const [seasonEnd, setSeasonEnd] = useState(false)
  const c = state.career!
  const p = state.players[c.playerId]
  const joined = p.clubId >= 0
  // 世代をつなぐ物語（M17）: ユース期は息子が主人公（クラブには入っていない）
  const youth = c.saga?.phase === 'youth' ? c.saga.youth : undefined
  // ユースの大会の準決勝・決勝（観戦できる）
  const bigMatch = youth ? youthBigMatch(state) : null
  const club = joined ? state.clubs[p.clubId] : undefined
  const style = PLAY_STYLE_BY_ID[c.style]
  const now = state.season * 48 + state.week
  const matchWeek = joined && !!playerFixtureThisWeek(state)
  // 代表戦（クラブの試合のあと）
  const natWeek = !matchWeek && !!careerNationalFixture(state)
  const next = joined ? upcomingFixtures(state, p.clubId, 1)[0] : undefined
  const rookie = c.offers.filter((o) => o.kind === 'rookie')
  const otherOffers = c.offers.filter((o) => o.kind !== 'rookie')
  const action = c.action ?? autoAction(state)

  const go = async (mode: AdvanceMode) => {
    if (c.talks.length || c.ceremony) return
    if (c.retired) return push({ id: 'careerEnd' })
    if (!joined && !youth) return setToast('まず入団するクラブを選びましょう')
    if (bigMatch && mode !== 'month') return push({ id: 'youthMatch' })
    if (matchWeek && mode !== 'month') return push({ id: 'preMatch' })
    if (natWeek && mode !== 'month') return push({ id: 'natMatch' })
    const apps = p.stats.apps
    const goals = p.stats.goals
    const out = mode === 'month' ? await advanceAsync(mode) : advance(mode)
    if (out.needMatch) return push({ id: 'preMatch' })
    if (out.needNational) return push({ id: 'natMatch' })
    const played = Math.max(0, p.stats.apps - apps)
    const scored = Math.max(0, p.stats.goals - goals)
    setToast([`${out.reports.length}週進みました`, played ? `（出場 ${played}・${scored} 得点）` : '', out.stopText ? `・${out.stopText}` : ''].join(''))
    if (out.seasonEnded && joined) setSeasonEnd(true)
  }

  // 見守り期（引退した親が、15 歳までの息子を見守る）
  if (c.retired && c.saga?.phase === 'watch') return <WatchHome state={state} />

  return (
    <AppShell
      title={p.name}
      current="home"
      right={
        <>
          {(joined || youth) && !c.retired && <MonthAutoButton label="おまかせ 1か月" onRun={() => void go('month')} />}
          <GameTopInfo />
        </>
      }
    >
      <div className="absolute inset-0 flex gap-3 p-3">
        {/* 左: 主人公 */}
        <div className="flex w-[40%] shrink-0 flex-col gap-2.5">
          <div className="panel panel-hero relative overflow-hidden p-3">
            <div className="absolute inset-0 opacity-30" style={{ background: `radial-gradient(70% 120% at 0% 0%, ${club?.colors.primary ?? '#1d4ed8'}, transparent 70%)` }} />
            <div className="relative flex items-center gap-3">
              <button className="relative shrink-0" onClick={() => push({ id: 'player', params: { id: p.id } })} aria-label="自分の詳細">
                <PlayerFace p={p} kit={club?.colors} className="h-[4.8rem] w-[4.8rem]" />
                <span className="absolute -bottom-1 -right-1">
                  <OvrBadge value={ovr(p)} size="sm" />
                </span>
              </button>
              <div className="min-w-0 flex-1">
                <div className="truncate text-[1.15rem] font-black">{p.name}</div>
                <div className="text-[0.76rem] text-ink-dim">
                  {careerAge(state)} 歳・{POSITION_DEFS[p.pos].name}・{style.name}
                </div>
                {club ? (
                  <div className="mt-0.5 flex items-center gap-1.5 text-[0.75rem]">
                    <Emblem id={`ch-${club.id}`} emblem={club.emblem} colors={club.colors} size="1.2rem" />
                    <span className="truncate font-bold">{club.name}</span>
                    <RankBadge rank={clubRank(state, club)} withName={false} />
                    <span className="shrink-0 rounded bg-accent/20 px-1.5 text-[0.68rem] font-bold text-accent">{STATUS_LABEL[careerStatus(state)]}</span>
                  </div>
                ) : (
                  <div className="mt-0.5 text-[0.75rem] font-bold text-gold">{c.retired ? '引退しました' : youth ? `${youth.team}・${youth.year} 年生` : '入団先を選ぶところ'}</div>
                )}
              </div>
            </div>
            <div className="relative mt-2 space-y-1">
              <Meter label="体力" value={c.stamina} color="#3ddc84" warn={c.stamina < 30} />
              <Meter label="調子" value={p.condition} color="#7dd3fc" />
              <Meter label="監督の評価" value={c.trust} />
              <Meter label="知名度" value={c.fame} color="#f472b6" />
            </div>
            <div className="relative mt-2 grid grid-cols-5 gap-1 text-center">
              {EXP_KINDS.map((k) => (
                <div key={k} className="rounded-md bg-black/30 py-0.5">
                  <div className="text-[0.66rem] text-ink-dim">{EXP_LABEL[k]}</div>
                  <div className="num text-[0.78rem] font-black">{Math.floor(c.exp[k])}</div>
                </div>
              ))}
            </div>
            {p.injury && <div className="relative mt-1.5 rounded bg-bad/20 px-2 py-0.5 text-[0.76rem] font-bold text-bad">{p.injury.name}（あと {p.injury.weeks} 週）</div>}
          </div>
          {youth ? (
            <YouthRecord state={state} />
          ) : (
          <div className="panel min-h-0 flex-1 overflow-hidden p-3">
            <div className="panel-head mb-1">監督の課題</div>
            {c.objectives.length === 0 && <div className="text-[0.75rem] text-ink-dim">{joined ? '次の課題を待っています' : '入団すると課題が出ます'}</div>}
            {c.objectives.map((o) => (
              <div key={o.id} className="mb-1.5">
                <div className="flex items-baseline justify-between text-[0.75rem]">
                  <span className="font-bold">{objectiveLabel(o)}</span>
                  <span className="num text-[0.72rem] text-ink-dim">あと {Math.max(0, o.untilAbsWeek - now)} 週</span>
                </div>
                <div className="mt-0.5 h-1.5 overflow-hidden rounded-full bg-black/40">
                  <div className="h-full rounded-full bg-good" style={{ width: `${Math.min(100, (o.progress / o.target) * 100)}%` }} />
                </div>
              </div>
            ))}
          </div>
          )}
        </div>

        {/* 右: 入団・試合・出来事・操作 */}
        <div className="flex min-w-0 flex-1 flex-col gap-2.5">
          {c.retired ? (
            <div className="panel flex min-h-0 flex-1 flex-col items-center justify-center gap-2 p-4 text-center">
              <Icon name="trophy" className="h-10 w-10 text-gold" />
              <div className="text-[1.05rem] font-black">おつかれさまでした</div>
              <div className="text-[0.8rem] text-ink-dim">{p.name}のプロ選手としての日々は幕を閉じました。キャリアの総括を見てみましょう。</div>
            </div>
          ) : youth ? (
            <>
              <div className="panel p-3">
                <div className="panel-head mb-1">次の試合</div>
                <YouthNext state={state} />
              </div>
              <Reports lines={c.report} />
            </>
          ) : !joined ? (
            <div className="panel scroll-y min-h-0 flex-1 space-y-2 p-3">
              <div className="flex items-end gap-2">
                <Portrait id="kato_misaki" kind="face" className="face-round h-11 w-11 shrink-0" />
                <div className="rounded-xl rounded-bl-none bg-white/10 px-2.5 py-1.5 text-[0.75rem] leading-snug">3 つのクラブから声がかかっています。試合に出られそうなところで経験を積むか、上のカテゴリーで揉まれるか……あなたが決めてください。</div>
              </div>
              {rookie.map((o) => (
                <OfferCard key={o.id} state={state} o={o} />
              ))}
            </div>
          ) : (
            <>
              <div className="panel panel-hero p-3">
                <div className="panel-head mb-1">次の試合</div>
                {next ? (
                  <NextMatch state={state} />
                ) : (
                  <div className="text-[0.78rem] text-ink-dim">予定された試合はありません</div>
                )}
              </div>
              {c.sponsorOffer && (
                <button className="flex items-center gap-2 rounded-xl border border-accent/50 bg-accent/10 px-3 py-2 text-left text-[0.82rem] font-bold text-accent" onClick={() => push({ id: 'life', params: { tab: 'sponsor', back: true } })}>
                  <Icon name="person" className="h-5 w-5" />
                  {c.sponsorOffer.company}から個人スポンサーの申し出
                </button>
              )}
              {c.mediaOffer && (
                <button className="flex items-center gap-2 rounded-xl border border-accent/50 bg-accent/10 px-3 py-2 text-left text-[0.82rem] font-bold text-accent" onClick={() => push({ id: 'life', params: { tab: 'media', back: true } })}>
                  <Icon name="tv" className="h-5 w-5" />
                  {c.mediaOffer.name}から出演の依頼
                </button>
              )}
              {otherOffers.length > 0 && (
                <button className="flex items-center gap-2 rounded-xl border border-gold/50 bg-gold/10 px-3 py-2 text-left text-[0.82rem] font-bold text-gold" onClick={() => push({ id: 'career', params: { back: true } })}>
                  <Icon name="trophy" className="h-5 w-5" />
                  オファーが {otherOffers.length} 件届いています
                </button>
              )}
              <Reports lines={c.report} />
            </>
          )}
          <div className="flex shrink-0 items-end justify-end gap-2">
            <button className="btn btn-ghost min-w-0 flex-1 flex-col !items-start !gap-0 text-left" onClick={() => setSheet(true)} disabled={!joined && !youth}>
              <span className="text-[0.7rem] text-ink-dim">今週の過ごし方{c.action ? '' : '（おまかせ）'}</span>
              <span className="truncate text-[0.88rem] font-black">{actionLabel(action)}</span>
            </button>
            <div className="flex flex-col">
              {c.retired ? (
                <button className="btn btn-gold min-w-[9.5rem] text-[1.02rem]" onClick={() => push({ id: 'careerEnd' })}>
                  <Icon name="trophy" className="h-5 w-5" />
                  キャリアの総括へ
                </button>
              ) : (
                <>
                  <button className={`btn min-w-[9.5rem] text-[1.02rem] ${matchWeek || natWeek || bigMatch ? 'btn-blue' : 'btn-gold'}`} onClick={() => go('week')}>
                    <Icon name={matchWeek || natWeek || bigMatch ? 'ball' : 'forward'} className="h-5 w-5" />
                    {matchWeek ? '試合へ' : natWeek ? '代表戦へ' : bigMatch ? (bigMatch.final ? '決勝へ' : '準決勝へ') : '次へ進む'}
                  </button>
                  {(joined || youth) && <MonthAutoButton label="おまかせ 1か月" className="btn btn-ghost btn-sm mt-1 !text-[0.74rem]" onRun={() => void go('month')} />}
                </>
              )}
            </div>
          </div>
        </div>
      </div>
      {toast && (
        <button className="anim-rise absolute left-1/2 top-2 z-30 -translate-x-1/2 rounded-full bg-[#0b1320]/90 px-4 py-1.5 text-[0.8rem] font-bold text-white shadow-lg" onClick={() => setToast(null)}>
          {toast}
        </button>
      )}
      {(joined || youth) && <ActionSheet state={state} open={sheet} onClose={() => setSheet(false)} />}
      {seasonEnd && !c.talks.length && !c.ceremony && <SeasonEndModal onClose={() => setSeasonEnd(false)} />}
      <TalkScene state={state} />
      <Ceremony state={state} />
    </AppShell>
  )
}

/** 出来事の種類の目印（文の中身から） */
function reportIcon(t: string): string {
  if (/得点|試合|リーグ戦|勝ち|負け|引き分け|大会|決勝/.test(t)) return 'ball'
  if (/練習の成果|自主トレ|能力/.test(t)) return 'growth'
  if (/会った|デート|絆/.test(t)) return 'story'
  if (/スポンサー|CM|出演|貯金|万円/.test(t)) return 'trophy'
  if (/入団|移籍|オファー/.test(t)) return 'transfer'
  return 'forward'
}

function Reports({ lines }: { lines: string[] }) {
  const list = [...lines].reverse()
  return (
    <div className="panel flex min-h-0 flex-1 flex-col p-3">
      <div className="panel-head mb-1">最近の出来事</div>
      <div className="scroll-y min-h-0 flex-1 space-y-1 pr-1">
        {list.map((t, i) => (
          <div key={i} className={`flex items-start gap-2 rounded-lg px-2.5 py-1.5 text-[0.8rem] leading-snug ${i === 0 ? 'bg-gold/10 text-ink' : 'bg-black/25 text-ink-dim'}`}>
            <Icon name={reportIcon(t)} className={`mt-0.5 h-4 w-4 shrink-0 ${i === 0 ? 'text-gold' : 'text-ink-mute'}`} />
            <span className="min-w-0">{t}</span>
          </div>
        ))}
        {/* 出来事が少ないうちは、何がここに並ぶかを出す */}
        {list.length < 4 && (
          <div className="rounded-lg border border-dashed border-white/10 px-3 py-2 text-[0.74rem] leading-relaxed text-ink-mute">
            練習の成果・試合・おでかけで会った人・オファーなど、毎週の出来事がここに並びます。右下の「次へ進む」で 1 週間すすみます。
          </div>
        )}
      </div>
    </div>
  )
}

/** ユース期のチームと成績（M17） */
function YouthRecord({ state }: { state: GameState }) {
  const c = state.career!
  const y = c.saga!.youth!
  return (
    <div className="panel scroll-y min-h-0 flex-1 p-3">
      <div className="panel-head mb-1">{y.team}</div>
      <div className="grid grid-cols-3 gap-1 text-center">
        {[
          ['学年', `${y.year} 年`],
          ['出場', `${y.apps}`],
          ['得点', `${y.goals}`],
        ].map(([k, v]) => (
          <div key={k} className="rounded-md bg-black/30 py-1">
            <div className="text-[0.66rem] text-ink-dim">{k}</div>
            <div className="num text-[0.9rem] font-black">{v}</div>
          </div>
        ))}
      </div>
      <div className="mt-1.5 text-[0.76rem] text-ink-dim">チームの力 {Math.round(y.strength)}{y.selected ? '・U-17 日本代表に選ばれた' : ''}</div>
      {y.titles.length > 0 && (
        <div className="mt-1.5 space-y-0.5">
          {y.titles.map((t, i) => (
            <div key={i} className="flex items-center gap-1.5 text-[0.75rem] font-bold text-gold">
              <Icon name="trophy" className="h-4 w-4" />
              {t}
            </div>
          ))}
        </div>
      )}
      <div className="mt-1.5 text-[0.72rem] text-ink-mute">18 歳の春に卒業し、プロのクラブから入団の話が届きます。</div>
    </div>
  )
}

/** ユース期の次の試合（リーグは偶数週、冬の大会 16〜21 週、夏の大会 42〜46 週） */
function YouthNext({ state }: { state: GameState }) {
  const big = youthBigMatch(state)
  if (big)
    return (
      <div className="text-[0.85rem] font-bold">
        <span className="text-gold">{big.label}</span>・vs {big.opp}
      </div>
    )
  return <div className="text-[0.85rem] font-bold">{youthNextLabel(state)}</div>
}

function NextMatch({ state }: { state: GameState }) {
  const c = state.career!
  const p = state.players[c.playerId]
  const f = upcomingFixtures(state, p.clubId, 1)[0]
  if (!f) return null
  const home = f.home === p.clubId
  const opp = state.clubs[home ? f.away : f.home]
  const comp = state.competitions.find((x) => x.id === f.compId)!
  const wk = f.absWeek - (state.season * 48 + state.week)
  const status = lineupStatus(state)
  return (
    <div className="flex items-center gap-3">
      <Emblem id={`nm-${opp.id}`} emblem={opp.emblem} colors={opp.colors} size="2.4rem" />
      <div className="min-w-0 flex-1">
        <div className="truncate text-[0.78rem] text-ink-dim">
          {comp.name} {roundName(comp, f.round)}・{wk === 0 ? '今週' : `${wk}週後（${dateLabel(state.startYear, Math.floor(f.absWeek / 48), f.absWeek % 48).replace(/^\d+年/, '')}）`}
        </div>
        <div className="truncate text-[0.95rem] font-black">
          <span className={home ? 'text-good' : 'text-accent'}>{home ? 'H' : 'A'}</span> {opp.name}
        </div>
      </div>
      <span className={`shrink-0 rounded-lg px-2 py-1 text-[0.78rem] font-bold ${status === '先発の予定' ? 'bg-good/20 text-good' : status === 'ベンチ入りの予定' ? 'bg-accent/20 text-accent' : 'bg-white/10 text-ink-dim'}`}>{status}</span>
    </div>
  )
}
