/** キャリアのクラブのランク（E〜S）の札と、ステップアップのはしご。 */
import type { GameState } from '../../engine'
import { RANKS, bestRank, myRank, type RankDef } from '../../engine/career/rank'

const RANK_COLOR: Record<string, string> = {
  E: 'bg-white/10 text-ink-dim',
  D: 'bg-sky-500/15 text-sky-300',
  C: 'bg-accent/20 text-accent',
  B: 'bg-good/20 text-good',
  A: 'bg-pink/20 text-pink',
  S: 'bg-gold/25 text-gold',
}

export function RankBadge({ rank, withName = true, className = '' }: { rank?: RankDef; withName?: boolean; className?: string }) {
  if (!rank) return null
  return (
    <span className={`inline-flex shrink-0 items-center gap-1 rounded px-1.5 text-[0.7rem] font-black ${RANK_COLOR[rank.grade]} ${className}`}>
      ランク{rank.grade}
      {withName && <span className="font-bold opacity-90">{rank.name}</span>}
    </span>
  )
}

/** ステップアップのはしご（下が E、上が S）。今いるランクと、これまでの最高を示す */
export function RankLadder({ state }: { state: GameState }) {
  const now = myRank(state)
  const best = bestRank(state)
  const seasonsAt = (step: number) => state.career!.log.filter((l) => l.rank === step).length
  return (
    <div className="space-y-1">
      {[...RANKS].reverse().map((r) => {
        const here = now?.step === r.step
        const reached = best !== undefined && r.step <= best.step
        return (
          <div key={r.grade} className={`flex items-center gap-2 rounded-lg px-2 py-1 ${here ? 'bg-gold/15 ring-1 ring-gold/60' : reached ? 'bg-white/[0.05]' : 'bg-black/20 opacity-60'}`}>
            <span className={`flex h-6 w-6 shrink-0 items-center justify-center rounded text-[0.8rem] font-black ${RANK_COLOR[r.grade]}`}>{r.grade}</span>
            <span className="min-w-0 flex-1 truncate text-[0.74rem] font-bold">{r.name}</span>
            {here && <span className="shrink-0 text-[0.7rem] font-black text-gold">いまここ</span>}
            {!here && seasonsAt(r.step) > 0 && <span className="num shrink-0 text-[0.7rem] text-ink-dim">{seasonsAt(r.step)} シーズン</span>}
          </div>
        )
      })}
    </div>
  )
}
