/**
 * 海外遠征・プレシーズンマッチ（M19。クラブモード）: プレシーズン（第 0〜2 週）に 1 回。
 *   行き先で費用・出場料・人気・サポーター・連携・疲れが変わる。現地のクラブと親善試合を 2 つ（FastSim。リーグの成績には入らない）
 *   合宿の最中は行けない。乱数は種とシーズンから。
 */
import { absWeekOf } from '../core/calendar'
import { createRng, hashSeed } from '../core/prng'
import { buildMatchSetup } from '../match/setup'
import { fastSim } from '../match/fastSim'
import { chemWeekly } from './chemistry'
import { squadOf } from '../match/lineup'
import { fansCap } from './fans'
import type { GameState } from '../models/game'

export type TourId = 'asia' | 'europe' | 'brazil'

export interface TourDef {
  id: TourId
  name: string
  desc: string
  /** 費用（万円） */
  cost: number
  /** 出場料（万円） */
  fee: number
  popularity: number
  /** サポーターの増え方（割合） */
  fans: number
  /** 連携の伸び（週あたりの合宿と同じ尺度） */
  chem: number
  /** 疲れ（全員） */
  fatigue: number
  /** 相手のリーグ */
  leagues: string[]
}

export const TOURS: TourDef[] = [
  { id: 'asia', name: 'アジアツアー', desc: '韓国・中国・オーストラリアのクラブと。近くて安く、アジアのファンが増える', cost: 1500, fee: 1200, popularity: 3, fans: 0.02, chem: 0.6, fatigue: 8, leagues: ['ASIA'] },
  { id: 'europe', name: '欧州遠征', desc: 'スペイン・ドイツ・イタリアの名門と。費用はかかるが、連携と人気が大きく伸びる', cost: 4000, fee: 1500, popularity: 5, fans: 0.03, chem: 1.2, fatigue: 12, leagues: ['ESP1', 'GER1', 'ITA1'] },
  { id: 'brazil', name: 'ブラジル遠征', desc: 'サッカー王国で腕試し。出場料がよく、技術のある相手と戦える', cost: 3000, fee: 2400, popularity: 4, fans: 0.025, chem: 0.9, fatigue: 14, leagues: ['BRA1'] },
]

/** 遠征に行けるか（プレシーズンの第 0〜2 週・今季まだ・合宿の最中でない） */
export function canTour(state: GameState): boolean {
  if (state.mode === 'career' || state.week > 2) return false
  const me = state.clubs[state.playerClubId]
  if (me.tour?.season === state.season) return false
  const now = absWeekOf(state.season, state.week)
  if (me.camp && now >= me.camp.startAbsWeek && now < me.camp.startAbsWeek + me.camp.weeks) return false
  return true
}

export interface TourResult {
  tour: TourId
  season: number
  games: { opp: number; gf: number; ga: number }[]
}

/** 遠征に行く（その週のうちに 2 試合して帰ってくる） */
export function goOnTour(state: GameState, id: TourId): TourResult | null {
  const def = TOURS.find((t) => t.id === id)
  const me = state.clubs[state.playerClubId]
  if (!def || !canTour(state) || me.budget < def.cost) return null
  const rng = createRng(hashSeed(state.seed, state.season, 0x70e))
  const absWeek = absWeekOf(state.season, state.week)
  // 相手: そのリーグの中位くらいのクラブ（違うクラブを 2 つ）
  const pool = state.clubs.filter((c) => def.leagues.includes(c.leagueId)).sort((a, b) => b.rep - a.rep)
  const mid = pool.slice(Math.floor(pool.length * 0.2), Math.max(Math.floor(pool.length * 0.2) + 2, Math.floor(pool.length * 0.8)))
  const opps = rng.shuffle([...(mid.length >= 2 ? mid : pool)]).slice(0, 2)
  const games: TourResult['games'] = []
  opps.forEach((opp, i) => {
    const setup = buildMatchSetup(state, -(absWeek * 10 + i + 1), opp.id, me.id, { neutral: false })
    const s = fastSim(setup, createRng(hashSeed(state.seed, absWeek, 0x70e0 + i)), opp.leagueId)
    games.push({ opp: opp.id, gf: s.score[1], ga: s.score[0] })
  })
  const wins = games.filter((g) => g.gf > g.ga).length
  // お金・人気・サポーター
  const net = def.fee - def.cost
  me.budget += net
  const last = state.finance[state.finance.length - 1]
  if (last) last.other += net
  me.popularity = Math.min(100, me.popularity + def.popularity + wins)
  me.fans = Math.round(Math.min(fansCap(state, me), me.fans * (1 + def.fans)))
  // 連携と疲れ・やる気（勝つと上がる）
  const squad = squadOf(state, me.id)
  chemWeekly(state, squad, 0, def.chem)
  for (const p of squad) {
    p.fatigue = Math.min(100, p.fatigue + def.fatigue)
    p.morale = Math.max(0, Math.min(100, p.morale + (wins - 1) * 3))
  }
  me.tour = { season: state.season, id }
  const result = games.map((g) => `${state.clubs[g.opp].name} ${g.gf}-${g.ga}`).join('・')
  state.news.push({ absWeek, category: 'club', mine: true, text: `${def.name}から帰国（${result}）。${net >= 0 ? `出場料で ${net.toLocaleString()} 万円の黒字` : `差し引き ${(-net).toLocaleString()} 万円`}・人気 +${def.popularity + wins}。` })
  return { tour: id, season: state.season, games }
}
