/**
 * キャリアの会話シーン: 下に台詞の枠、横に話し手（女性は上半身、男性は写真、主人公は選んだ写真か自動の顔）。
 * 押して進み、最後に選択肢があれば選ぶ。見終わったら finishTalk で効果を反映し、次の会話へ。
 * 選択肢のあとの台詞は、会話が予約から外れたあとに見せる（親で持つ）。
 */
import { useState } from 'react'
import { createPortal } from 'react-dom'
import type { GameState } from '../../engine'
import { CAST_BY_ID } from '../../engine/data/career'
import { fillLine, finishTalk, getEvent, type EventOption, type TalkLineDef } from '../../engine/career/events'
import { PlayerAvatar } from '../components/PlayerAvatar'
import { usePhotoId } from '../components/usePhotoId'
import { Portrait } from '../components/Portrait'
import { useGame } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { partnerId, roleLabel } from '../../engine/career/family'
import { castPhotoId, genPhotoFor, motherPhotoId } from '../components/portraits'
import { castName } from '../../engine/career/core'
import { ageAt, currentAbsWeek } from '../../engine'
import { growthShiftHint } from '../../engine/career/growth'

/** 'partner'（結婚相手・恋人）・'mother'（ひとつ前の主人公の妻）を実際の人に読み替える。'father' はそのまま */
function who(state: GameState, s: string | undefined): string | undefined {
  if (s === 'partner') return partnerId(state)
  if (s === 'mother') return state.career?.saga?.mother ?? 'nar'
  return s
}

/** 父（ひとつ前の主人公。年齢に合わせた写真） */
/** 父（ひとつ前の主人公）の今の年齢。母の写真をこれで選ぶ */
function fatherAge(state: GameState): number | undefined {
  const fp = state.career?.saga?.father ? state.players[state.career.saga.father.playerId] : undefined
  return fp ? ageAt(currentAbsWeek(state), fp.birthAbsWeek) : undefined
}

function Father({ state }: { state: GameState }) {
  const f = state.career?.saga?.father
  const fp = f ? state.players[f.playerId] : undefined
  if (!f?.photo || !fp) return null
  const id = genPhotoFor(f.photo, ageAt(currentAbsWeek(state), fp.birthAbsWeek))
  return <Portrait id={id} kind="bust" className="anim-fade h-[12rem] w-[10rem] rounded-2xl border border-white/20 shadow-2xl" position="50% 20%" />
}

function Me({ state }: { state: GameState }) {
  const p = state.players[state.career!.playerId]
  const photo = usePhotoId(p)
  if (photo) return <Portrait id={photo} kind="bust" className="anim-fade h-[12rem] w-[10rem] rounded-2xl border border-white/20 shadow-2xl" position="50% 20%" />
  return (
    <div className="anim-fade h-[11rem] w-[11rem] overflow-hidden rounded-2xl border border-white/20 shadow-2xl">
      <PlayerAvatar seed={p.id} nation={p.nation} face={p.face} size="100%" mood="happy" />
    </div>
  )
}

function Speaker({ state, s: raw }: { state: GameState; s: string }) {
  const s = who(state, raw) ?? 'nar'
  if (s === 'nar') return null
  if (s === 'me') return <Me state={state} />
  if (s === 'father') return <Father state={state} />
  const cast = CAST_BY_ID[s]
  const photo = raw === 'mother' ? motherPhotoId(s, fatherAge(state)) : castPhotoId(s, state.career?.spouse)
  if (cast?.portrait === 'bust') return <Portrait id={photo} kind="bust" className="anim-fade h-full w-[15rem] rounded-2xl shadow-2xl" position="50% 15%" />
  return <Portrait id={photo} kind="photo" className="anim-fade h-[12rem] w-[10rem] rounded-2xl border border-white/20 shadow-2xl" />
}

interface LinesProps {
  state: GameState
  title: string
  char?: string
  lines: TalkLineDef[]
  vars?: Record<string, string>
  options?: EventOption[]
  /** 見終わった（選択肢があれば選んだもの） */
  onDone: (optionId?: string) => void
}

/** 台詞を順に見せる */
function Lines({ state, title, char, lines, vars, options, onDone }: LinesProps) {
  const [i, setI] = useState(0)
  const root = useOverlayRoot()
  if (!root || !lines.length) return null
  const atEnd = i >= lines.length - 1
  const showOptions = atEnd && !!options?.length
  const line = lines[Math.min(i, lines.length - 1)]
  const c = state.career!
  const sp = who(state, line.s) ?? 'nar'
  const speakerName = sp === 'me' ? state.players[c.playerId].short : sp === 'nar' ? '' : sp === 'father' ? `${c.saga?.father?.name ?? ''}（父）` : line.s === 'mother' ? `${c.saga?.motherName ?? castName(state, sp)}（母）` : castName(state, sp)
  const ch = who(state, char)
  const next = () => {
    if (showOptions) return
    if (!atEnd) setI(i + 1)
    else onDone()
  }
  return createPortal(
    <div className="anim-fade absolute inset-0 z-50 flex flex-col bg-gradient-to-b from-black/70 via-black/55 to-black/85" onClick={next}>
      <div className="flex items-center gap-2 px-4 pt-3">
        <span className="rounded-full bg-gold/90 px-3 py-0.5 text-[0.75rem] font-black text-[#2a1a00]">{title}</span>
        {ch && CAST_BY_ID[ch] && (
          <span className="rounded-full bg-black/70 px-2.5 py-0.5 text-[0.78rem] text-ink">
            {castName(state, ch)}（{roleLabel(state, ch)}）
          </span>
        )}
        <button
          className="btn btn-ghost btn-sm ml-auto !min-h-[2rem]"
          onClick={(e) => {
            e.stopPropagation()
            if (options?.length) setI(lines.length - 1)
            else onDone()
          }}
        >
          スキップ
        </button>
      </div>
      <div className="relative flex min-h-0 flex-1 items-end justify-center px-6">
        <Speaker key={line.s} state={state} s={line.s} />
      </div>
      <div className="safe-px safe-pb px-4 pb-3">
        <div className="panel relative min-h-[6.2rem] px-4 pb-3 pt-2">
          {speakerName && <div className="mb-1 text-[0.8rem] font-black text-gold">{speakerName}</div>}
          <div className={`text-[0.98rem] leading-relaxed ${line.s === 'nar' ? 'italic text-ink-dim' : ''}`}>{fillLine(state, line.t, vars)}</div>
          {!showOptions && <div className="absolute bottom-1.5 right-3 animate-pulse text-[0.76rem] text-ink-dim">▼</div>}
          {showOptions && (
            <div className="mt-2 grid gap-2" style={{ gridTemplateColumns: `repeat(${options!.length}, minmax(0, 1fr))` }}>
              {options!.map((o) => (
                <button
                  key={o.id}
                  className="btn btn-blue !min-h-[2.6rem] !whitespace-normal text-[0.85rem] leading-tight"
                  onClick={(e) => {
                    e.stopPropagation()
                    onDone(o.id)
                  }}
                >
                  <span>
                    {o.label}
                    {o.effect.growthShift ? <span className="block text-[0.72rem] font-bold opacity-80">{growthShiftHint(state, o.effect.growthShift) ?? 'タイプはこれ以上変わらない'}</span> : null}
                  </span>
                </button>
              ))}
            </div>
          )}
        </div>
      </div>
    </div>,
    root,
  )
}

/** 予約された会話の先頭を見せる（なければ何も出さない） */
export function TalkScene({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const [after, setAfter] = useState<{ title: string; char?: string; lines: TalkLineDef[]; vars?: Record<string, string> } | null>(null)
  if (after) return <Lines key="after" state={state} title={after.title} char={after.char} lines={after.lines} vars={after.vars} onDone={() => setAfter(null)} />
  const c = state.career
  const talk = c?.talks[0]
  if (!c || !talk) return null
  const ev = getEvent(talk.eventId)
  const finish = (optionId?: string) => {
    let rest: TalkLineDef[] = []
    mutate((st) => {
      rest = finishTalk(st, optionId)
    })
    if (rest.length && ev) setAfter({ title: ev.title, char: ev.char, lines: rest, vars: talk.vars })
  }
  // データが見つからない会話は飛ばす
  if (!ev) return <Lines key={`missing-${c.talks.length}`} state={state} title="" lines={[{ s: 'nar', t: '……' }]} onDone={() => finish()} />
  return <Lines key={`${talk.eventId}-${c.talks.length}-${Object.keys(c.done).length}`} state={state} title={ev.title} char={ev.char} lines={ev.lines} vars={talk.vars} options={ev.options} onDone={finish} />
}
