/**
 * 入団会見（M16、クラブモード）: 大型補強のあとに出る。背番号を選び、選手の一言と記者の質問。
 * どの画面でも出るように App に置く（交渉が終わった移籍の画面の上にも出る）。#overlay-root に描く。
 */
import { useState } from 'react'
import { createPortal } from 'react-dom'
import { finishPress, freeNumbers, PRESS_LINES } from '../../engine/club/press'
import { ovr } from '../../engine/player/overall'
import { POSITION_DEFS } from '../../engine/data/positions'
import { useGame } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { PlayerFace } from '../components/PersonFace'
import { formatMoney } from '../format'
import { sound } from '../audio/sound'

export function PressConference() {
  const state = useGame((s) => s.state)
  useGame((s) => s.version)
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const item = state?.mode === 'club' ? state.press?.[0] : undefined
  const p = item ? state!.players[item.playerId] : undefined
  const [num, setNum] = useState<number | null>(null)
  if (!root || !state || !item || !p) return null
  const me = state.clubs[state.playerClubId]
  const nums = freeNumbers(state, p)
  const chosen = num ?? p.number
  const close = () => {
    sound.play('notify')
    mutate((st) => void finishPress(st, chosen))
    setNum(null)
  }
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[55] flex items-center justify-center bg-[#050b14]/88 p-3">
      <div className="panel panel-solid anim-rise flex max-h-full w-[44rem] max-w-full gap-4 p-4">
        <div className="scroll-y flex w-[13rem] shrink-0 flex-col items-center text-center">
          <div className="text-[0.76rem] font-bold tracking-widest text-gold">入団会見</div>
          <PlayerFace p={p} kit={me.colors} className="mt-1 h-[7.5rem] w-[7.5rem]" photo />
          <div className="mt-1.5 text-[1.05rem] font-black">{p.name}</div>
          <div className="text-[0.78rem] text-ink-dim">
            {POSITION_DEFS[p.pos].name}・総合 {ovr(p)}
          </div>
          {item.fee > 0 && <div className="num text-[0.78rem] text-gold">移籍金 {formatMoney(item.fee)}</div>}
          <div className="num mt-2 flex h-14 w-14 items-center justify-center rounded-xl text-[1.6rem] font-black" style={{ background: me.colors.primary, color: me.colors.secondary }}>
            {chosen}
          </div>
        </div>
        <div className="flex min-h-0 min-w-0 flex-1 flex-col gap-2 text-[0.8rem]">
          <div className="scroll-y min-h-0 flex-1 space-y-2">
            <div className="rounded-lg bg-white/[0.05] px-2.5 py-1.5">
              <span className="text-[0.72rem] text-ink-dim">記者</span>
              <br />
              {me.name}を選んだ理由と、サポーターへひと言お願いします。
            </div>
            <div className="rounded-lg bg-gold/10 px-2.5 py-1.5">
              <span className="text-[0.72rem] text-ink-dim">{p.short}</span>
              <br />
              {PRESS_LINES[p.personality]}
            </div>
            <div className="text-[0.76rem] font-bold text-ink-dim">背番号を選ぶ</div>
            <div className="flex flex-wrap gap-1">
              {nums.map((n) => (
                <button key={n} className={`num h-9 w-11 rounded-lg text-[0.9rem] font-black ${n === chosen ? 'bg-gold text-[#2a1a00]' : 'bg-white/[0.06]'}`} onClick={() => setNum(n)}>
                  {n}
                </button>
              ))}
            </div>
          </div>
          <button className="btn btn-gold w-full shrink-0" onClick={close}>
            会見を終える
          </button>
        </div>
      </div>
    </div>,
    root,
  )
}
