/** キャリア: オファー・シーズンごとの成績・契約（移籍の志願）。 */
import { useState } from 'react'
import { SQUAD_ROLE_LABEL, ovr, seasonLabel, type GameState } from '../../engine'
import { seasonRating } from '../../engine/career/offers'
import { careerStatus, STATUS_LABEL } from '../../engine/career/manager'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Emblem } from '../components/ClubArt'
import { OfferCard } from '../career/OfferCard'
import { useGame, useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { formatMoney, formatMoneyShort } from '../format'
import { exportLegend } from '../career/legends'
import { RankLadder } from '../career/RankBadge'
import { myRank, RANKS } from '../../engine/career/rank'
import { LineageTree } from '../career/Lineage'
import { FORCED_RETIRE_AGE, canCancelRetirement, canPlanRetirement, cancelRetirement, planRetirement } from '../../engine/career/retire'
import { careerAge } from '../../engine/career/core'
import { ConfirmDialog } from '../components/ConfirmDialog'

type Tab = 'offers' | 'log' | 'contract' | 'family'

function OffersTab({ state, back }: { state: GameState; back: boolean }) {
  const c = state.career!
  const pop = useUi((s) => s.pop)
  // ホームの知らせから開いたときは、受けたら（断ったときはオファーが残っていなければ）ホームへ戻る
  const done = (accepted: boolean) => {
    if (back && (accepted || !useGame.getState().state?.career?.offers.length)) pop()
  }
  return (
    <div className="panel scroll-y min-h-0 flex-1 space-y-2 p-3">
      {c.offers.length === 0 && (
        <div className="text-[0.82rem] text-ink-dim">
          いまはオファーがありません。移籍期間（8 月・1 月）に、活躍と知名度に合ったクラブから届きます。契約の最終年には、更改の話とフリー移籍の話も来ます。
        </div>
      )}
      {c.offers.map((o) => (
        <OfferCard key={o.id} state={state} o={o} onDone={done} />
      ))}
    </div>
  )
}

function LogTab({ state }: { state: GameState }) {
  const c = state.career!
  const p = state.players[c.playerId]
  const rows = [...c.log]
  const cur = { season: state.season, clubId: p.clubId, apps: p.stats.apps, goals: p.stats.goals, assists: p.stats.assists, rating: Math.round(seasonRating(state) * 100) / 100, ovr: ovr(p), wage: p.contract.wage, titles: [] as string[], rank: undefined as number | undefined }
  const total = rows.reduce((s, r) => ({ apps: s.apps + r.apps, goals: s.goals + r.goals, assists: s.assists + r.assists }), { apps: cur.apps, goals: cur.goals, assists: cur.assists })
  const titles = rows.flatMap((r) => r.titles)
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y min-w-0 flex-1 p-2.5">
        <div className="grid grid-cols-[4.2rem_1fr_2.4rem_2.4rem_2.4rem_2.6rem_2.2rem_4rem] gap-x-1.5 border-b border-line/40 pb-1 text-[0.72rem] text-ink-dim">
          <span>シーズン</span>
          <span>クラブ</span>
          <span className="text-right">出場</span>
          <span className="text-right">得点</span>
          <span className="text-right">アシ</span>
          <span className="text-right">評価</span>
          <span className="text-right">総合</span>
          <span className="text-right">年俸</span>
        </div>
        {[...rows, cur].map((r, i) => {
          const club = r.clubId >= 0 ? state.clubs[r.clubId] : undefined
          const live = i === rows.length
          return (
            <div key={i} className={`grid grid-cols-[4.2rem_1fr_2.4rem_2.4rem_2.4rem_2.6rem_2.2rem_4rem] items-center gap-x-1.5 border-b border-line/20 py-1 text-[0.74rem] ${live ? 'bg-gold/5' : ''}`}>
              <span className="num text-[0.72rem] text-ink-dim">
                {live ? '今季' : seasonLabel(state.startYear, r.season)}
              </span>
              <span className="flex min-w-0 items-center gap-1">
                {club && <Emblem id={`cl-${i}`} emblem={club.emblem} colors={club.colors} size="1rem" />}
                <span className="truncate font-bold">{club?.short ?? '―'}</span>
                {(() => {
                  const rk = live ? myRank(state) : r.rank !== undefined ? RANKS[r.rank] : undefined
                  return rk ? <span className="shrink-0 text-[0.68rem] font-black text-ink-dim">{rk.grade}</span> : null
                })()}
                {r.titles.length > 0 && <span className="shrink-0 text-[0.7rem] text-gold">★{r.titles.length}</span>}
              </span>
              <span className="num text-right">{r.apps}</span>
              <span className="num text-right font-bold">{r.goals}</span>
              <span className="num text-right">{r.assists}</span>
              <span className="num text-right">{r.apps ? r.rating.toFixed(2) : '―'}</span>
              <span className="num text-right">{r.ovr}</span>
              <span className="num text-right text-[0.74rem]">{formatMoneyShort(r.wage)}</span>
            </div>
          )
        })}
      </div>
      <div className="panel scroll-y w-[32%] shrink-0 p-3 text-[0.8rem]">
        <div className="panel-head mb-1">ステップアップ</div>
        <RankLadder state={state} />
        <div className="panel-head mb-1 mt-2">通算</div>
        <div className="num grid grid-cols-3 gap-1 text-center">
          {[
            ['出場', total.apps],
            ['得点', total.goals],
            ['アシスト', total.assists],
          ].map(([k, v]) => (
            <div key={k} className="rounded-lg bg-black/25 py-1">
              <div className="text-[0.68rem] text-ink-dim">{k}</div>
              <div className="text-[1rem] font-black">{v}</div>
            </div>
          ))}
        </div>
        <div className="panel-head mb-1 mt-2">タイトル・表彰</div>
        {titles.length === 0 && <div className="text-[0.75rem] text-ink-dim">まだありません</div>}
        {titles.map((t, i) => (
          <div key={i} className="text-[0.76rem] font-bold text-gold">
            ★ {t}
          </div>
        ))}
        {p.intl && p.intl.caps > 0 && (
          <>
            <div className="panel-head mb-1 mt-2">日本代表</div>
            <div className="num">
              {p.intl.caps} 試合 {p.intl.goals} 得点{p.intl.wc ? `・W杯 ${p.intl.wc} 回` : ''}
            </div>
          </>
        )}
      </div>
    </div>
  )
}

function ContractTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const [askRetire, setAskRetire] = useState(false)
  const c = state.career!
  const age = careerAge(state)
  const p = state.players[c.playerId]
  const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel w-[48%] shrink-0 space-y-1.5 p-3 text-[0.82rem]">
        <div className="panel-head">契約</div>
        {club ? (
          <>
            <div className="flex items-center gap-2">
              <Emblem id="ct-club" emblem={club.emblem} colors={club.colors} size="2rem" />
              <span className="text-[0.95rem] font-black">{club.name}</span>
            </div>
            <div className="num grid grid-cols-2 gap-y-1">
              <span className="text-ink-dim">年俸</span>
              <span className="font-bold">{formatMoney(p.contract.wage)}</span>
              <span className="text-ink-dim">契約</span>
              <span className="font-bold">{seasonLabel(state.startYear, p.contract.until)} シーズンまで</span>
              <span className="text-ink-dim">約束された立場</span>
              <span className="font-bold">{SQUAD_ROLE_LABEL[p.contract.role ?? 'rotation']}</span>
              <span className="text-ink-dim">いまの立場</span>
              <span className="font-bold">{STATUS_LABEL[careerStatus(state)]}</span>
              <span className="text-ink-dim">貯金</span>
              <span className="font-bold text-gold">{formatMoney(c.money)}</span>
            </div>
          </>
        ) : (
          <div className="text-ink-dim">まだどこにも所属していません</div>
        )}
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-2 p-3 text-[0.8rem]">
        <div className="panel-head">移籍の志願</div>
        <p className="text-[0.74rem] text-ink-dim">出番が少ないときや、上のステージに挑みたいときは、代理人を通して移籍を志願できます。志願中はオファーが届きやすくなりますが、監督の評価が少し下がります。</p>
        <button
          className={`btn w-full ${c.wantsMove ? 'btn-ghost' : 'btn-blue'}`}
          disabled={!club}
          onClick={() =>
            mutate((st) => {
              const cc = st.career!
              cc.wantsMove = !cc.wantsMove
              if (cc.wantsMove) cc.trust = Math.max(0, cc.trust - 5)
            })
          }
        >
          {c.wantsMove ? '志願を取り下げる' : '移籍を志願する'}
        </button>
        {c.wantsMove && <div className="text-[0.78rem] font-bold text-accent">移籍を志願中です（シーズン末まで）</div>}
        <div className="panel-head pt-2">引退</div>
        {c.retirePlanned ? (
          <>
            <div className="rounded-lg bg-gold/10 px-2.5 py-1.5 text-[0.8rem] font-bold text-gold">今季限りで引退します（シーズン最後のリーグ戦がラストゲーム）</div>
            {canCancelRetirement(state) ? (
              <button className="btn btn-ghost w-full" onClick={() => mutate((st) => void cancelRetirement(st))}>
                引退を取り消す（来季も続ける）
              </button>
            ) : (
              <div className="text-[0.74rem] text-ink-dim">{FORCED_RETIRE_AGE} 歳なので、今季が最後のシーズンです。</div>
            )}
          </>
        ) : (
          <>
            <p className="text-[0.74rem] text-ink-dim">何歳でも、今季限りで引退すると決められます（シーズンが終わるまでは取り消せます）。</p>
            <button className="btn btn-ghost w-full" disabled={!canPlanRetirement(state)} onClick={() => setAskRetire(true)}>
              今季限りで引退する
            </button>
          </>
        )}
        <ConfirmDialog
          open={askRetire}
          title="今季限りで引退しますか？"
          text={`${age} 歳。シーズン最後のリーグ戦がラストゲームになり、シーズンが終わると引退します。シーズンが終わるまでは取り消せます。`}
          ok="引退すると決める"
          onOk={() => {
            mutate((st) => void planRetirement(st))
            setAskRetire(false)
          }}
          onCancel={() => setAskRetire(false)}
        />
        <div className="panel-head pt-2">クラブモードへ連れていく</div>
        <p className="text-[0.78rem] text-ink-dim">今の能力のまま、クラブモードにフリーの選手として登場させられます（クラブ画面のスタッフの「キャリアの OB」から呼べます）。引退したあとに書き出すと、監督・コーチの候補になります。</p>
        <button
          className="btn btn-ghost w-full"
          onClick={() => {
            exportLegend(state)
            mutate((st) => void (st.career!.exported = true))
          }}
        >
          {c.exported ? '書き出し済み（もう一度書き出して更新）' : 'クラブモードへ書き出す'}
        </button>
      </div>
    </div>
  )
}

export function CareerScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const [tab, setTab] = useState<Tab>((screen.params?.tab as Tab | undefined) ?? 'offers')
  const n = state.career!.offers.length
  return (
    <AppShell title="キャリア" current="career" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className="seg shrink-0 self-start">
          {(
            [
              ['offers', `オファー${n ? `（${n}）` : ''}`],
              ['log', '成績'],
              ['contract', '契約・引退'],
              ...((state.career!.lineage ?? []).length ? [['family', '一族']] : []),
            ] as [Tab, string][]
          ).map(([id, label]) => (
            <button key={id} aria-selected={tab === id} onClick={() => setTab(id)}>
              {label}
            </button>
          ))}
        </div>
        {tab === 'offers' && <OffersTab state={state} back={!!screen.params?.back} />}
        {tab === 'log' && <LogTab state={state} />}
        {tab === 'contract' && <ContractTab state={state} />}
        {tab === 'family' && (
          <div className="panel min-h-0 flex-1 p-3">
            <div className="panel-head mb-1">一族の記録</div>
            <LineageTree state={state} />
          </div>
        )}
      </div>
    </AppShell>
  )
}
