/** 選手の詳細（能力・適性・特殊能力・契約・成績）。 */
import {
  ATTRS,
  GROUP_LABEL,
  GROWTH_DEFS,
  NATION_NAME,
  PERSONALITY_DEFS,
  POSITIONS,
  SKILL_BY_ID,
  SUMMARY_KEYS,
  SUMMARY_LABEL,
  ageOf,
  weightOf,
  aptMark,
  currentAbsWeek,
  gkSummaryOf,
  marketValue,
  ovr,
  potentialOvr,
  summaryOf,
  type AttrGroup,
  type Player,
  type Position,
} from '../../engine'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { ConditionArrow, EstOvr, Flag, OvrBadge, PosBadge, RankChip, StatBar, Stars } from '../components/common'
import { compareWithStarter, strengthsOf } from '../../engine/player/profile'
import { PlayerFace } from '../components/PersonFace'
import { RadarChart } from '../components/RadarChart'
import { Emblem } from '../components/ClubArt'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen } from '../../stores/uiStore'
import { attrColor, formatMoney } from '../format'
import { useState } from 'react'
import { estimate } from '../../engine/scout/knowledge'
import { loanOut, releaseCost, releasePlayer, windowOpen } from '../../engine/transfer/market'
import { NegotiationSheet } from '../transfer/NegotiationSheet'
import { SideSheet } from '../layout/SideSheet'
import { GrowthChart } from '../career/GrowthChart'
import { projectPlayer } from '../../engine/player/projection'
import { projectGrowth } from '../../engine/career/projection'
import { useGame } from '../../stores/gameStore'
import { MeetingSheet } from '../club/MeetingSheet'
import { meetingWait } from '../../engine/club/meeting'
import { signability, talkBlocker } from '../../engine/transfer/talks'
import { upgradeOf, weakSpots } from '../../engine/transfer/recommend'
import { SignChip, UpgradeChip } from '../transfer/TalkParts'

/** ミニピッチ上の各ポジションの位置（横向き: 左が自陣） */
const APT_SPOTS: Record<Position, [number, number]> = {
  GK: [7, 50],
  CB: [24, 50],
  SB: [28, 15],
  WB: [44, 12],
  DM: [40, 50],
  CM: [54, 50],
  SM: [57, 15],
  AM: [69, 50],
  WG: [77, 18],
  ST: [88, 50],
}

function AptitudePitch({ p }: { p: Player }) {
  return (
    <svg viewBox="0 0 100 64" className="w-full" aria-label="ポジション適性">
      <rect x="0" y="0" width="100" height="64" rx="3" fill="#145c35" />
      <g fill="none" stroke="#ffffff" strokeOpacity="0.35" strokeWidth="0.6">
        <rect x="2" y="2" width="96" height="60" />
        <line x1="50" y1="2" x2="50" y2="62" />
        <circle cx="50" cy="32" r="8" />
        <rect x="2" y="17" width="13" height="30" />
        <rect x="85" y="17" width="13" height="30" />
      </g>
      {POSITIONS.map((pos) => {
        const [x, y] = APT_SPOTS[pos]
        const v = p.apt[pos]
        const mark = aptMark(v)
        const fill = mark === '◎' ? '#f5c542' : mark === '○' ? '#3ddc84' : mark === '△' ? '#7dd3fc' : '#475569'
        const yy = (y / 100) * 64
        return (
          <g key={pos} opacity={mark === '×' ? 0.55 : 1}>
            <rect x={x - 6} y={yy - 4.5} width="12" height="9" rx="2" fill={fill} />
            <text x={x} y={yy + 0.4} textAnchor="middle" dominantBaseline="middle" fontSize="4.2" fontWeight="900" fill="#0b1320">
              {pos}
            </text>
            {(pos === 'SB' || pos === 'WB' || pos === 'SM' || pos === 'WG') && (
              <>
                <rect x={x - 6} y={64 - yy - 4.5} width="12" height="9" rx="2" fill={fill} />
                <text x={x} y={64 - yy + 0.4} textAnchor="middle" dominantBaseline="middle" fontSize="4.2" fontWeight="900" fill="#0b1320">
                  {pos}
                </text>
              </>
            )}
          </g>
        )
      })}
    </svg>
  )
}

const GROUP_ORDER: AttrGroup[] = ['tech', 'body', 'mind', 'def', 'gk']

export function PlayerScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const mutate = useGame((s) => s.mutate)
  const [nego, setNego] = useState<'buy' | 'renew' | null>(null)
  const [confirm, setConfirm] = useState<'release' | null>(null)
  const [curve, setCurve] = useState(false)
  const [meeting, setMeeting] = useState(false)
  const p = state.players[screen.params?.id as number]
  if (!p) return null
  const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
  const now = currentAbsWeek(state)
  const mine = p.clubId === state.playerClubId
  // 他クラブの選手は推定値（スカウトの知識に応じた誤差）
  const est = estimate(state, p)
  const shown = mine ? p.attr : est.attr
  const o = ovr(p)
  const isGk = p.pos === 'GK'
  const sum = isGk ? gkSummaryOf(shown) : summaryOf(shown)
  const sumCap = isGk ? gkSummaryOf(p.cap) : summaryOf(p.cap)
  const potStars = (est.potLo + est.potHi) / 2
  // 霧の段階: exact=自クラブか完全に把握 / rough=推定値 / unknown=ほぼ知らない
  const fog = mine || est.k >= 100 ? 'exact' : est.k >= 20 ? 'rough' : 'unknown'
  // 獲得の見込みと、弱点を埋めるか（M20。クラブモードの他クラブの選手）
  const sign = !mine && !state.career && !p.retired ? signability(state, p) : null
  const up = sign ? upgradeOf(state, p, weakSpots(state), est) : null
  // GK は GK の能力から（シュートなどは参考）
  const groups: AttrGroup[] = isGk ? ['gk', 'body', 'mind', 'def', 'tech'] : GROUP_ORDER.filter((g) => g !== 'gk')
  // 能力の見方（M21）: 推定の誤差・得意と苦手・うちの先発との比べ
  const err = fog === 'exact' ? 0 : Math.round((1 - est.k / 100) * 7)
  const profile = strengthsOf(shown, p.pos)
  const vsStarter = state.mode === 'club' ? compareWithStarter(state, p, shown) : null
  void potentialOvr

  return (
    <AppShell title={p.name} current="squad" back right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        {/* 左: 顔と基本情報 */}
        <div className="panel scroll-y flex w-[27%] shrink-0 flex-col p-3">
          <div className="relative">
            <PlayerFace p={p} kit={club?.colors} photo={!!(p.starId || p.face?.photo)} className={p.starId || p.face?.photo ? 'aspect-[3/2] w-full rounded-lg' : 'mx-auto h-24 w-24'} />
            <div className="absolute -bottom-2 right-1">
              {mine || est.k >= 100 ? <OvrBadge value={o} size="lg" /> : fog === 'unknown' ? <span className="num rounded-xl bg-[#0b1320]/90 px-2 py-1 text-[1.1rem] font-black text-ink-mute">??</span> : <EstOvr lo={est.ovrLo} hi={est.ovrHi} size="lg" />}
            </div>
          </div>
          <div className="mt-2 flex items-center gap-1.5">
            <span className="num text-[1.1rem] font-black text-ink-dim">{p.number}</span>
            <PosBadge pos={p.pos} />
            <Flag nation={p.nation} />
            <span className="text-[0.78rem] text-ink-dim">{NATION_NAME[p.nation]}</span>
          </div>
          <div className="mt-1 text-[1.05rem] font-black leading-tight">
            {p.name}
            {p.homegrown !== undefined && p.homegrown === p.clubId && state.mode === 'club' && <span className="ml-1.5 rounded bg-good/20 px-1.5 align-middle text-[0.68rem] font-bold text-good">生え抜き</span>}
          </div>
          {p.origin && p.clubId === state.playerClubId && state.mode === 'club' && (
            <div className="mt-0.5 truncate text-[0.7rem] text-ink-dim">
              出身 {p.origin}
              {p.study && now < p.study.untilAbsWeek && <span className="ml-1 font-bold text-accent">（{NATION_NAME[p.study.nation]}に留学中）</span>}
            </div>
          )}
          <div className="mt-1.5 grid grid-cols-2 gap-x-2 gap-y-1 text-[0.75rem]">
            <span className="text-ink-dim">年齢</span>
            <span className="num font-bold">{ageOf(p, now)}歳</span>
            <span className="text-ink-dim">身長</span>
            <span className="num font-bold">
              {p.heightCm}cm・{weightOf(p)}kg
            </span>
            <span className="text-ink-dim">利き足</span>
            <span className="font-bold">{p.foot === 'R' ? '右' : p.foot === 'L' ? '左' : '両足'}</span>
            <span className="text-ink-dim">性格</span>
            <span className="font-bold">{PERSONALITY_DEFS[p.personality].name}</span>
            <span className="text-ink-dim">成長</span>
            <span className="font-bold">{GROWTH_DEFS[p.growth].name}</span>
            <span className="text-ink-dim">調子</span>
            <span className="flex items-center gap-1 font-bold">
              <ConditionArrow value={p.condition} />
            </span>
            {p.intl && p.intl.caps > 0 && (
              <>
                <span className="text-ink-dim">代表</span>
                <span className="num font-bold text-accent">
                  {p.intl.caps}試合 {p.intl.goals}点{p.intl.wc > 0 ? `・W杯${p.intl.wc}回` : ''}
                </span>
              </>
            )}
          </div>
          <div className="mt-2 flex items-center justify-between rounded-lg bg-black/25 px-2 py-1.5">
            <span className="text-[0.78rem] text-ink-dim">将来性</span>
            {mine || est.potLo === est.potHi ? <Stars value={potStars} /> : <span className="text-[0.75rem] text-gold">★{est.potLo}〜{est.potHi}</span>}
          </div>
          {(mine || est.k >= 100) && !p.retired && (
            <button className="btn btn-ghost btn-sm mt-1.5 w-full !text-[0.78rem]" onClick={() => setCurve(true)}>
              成長の見込み ▸
            </button>
          )}
          {club && (
            <div className="mt-2 flex items-center gap-2 text-[0.75rem]">
              <Emblem id={`pc-${club.id}`} emblem={club.emblem} colors={club.colors} size="1.6rem" />
              <span className="truncate font-bold">{club.name}</span>
            </div>
          )}
          {!mine && (
            <div className="mt-2">
              <div className="flex items-center justify-between text-[0.72rem] text-ink-dim">
                <span>スカウトの情報</span>
                <span className="num">{Math.round(est.k)}%</span>
              </div>
              <div className="mt-0.5 h-1.5 overflow-hidden rounded-full bg-black/40">
                <div className="h-full rounded-full bg-accent" style={{ width: `${est.k}%` }} />
              </div>
            </div>
          )}
          <div className={`mt-auto grid grid-cols-2 gap-1.5 pt-2 ${state.career ? 'hidden' : ''}`}>
            {mine ? (
              <>
                <button className="btn btn-gold btn-sm col-span-2" onClick={() => setMeeting(true)}>
                  面談する{meetingWait(state, p) > 0 ? `（あと ${meetingWait(state, p)} 週）` : ''}
                </button>
                <button className="btn btn-blue btn-sm" onClick={() => setNego('renew')}>
                  契約更新
                </button>
                {p.id in state.forSale ? (
                  <button className="btn btn-ghost btn-sm" onClick={() => mutate((st) => void delete st.forSale[p.id])}>
                    売却を取り下げ
                  </button>
                ) : (
                  <button className="btn btn-ghost btn-sm" onClick={() => mutate((st) => void (st.forSale[p.id] = Math.round(marketValue(st.players[p.id], now, st.season) / 100) * 100))}>
                    売りに出す
                  </button>
                )}
                <button className="btn btn-ghost btn-sm" disabled={!windowOpen(state) || !!p.loan} onClick={() => mutate((st) => void loanOut(st, st.players[p.id]))}>
                  レンタル
                </button>
                <button className="btn btn-ghost btn-sm" onClick={() => setConfirm('release')}>
                  契約解除
                </button>
              </>
            ) : (
              <>
                {sign && (
                  <div className="col-span-2 space-y-1">
                    {up && (
                      <div className="upgrade-row flex items-center gap-1.5 rounded-lg px-1.5 py-1">
                        <UpgradeChip up={up} />
                        <span className="min-w-0 truncate text-[0.68rem] text-gold">先発より +{Math.round(up.gain)}</span>
                      </div>
                    )}
                    <div className="flex items-center gap-1.5 text-[0.7rem] text-ink-dim">
                      <SignChip s={sign} />
                      <span className="min-w-0 truncate">{sign.canTalk ? `移籍金 ${formatMoney(sign.fee)}` : (talkBlocker(state, p, 'buy') ?? '')}</span>
                    </div>
                  </div>
                )}
                <button className="btn btn-gold btn-sm" disabled={sign ? !sign.canTalk && sign.status !== 'refuse' : p.clubId >= 0 && !windowOpen(state)} onClick={() => setNego('buy')}>
                  {sign?.status === 'talking' ? '交渉の続き' : '獲得交渉'}
                </button>
                <button
                  className="btn btn-ghost btn-sm"
                  onClick={() =>
                    mutate((st) => {
                      st.scout.watch = st.scout.watch.includes(p.id) ? st.scout.watch.filter((x) => x !== p.id) : [...st.scout.watch, p.id]
                    })
                  }
                >
                  {state.scout.watch.includes(p.id) ? '★ 注目中' : '☆ 注目'}
                </button>
              </>
            )}
          </div>
          {confirm === 'release' && (
            <div className="mt-1.5 rounded-lg bg-bad/15 p-2 text-[0.78rem]">
              違約金 {formatMoney(releaseCost(state, p))} を払って契約を解除しますか？
              <div className="mt-1 flex gap-1">
                <button className="btn btn-sm flex-1 bg-bad text-white" onClick={() => mutate((st) => void releasePlayer(st, st.players[p.id]))}>
                  解除する
                </button>
                <button className="btn btn-ghost btn-sm flex-1" onClick={() => setConfirm(null)}>
                  やめる
                </button>
              </div>
            </div>
          )}
        </div>

        {/* 中: 能力 */}
        <div className="panel scroll-y min-w-0 flex-1 p-3">
          {fog !== 'exact' && (
            <div className="mb-1.5 rounded-lg bg-accent/10 px-2 py-1 text-[0.74rem] text-ink-dim">
              {fog === 'unknown' ? 'この選手の情報はほとんどありません。スカウトを派遣するか、対戦すると分かってきます。' : `スカウトの推定値です（誤差 ±${err} ほど）。ランクの「C〜B」は、そのどちらかという意味です。`}
            </div>
          )}
          {fog !== 'unknown' && (
            <div className="mb-2 space-y-1 rounded-lg bg-black/25 px-2 py-1.5 text-[0.76rem]">
              <div className="flex flex-wrap items-center gap-1">
                <span className="w-9 shrink-0 font-bold text-good">得意</span>
                {profile.strong.map((a) => (
                  <span key={a.key} className="flex items-center gap-1 rounded-md bg-white/[0.06] px-1.5 py-0.5">
                    {a.name}
                    <RankChip value={a.value} err={err} />
                  </span>
                ))}
              </div>
              <div className="flex flex-wrap items-center gap-1">
                <span className="w-9 shrink-0 font-bold text-bad">苦手</span>
                {profile.weak.map((a) => (
                  <span key={a.key} className="flex items-center gap-1 rounded-md bg-white/[0.06] px-1.5 py-0.5">
                    {a.name}
                    <RankChip value={a.value} err={err} />
                  </span>
                ))}
              </div>
              {vsStarter && (
                <div className="flex flex-wrap items-center gap-1">
                  <span className="w-9 shrink-0 font-bold text-accent">比較</span>
                  <span>
                    うちの {vsStarter.pos} の先発{state.players[vsStarter.starterId] ? `（${state.players[vsStarter.starterId].short}）` : ''}
                    <b className="num"> {Math.round(vsStarter.starterRating)}</b> → この選手{fog === 'exact' ? '' : '（推定）'}
                    <b className="num"> {Math.round(vsStarter.rating)}</b>
                  </span>
                  <span className={`num rounded px-1.5 font-black ${vsStarter.diff >= 3 ? 'bg-good/20 text-good' : vsStarter.diff <= -3 ? 'bg-bad/20 text-bad' : 'bg-white/10 text-ink-dim'}`}>
                    {vsStarter.diff >= 0 ? '+' : ''}
                    {Math.round(vsStarter.diff)}
                  </span>
                  <span className="text-ink-dim">{vsStarter.diff >= 3 ? '先発を上回る' : vsStarter.diff <= -3 ? '控えの力' : '先発と同じくらい'}</span>
                </div>
              )}
            </div>
          )}
          <div className="grid grid-cols-2 gap-x-4 gap-y-2">
            {groups.map((g) => (
              <div key={g}>
                <div className="panel-head mb-1">{GROUP_LABEL[g]}</div>
                {ATTRS.filter((a) => a.group === g).map((a) => {
                  const v = shown[a.key]
                  return (
                    <div key={a.key} className="py-[0.12rem]">
                      <div className="flex items-center gap-1.5">
                        <span className="min-w-0 flex-1 truncate text-[0.75rem] text-ink-dim">{a.name}</span>
                        {fog === 'unknown' ? (
                          <span className="num w-6 shrink-0 text-right text-[0.85rem] font-extrabold text-ink-mute">??</span>
                        ) : (
                          <>
                            <RankChip value={v} err={err} />
                            <span className={`num w-6 shrink-0 text-right text-[0.85rem] font-extrabold ${fog === 'rough' ? 'opacity-70' : ''}`} style={{ color: attrColor(v) }}>
                              {Math.round(v)}
                            </span>
                          </>
                        )}
                      </div>
                      <div className={`mt-[0.1rem] ${fog === 'rough' ? 'opacity-50' : fog === 'unknown' ? 'opacity-0' : ''}`}>
                        <StatBar value={v} />
                      </div>
                    </div>
                  )
                })}
              </div>
            ))}
          </div>
        </div>

        {/* 右: レーダー・適性・特殊能力・契約 */}
        <div className="panel scroll-y w-[28%] shrink-0 p-3">
          {fog === 'unknown' ? (
            <div className="flex aspect-square w-full max-w-[13rem] items-center justify-center text-[2.4rem] font-black text-ink-mute mx-auto">?</div>
          ) : (
          <RadarChart labels={SUMMARY_KEYS.map((k) => SUMMARY_LABEL[k])} values={SUMMARY_KEYS.map((k) => sum[k])} potential={mine ? SUMMARY_KEYS.map((k) => sumCap[k]) : undefined} className="mx-auto -my-1 w-full max-w-[13rem]" color="#f5c542" />
          )}
          <div className="panel-head mb-1 mt-1">ポジション適性</div>
          <AptitudePitch p={p} />
          <div className="panel-head mb-1 mt-2">特殊能力</div>
          <div className="flex flex-wrap gap-1">
            {fog !== 'exact' && est.k < 50 && <span className="text-[0.78rem] text-ink-mute">？？？</span>}
            {(fog === 'exact' || est.k >= 50) && p.skills.length === 0 && <span className="text-[0.78rem] text-ink-mute">なし</span>}
            {(fog === 'exact' || est.k >= 50) && p.skills.map((id) => {
              const s = SKILL_BY_ID[id]
              if (!s) return null
              const cls = s.tier === 'gold' ? 'border-gold/60 bg-gold/15 text-gold' : s.tier === 'red' ? 'border-bad/50 bg-bad/15 text-bad' : 'border-accent/50 bg-accent/15 text-accent'
              return (
                <span key={id} title={s.desc} className={`rounded-md border px-1.5 py-0.5 text-[0.76rem] font-bold ${cls}`}>
                  {s.name}
                </span>
              )
            })}
          </div>
          <div className="panel-head mb-1 mt-2">契約</div>
          <div className="grid grid-cols-2 gap-y-1 text-[0.75rem]">
            <span className="text-ink-dim">年俸</span>
            <span className="num text-right font-bold">{formatMoney(p.contract.wage)}</span>
            <span className="text-ink-dim">契約</span>
            <span className="num text-right font-bold">{p.contract.until < state.season ? 'なし' : `${state.startYear + p.contract.until + 1}年夏まで`}</span>
            <span className="text-ink-dim">市場価値</span>
            <span className="num text-right font-bold">{formatMoney(marketValue(p, now, state.season))}</span>
          </div>
          <div className="panel-head mb-1 mt-2">今季の成績</div>
          <div className="grid grid-cols-4 gap-1 text-center">
            {[
              ['出場', p.stats.apps],
              ['得点', p.stats.goals],
              ['アシスト', p.stats.assists],
              ['平均点', p.stats.apps ? (p.stats.ratingSum / p.stats.apps).toFixed(1) : '-'],
            ].map(([k, v]) => (
              <div key={k as string} className="rounded-md bg-black/25 py-1">
                <div className="text-[0.66rem] text-ink-dim">{k}</div>
                <div className="num text-[0.85rem] font-extrabold">{v}</div>
              </div>
            ))}
          </div>
        </div>
      </div>
      <NegotiationSheet key={`${p.id}-${nego}`} player={nego ? p : null} mode={nego ?? 'buy'} open={!!nego} onClose={() => setNego(null)} />
      {mine && !state.career && <MeetingSheet state={state} playerId={p.id} open={meeting} onClose={() => setMeeting(false)} />}
      <SideSheet open={curve} onClose={() => setCurve(false)} title={`${p.short}の成長の見込み`} width="70%">
        {curve && (
          <div className="p-3">
            <GrowthChart proj={state.career?.playerId === p.id ? projectGrowth(state) : projectPlayer(p, now)} type={p.growth} />
            <p className="mt-1 text-[0.72rem] text-ink-mute">成長タイプ（{GROWTH_DEFS[p.growth].name}）と伸びしろからの目安です。出場・練習・コーチ・ケガで変わります。</p>
          </div>
        )}
      </SideSheet>
    </AppShell>
  )
}
