/**
 * 見守り期のホーム（M17）: 引退した父として、15 歳になるまで息子を見守る。1 か月ごとに練習の方針を選んで進める。
 * 子どもの節目・家族の行事は会話で出る（TalkScene）。15 歳になると息子が主人公になる。
 */
import { useRef, useState } from 'react'
import type { GameState } from '../../engine'
import { becomeHeir, heirFace, heirReady, watchMonth } from '../../engine/career/saga'
import { childAge } from '../../engine/career/children'
import { careerAge, castName } from '../../engine/career/core'
import type { ExpKind } from '../../engine/models/career'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Portrait } from '../components/Portrait'
import { genPhotoFor, motherPhotoId } from '../components/portraits'
import { TalkScene } from './TalkScene'
import { useGame } from '../../stores/gameStore'
import { Icon } from '../components/Icon'

const CHOICES: { id: ExpKind | 'rest'; label: string; desc: string }[] = [
  { id: 'tech', label: 'ボール扱い', desc: '公園でいっしょにボールを蹴る（技術）' },
  { id: 'speed', label: '走り込み', desc: '朝の河川敷を走る（スピード）' },
  { id: 'power', label: '体づくり', desc: 'よく食べて、よく遊ぶ（体）' },
  { id: 'tactics', label: '試合を見て学ぶ', desc: 'プロの試合をいっしょに見る（戦術）' },
  { id: 'mental', label: '心を鍛える', desc: '負けた日の話をじっくり聞く（精神）' },
  { id: 'rest', label: 'のびのび', desc: 'サッカーのことは忘れて遊ばせる' },
]

export function WatchHome({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const c = state.career!
  const saga = c.saga!
  const heir = (c.children ?? [])[saga.heirIdx ?? 0]
  const father = state.players[c.playerId]
  const [focus, setFocus] = useState<ExpKind | 'rest'>('tech')
  // 1 年すすめる: 1 か月ずつ（1 か月で 1 秒ほどかかるので、進み具合を出す）。会話が出たら止まる
  const [left, setLeft] = useState(0)
  const running = useRef(false)
  if (!heir) return null
  const age = childAge(state, heir)
  const ready = heirReady(state)
  const busy = left > 0
  const run = async (months: number) => {
    if (running.current) return
    running.current = true
    for (let i = 0; i < months; i++) {
      setLeft(months - i)
      await new Promise((r) => setTimeout(r, 30))
      const st = useGame.getState().state
      const cc = st?.career
      if (!st || cc?.saga?.phase !== 'watch' || cc.talks.length || heirReady(st)) break
      mutate((x) => watchMonth(x, focus))
    }
    setLeft(0)
    running.current = false
  }
  const photo = genPhotoFor(heirFace(state, saga.gen + 1, father.face?.photo), age)
  return (
    <AppShell title={`${heir.name}を見守る`} current="home" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="panel flex w-[40%] shrink-0 flex-col items-center gap-2 p-3 text-center">
          <div className="text-[0.76rem] font-bold tracking-widest text-gold">次の世代</div>
          <Portrait id={photo} kind="face" className="face-round h-24 w-24" />
          <div className="text-[1.15rem] font-black">{heir.name}</div>
          <div className="text-[0.8rem] text-ink-dim">
            {age} 歳・{heir.path === 'school' ? '高校のサッカー部を目指す' : heir.path === 'clubYouth' ? 'クラブのユースを目指す' : 'サッカー少年'}
          </div>
          <div className="text-[0.9rem] text-gold">才能 {'★'.repeat(Math.max(1, heir.talent ?? 1))}</div>
          <div className="mt-auto w-full space-y-1 text-left text-[0.76rem] text-ink-dim">
            <div>父: {father.name}（引退）</div>
            {c.spouse && (
              <div className="flex items-center gap-1.5">
                <Portrait id={motherPhotoId(c.spouse, careerAge(state))} kind="face" className="face-round h-7 w-7" />母: {castName(state, c.spouse)}
              </div>
            )}
            <div>{ready ? `${heir.name}は 15 歳。ここからは${heir.name}が主人公です` : `15 歳になると、${heir.name}が主人公になります（あと ${Math.max(0, 15 - age)} 年）`}</div>
          </div>
        </div>
        <div className="flex min-w-0 flex-1 flex-col gap-2.5">
          <div className="panel p-3">
            <div className="panel-head mb-1">この 1 か月の方針</div>
            <div className="grid grid-cols-2 gap-1.5">
              {CHOICES.map((x) => (
                <button key={x.id} className={`rounded-lg px-2.5 py-1.5 text-left ${focus === x.id ? 'bg-gold/15 ring-1 ring-gold/60' : 'bg-white/[0.04]'}`} onClick={() => setFocus(x.id)}>
                  <div className="text-[0.82rem] font-bold">{x.label}</div>
                  <div className="text-[0.7rem] text-ink-dim">{x.desc}</div>
                </button>
              ))}
            </div>
          </div>
          <div className="panel flex min-h-0 flex-1 flex-col p-3">
            <div className="panel-head mb-1">最近の出来事</div>
            <div className="scroll-y min-h-0 flex-1 space-y-1 pr-1">
              {[...c.report].reverse().map((t, i) => (
                <div key={i} className={`rounded-lg px-2.5 py-1 text-[0.76rem] ${i === 0 ? 'bg-gold/10' : 'bg-black/20 text-ink-dim'}`}>
                  {t}
                </div>
              ))}
            </div>
          </div>
          <div className="flex items-center justify-end gap-2">
            {ready ? (
              <button className="btn btn-gold min-w-[13rem]" disabled={c.talks.length > 0} onClick={() => mutate((st) => becomeHeir(st))}>
                <Icon name="forward" className="h-5 w-5" />
                {heir.name}の物語へ
              </button>
            ) : (
              <>
                <button className="btn btn-ghost min-w-[8rem]" disabled={c.talks.length > 0 || busy} onClick={() => void run(12)}>
                  {busy ? `すすめています… あと ${left} か月` : '1 年すすめる'}
                </button>
                <button className="btn btn-gold min-w-[10rem]" disabled={c.talks.length > 0 || busy} onClick={() => void run(1)}>
                  <Icon name="forward" className="h-5 w-5" />1 か月すすめる
                </button>
              </>
            )}
          </div>
        </div>
      </div>
      <TalkScene state={state} />
    </AppShell>
  )
}
