/**
 * 地域（M19）: ホームタウンの様子と、4 週に 1 回の地域の活動。クラブ画面のタブ。
 */
import type { GameState } from '../../engine'
import { ACTIVITIES, TIE_STAGES, activityAvailable, activityWait, doActivity, tieStage } from '../../engine/club/community'
import { TOWN_TRAITS } from '../../engine/data/clubs'
import { useGame } from '../../stores/gameStore'
import { formatMoney } from '../format'

function Meter({ label, value, max = 100 }: { label: string; value: number; max?: number }) {
  return (
    <div className="flex items-center gap-2 text-[0.76rem]">
      <span className="w-[5.5rem] shrink-0 text-ink-dim">{label}</span>
      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-black/40">
        <div className="h-full rounded-full bg-gold" style={{ width: `${Math.min(100, (value / max) * 100)}%` }} />
      </div>
      <span className="num w-10 shrink-0 text-right font-bold">{Math.round(value * 10) / 10}</span>
    </div>
  )
}

export function CommunityTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const h = state.hometown
  const stage = tieStage(state)
  const total = state.community?.total ?? 0
  const next = TIE_STAGES[stage + 1]
  const wait = activityWait(state)
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[42%] shrink-0 space-y-2 p-3 text-[0.8rem]">
        <div className="panel-head">
          {h.pref}・{h.city}
        </div>
        {h.trait && (
          <div className="rounded-lg border border-gold/40 bg-gold/10 px-2.5 py-1">
            <b className="text-gold">{TOWN_TRAITS[h.trait].name}</b>
            <span className="ml-1 text-[0.72rem] text-ink-dim">{TOWN_TRAITS[h.trait].desc}</span>
          </div>
        )}
        <Meter label="人口（万人）" value={h.population} max={150} />
        <Meter label="地元企業" value={h.economy} />
        <Meter label="サッカー熱" value={h.passion} />
        <Meter label="街の発展度" value={h.development} />
        <div className="rounded-lg bg-black/25 px-2.5 py-2">
          <div className="text-[0.72rem] text-ink-dim">地域とのつながり</div>
          <div className="text-[1.05rem] font-black text-gold">{TIE_STAGES[stage].name}</div>
          <div className="text-[0.72rem] text-ink-dim">
            活動 {total} 回{next ? `・あと ${next.min - total} 回で「${next.name}」` : ''}・観客 +{stage}%
          </div>
        </div>
        <div className="text-[0.7rem] leading-snug text-ink-mute">発展度が 10 上がるごとに、街の人口と地元企業が育ちます。</div>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 space-y-1.5 p-3 text-[0.8rem]">
        <div className="flex items-baseline gap-2">
          <span className="panel-head">地域の活動</span>
          <span className="ml-auto text-[0.74rem] text-ink-dim">{wait > 0 ? `次は ${wait} 週後` : '4 週に 1 回'}</span>
        </div>
        {ACTIVITIES.map((a) => {
          const effects = [
            a.popularity && `人気 +${Math.max(1, Math.round(a.popularity))}`,
            a.passion && `サッカー熱 +${a.passion}`,
            a.economy && `地元企業 +${a.economy}`,
            a.development && `発展度 +${a.development}`,
            a.morale && `選手のやる気 +${a.morale}`,
            a.fans && `サポーター +${Math.round(a.fans * 100)}%`,
          ].filter(Boolean)
          return (
            <div key={a.id} className="flex items-center gap-2 rounded-lg bg-black/25 px-2.5 py-1.5">
              <div className="min-w-0 flex-1">
                <div className="font-bold">
                  {a.name}
                  <span className="num ml-1.5 text-[0.7rem] font-normal text-ink-dim">（{state.community?.count[a.id] ?? 0} 回）</span>
                </div>
                <div className="text-[0.7rem] text-ink-dim">{a.desc}</div>
                <div className="text-[0.7rem] text-good">{effects.join('・')}</div>
              </div>
              <button className="btn btn-blue btn-sm shrink-0" disabled={!activityAvailable(state, a.id)} onClick={() => mutate((st) => void doActivity(st, a.id))}>
                {a.cost ? formatMoney(a.cost) : '費用なし'}
              </button>
            </div>
          )
        })}
      </div>
    </div>
  )
}
