/** 全体ミーティング（M19）: 選手一覧の上部バー。4 週に 1 回、全員のやる気が少し上がる */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { holdTeamMeeting, teamMeetingWait } from '../../engine/club/meeting'
import { useGame } from '../../stores/gameStore'

export function TeamMeetingButton({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const [done, setDone] = useState(false)
  const wait = teamMeetingWait(state)
  return (
    <button
      className="btn btn-ghost btn-sm !min-h-[2.3rem] !text-[0.78rem]"
      disabled={wait > 0}
      onClick={() => {
        mutate((st) => void holdTeamMeeting(st))
        setDone(true)
      }}
    >
      {done ? '全員のやる気が上がった' : wait > 0 ? `全体ミーティング（あと ${wait} 週）` : '全体ミーティング'}
    </button>
  )
}
