/** ユースアカデミー（M25）: ユースの選手・海外アカデミー・海外の有望株・国際ユースカップ。 */
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen } from '../../stores/uiStore'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Icon, type IconName } from '../components/Icon'
import { useScreenState } from '../hooks/useScreenState'
import { YouthTab } from '../squad/SquadExtras'
import { AcademyTab } from '../youth/AcademyTab'
import { OverseasTab } from '../youth/OverseasTab'
import { YouthCupTab } from '../youth/YouthCupTab'
import { badgesOf } from '../layout/menu'

type Tab = 'players' | 'academy' | 'scout' | 'cup'
const TABS: [Tab, string, IconName][] = [
  ['players', 'ユースの選手', 'squad'],
  ['academy', '海外アカデミー', 'plane'],
  ['scout', '海外の有望株', 'person'],
  ['cup', '国際ユースカップ', 'trophy'],
]

export function YouthScreen() {
  const state = useGameState()
  const [tab, setTab] = useScreenState<Tab>('tab', 'players', useCurrentScreen().params?.tab as Tab | undefined)
  const badges = badgesOf(state)
  return (
    <AppShell title="ユースアカデミー" current="squad" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className="seg scroll-x shrink-0 self-start">
          {TABS.map(([id, label, icon]) => (
            <button key={id} aria-selected={tab === id} onClick={() => setTab(id)} className="relative !flex items-center gap-1">
              <Icon name={icon} className="h-4 w-4 shrink-0" />
              {label}
              {(badges[`youth:${id}`] ?? 0) > 0 && <span className="nav-badge !-right-0.5 !-top-1">{badges[`youth:${id}`]}</span>}
            </button>
          ))}
        </div>
        {tab === 'players' && (
          <div className="panel flex min-h-0 flex-1 flex-col pt-1">
            <YouthTab />
          </div>
        )}
        {tab === 'academy' && <AcademyTab state={state} />}
        {tab === 'scout' && <OverseasTab state={state} />}
        {tab === 'cup' && <YouthCupTab state={state} />}
      </div>
    </AppShell>
  )
}
