/** ホームのお知らせ（申し出への対応）と、相談ごとのモーダル。 */
import { useState } from 'react'
import { createPortal } from 'react-dom'
import { EVENT_BY_ID } from '../../engine/data/clubEvents'
import { answerRequest, fillEventText, resolveEvent } from '../../engine/club/events'
import { RENEWAL_WEEK, expiringPlayers } from '../../engine/transfer/contracts'
import { canPlanCamp } from '../../engine/growth/camp'
import { rosterInfo } from '../../engine/club/roster'
import { worldEligibility } from '../../engine/competition/worldLeague'
import { ourCupMatch } from '../../engine/club/youthCup'
import { playerClub, type GameState } from '../../engine'
import { Icon } from '../components/Icon'
import { PlayerFace, StaffFace } from '../components/PersonFace'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

function Banner({ color, icon, text, onClick }: { color: 'gold' | 'accent' | 'pink' | 'bad'; icon: Parameters<typeof Icon>[0]['name']; text: string; onClick: () => void }) {
  const cls = color === 'gold' ? 'border-gold/50 bg-gold/10 text-gold' : color === 'accent' ? 'border-accent/50 bg-accent/10 text-accent' : color === 'pink' ? 'border-pink/50 bg-pink/10 text-pink' : 'border-bad/50 bg-bad/10 text-bad'
  return (
    <button className={`anim-rise flex min-w-0 flex-1 items-center gap-2 rounded-xl border px-3 py-2 text-left text-[0.78rem] font-bold ${cls}`} onClick={onClick}>
      <Icon name={icon} className="h-5 w-5 shrink-0" />
      <span className="min-w-0 truncate">{text}</span>
    </button>
  )
}

export function OfferBanners() {
  const state = useGameState()
  const push = useUi((s) => s.push)
  const [eventId, setEventId] = useState<number | null>(null)
  const me = playerClub(state)
  const sponsors = state.offers.filter((o) => o.kind === 'sponsor').length
  const bids = state.offers.filter((o) => o.kind === 'bid').length
  const events = state.offers.filter((o) => o.kind === 'event' || o.kind === 'request')
  const expiring = state.week >= RENEWAL_WEEK ? expiringPlayers(state).length : 0
  const items: React.ReactNode[] = []
  const wle = worldEligibility(state)
  if (wle.ok && !wle.applied) items.push(<Banner key="wl" color="gold" icon="trophy" text="ワールドリーグに申請できます" onClick={() => push({ id: 'club', params: { tab: 'info' } })} />)
  const roster = rosterInfo(state)
  if (roster.over) items.push(<Banner key="ro" color="bad" icon="squad" text={`選手枠オーバー（${roster.count}/${roster.limit}）`} onClick={() => push({ id: 'squad', params: { release: 1 } })} />)
  if (events.length) items.push(<Banner key="ev" color="pink" icon="story" text={`相談ごと ${events.length} 件`} onClick={() => setEventId(events[0].id)} />)
  if (expiring) items.push(<Banner key="rn" color="bad" icon="squad" text={`契約更改 ${expiring} 人`} onClick={() => push({ id: 'squad', params: { view: 'contract' } })} />)
  if (bids) items.push(<Banner key="bd" color="gold" icon="transfer" text={`移籍オファー ${bids} 件`} onClick={() => push({ id: 'transfer', params: { tab: 'sell' } })} />)
  if (sponsors) items.push(<Banner key="sp" color="gold" icon="trophy" text={`スポンサーの申し出（${new Set(state.offers.flatMap((o) => (o.kind === 'sponsor' ? [o.slot] : []))).size} 枠）`} onClick={() => push({ id: 'club', params: { tab: 'sponsor' } })} />)
  // 海外ユース（M25）: 国際ユースカップの今週の試合（先頭）・招待・海外の有望株
  const ycNow = ourCupMatch(state)
  if (ycNow) items.unshift(<Banner key="yc" color="gold" icon="trophy" text={ycNow.round === 2 ? 'ユース杯の決勝' : 'ユース杯の試合'} onClick={() => push({ id: 'youthCup' })} />)
  if (state.youthCup?.season === state.season && state.youthCup.status === 'invited') items.push(<Banner key="yi" color="accent" icon="trophy" text="ユース杯に招待" onClick={() => push({ id: 'youth', params: { tab: 'cup' } })} />)
  const oy = state.overseasYouth
  if (oy && oy.list.every((p) => !p.applied)) items.push(<Banner key="oy" color="accent" icon="person" text={`海外の有望株 ${oy.list.length} 人`} onClick={() => push({ id: 'youth', params: { tab: 'scout' } })} />)
  if (canPlanCamp(state, me)) items.push(<Banner key="cp" color="accent" icon="whistle" text="合宿の時期です" onClick={() => push({ id: 'training' })} />)
  return (
    <>
      {items.length > 0 && <div className="flex gap-2">{items.slice(0, 3)}</div>}
      {eventId !== null && <EventModal state={state} offerId={eventId} onClose={() => setEventId(null)} />}
    </>
  )
}

function EventModal({ state, offerId, onClose }: { state: GameState; offerId: number; onClose: () => void }) {
  const mutate = useGame((s) => s.mutate)
  const [result, setResult] = useState<string | null>(null)
  const o = state.offers.find((x) => x.id === offerId)
  const root = document.getElementById('overlay-root')
  if (!root) return null
  const me = playerClub(state)
  const secretary = me.staff.map((id) => state.staff[id]).find((s) => s?.role === 'secretary')
  const owner = me.staff.map((id) => state.staff[id]).find((s) => s?.role === 'owner')
  let title = ''
  let body = ''
  let speaker: React.ReactNode = null
  let options: { label: string; run: () => string | null }[] = []
  if (o?.kind === 'event') {
    const def = EVENT_BY_ID[o.eventId]
    title = def.title
    body = fillEventText(state, def.body, o.playerId)
    const p = o.playerId !== undefined ? state.players[o.playerId] : undefined
    speaker = def.speaker === 'player' && p ? <PlayerFace p={p} kit={me.colors} className="h-20 w-20" /> : def.speaker === 'owner' && owner ? <StaffFace s={owner} className="h-20 w-20" /> : secretary ? <StaffFace s={secretary} className="h-20 w-20" /> : null
    options = def.options.map((opt, i) => ({ label: opt.label, run: () => resolveEvent(state, offerId, i) }))
  } else if (o?.kind === 'request' && o.abroad) {
    const p = state.players[o.playerId]
    const buyer = state.clubs[o.abroad.clubId]
    title = '海外挑戦の志願'
    body = `${p?.name ?? '選手'}「${buyer.name}から話が来ています。海外で挑戦させてください！」（移籍金 ${o.abroad.fee.toLocaleString()} 万円）`
    speaker = p ? <PlayerFace p={p} kit={me.colors} className="h-20 w-20" /> : null
    options = [
      { label: '送り出す', run: () => answerRequest(state, offerId, 'sell') },
      { label: '引き止める（やる気が下がる）', run: () => answerRequest(state, offerId, 'promise') },
    ]
  } else if (o?.kind === 'request') {
    const p = state.players[o.playerId]
    title = '移籍の志願'
    body = `${p?.name ?? '選手'}「社長、このままでは試合に出られません。移籍を認めてもらえませんか？」`
    speaker = p ? <PlayerFace p={p} kit={me.colors} className="h-20 w-20" /> : null
    options = [
      { label: '起用を約束して引き留める', run: () => answerRequest(state, offerId, 'promise') },
      { label: '移籍を認める（売りに出す）', run: () => answerRequest(state, offerId, 'sell') },
    ]
  }
  return createPortal(
    <div className="anim-fade absolute inset-0 z-50 flex items-end justify-center bg-black/55 p-3">
      <div className="panel anim-rise flex w-[44rem] max-w-full gap-3 p-4">
        <div className="shrink-0">{speaker}</div>
        <div className="min-w-0 flex-1">
          <div className="text-[0.8rem] font-bold text-pink">{title}</div>
          <p className="mt-1 text-[0.9rem] leading-relaxed">{result ?? (o ? body : 'この相談は終わりました。')}</p>
          <div className="mt-3 flex flex-wrap justify-end gap-2">
            {!result && o
              ? options.map((opt) => (
                  <button
                    key={opt.label}
                    className="btn btn-blue btn-sm"
                    onClick={() => {
                      let text: string | null = null
                      mutate(() => {
                        text = opt.run()
                      })
                      setResult(text ?? '')
                    }}
                  >
                    {opt.label}
                  </button>
                ))
              : (
                <button className="btn btn-gold btn-sm min-w-[8rem]" onClick={onClose}>
                  閉じる
                </button>
              )}
          </div>
        </div>
      </div>
    </div>,
    root,
  )
}
