/**
 * 有望株（M19）: 高校選手権・クラブユースで話題の 5 人。役割の約束と契約金を決めて申し込む。第 31 週に本人が決める。
 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { PROSPECT_BONUSES, PROSPECT_DEADLINE, applyProspect, chanceLabel, prospectChance, prospectEstimate } from '../../engine/club/prospects'
import { Emblem } from '../components/ClubArt'
import { PlayerFace } from '../components/PersonFace'
import { useGame } from '../../stores/gameStore'
import { formatMoney } from '../format'

export function ProspectsTab({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const [open, setOpen] = useState<number | null>(null)
  const [role, setRole] = useState<'main' | 'develop'>('develop')
  const [bonus, setBonus] = useState(0)
  const ps = state.prospects
  if (!ps)
    return (
      <div className="panel min-h-0 flex-1 p-3 text-[0.82rem] text-ink-dim">
        高校選手権とクラブユース選手権のあと（第 22 週）に、話題の有望株がここに並びます。入団の申し込みは第 {PROSPECT_DEADLINE + 1} 週まで。
      </div>
    )
  return (
    <div className="panel scroll-y min-h-0 flex-1 space-y-2 p-3 text-[0.8rem]">
      <div className="text-[0.74rem] text-ink-dim">申し込みは第 {PROSPECT_DEADLINE + 1} 週まで。地元出身の子は来てくれやすく、ほかのクラブが狙っていると難しくなります。</div>
      {ps.list.map((pr, i) => {
        const p = pr.player
        const est = prospectEstimate(state, pr)
        const local = pr.pref === state.hometown.pref
        const chance = prospectChance(state, pr, open === i ? role : (pr.applied?.role ?? 'develop'), open === i ? bonus : (pr.applied?.bonus ?? 0))
        return (
          <div key={p.id} className={`rounded-lg px-2.5 py-2 ${pr.applied ? 'bg-gold/10 ring-1 ring-gold/40' : 'bg-black/25'}`}>
            <div className="flex items-center gap-2.5">
              <PlayerFace p={p} className="h-11 w-11 shrink-0" />
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-1.5">
                  <span className="font-black">{p.name}</span>
                  <span className="rounded bg-white/10 px-1.5 text-[0.7rem] font-bold">{p.pos}</span>
                  {local && <span className="rounded bg-good/20 px-1.5 text-[0.7rem] font-bold text-good">地元出身</span>}
                </div>
                <div className="text-[0.72rem] text-ink-dim">
                  {pr.team}（{pr.source}）・{pr.pref}・18 歳
                </div>
                <div className="num text-[0.74rem]">
                  総合 {est.lo}〜{est.hi}・将来性 <span className="text-gold">{'★'.repeat(est.stars)}</span>
                </div>
              </div>
              <div className="flex shrink-0 flex-col items-end gap-1">
                <div className="flex items-center gap-1">
                  {pr.interest.map((id) => {
                    const c = state.clubs[id]
                    return <Emblem key={id} id={`pi-${p.id}-${id}`} emblem={c.emblem} colors={c.colors} size="1.2rem" />
                  })}
                  <span className="text-[0.66rem] text-ink-dim">が狙っている</span>
                </div>
                {pr.applied ? (
                  <span className="text-[0.74rem] font-bold text-gold">申し込み済み（見込み {chanceLabel(chance)}）</span>
                ) : (
                  <button
                    className="btn btn-gold btn-sm"
                    onClick={() => {
                      setOpen(open === i ? null : i)
                      setRole('develop')
                      setBonus(0)
                    }}
                  >
                    申し込む
                  </button>
                )}
              </div>
            </div>
            {open === i && !pr.applied && (
              <div className="anim-rise mt-2 space-y-1.5 border-t border-white/10 pt-2">
                <div className="flex items-center gap-2">
                  <span className="w-16 shrink-0 text-[0.74rem] text-ink-dim">約束</span>
                  <div className="seg">
                    <button aria-selected={role === 'develop'} onClick={() => setRole('develop')}>
                      じっくり育てる
                    </button>
                    <button aria-selected={role === 'main'} onClick={() => setRole('main')}>
                      主力候補
                    </button>
                  </div>
                </div>
                <div className="flex items-center gap-2">
                  <span className="w-16 shrink-0 text-[0.74rem] text-ink-dim">契約金</span>
                  <div className="seg">
                    {PROSPECT_BONUSES.map((b) => (
                      <button key={b} aria-selected={bonus === b} onClick={() => setBonus(b)}>
                        {b ? formatMoney(b) : 'なし'}
                      </button>
                    ))}
                  </div>
                  <span className="ml-auto text-[0.78rem]">
                    来てくれる見込み <b className="text-gold">{chanceLabel(chance)}</b>
                  </span>
                </div>
                <button
                  className="btn btn-gold w-full"
                  onClick={() => {
                    mutate((st) => void applyProspect(st, i, role, bonus))
                    setOpen(null)
                  }}
                >
                  この条件で申し込む（契約金は入団が決まったら払う）
                </button>
              </div>
            )}
          </div>
        )
      })}
    </div>
  )
}
