/** 宿命のライバルと、同じリーグのダービーの相手（クラブ画面の概要）。 */
import { playerClub, rankOf, type GameState } from '../../engine'
import { derbyOf } from '../../engine/club/derby'
import { Emblem } from '../components/ClubArt'

export function RivalPanel({ state }: { state: GameState }) {
  const me = playerClub(state)
  const r = state.rival
  const league = state.competitions.find((c) => c.id === me.leagueId)
  const rival = r ? state.clubs[r.clubId] : undefined
  const derbies = (league?.clubIds ?? [])
    .filter((id) => id !== me.id)
    .map((id) => ({ id, d: derbyOf(state, me.id, id) }))
    .filter((x) => x.d && !x.d.rival)
    .sort((a, b) => b.d!.intensity - a.d!.intensity)
  return (
    <div>
      <div className="panel-head mb-1">宿命のライバル</div>
      {rival && r ? (
        <div className="flex items-center gap-2 rounded-lg bg-bad/10 px-2 py-1.5 ring-1 ring-bad/30">
          <Emblem id={`rv-${rival.id}`} emblem={rival.emblem} colors={rival.colors} size="1.8rem" />
          <div className="min-w-0 flex-1">
            <div className="truncate text-[0.85rem] font-black">{rival.name}</div>
            <div className="text-[0.72rem] text-ink-dim">{league && league.clubIds.includes(rival.id) ? `${league.short} ${Math.max(1, rankOf(league, rival.id))} 位` : '別のリーグ'}</div>
          </div>
          <div className="text-right">
            <div className="text-[0.68rem] text-ink-dim">対戦成績</div>
            <div className="num text-[0.8rem] font-bold">
              {r.w}勝{r.d}分{r.l}敗
            </div>
          </div>
        </div>
      ) : (
        <div className="text-[0.75rem] text-ink-dim">まだいません</div>
      )}
      {derbies.length > 0 && (
        <div className="mt-1.5 flex flex-wrap gap-1">
          {derbies.map(({ id, d }) => (
            <span key={id} className={`rounded px-1.5 py-0.5 text-[0.7rem] ${d!.intensity >= 1 ? 'bg-accent/20 font-bold text-accent' : 'bg-white/[0.06] text-ink-dim'}`}>
              {d!.name}: {state.clubs[id].short}
            </span>
          ))}
        </div>
      )}
    </div>
  )
}

/** 試合の見出しに付けるダービーの札 */
export function DerbyBadge({ state, home, away, className = '' }: { state: GameState; home: number; away: number; className?: string }) {
  const d = derbyOf(state, home, away)
  if (!d) return null
  return <span className={`rounded px-1.5 py-0.5 text-[0.7rem] font-black ${d.intensity >= 1 ? 'bg-bad/80 text-white' : 'bg-accent/25 text-accent'} ${className}`}>{d.rival && d.name !== 'ライバル対決' ? `${d.name}・ライバル` : d.name}</span>
}
