/** 代表とワールドカップ: 日本代表（招集メンバー・試合）・大会（予選・W 杯）・ランキング・W 杯の歴史。 */
import { useState } from 'react'
import { NATION_NAME, dateLabel, ovr, playerClub, type GameState } from '../../engine'
import { CONFED_NAME, CONFED_OF, CONFEDS, WC_QF, WC_ROUND_NAMES, isWcYear, wcHost, type Confed } from '../../engine/data/national'
import type { Nation } from '../../engine/data/nations'
import { POSITION_DEFS } from '../../engine/data/positions'
import { endYear, natGroupStandings, natRoundName, nationRanking, nextJapanFixture, selectSquad } from '../../engine/national/national'
import type { NatComp, NatFixture } from '../../engine/models/national'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Flag } from '../components/common'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'

type Tab = 'japan' | 'comps' | 'ranking' | 'history'
const TABS: [Tab, string][] = [
  ['japan', '日本代表'],
  ['comps', '予選・W杯'],
  ['ranking', 'ランキング'],
  ['history', 'W杯の歴史'],
]

function Nat({ n, bold }: { n: Nation; bold?: boolean }) {
  return (
    <span className={`inline-flex min-w-0 items-center gap-1 ${bold ? 'font-bold' : ''} ${n === 'JP' ? 'text-gold' : ''}`}>
      <Flag nation={n} className="h-[0.75rem] w-[1.1rem] shrink-0" />
      <span className="truncate">{NATION_NAME[n]}</span>
    </span>
  )
}

function wdl(gf: number, ga: number, pens?: [number, number]): 'W' | 'D' | 'L' {
  if (gf !== ga) return gf > ga ? 'W' : 'L'
  if (pens) return pens[0] > pens[1] ? 'W' : 'L'
  return 'D'
}

function ResultMark({ r }: { r: 'W' | 'D' | 'L' }) {
  return <span className={`flex h-4 w-4 shrink-0 items-center justify-center rounded text-[0.68rem] font-black ${r === 'W' ? 'bg-good text-[#06210f]' : r === 'L' ? 'bg-bad text-white' : 'bg-white/20'}`}>{r === 'W' ? '勝' : r === 'L' ? '負' : '分'}</span>
}

/** 日本の W 杯への道（今の状況のひとこと） */
function wcStatus(state: GameState): string {
  const nat = state.national
  const y = endYear(state)
  const target = isWcYear(y) ? y : isWcYear(y + 1) ? y + 1 : isWcYear(y + 2) ? y + 2 : y + 3
  const host = wcHost(target)
  const wc = nat?.comps.find((c) => c.kind === 'worldCup' && c.year === target)
  if (wc) return wc.nations.includes('JP') ? `W杯 ${target}（${NATION_NAME[host]}開催）に出場中` : `W杯 ${target} は出場できませんでした`
  if (host === 'JP') return `W杯 ${target} は日本開催（予選なしで出場）`
  const q = nat?.comps.find((c) => c.kind === 'qualifier' && c.year === target && c.confed === 'AFC')
  if (q) {
    const rows = natGroupStandings(state, q, 0)
    const rank = rows.findIndex((r) => r.nation === 'JP') + 1
    return `W杯 ${target} アジア予選 ${rank} 位（上位 ${q.quota} か国が出場）`
  }
  return `次の W杯は ${target} 年（${NATION_NAME[host]}開催）。予選は ${target - 2} 年の秋から`
}

function JapanTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const push = useUi((s) => s.push)
  const nat = state.national
  const rank = nationRanking(state).indexOf('JP') + 1
  const next = nextJapanFixture(state)
  const called = nat?.squads.JP ?? []
  const ids = called.length ? called : selectSquad(state, 'JP')
  const squad = ids.map((id) => state.players[id]).filter(Boolean)
  const lines: ('GK' | 'DF' | 'MF' | 'FW')[] = ['GK', 'DF', 'MF', 'FW']
  const log = [...(nat?.japanLog ?? [])].reverse().slice(0, 10)
  const mineCount = squad.filter((p) => p.clubId === me.id).length
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[40%] shrink-0 space-y-2.5 p-3 text-[0.78rem]">
        <div className="flex items-center gap-2.5">
          <Flag nation="JP" className="h-[2.2rem] w-[3.3rem] rounded shadow" />
          <div>
            <div className="text-[1.05rem] font-black">日本代表</div>
            <div className="num text-[0.78rem] text-ink-dim">
              世界ランキング {rank} 位（{nat?.elo.JP ?? '―'}）
            </div>
          </div>
        </div>
        <div className="rounded-lg bg-accent/10 px-2.5 py-1.5 text-[0.75rem] font-bold text-accent">{wcStatus(state)}</div>
        <div>
          <div className="panel-head mb-1">次の試合</div>
          {next ? (
            <div className="flex items-center gap-2">
              <span className="num w-[4.6rem] shrink-0 text-[0.74rem] text-ink-dim">{dateLabel(state.startYear, Math.floor(next.f.absWeek / 48), next.f.absWeek % 48).replace(/^\d+年/, '')}</span>
              <span className="shrink-0 text-[0.74rem] text-ink-dim">
                {next.comp.short}
                {natRoundName(next.comp, next.f)}
              </span>
              <Nat n={next.f.home === 'JP' ? next.f.away : next.f.home} bold />
            </div>
          ) : (
            <div className="text-ink-dim">予定はありません</div>
          )}
        </div>
        <div>
          <div className="panel-head mb-1">最近の試合</div>
          {log.length === 0 && <div className="text-ink-dim">まだ試合をしていません</div>}
          {log.map((m, i) => (
            <div key={i} className="flex items-center gap-1.5 py-0.5">
              <ResultMark r={wdl(m.gf, m.ga, m.pens)} />
              <span className="w-[4.2rem] shrink-0 truncate text-[0.7rem] text-ink-dim">
                {m.compShort}
                {m.round}
              </span>
              <span className={`w-3 shrink-0 text-center text-[0.68rem] font-bold ${m.neutral ? 'text-ink-dim' : m.home ? 'text-good' : 'text-accent'}`}>{m.neutral ? '中' : m.home ? 'H' : 'A'}</span>
              <span className="min-w-0 flex-1">
                <Nat n={m.opp} />
              </span>
              <span className="num shrink-0 font-bold">
                {m.gf}-{m.ga}
                {m.pens && <span className="text-[0.68rem] text-ink-dim">（PK）</span>}
              </span>
            </div>
          ))}
        </div>
      </div>
      <div className="panel flex min-w-0 flex-1 flex-col p-3">
        <div className="mb-1 flex items-baseline gap-2">
          <span className="panel-head">{called.length ? '招集メンバー' : '候補（次の代表戦で発表）'}</span>
          {mineCount > 0 && <span className="text-[0.76rem] font-bold text-gold">{me.short}から {mineCount} 人</span>}
        </div>
        <div className="scroll-y min-h-0 flex-1 pr-1">
          {lines.map((line) => (
            <div key={line} className="mb-1.5">
              <div className="text-[0.7rem] font-bold text-ink-mute">{line}</div>
              {squad
                .filter((p) => POSITION_DEFS[p.pos].line === line)
                .map((p) => {
                  const club = p.clubId >= 0 ? state.clubs[p.clubId] : undefined
                  const mine = p.clubId === me.id
                  return (
                    <button key={p.id} className={`flex w-full items-center gap-2 rounded-md px-1.5 py-0.5 text-left text-[0.75rem] ${mine ? 'bg-gold/10' : ''}`} onClick={() => push({ id: 'player', params: { id: p.id } })}>
                      <span className="w-7 shrink-0 text-[0.7rem] text-ink-dim">{p.pos}</span>
                      <span className={`min-w-0 flex-1 truncate ${mine ? 'font-bold text-gold' : ''}`}>{p.name}</span>
                      <span className="w-[5.5rem] shrink-0 truncate text-[0.72rem] text-ink-dim">{club ? club.short : 'フリー'}</span>
                      <span className="num w-[4.4rem] shrink-0 text-right text-[0.7rem] text-ink-dim">
                        {p.intl?.caps ?? 0}試合{p.intl?.goals ?? 0}点
                      </span>
                      <span className="num w-6 shrink-0 text-right font-black">{ovr(p)}</span>
                    </button>
                  )
                })}
            </div>
          ))}
        </div>
      </div>
    </div>
  )
}

/** グループの順位表（compact = 勝・分・負を省く。W 杯の 4 組を並べるとき） */
function GroupTable({ state, comp, group, title, cut, compact }: { state: GameState; comp: NatComp; group: number; title?: string; cut: number; compact?: boolean }) {
  const rows = natGroupStandings(state, comp, group)
  const cols = compact ? 'grid-cols-[0.8rem_1fr_1.2rem_1.8rem_1.4rem]' : 'grid-cols-[1rem_1fr_1.4rem_1.4rem_1.4rem_1.4rem_2rem_1.6rem]'
  return (
    <div className="rounded-lg bg-black/20 p-1.5">
      {title && <div className="mb-0.5 text-[0.74rem] font-bold text-ink-dim">{title}</div>}
      <div className={`grid ${cols} gap-x-1 text-[0.72rem] text-ink-dim`}>
        <span />
        <span />
        <span className="text-right">試</span>
        {!compact && (
          <>
            <span className="text-right">勝</span>
            <span className="text-right">分</span>
            <span className="text-right">負</span>
          </>
        )}
        <span className="text-right">差</span>
        <span className="text-right">点</span>
      </div>
      {rows.map((r, i) => (
        <div key={r.nation} className={`grid ${cols} items-center gap-x-1 py-[1px] text-[0.78rem] ${i < cut ? '' : 'opacity-60'}`}>
          <span className={`num text-[0.7rem] ${i < cut ? 'text-good' : 'text-ink-dim'}`}>{i + 1}</span>
          <Nat n={r.nation} bold={i < cut} />
          <span className="num text-right">{r.played}</span>
          {!compact && (
            <>
              <span className="num text-right">{r.won}</span>
              <span className="num text-right">{r.drawn}</span>
              <span className="num text-right">{r.lost}</span>
            </>
          )}
          <span className="num text-right">{r.gf - r.ga > 0 ? `+${r.gf - r.ga}` : r.gf - r.ga}</span>
          <span className="num text-right font-bold">{r.points}</span>
        </div>
      ))}
    </div>
  )
}

function FixtureLine({ f }: { f: NatFixture }) {
  const r = f.result
  return (
    <div className="flex items-center gap-1.5 py-0.5 text-[0.78rem]">
      <span className="min-w-0 flex-1 text-right">
        <Nat n={f.home} bold={!!r && (r.hg > r.ag || (r.hg === r.ag && !!r.pens && r.pens[0] > r.pens[1]))} />
      </span>
      <span className="num w-[3.6rem] shrink-0 text-center font-bold">
        {r ? `${r.hg}-${r.ag}` : 'vs'}
        {r?.pens && <span className="block text-[0.66rem] font-normal text-ink-dim">PK {r.pens[0]}-{r.pens[1]}</span>}
      </span>
      <span className="min-w-0 flex-1">
        <Nat n={f.away} bold={!!r && (r.ag > r.hg || (r.hg === r.ag && !!r.pens && r.pens[1] > r.pens[0]))} />
      </span>
    </div>
  )
}

function WorldCupView({ state, comp }: { state: GameState; comp: NatComp }) {
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[55%] shrink-0 p-2">
        <div className="mb-1 px-1 text-[0.85rem] font-black">
          {comp.name}（{NATION_NAME[comp.host!]}開催）
        </div>
        <div className="grid grid-cols-2 gap-1.5">
          {[0, 1, 2, 3].map((g) => (
            <GroupTable key={g} state={state} comp={comp} group={g} title={`${String.fromCharCode(65 + g)}組`} cut={2} compact />
          ))}
        </div>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 p-2">
        <div className="panel-head mb-1">決勝トーナメント</div>
        {[WC_QF, WC_QF + 1, WC_QF + 2].map((round) => {
          const list = comp.fixtures.filter((f) => f.round === round)
          return (
            <div key={round} className="mb-1.5">
              <div className="text-[0.72rem] font-bold text-ink-dim">{WC_ROUND_NAMES[round]}</div>
              {list.length ? list.map((f) => <FixtureLine key={f.id} f={f} />) : <div className="text-[0.76rem] text-ink-mute">未定</div>}
            </div>
          )
        })}
        <div className="panel-head mb-1 mt-2">日本の試合</div>
        {comp.fixtures.filter((f) => f.home === 'JP' || f.away === 'JP').length === 0 && <div className="text-[0.78rem] text-ink-dim">日本は出場していません</div>}
        {comp.fixtures
          .filter((f) => f.home === 'JP' || f.away === 'JP')
          .map((f) => (
            <FixtureLine key={f.id} f={f} />
          ))}
      </div>
    </div>
  )
}

function CompsTab({ state }: { state: GameState }) {
  const nat = state.national
  const y = endYear(state)
  const wc = nat?.comps.find((c) => c.kind === 'worldCup' && c.year === y)
  const quals = (nat?.comps ?? []).filter((c) => c.kind === 'qualifier')
  const [cf, setCf] = useState<Confed>('AFC')
  if (wc) return <WorldCupView state={state} comp={wc} />
  const q = quals.find((c) => c.confed === cf) ?? quals[0]
  if (!q)
    return (
      <div className="panel flex-1 p-4 text-[0.82rem] text-ink-dim">
        今は W杯の予選の期間ではありません。代表戦の週には親善試合が行われます。
        <div className="mt-1">{wcStatus(state)}</div>
      </div>
    )
  const groups = [...new Set(q.table.map((r) => r.group))].sort()
  const perGroup = Math.floor((q.quota ?? 0) / groups.length)
  const jpFixtures = q.fixtures.filter((f) => f.home === 'JP' || f.away === 'JP')
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[55%] shrink-0 p-2">
        <div className="seg mb-2">
          {CONFEDS.filter((c) => quals.some((x) => x.confed === c)).map((c) => (
            <button key={c} aria-selected={q.confed === c} onClick={() => setCf(c)}>
              {CONFED_NAME[c]}
            </button>
          ))}
        </div>
        <div className="mb-1 px-1 text-[0.8rem] font-black">
          {q.name}（W杯 {q.year}・出場枠 {q.quota}）
        </div>
        <div className="space-y-1.5">
          {groups.map((g) => (
            <GroupTable key={g} state={state} comp={q} group={g} title={groups.length > 1 ? `${String.fromCharCode(65 + g)}組` : undefined} cut={perGroup} />
          ))}
        </div>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 p-2">
        <div className="panel-head mb-1">{jpFixtures.length ? '日本の日程' : `${CONFED_NAME[q.confed!]}の最近の結果`}</div>
        {(jpFixtures.length ? jpFixtures : q.fixtures.filter((f) => f.result).slice(-12)).map((f) => (
          <div key={f.id} className="flex items-center gap-1.5">
            <span className="num w-[2.6rem] shrink-0 text-[0.68rem] text-ink-dim">第{f.round + 1}節</span>
            <div className="min-w-0 flex-1">
              <FixtureLine f={f} />
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

function RankingTab({ state }: { state: GameState }) {
  const nat = state.national
  const titles = (n: Nation) => (nat?.worldCups ?? []).filter((w) => w.champion === n).length
  const list = nationRanking(state)
  return (
    <div className="panel scroll-y min-h-0 flex-1 p-2">
      <div className="grid grid-cols-2 gap-x-4">
        {list.map((n, i) => (
          <div key={n} className={`flex items-center gap-2 border-b border-line/30 py-1 text-[0.76rem] ${n === 'JP' ? 'bg-gold/10' : ''}`}>
            <span className="num w-5 shrink-0 text-right font-bold text-ink-dim">{i + 1}</span>
            <span className="min-w-0 flex-1">
              <Nat n={n} bold />
            </span>
            <span className="w-12 shrink-0 text-[0.7rem] text-ink-dim">{CONFED_NAME[CONFED_OF[n]]}</span>
            {titles(n) > 0 && <span className="shrink-0 text-[0.7rem] font-bold text-gold">★{titles(n)}</span>}
            <span className="num w-10 shrink-0 text-right font-bold">{nat?.elo[n] ?? '―'}</span>
          </div>
        ))}
      </div>
    </div>
  )
}

function HistoryTab({ state }: { state: GameState }) {
  const list = [...(state.national?.worldCups ?? [])].reverse()
  const y = endYear(state)
  const next = isWcYear(y) ? y : y + ((2 - (y % 4) + 4) % 4)
  if (!list.length)
    return (
      <div className="panel flex-1 p-4 text-[0.82rem] text-ink-dim">
        まだ W杯は開かれていません。次は {next} 年（{NATION_NAME[wcHost(next)]}開催）です。
      </div>
    )
  return (
    <div className="panel scroll-y min-h-0 flex-1 space-y-1.5 p-2">
      {list.map((w) => (
        <div key={w.year} className="rounded-lg bg-black/20 px-2.5 py-1.5 text-[0.74rem]">
          <div className="flex flex-wrap items-center gap-x-3 gap-y-0.5">
            <span className="num text-[0.85rem] font-black">{w.year}</span>
            <span className="text-[0.72rem] text-ink-dim">
              <Nat n={w.host} /> 開催
            </span>
            <span className="flex items-center gap-1 font-bold text-gold">
              優勝 <Nat n={w.champion} bold />
            </span>
            <span className="flex items-center gap-1 text-ink-dim">
              準優勝 <Nat n={w.runnerUp} />
            </span>
            <span className={`font-bold ${w.japan === '優勝' || w.japan === '準優勝' || w.japan === 'ベスト4' ? 'text-gold' : w.japan === '不出場' ? 'text-ink-mute' : ''}`}>日本: {w.japan}</span>
          </div>
          <div className="mt-0.5 flex flex-wrap gap-x-3 text-[0.74rem] text-ink-dim">
            {w.topScorer && (
              <span>
                得点王 {w.topScorer.name}（{NATION_NAME[w.topScorer.nation]}）{w.topScorer.goals}点
              </span>
            )}
            {w.mvp && <span>MVP {w.mvp.name}</span>}
            {w.mine.length > 0 && <span className="text-gold">自クラブから: {w.mine.map((m) => `${m.name}${m.goals ? `（${m.goals}点）` : ''}`).join('、')}</span>}
          </div>
        </div>
      ))}
    </div>
  )
}

export function NationalScreen() {
  const state = useGameState()
  const [tab, setTab] = useState<Tab>((useCurrentScreen().params?.tab as Tab | undefined) ?? 'japan')
  return (
    <AppShell title="代表・W杯" current="schedule" back right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className="seg shrink-0 self-start">
          {TABS.map(([id, label]) => (
            <button key={id} aria-selected={tab === id} onClick={() => setTab(id)}>
              {label}
            </button>
          ))}
        </div>
        {tab === 'japan' && <JapanTab state={state} />}
        {tab === 'comps' && <CompsTab state={state} />}
        {tab === 'ranking' && <RankingTab state={state} />}
        {tab === 'history' && <HistoryTab state={state} />}
      </div>
    </AppShell>
  )
}
