/** キャリアのオファー 1 件（入団・移籍・契約更改）。受ける・断る。 */
import { SQUAD_ROLE_LABEL, type GameState } from '../../engine'
import type { CareerOffer } from '../../engine/models/career'
import { acceptOffer } from '../../engine/career/create'
import { declineOffer } from '../../engine/career/offers'
import { Emblem } from '../components/ClubArt'
import { useGame } from '../../stores/gameStore'
import { formatMoney } from '../format'
import { RankBadge } from './RankBadge'
import { clubRank, myRank } from '../../engine/career/rank'

const KIND_LABEL: Record<CareerOffer['kind'], string> = { rookie: '入団', transfer: '移籍', renewal: '契約更改' }
const ROLE_COLOR: Record<string, string> = { star: 'text-gold', regular: 'text-good', rotation: 'text-accent', backup: 'text-ink-dim', prospect: 'text-ink-dim' }

/** onDone: 返事をしたあと（accepted = 受けた）。ホームの知らせから開いたときにホームへ戻すのに使う */
export function OfferCard({ state, o, compact = false, onDone }: { state: GameState; o: CareerOffer; compact?: boolean; onDone?: (accepted: boolean) => void }) {
  const mutate = useGame((s) => s.mutate)
  const club = state.clubs[o.clubId]
  const comp = state.competitions.find((c) => c.id === club.leagueId)
  const canDecline = !(o.kind === 'rookie' && state.career!.offers.filter((x) => x.kind === 'rookie').length <= 1)
  return (
    <div className="flex items-center gap-2.5 rounded-xl bg-white/[0.05] p-2.5">
      <Emblem id={`of-${o.id}`} emblem={club.emblem} colors={club.colors} size={compact ? '2.2rem' : '2.8rem'} />
      <div className="min-w-0 flex-1">
        <div className="flex items-center gap-1.5">
          <span className="rounded bg-accent/20 px-1.5 text-[0.68rem] font-bold text-accent">{KIND_LABEL[o.kind]}</span>
          <span className="truncate text-[0.9rem] font-black">{club.name}</span>
        </div>
        <div className="flex flex-wrap items-center gap-1.5 text-[0.72rem] text-ink-dim">
          <RankBadge rank={clubRank(state, club)} />
          {comp?.name ?? ''}
          {o.kind !== 'renewal' && (() => {
            const to = clubRank(state, club)
            const from = myRank(state)
            if (!to || !from || to.step === from.step) return null
            return to.step > from.step ? <span className="font-black text-good">ステップアップ ↑</span> : <span className="text-bad">ランクが下がる ↓</span>
          })()}
        </div>
        <div className="num mt-0.5 flex flex-wrap gap-x-2.5 text-[0.78rem]">
          <span>
            立場の見込み <b className={ROLE_COLOR[o.role]}>{SQUAD_ROLE_LABEL[o.role]}</b>
          </span>
          <span>年俸 {formatMoney(o.wage)}</span>
          <span>{o.years} 年</span>
          {o.fee > 0 && <span className="text-ink-dim">移籍金 {formatMoney(o.fee)}</span>}
        </div>
      </div>
      <div className="flex shrink-0 flex-col gap-1">
        <button
          className="btn btn-gold btn-sm"
          onClick={() => {
            mutate((st) => void acceptOffer(st, o.id))
            onDone?.(true)
          }}
        >
          {o.kind === 'renewal' ? '更新する' : o.kind === 'rookie' ? '入団する' : '移籍する'}
        </button>
        {canDecline && (
          <button
            className="btn btn-ghost btn-sm !min-h-[2rem]"
            onClick={() => {
              mutate((st) => void declineOffer(st, o.id))
              onDone?.(false)
            }}
          >
            断る
          </button>
        )}
      </div>
    </div>
  )
}
