/** 試合後（キャリア）: 主人公の評価点・得点・見せ場の結果・入った経験点・監督の評価。 */
import type { GameState } from '../../engine'
import { EXP_LABEL, type ExpKind } from '../../engine/models/career'

function ratingColor(r: number): string {
  return r >= 8 ? '#f5c542' : r >= 7 ? '#3ddc84' : r >= 6 ? '#e8eef6' : '#ff8a8a'
}

export function CareerMatchPanel({ state }: { state: GameState }) {
  const lm = state.career?.lastMatch
  return (
    <div className="panel scroll-y w-[30%] shrink-0 p-3">
      <div className="panel-head mb-1.5">あなたの試合</div>
      {!lm || lm.minutes === 0 ? (
        <div className="text-[0.78rem] text-ink-dim">今日は出番がありませんでした。練習で監督にアピールしよう。</div>
      ) : (
        <div className="space-y-2 text-[0.78rem]">
          <div className="flex items-end gap-3">
            <div>
              <div className="text-[0.68rem] text-ink-dim">評価点</div>
              <div className="num text-[2rem] font-black leading-none" style={{ color: ratingColor(lm.rating) }}>
                {lm.rating.toFixed(1)}
              </div>
            </div>
            <div className="num pb-0.5 text-[0.75rem] text-ink-dim">
              {lm.started ? '先発' : '途中出場'}・{lm.minutes} 分
              <div className="text-[0.85rem] font-bold text-ink">
                {lm.goals > 0 && `${lm.goals} 得点 `}
                {lm.assists > 0 && `${lm.assists} アシスト`}
              </div>
            </div>
          </div>
          {lm.moments.length > 0 && (
            <div>
              <div className="text-[0.7rem] text-ink-dim">見せ場</div>
              <div className="mt-0.5 flex flex-wrap gap-1">
                {lm.moments.map((m, i) => (
                  <span key={i} className={`rounded px-1.5 py-0.5 text-[0.72rem] font-bold ${m.ok ? 'bg-good/20 text-good' : 'bg-bad/15 text-bad'}`}>
                    {m.ok ? '○' : '×'} {m.label}
                  </span>
                ))}
              </div>
            </div>
          )}
          <div>
            <div className="text-[0.7rem] text-ink-dim">経験点</div>
            <div className="mt-0.5 flex flex-wrap gap-1">
              {(Object.entries(lm.expGain) as [ExpKind, number][]).map(([k, v]) => (
                <span key={k} className="num rounded bg-gold/15 px-1.5 text-[0.74rem] font-bold text-gold">
                  {EXP_LABEL[k]} +{v}
                </span>
              ))}
            </div>
          </div>
          <div className="flex justify-between">
            <span className="text-ink-dim">監督の評価</span>
            <span className={`num font-bold ${lm.trustDelta > 0 ? 'text-good' : lm.trustDelta < 0 ? 'text-bad' : 'text-ink-dim'}`}>
              {lm.trustDelta > 0 ? '+' : ''}
              {lm.trustDelta}（{Math.round(state.career!.trust)}）
            </span>
          </div>
        </div>
      )}
    </div>
  )
}
