/** 画面から使う問い合わせ（state を書き換えない）。 */
import { absWeekOf } from './core/calendar'
import type { Competition, Fixture } from './models/competition'
import type { GameState } from './models/game'
import type { Club } from './models/club'
import type { Staff, StaffRole } from './models/staff'
import { rankOf } from './competition/league'

export function currentAbsWeek(state: GameState): number {
  return absWeekOf(state.season, state.week)
}

export function playerClub(state: GameState): Club {
  return state.clubs[state.playerClubId]
}

export function leagueOf(state: GameState, club: Club): Competition {
  return state.competitions.find((c) => c.id === club.leagueId)!
}

/** そのクラブのこれからの試合（全大会、日付順） */
export function upcomingFixtures(state: GameState, clubId: number, limit = 5): Fixture[] {
  const now = currentAbsWeek(state)
  const out: Fixture[] = []
  for (const comp of state.competitions) {
    for (const f of comp.fixtures) {
      if (f.result || f.absWeek < now) continue
      if (f.home === clubId || f.away === clubId) out.push(f)
    }
  }
  return out.sort((a, b) => a.absWeek - b.absWeek || (a.slot === 'midweek' ? -1 : 1)).slice(0, limit)
}

export function recentFixtures(state: GameState, clubId: number, limit = 5): Fixture[] {
  const out: Fixture[] = []
  for (const comp of state.competitions) {
    for (const f of comp.fixtures) if (f.result && (f.home === clubId || f.away === clubId)) out.push(f)
  }
  return out.sort((a, b) => b.absWeek - a.absWeek).slice(0, limit)
}

export function clubRank(state: GameState, club: Club): number {
  return Math.max(1, rankOf(leagueOf(state, club), club.id))
}

export function clubStaff(state: GameState, club: Club): Staff[] {
  return club.staff.map((id) => state.staff[id]).filter(Boolean)
}

export function staffByRole(state: GameState, club: Club, role: StaffRole): Staff | undefined {
  return clubStaff(state, club).find((s) => s.role === role)
}

export function compById(state: GameState, id: string): Competition | undefined {
  return state.competitions.find((c) => c.id === id)
}
