/** クラブ画面の「事業」タブ: サイドビジネスの開業・拡大・方針・売却と、今シーズンの損益。 */
import { useState } from 'react'
import { currentAbsWeek, playerClub, type GameState } from '../../engine'
import { useUi } from '../../stores/uiStore'
import { BUSINESS_BY_ID, BUSINESS_DEFS, MAX_BUSINESS_LEVEL, POLICY_DESC, POLICY_LABEL } from '../../engine/data/business'
import {
  canOpen,
  canUpgrade,
  cycleLabel,
  cycleOf,
  estimate,
  findBusiness,
  openBusiness,
  sellBusiness,
  sellValue,
  setPolicy,
  upgradeBusiness,
  upgradeCost,
} from '../../engine/economy/business'
import type { Business, BusinessId, BusinessPolicy } from '../../engine/models/club'
import { SideSheet } from '../layout/SideSheet'
import { useGame } from '../../stores/gameStore'
import { formatMoney, formatMoneyShort } from '../format'

/** 事業ごとの目印（色と一文字） */
const MARK: Record<BusinessId, [string, string]> = {
  cafe: ['#f59e0b', '食'],
  school: ['#22c55e', '学'],
  clinic: ['#38bdf8', '癒'],
  hotel: ['#a78bfa', '宿'],
  media: ['#f43f5e', '映'],
  esports: ['#06b6d4', 'e'],
  realestate: ['#eab308', '街'],
  academy: ['#10b981', '海'],
}

function Mark({ id, size = '2rem' }: { id: BusinessId; size?: string }) {
  const [c, ch] = MARK[id]
  return (
    <span className="flex shrink-0 items-center justify-center rounded-lg font-black text-[#0b1320]" style={{ background: c, width: size, height: size, fontSize: `calc(${size} * 0.55)` }}>
      {ch}
    </span>
  )
}

function Lv({ v }: { v: number }) {
  return (
    <span className="inline-flex gap-0.5">
      {Array.from({ length: MAX_BUSINESS_LEVEL }, (_, i) => (
        <span key={i} className={`h-2 w-2.5 rounded-sm ${i < v ? 'bg-gold' : 'bg-white/10'}`} />
      ))}
    </span>
  )
}

function Money({ v, className = '' }: { v: number; className?: string }) {
  return <span className={`num font-bold ${v < 0 ? 'text-bad' : v > 0 ? 'text-good' : ''} ${className}`}>{v > 0 ? '+' : ''}{formatMoneyShort(v)}</span>
}

/** 事業の状態の一言 */
function statusOf(state: GameState, b: Business | undefined): string {
  if (!b) return '未開業'
  const now = currentAbsWeek(state)
  if (now < b.openAbsWeek) return `開業まで ${b.openAbsWeek - now} 週`
  if (b.pending) return `拡大中（あと ${b.pending.doneAbsWeek - now} 週）`
  return '営業中'
}

export function BusinessTab({ state }: { state: GameState }) {
  const push = useUi((s) => s.push)
  const me = playerClub(state)
  const [sel, setSel] = useState<BusinessId | null>(null)
  const owned = me.businesses ?? []
  const cycle = cycleOf(state)
  const seasonProfit = owned.reduce((s, b) => s + b.profit, 0)
  const total = owned.reduce((s, b) => s + b.total, 0)
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[30%] shrink-0 p-3">
        <div className="panel-head mb-1">事業のまとめ</div>
        <div className="space-y-1 text-[0.78rem]">
          <div className="flex justify-between">
            <span className="text-ink-dim">景気</span>
            <span className={`font-bold ${cycle >= 1.04 ? 'text-good' : cycle <= 0.96 ? 'text-bad' : ''}`}>{cycleLabel(cycle)}</span>
          </div>
          <div className="relative h-1.5 rounded-full bg-white/10">
            <div className="absolute top-1/2 h-3 w-1 -translate-y-1/2 rounded bg-gold" style={{ left: `${((cycle - 0.75) / 0.55) * 100}%` }} />
          </div>
          <div className="flex justify-between pt-1">
            <span className="text-ink-dim">営業中</span>
            <span className="num font-bold">{owned.length} / {BUSINESS_DEFS.length}</span>
          </div>
          <div className="flex justify-between">
            <span className="text-ink-dim">今季の利益</span>
            <Money v={seasonProfit} />
          </div>
          <div className="flex justify-between">
            <span className="text-ink-dim">開業からの利益</span>
            <Money v={total} />
          </div>
        </div>
        <p className="mt-2 text-[0.72rem] leading-snug text-ink-mute">
          売上はクラブの人気・サポーター・ホームタウンの人口や経済と、景気で変わります。小さいクラブのうちは赤字になる事業もあるので、開業前に見込みを確かめましょう。事業ごとにクラブへの効果もあります。
        </p>
        <button className="btn btn-ghost btn-sm mt-2 w-full !text-[0.74rem]" onClick={() => push({ id: 'youth', params: { tab: 'academy' } })}>
          海外アカデミーはユースアカデミーの画面へ →
        </button>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 p-2">
        <div className="grid grid-cols-2 gap-2">
          {BUSINESS_DEFS.map((def) => {
            const b = findBusiness(me, def.id)
            const est = estimate(state, me, def.id, b?.level ?? 1, b?.policy ?? 'normal')
            const chk = b ? canUpgrade(state, me, def.id) : canOpen(state, me, def.id)
            const locked = !b && !chk.ok && chk.reason?.startsWith('条件')
            return (
              <button key={def.id} className={`rounded-xl p-2 text-left transition ${b ? 'bg-gold/[0.07] ring-1 ring-gold/30' : 'bg-white/[0.04]'} ${locked ? 'opacity-60' : ''}`} onClick={() => setSel(def.id)}>
                <div className="flex items-center gap-2">
                  <Mark id={def.id} />
                  <div className="min-w-0 flex-1">
                    <div className="truncate text-[0.85rem] font-black">{def.name}</div>
                    <div className="flex items-center gap-1.5 text-[0.7rem] text-ink-dim">
                      {b ? <Lv v={b.level} /> : null}
                      <span className="truncate">{statusOf(state, b)}</span>
                    </div>
                  </div>
                </div>
                <div className="mt-1.5 grid grid-cols-2 gap-x-2 text-[0.72rem]">
                  {b ? (
                    <>
                      <span className="text-ink-dim">今季の利益</span>
                      <Money v={b.profit} className="text-right" />
                    </>
                  ) : (
                    <>
                      <span className="text-ink-dim">開業費</span>
                      <span className="num text-right font-bold">{formatMoneyShort(def.openCost)}</span>
                    </>
                  )}
                  <span className="text-ink-dim">見込み/年</span>
                  <Money v={est.profit} className="text-right" />
                </div>
                {b?.boost && <div className="mt-1 truncate rounded bg-accent/15 px-1.5 text-[0.68rem] font-bold text-accent">{b.boost.label}（×{b.boost.mul}）</div>}
                {locked && <div className="mt-1 truncate text-[0.68rem] text-ink-mute">{chk.reason}</div>}
              </button>
            )
          })}
        </div>
      </div>
      <SideSheet open={sel !== null} onClose={() => setSel(null)} title={sel ? BUSINESS_BY_ID[sel].name : ''} width="60%">
        {sel && <BusinessDetail state={state} id={sel} onSold={() => setSel(null)} />}
      </SideSheet>
    </div>
  )
}

function BusinessDetail({ state, id, onSold }: { state: GameState; id: BusinessId; onSold: () => void }) {
  const mutate = useGame((s) => s.mutate)
  const me = playerClub(state)
  const def = BUSINESS_BY_ID[id]
  const b = findBusiness(me, id)
  const [confirmSell, setConfirmSell] = useState(false)
  const level = b?.level ?? 1
  const policy = b?.policy ?? 'normal'
  const now = estimate(state, me, id, level, policy)
  const next = level < MAX_BUSINESS_LEVEL ? estimate(state, me, id, level + 1, policy) : null
  const open = canOpen(state, me, id)
  const up = canUpgrade(state, me, id)
  const act = (fn: (st: GameState) => void) => mutate(fn)
  return (
    <div className="space-y-3 p-3 text-[0.8rem]">
      <div className="flex items-start gap-3">
        <Mark id={id} size="2.8rem" />
        <div className="min-w-0 flex-1">
          <div className="text-[0.78rem] text-ink-dim">{def.desc}</div>
          <div className="mt-1 text-[0.78rem] font-bold text-accent">効果: {def.effect}</div>
        </div>
      </div>

      <div className="rounded-xl bg-black/25 p-2.5">
        <div className="mb-1 flex items-center gap-2">
          <span className="font-black">{b ? `Lv${b.level}` : '開業すると Lv1'}</span>
          {b && <Lv v={b.level} />}
          <span className="ml-auto text-[0.76rem] text-ink-dim">{statusOf(state, b)}</span>
        </div>
        <div className="grid grid-cols-4 gap-x-2 gap-y-0.5 text-[0.78rem]">
          <span className="text-ink-dim" />
          <span className="text-right text-ink-dim">売上/年</span>
          <span className="text-right text-ink-dim">経費/年</span>
          <span className="text-right text-ink-dim">利益/年</span>
          <span className="text-ink-dim">いまの見込み</span>
          <span className="num text-right">{formatMoneyShort(now.sales)}</span>
          <span className="num text-right">{formatMoneyShort(now.cost)}</span>
          <Money v={now.profit} className="text-right" />
          {b && next && (
            <>
              <span className="text-ink-dim">Lv{level + 1} にすると</span>
              <span className="num text-right">{formatMoneyShort(next.sales)}</span>
              <span className="num text-right">{formatMoneyShort(next.cost)}</span>
              <Money v={next.profit} className="text-right" />
            </>
          )}
          {b && (
            <>
              <span className="text-ink-dim">今季の実績</span>
              <span className="num text-right">{formatMoneyShort(b.sales)}</span>
              <span className="num text-right">{formatMoneyShort(b.sales - b.profit)}</span>
              <Money v={b.profit} className="text-right" />
            </>
          )}
        </div>
        {b?.boost && <div className="mt-1.5 rounded bg-accent/15 px-2 py-0.5 text-[0.76rem] font-bold text-accent">{b.boost.label}: 売上 ×{b.boost.mul}</div>}
      </div>

      {!b && (
        <div className="space-y-2">
          <button className="btn btn-gold w-full" disabled={!open.ok} onClick={() => act((st) => void openBusiness(st, st.clubs[st.playerClubId], id))}>
            {open.ok || open.reason === '資金が足りない' ? `開業する（${formatMoney(def.openCost)}・準備 ${def.weeks} 週）` : open.reason}
          </button>
          {!open.ok && open.reason === '資金が足りない' && <div className="text-center text-[0.76rem] text-bad">資金が足りません</div>}
        </div>
      )}

      {b && (
        <>
          <div>
            <div className="mb-1 text-[0.78rem] text-ink-dim">方針</div>
            <div className="seg w-full">
              {(['local', 'normal', 'profit'] as BusinessPolicy[]).map((p) => (
                <button key={p} className="flex-1" aria-selected={policy === p} onClick={() => act((st) => setPolicy(st.clubs[st.playerClubId], id, p))}>
                  {POLICY_LABEL[p]}
                </button>
              ))}
            </div>
            <div className="mt-1 text-[0.72rem] text-ink-mute">{POLICY_DESC[policy]}</div>
          </div>
          {b.level < MAX_BUSINESS_LEVEL && (
            <button className="btn btn-blue w-full" disabled={!up.ok} onClick={() => act((st) => void upgradeBusiness(st, st.clubs[st.playerClubId], id))}>
              {up.ok || up.reason === '資金が足りない' ? `Lv${b.level + 1} に拡大（${formatMoney(upgradeCost(id, b.level + 1))}・${Math.ceil(def.weeks / 2)} 週）` : up.reason}
            </button>
          )}
          {b.history.length > 0 && <History b={b} />}
          <div className="flex items-center gap-2 border-t border-line/40 pt-2">
            <span className="text-[0.78rem] text-ink-dim">
              つぎ込んだ額 {formatMoneyShort(b.invested)}・開業からの利益 <Money v={b.total} />
            </span>
            {confirmSell ? (
              <button
                className="btn btn-sm ml-auto bg-bad/80 text-white"
                onClick={() => {
                  act((st) => void sellBusiness(st, st.clubs[st.playerClubId], id))
                  onSold()
                }}
              >
                {formatMoneyShort(sellValue(b))}円で売る
              </button>
            ) : (
              <button className="btn btn-ghost btn-sm ml-auto" onClick={() => setConfirmSell(true)}>
                売却する
              </button>
            )}
          </div>
        </>
      )}
    </div>
  )
}

/** シーズンごとの利益 */
function History({ b }: { b: Business }) {
  const max = Math.max(1, ...b.history.map((h) => Math.abs(h.profit)))
  return (
    <div>
      <div className="mb-1 text-[0.78rem] text-ink-dim">これまでの利益</div>
      <div className="flex h-16 items-stretch gap-1">
        {b.history.map((h) => {
          const pct = (Math.abs(h.profit) / max) * 50
          return (
            <div key={h.season} className="relative flex-1" title={`${formatMoneyShort(h.profit)}円`}>
              <div className="absolute inset-x-0 top-1/2 h-px bg-white/15" />
              <div className={`absolute inset-x-0.5 rounded-sm ${h.profit >= 0 ? 'bg-good' : 'bg-bad'}`} style={h.profit >= 0 ? { bottom: '50%', height: `${pct}%` } : { top: '50%', height: `${pct}%` }} />
            </div>
          )
        })}
      </div>
    </div>
  )
}
