/** 試合中の介入: 交代（次のプレー中断で反映）とフォーメーション・作戦の変更。 */
import { useState } from 'react'
import { FORMATIONS, TACTIC_PRESETS } from '../../engine'
import type { LiveMatch } from '../../engine/match/live/sim'
import { SideSheet } from '../layout/SideSheet'
import { PosBadge } from '../components/common'

export function InterventionSheet({ m, side, open, onClose }: { m: LiveMatch; side: 0 | 1; open: boolean; onClose: () => void }) {
  const [tab, setTab] = useState<'subs' | 'tactics'>('subs')
  const [out, setOut] = useState<number | null>(null)
  const [, force] = useState(0)
  const team = m.teams[side]
  const onPitch = m.onPitch(side)
  const pending = team.pendingSubs
  const used = team.subsUsed + pending.length
  const rerender = () => force((v) => v + 1)

  return (
    <SideSheet open={open} onClose={onClose} title={`作戦タイム（${m.clockLabel()}）`} width="62%">
      <div className="p-3">
        <div className="seg mb-2">
          <button aria-selected={tab === 'subs'} onClick={() => setTab('subs')}>
            選手交代（{used}/5）
          </button>
          <button aria-selected={tab === 'tactics'} onClick={() => setTab('tactics')}>
            フォーメーション・作戦
          </button>
        </div>
        {tab === 'subs' ? (
          <div className="grid grid-cols-2 gap-2">
            <div>
              <div className="panel-head mb-1">ピッチ上（交代する選手）</div>
              <div className="space-y-1">
                {onPitch.map((b) => {
                  const queued = pending.some((p) => p.out === b.s.id)
                  return (
                    <button key={b.idx} disabled={queued || used >= 5} onClick={() => setOut(b.s.id)} className={`flex w-full items-center gap-1.5 rounded-lg px-1.5 py-1 text-left ${out === b.s.id ? 'bg-gold/20 ring-1 ring-gold' : 'bg-white/[0.05]'} disabled:opacity-40`}>
                      <span className="num w-5 text-center text-[0.75rem] font-bold text-ink-dim">{b.s.number}</span>
                      <PosBadge pos={team.formation.slots[b.slot]?.pos ?? b.s.pos} />
                      <span className="min-w-0 flex-1 truncate text-[0.78rem] font-bold">{b.s.short}</span>
                      {b.yellow > 0 && <span className="h-3 w-2 rounded-[1px] bg-warn" />}
                      <span className="h-1.5 w-10 overflow-hidden rounded-full bg-black/40">
                        <span className="block h-full rounded-full" style={{ width: `${b.stamina}%`, background: b.stamina > 60 ? '#3ddc84' : b.stamina > 40 ? '#ffb020' : '#ff5a5f' }} />
                      </span>
                    </button>
                  )
                })}
              </div>
            </div>
            <div>
              <div className="panel-head mb-1">ベンチ（入る選手）</div>
              <div className="space-y-1">
                {team.bench.map((p) => {
                  const queued = pending.some((s) => s.in === p.id)
                  return (
                    <button
                      key={p.id}
                      disabled={out === null || queued}
                      onClick={() => {
                        if (out === null) return
                        m.command({ kind: 'sub', team: side, out, in: p.id })
                        setOut(null)
                        rerender()
                      }}
                      className="flex w-full items-center gap-1.5 rounded-lg bg-white/[0.05] px-1.5 py-1 text-left disabled:opacity-40"
                    >
                      <span className="num w-5 text-center text-[0.75rem] font-bold text-ink-dim">{p.number}</span>
                      <PosBadge pos={p.pos} />
                      <span className="min-w-0 flex-1 truncate text-[0.78rem] font-bold">{p.short}</span>
                      {queued && <span className="text-[0.7rem] text-accent">交代準備中</span>}
                    </button>
                  )
                })}
              </div>
              {pending.length > 0 && <p className="mt-2 text-[0.76rem] text-ink-dim">交代は次にプレーが止まったときに行われます。</p>}
            </div>
          </div>
        ) : (
          <div className="space-y-3">
            <div>
              <div className="panel-head mb-1">フォーメーション</div>
              <div className="grid grid-cols-5 gap-1">
                {FORMATIONS.map((f) => (
                  <button
                    key={f.id}
                    onClick={() => {
                      m.command({ kind: 'formation', team: side, formation: f.id })
                      rerender()
                    }}
                    className={`rounded-md border py-1.5 text-[0.76rem] font-bold ${team.formation.id === f.id ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}
                  >
                    {f.name.replace(' ダイヤ', '◇')}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <div className="panel-head mb-1">作戦</div>
              <div className="grid grid-cols-4 gap-1">
                {TACTIC_PRESETS.map((p) => (
                  <button
                    key={p.id}
                    onClick={() => {
                      m.command({ kind: 'tactics', team: side, tactics: p.values })
                      rerender()
                    }}
                    className="rounded-md border border-line/60 bg-black/20 py-1.5 text-[0.76rem] font-bold"
                  >
                    {p.name}
                  </button>
                ))}
              </div>
            </div>
            <div>
              <div className="panel-head mb-1">攻撃意識</div>
              <div className="seg w-full">
                {[-2, -1, 0, 1, 2].map((v) => (
                  <button
                    key={v}
                    aria-selected={team.tactics.mentality === v}
                    onClick={() => {
                      m.command({ kind: 'tactics', team: side, tactics: { mentality: v } })
                      rerender()
                    }}
                    className="flex-1"
                  >
                    {['守備的', 'やや守', '普通', 'やや攻', '攻撃的'][v + 2]}
                  </button>
                ))}
              </div>
            </div>
          </div>
        )}
      </div>
    </SideSheet>
  )
}
