/** 生え抜きの物語（M16、クラブモード）: ユース出身の選手の節目を、秘書の話として 1 つずつ見せる。#overlay-root に描く。 */
import { useEffect } from 'react'
import { createPortal } from 'react-dom'
import type { GameState } from '../../engine'
import { staffByRole } from '../../engine'
import { YOUTH_STORY_TEXT } from '../../engine/club/youthStory'
import { useGame } from '../../stores/gameStore'
import { useOverlayRoot } from '../stage/overlayRoot'
import { PlayerFace, StaffFace } from '../components/PersonFace'

const TITLE = { promote: 'トップ昇格', debut: 'デビュー', goal: 'プロ初ゴール', cap: '代表初選出', apps100: '100 試合出場' } as const

export function YouthStoryCard({ state }: { state: GameState }) {
  const mutate = useGame((s) => s.mutate)
  const root = useOverlayRoot()
  const item = state.mode === 'club' ? state.youthStories?.[0] : undefined
  const p = item ? state.players[item.playerId] : undefined
  // 選手がいなくなっていたら（引退など）飛ばす
  const missing = !!item && !p
  useEffect(() => {
    if (missing) mutate((st) => void (st.youthStories = (st.youthStories ?? []).slice(1)))
  }, [missing, mutate])
  if (!root || !item || !p) return null
  const me = state.clubs[state.playerClubId]
  const secretary = staffByRole(state, me, 'secretary')
  const close = () => mutate((st) => void (st.youthStories = (st.youthStories ?? []).slice(1)))
  return createPortal(
    <div className="anim-fade absolute inset-0 z-[52] flex items-center justify-center bg-black/60 p-3" onClick={close}>
      <div className="panel panel-solid anim-rise flex max-h-full w-[30rem] max-w-full flex-col p-4" onClick={(e) => e.stopPropagation()}>
        <div className="scroll-y min-h-0 flex-1">
          <div className="text-center text-[0.76rem] font-bold tracking-widest text-good">生え抜きの物語</div>
          <div className="mt-1 flex items-center justify-center gap-3">
            <PlayerFace p={p} kit={me.colors} className="h-16 w-16" />
            <div>
              <div className="text-[1.05rem] font-black">{p.name}</div>
              <div className="text-[0.85rem] font-bold text-gold">{TITLE[item.kind]}</div>
            </div>
          </div>
          <div className="mt-3 flex items-start gap-2.5">
            {secretary && <StaffFace s={secretary} className="h-11 w-11 shrink-0" photo />}
            <p className="rounded-lg bg-white/[0.06] px-2.5 py-1.5 text-[0.82rem]">{YOUTH_STORY_TEXT[item.kind](p.short)}</p>
          </div>
        </div>
        <button className="btn btn-gold mt-3 w-full shrink-0" onClick={close}>
          閉じる
        </button>
      </div>
    </div>,
    root,
  )
}
