/**
 * 場面（Clip）を再生するキャンバス。試合中のゴールのリプレイと、試合後のハイライトで使う。
 * rate は再生の速さ（1 = 試合の ×1。リプレイは少し遅く）。最後まで来たら onEnd。
 */
import { useEffect, useRef } from 'react'
import { PitchRenderer } from './renderer'
import { ReplaySource, type Clip } from './replay'
import { DT } from '../../engine/match/live/types'

export function ReplayCanvas({ clip, rate = 0.7, onEnd, className = 'relative h-full w-full', focusId }: { clip: Clip; rate?: number; onEnd?: () => void; className?: string; focusId?: number }) {
  const canvasRef = useRef<HTMLCanvasElement>(null)
  const wrapRef = useRef<HTMLDivElement>(null)
  const endRef = useRef(onEnd)
  useEffect(() => {
    endRef.current = onEnd
  }, [onEnd])

  useEffect(() => {
    const canvas = canvasRef.current!
    const wrap = wrapRef.current!
    const r = new PitchRenderer(canvas)
    const fit = () => r.resize(wrap.clientWidth, wrap.clientHeight)
    fit()
    const ro = new ResizeObserver(fit)
    ro.observe(wrap)
    const src = new ReplaySource(clip)
    r.snapCamera()
    let t = 0
    let last = performance.now()
    let raf = 0
    let ended = false
    const frame = (now: number) => {
      const dt = Math.min(0.1, (now - last) / 1000)
      last = now
      t += (dt / DT) * rate
      const i = Math.floor(t)
      if (i >= src.length - 1) {
        if (!ended) {
          ended = true
          endRef.current?.()
        }
        src.seek(src.length - 2)
        r.draw(src, 1, { camera: 'follow', showNames: true, zoom: 2.1, focusId })
      } else {
        src.seek(i)
        r.draw(src, t - i, { camera: 'follow', showNames: true, zoom: 2.1, focusId })
      }
      raf = requestAnimationFrame(frame)
    }
    raf = requestAnimationFrame(frame)
    return () => {
      cancelAnimationFrame(raf)
      ro.disconnect()
    }
  }, [clip, rate, focusId])

  return (
    <div ref={wrapRef} className={className}>
      <canvas ref={canvasRef} className="absolute inset-0 h-full w-full" />
    </div>
  )
}
