/** 1か月オートの前の様子（月間レポートでくらべる）。 */
import { clubRank, ovr, playerClub, squadOf, type GameState } from '../../engine'

/** 進める前の様子（くらべる用） */
export interface MonthSnap {
  rank: number
  points: number
  fans: number
  popularity: number
  ovr: Record<number, number>
  injured: number[]
}

export function takeSnap(state: GameState): MonthSnap {
  const me = playerClub(state)
  const row = state.competitions.find((c) => c.id === me.leagueId)?.table.find((r) => r.clubId === me.id)
  const sq = squadOf(state, me.id)
  return {
    rank: clubRank(state, me),
    points: row?.points ?? 0,
    fans: me.fans,
    popularity: me.popularity,
    ovr: Object.fromEntries(sq.map((p) => [p.id, ovr(p)])),
    injured: sq.filter((p) => p.injury).map((p) => p.id),
  }
}
