/** 自クラブの試合の観戦。終わったら結果をゲームに反映して試合後の画面へ。 */
import { useMemo, useState } from 'react'
import { matchOptions } from '../../engine/competition/continental'
import { playerFixtureThisWeek } from '../../engine'
import { buildMatchSetup } from '../../engine/match/setup'
import type { MatchSummary } from '../../engine/match/live/types'
import { MatchView } from '../match/MatchView'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

export function LiveMatchScreen() {
  const state = useGameState()
  const playWeek = useGame((s) => s.playWeek)
  const reset = useUi((s) => s.reset)
  // 画面を開いた時点の試合を固定する（観戦中に state が変わっても作り直さない）
  const [fx] = useState(() => playerFixtureThisWeek(state))
  const setup = useMemo(() => (fx ? buildMatchSetup(state, fx.fixture.id, fx.fixture.home, fx.fixture.away, matchOptions(fx.comp, fx.fixture)) : null), [fx, state])
  if (!fx || !setup) return null
  const side: 0 | 1 = fx.fixture.home === state.playerClubId ? 0 : 1
  const exit = (s: MatchSummary | null) => {
    playWeek(s ?? undefined)
    reset({ id: 'postMatch' })
  }
  // キャリア: 指示は出せない。主人公をカメラで追い、見せ場で選ぶ
  if (state.career) return <MatchView setup={setup} onExit={exit} focus={state.career.playerId} />
  return <MatchView setup={setup} userSide={side} onExit={exit} />
}
