/**
 * スカウト（M21）: 左にスカウト陣（目利き・人脈のランク、視察の進み具合、派遣先）、右に報告のカード。
 * 報告のカード: 顔・名前・推定の総合値と将来性、スカウトのひと言、弱点補強・獲得の見込みの札、掲載の残り（バー）、注目・外す・交渉。
 */
import { useEffect, useState } from 'react'
import { ageOf, clubStaff, currentAbsWeek, playerClub, type GameState, type Nation, type Player, type ScoutRegion, type Staff } from '../../engine'
import { REGION_LABEL, dispatchScout, estimate } from '../../engine/scout/knowledge'
import { REASON_LABEL, REPORT_WEEKS, dropReport, keepReport, markReportsSeen, reportWeeksLeft, reportsOf, scoutComment, type ReportReason, type ScoutReport } from '../../engine/scout/reports'
import { squadRanks } from '../../engine/transfer/market'
import { upgradeOf, type WeakSpots } from '../../engine/transfer/recommend'
import { outOfReach, signability, type Signability } from '../../engine/transfer/talks'
import { EstOvr, Flag, PosBadge, RankChip, Stars } from '../components/common'
import { PlayerFace, StaffFace } from '../components/PersonFace'
import { useGame } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'
import { useScreenState, useScrollMemo } from '../hooks/useScreenState'
import { useStageWide } from '../stage/useStage'
import { formatMoneyShort } from '../format'
import { ForeignQuota, SignChip, UpgradeChip } from './TalkParts'
import { foreignRoster, isForeign } from '../../engine/match/lineup'

const REGIONS: ScoutRegion[] = ['JP', 'AS', 'EU', 'SA']
const REGION_FLAGS: Record<ScoutRegion, Nation[]> = { JP: ['JP'], AS: ['KR', 'AU'], EU: ['EN', 'ES'], SA: ['BR', 'AR'] }
const MISSION_WEEKS = 4
const REASON_CLASS: Record<ReportReason, string> = { need: 'bg-gold text-[#2a1a00]', gem: 'bg-good/25 text-good', bargain: 'bg-accent/25 text-accent' }
type Filter = 'all' | ReportReason

function RegionFlags({ r }: { r: ScoutRegion }) {
  return (
    <span className="flex shrink-0 -space-x-1">
      {REGION_FLAGS[r].map((n) => (
        <Flag key={n} nation={n} className="h-[0.8rem] w-[1.2rem]" />
      ))}
    </span>
  )
}

/** スカウトの札: 目利き・人脈（ランク）と、視察の進み具合か派遣のボタン */
function ScoutCard({ state, s, reports }: { state: GameState; s: Staff; reports: ScoutReport[] }) {
  const mutate = useGame((st) => st.mutate)
  const now = currentAbsWeek(state)
  const m = state.scout.missions.find((x) => x.staffId === s.id)
  const judging = s.sub.judging ?? s.ability
  const network = s.sub.network ?? s.ability
  const found = m ? reports.filter((r) => r.staffId === s.id && r.foundAbsWeek >= m.untilAbsWeek - MISSION_WEEKS).length : 0
  const left = m ? Math.max(0, m.untilAbsWeek - now) : 0
  const trip = state.scout.trips?.[s.id]
  return (
    <div className="rounded-xl bg-white/[0.05] p-2 ring-1 ring-white/10">
      <div className="flex items-center gap-2">
        <StaffFace s={s} className="h-12 w-12 shrink-0" photo />
        <div className="min-w-0 flex-1">
          <div className="truncate text-[0.86rem] font-black">{s.name}</div>
          <div className="mt-0.5 flex items-center gap-1 text-[0.68rem] text-ink-dim">
            目利き
            <RankChip value={judging} />
            <span className="ml-1">人脈</span>
            <RankChip value={network} />
          </div>
        </div>
      </div>
      {m ? (
        <div className="mt-1.5 rounded-lg bg-accent/10 px-2 py-1.5">
          <div className="flex items-center gap-1.5 text-[0.74rem] font-bold text-accent">
            <RegionFlags r={m.region} />
            {REGION_LABEL[m.region]}を視察中
            <span className="num ml-auto text-ink-dim">あと {left} 週</span>
          </div>
          <div className="mt-1 h-1.5 overflow-hidden rounded-full bg-black/40">
            <div className="h-full rounded-full bg-accent" style={{ width: `${((MISSION_WEEKS - left) / MISSION_WEEKS) * 100}%` }} />
          </div>
          <div className="mt-0.5 text-[0.68rem] text-ink-dim">今回の報告 {found} 件</div>
        </div>
      ) : (
        <div className="mt-1.5">
          {trip && (
            <div className="mb-1.5 rounded-md bg-black/25 px-1.5 py-1 text-[0.68rem] leading-snug text-ink-dim">
              <span className="flex items-center gap-1">
                前回
                <RegionFlags r={trip.region} />
                {REGION_LABEL[trip.region]}・報告 <b className={trip.count ? 'text-gold' : 'text-ink'}>{trip.count}</b> 件
              </span>
              {trip.count === 0 && <span className="block">獲れそうな選手はいませんでした。格の高い地域の選手は、クラブの格が上がると来てくれます。</span>}
            </div>
          )}
          <div className="mb-1 text-[0.68rem] text-ink-dim">待機中。派遣する地域を選んでください（4 週間）</div>
          <div className="grid grid-cols-2 gap-1">
            {REGIONS.map((r) => (
              <button key={r} className="btn btn-blue btn-sm !min-h-[2.3rem] !justify-start gap-1.5 !px-2 !text-[0.74rem]" onClick={() => mutate((st) => void dispatchScout(st, s.id, r))}>
                <RegionFlags r={r} />
                {REGION_LABEL[r]}
              </button>
            ))}
          </div>
        </div>
      )}
    </div>
  )
}

/** 報告のカード */
function ReportCard({
  state,
  r,
  p,
  spots,
  sign,
  fresh,
  negoBtn,
  onOpen,
}: {
  state: GameState
  r: ScoutReport
  p: Player
  spots: WeakSpots
  sign: Signability
  fresh: boolean
  negoBtn: (p: Player, s?: Signability) => React.ReactNode
  onOpen: (p: Player) => void
}) {
  const mutate = useGame((st) => st.mutate)
  const e = estimate(state, p)
  const up = upgradeOf(state, p, spots, e)
  const club = p.clubId >= 0 ? state.clubs[p.clubId] : null
  const scout = state.staff[r.staffId]
  const left = reportWeeksLeft(state, r)
  const dim = outOfReach(sign)
  const me = state.clubs[state.playerClubId]
  const foreign = isForeign(p, me)
  const foreignFull = foreign && foreignRoster(state, me).full
  return (
    <div className={`relative flex flex-col gap-1.5 rounded-xl p-2 ${up ? 'upgrade-row' : 'bg-white/[0.05] ring-1 ring-white/10'} ${dim ? 'opacity-55' : ''}`}>
      {fresh && <span className="absolute -left-1 -top-1.5 z-10 rounded-full bg-bad px-1.5 text-[0.62rem] font-black text-white shadow">NEW</span>}
      <button className="flex items-center gap-2 text-left" onClick={() => onOpen(p)}>
        <PlayerFace p={p} kit={club?.colors} className="h-11 w-11 shrink-0" />
        <span className="min-w-0 flex-1">
          <span className="flex items-center gap-1">
            <PosBadge pos={p.pos} />
            <span className="truncate text-[0.88rem] font-black">{p.name}</span>
            <Flag nation={p.nation} className="h-[0.75rem] w-[1.1rem]" />
          </span>
          <span className="block truncate text-[0.7rem] text-ink-dim">
            {ageOf(p, currentAbsWeek(state))}歳・{club ? club.short : 'フリー'}・{sign.fee > 0 ? `移籍金 ${formatMoneyShort(sign.fee)}` : '移籍金なし'}
          </span>
        </span>
        <span className="flex shrink-0 flex-col items-end gap-0.5">
          <EstOvr lo={e.ovrLo} hi={e.ovrHi} />
          <Stars value={(e.potLo + e.potHi) / 2} className="text-[0.7rem]" />
        </span>
      </button>
      <div className="flex items-start gap-1.5 rounded-lg bg-black/30 px-1.5 py-1">
        {scout ? <StaffFace s={scout} className="h-6 w-6 shrink-0" /> : <span className="h-6 w-6 shrink-0 rounded-full bg-white/10" />}
        <p className="min-w-0 flex-1 text-[0.74rem] leading-snug">「{scoutComment(state, r, up)}」</p>
      </div>
      <div className="flex flex-wrap items-center gap-1">
        {r.reason !== 'need' && <span className={`rounded px-1.5 text-[0.7rem] font-black ${REASON_CLASS[r.reason]}`}>{REASON_LABEL[r.reason]}</span>}
        {up ? <UpgradeChip up={up} /> : r.reason === 'need' && <span className={`rounded px-1.5 text-[0.7rem] font-black ${REASON_CLASS.need}`}>{REASON_LABEL.need}</span>}
        <SignChip s={sign} />
        {foreign && <span className={`rounded px-1.5 text-[0.7rem] font-bold ${foreignFull ? 'bg-bad/20 text-bad' : 'bg-white/10 text-ink-dim'}`}>{foreignFull ? '外国籍・枠いっぱい' : '外国籍'}</span>}
      </div>
      <div className="flex items-center gap-1.5">
        <div className="min-w-0 flex-1">
          <div className="h-1.5 overflow-hidden rounded-full bg-black/40">
            <div className={`h-full rounded-full ${left <= 2 ? 'bg-bad' : 'bg-gold/80'}`} style={{ width: `${(left / REPORT_WEEKS) * 100}%` }} />
          </div>
          <div className={`num mt-0.5 text-[0.66rem] font-bold ${left <= 2 ? 'text-[#ff9a97]' : 'text-ink-dim'}`}>掲載 あと {left} 週</div>
        </div>
        <button className="h-9 w-9 shrink-0 rounded-lg bg-white/[0.06] text-[1rem] text-gold" aria-label="注目に入れる" onClick={() => mutate((st) => keepReport(st, p.id))}>
          ☆
        </button>
        <button className="h-9 w-8 shrink-0 rounded-lg bg-white/[0.04] text-[0.85rem] text-ink-mute" aria-label="報告から外す" onClick={() => mutate((st) => dropReport(st, p.id))}>
          ✕
        </button>
        {negoBtn(p, sign)}
      </div>
    </div>
  )
}

export function ScoutTab({ state, spots, negoBtn, onOpen }: { state: GameState; spots: WeakSpots; negoBtn: (p: Player, s?: Signability) => React.ReactNode; onOpen: (p: Player) => void }) {
  const mutate = useGame((s) => s.mutate)
  const push = useUi((s) => s.push)
  const wide = useStageWide(760)
  const me = playerClub(state)
  const scouts = clubStaff(state, me).filter((s) => s.role === 'scout')
  const all = reportsOf(state)
  // 開いたときに見ていなかった報告は NEW（すぐ「見た」にしてナビのバッジを消す）
  const [fresh] = useState(() => new Set(all.filter((r) => !r.seen).map((r) => r.playerId)))
  const unseen = all.some((r) => !r.seen)
  useEffect(() => {
    if (unseen) mutate((st) => markReportsSeen(st))
  }, [unseen, mutate])
  const [filter, setFilter] = useScreenState<Filter>('scout:filter', 'all')
  const reportScroll = useScrollMemo('scout')
  const ranks = squadRanks(state)
  const order: Record<ReportReason, number> = { need: 0, gem: 1, bargain: 2 }
  const list = all
    .filter((r) => filter === 'all' || r.reason === filter)
    .map((r) => ({ r, p: state.players[r.playerId] }))
    .filter((x): x is { r: ScoutReport; p: Player } => !!x.p)
    .sort((a, b) => Number(fresh.has(b.r.playerId)) - Number(fresh.has(a.r.playerId)) || order[a.r.reason] - order[b.r.reason] || b.r.foundAbsWeek - a.r.foundAbsWeek)
  const count = (f: ReportReason) => all.filter((r) => r.reason === f).length
  const busy = scouts.filter((s) => state.scout.missions.some((m) => m.staffId === s.id)).length
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[31%] shrink-0 space-y-2 p-2.5">
        <div className="flex items-baseline gap-2">
          <span className="panel-head">スカウト陣</span>
          <span className="ml-auto text-[0.7rem] text-ink-dim">
            視察中 {busy}/{scouts.length}
          </span>
        </div>
        <ForeignQuota state={state} />
        {scouts.length === 0 && <div className="rounded-lg bg-black/25 p-2 text-[0.78rem] text-ink-dim">スカウトがいません。クラブ → スタッフから雇えます。</div>}
        {scouts.map((s) => (
          <ScoutCard key={s.id} state={state} s={s} reports={all} />
        ))}
        <button className="btn btn-ghost btn-sm w-full !text-[0.74rem]" onClick={() => push({ id: 'club', params: { tab: 'staff' } })}>
          スカウトを増やす（クラブ → スタッフ）
        </button>
        <p className="text-[0.68rem] leading-relaxed text-ink-mute">目利きが高いほど能力を正しく見抜き、人脈が広いほど多くの選手を調べます。スカウト事務所のレベルでも調べる人数が増えます。</p>
      </div>
      <div className="panel flex min-w-0 flex-1 flex-col gap-2 p-2">
        <div className="flex shrink-0 flex-wrap items-center gap-2">
          <span className="panel-head">スカウトの報告</span>
          <div className="seg !min-h-0">
            {(
              [
                ['all', `すべて ${all.length}`],
                ['need', `弱点補強 ${count('need')}`],
                ['gem', `伸びしろ ${count('gem')}`],
                ['bargain', `移籍金なし ${count('bargain')}`],
              ] as [Filter, string][]
            ).map(([id, label]) => (
              <button key={id} aria-selected={filter === id} className="!min-h-[2.1rem] !px-2 !text-[0.72rem]" onClick={() => setFilter(id)}>
                {label}
              </button>
            ))}
          </div>
          <span className="ml-auto text-[0.68rem] text-ink-dim">掲載は {REPORT_WEEKS} 週。残したい選手は ☆ で注目へ</span>
        </div>
        <div ref={reportScroll} className="scroll-y min-h-0 flex-1">
          {list.length === 0 ? (
            <div className="flex h-full flex-col items-center justify-center gap-1 p-4 text-center text-[0.8rem] text-ink-dim">
              {all.length === 0 ? 'スカウトを派遣すると、獲る値打ちのある選手を報告してくれます。' : 'この種類の報告はありません。'}
            </div>
          ) : (
            <div className={`grid gap-2 pt-1.5 ${wide ? 'grid-cols-2' : 'grid-cols-1'}`}>
              {list.map(({ r, p }) => (
                <ReportCard key={r.playerId} state={state} r={r} p={p} spots={spots} sign={signability(state, p, ranks)} fresh={fresh.has(r.playerId)} negoBtn={negoBtn} onOpen={onOpen} />
              ))}
            </div>
          )}
        </div>
      </div>
    </div>
  )
}
