/**
 * 一族の記録（M17）: 家系図と、次の世代を選ぶ画面。
 *   LineageTree: 世代ごとの写真・クラブ・タイトル・結婚相手・子ども（キャリア画面の「一族」タブと引退の総括）
 *   NextGenSheet: 引退のあと、次の主人公（サッカーをしている息子）とプレースタイルを選ぶ
 */
import { useState } from 'react'
import type { GameState } from '../../engine'
import { PLAY_STYLES } from '../../engine/data/career'
import type { LineageEntry, PlayStyle } from '../../engine/models/career'
import { beginNextGeneration, genLabel, heirFace, heirs } from '../../engine/career/saga'
import { careerAge } from '../../engine/career/core'
import { Portrait } from '../components/Portrait'
import { castPhotoId, genPhotoFor } from '../components/portraits'
import { Icon } from '../components/Icon'
import { useGame } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

function Gen({ e, now }: { e: LineageEntry | { gen: number; name: string; photo?: string; age: number; current: true }; now?: boolean }) {
  const photo = e.photo ? genPhotoFor(e.photo, 'retiredAge' in e ? e.retiredAge : e.age) : undefined
  return (
    <div className={`flex w-[9.5rem] shrink-0 flex-col items-center rounded-xl p-2 text-center ${now ? 'bg-gold/10 ring-1 ring-gold/50' : 'bg-black/25'}`}>
      <div className="text-[0.7rem] font-bold tracking-widest text-gold">{genLabel(e.gen)}</div>
      {photo ? <Portrait id={photo} kind="face" className="face-round mt-1 h-14 w-14" /> : <div className="mt-1 h-14 w-14 rounded-full bg-white/10" />}
      <div className="mt-1 text-[0.82rem] font-black">{e.name}</div>
      {'retiredAge' in e ? (
        <>
          <div className="text-[0.7rem] text-ink-dim">
            評価 <b className="text-gold">{e.grade}</b>・{e.retiredAge} 歳で引退
          </div>
          <div className="num text-[0.7rem] text-ink-dim">
            {e.apps} 試合 {e.goals} 点{e.caps ? `・代表 ${e.caps}` : ''}
          </div>
          {e.clubs.length > 0 && <div className="mt-0.5 line-clamp-2 text-[0.68rem] text-ink-mute">{e.clubs.join(' → ')}</div>}
          {e.titles.length > 0 && <div className="mt-0.5 text-[0.7rem] font-bold text-gold">★ タイトル {e.titles.length}</div>}
          {e.spouse && (
            <div className="mt-1 flex items-center gap-1 text-[0.7rem]">
              <Portrait id={castPhotoId(e.spouse, e.spouse)} kind="face" className="face-round h-6 w-6" />
              {e.spouseName ?? e.spouse}
            </div>
          )}
          {e.children.length > 0 && <div className="text-[0.68rem] text-ink-dim">子ども: {e.children.join('、')}</div>}
        </>
      ) : (
        <div className="text-[0.7rem] text-ink-dim">{e.age} 歳・現役</div>
      )}
    </div>
  )
}

/** 家系図（世代を横に並べる。いまの主人公が最後） */
export function LineageTree({ state }: { state: GameState }) {
  const c = state.career!
  const list = c.lineage ?? []
  const p = state.players[c.playerId]
  const gen = c.saga?.gen ?? 1
  // 引退して記録に入った本人は、二重に出さない
  const showCurrent = !list.some((l) => l.playerId === p.id)
  return (
    <div className="scroll-x flex items-stretch gap-1.5 pb-1">
      {list.map((e, i) => (
        <div key={i} className="flex items-center gap-1.5">
          <Gen e={e} />
          <Icon name="forward" className="h-4 w-4 shrink-0 text-ink-mute" />
        </div>
      ))}
      {showCurrent && <Gen e={{ gen, name: p.name, photo: p.face?.photo, age: careerAge(state), current: true }} now />}
    </div>
  )
}

/** 次の世代へ（息子とプレースタイルを選ぶ） */
export function NextGenSheet({ state, onClose }: { state: GameState; onClose: () => void }) {
  const mutate = useGame((s) => s.mutate)
  const reset = useUi((s) => s.reset)
  const c = state.career!
  const list = heirs(state)
  const father = state.players[c.playerId]
  const gen = c.saga?.gen ?? 1
  const [idx, setIdx] = useState(list[0]?.idx ?? 0)
  const [style, setStyle] = useState<PlayStyle>(c.style)
  const heir = list.find((x) => x.idx === idx)
  if (!heir) return null
  const face = genPhotoFor(heirFace(state, gen + 1, father.face?.photo), heir.age)
  const start = () => {
    mutate((st) => beginNextGeneration(st, idx, style))
    reset({ id: 'home' })
  }
  return (
    <div className="anim-fade absolute inset-0 z-40 flex items-center justify-center bg-black/70 p-3">
      <div className="panel flex max-h-full w-full max-w-[44rem] gap-3 overflow-hidden p-3">
        <div className="flex w-[34%] shrink-0 flex-col items-center gap-1.5 text-center">
          <div className="text-[0.72rem] font-bold tracking-widest text-gold">{genLabel(gen + 1)}の物語</div>
          <Portrait id={face} kind="face" className="face-round h-20 w-20" />
          <div className="text-[1.05rem] font-black">
            {father.name.split(/\s+/)[0]} {heir.child.name}
          </div>
          <div className="text-[0.78rem] text-ink-dim">
            {heir.age} 歳・才能 <span className="text-gold">{'★'.repeat(Math.max(1, heir.child.talent ?? 1))}</span>
          </div>
          <div className="text-[0.72rem] leading-snug text-ink-mute">
            {heir.age < 15 ? `15 歳になるまでは、親として 1 か月ごとに練習の方針を選んで見守ります。` : heir.age < 18 ? '15 歳。ユースのチームで、息子が主人公になります。' : '18 歳。プロのクラブへの入団から始まります。'}
          </div>
          {list.length > 1 && (
            <div className="mt-1 flex flex-wrap justify-center gap-1">
              {list.map((x) => (
                <button key={x.idx} className={`rounded-lg px-2 py-1 text-[0.78rem] font-bold ${x.idx === idx ? 'bg-gold/20 text-gold ring-1 ring-gold/60' : 'bg-white/[0.06]'}`} onClick={() => setIdx(x.idx)}>
                  {x.child.name}（{x.age}）
                </button>
              ))}
            </div>
          )}
        </div>
        <div className="flex min-w-0 flex-1 flex-col gap-1.5">
          <div className="panel-head">プレースタイル</div>
          <div className="scroll-y grid min-h-0 grid-cols-2 gap-1.5">
            {PLAY_STYLES.map((s) => (
              <button key={s.id} className={`rounded-lg px-2.5 py-1.5 text-left ${style === s.id ? 'bg-gold/15 ring-1 ring-gold/60' : 'bg-white/[0.04]'}`} onClick={() => setStyle(s.id)}>
                <div className="text-[0.82rem] font-bold">{s.name}</div>
                <div className="text-[0.68rem] leading-snug text-ink-dim">{s.desc}</div>
              </button>
            ))}
          </div>
          <div className="mt-auto flex justify-end gap-2 pt-1">
            <button className="btn btn-ghost" onClick={onClose}>
              もどる
            </button>
            <button className="btn btn-gold min-w-[10rem]" onClick={start}>
              <Icon name="forward" className="h-5 w-5" />
              {heir.child.name}の物語へ
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}
