/** 交渉の部品（M20）: 見込みのメーター・判定のバー・乗り気の決め手・獲得の札・弱点補強の札 */
import type { WillFactor } from '../../engine/transfer/market'
import type { Signability } from '../../engine/transfer/talks'
import { oddsLabel } from '../../engine/transfer/talks'
import type { Upgrade } from '../../engine/transfer/recommend'
import { chanceColor } from './talkColor'
import type { GameState } from '../../engine'
import { foreignRoster } from '../../engine/match/lineup'


/** 半円のメーター（左 0% → 右 100%）。針はなめらかに動く */
export function ChanceGauge({ value, title, thinking = false }: { value: number; title: string; thinking?: boolean }) {
  const v = Math.max(0, Math.min(1, value))
  const pct = Math.round(v * 100)
  return (
    <div className="flex items-center gap-3">
      <div className="relative h-[4.6rem] w-[8.4rem] shrink-0">
        <svg viewBox="0 0 200 112" className="absolute inset-0 h-full w-full" aria-hidden>
          <defs>
            <linearGradient id="talk-gauge" x1="0" x2="1" y1="0" y2="0">
              <stop offset="0" stopColor="#ef5350" />
              <stop offset="0.45" stopColor="#f5c542" />
              <stop offset="1" stopColor="#3ddc84" />
            </linearGradient>
          </defs>
          <path d="M 18 100 A 82 82 0 0 1 182 100" fill="none" stroke="rgba(255,255,255,0.09)" strokeWidth="16" strokeLinecap="round" />
          <path d="M 18 100 A 82 82 0 0 1 182 100" fill="none" stroke="url(#talk-gauge)" strokeWidth="16" strokeLinecap="round" pathLength={100} strokeDasharray={`${Math.max(0.01, pct)} 100`} style={{ transition: 'stroke-dasharray 0.45s ease' }} />
          <g style={{ transform: `rotate(${-90 + v * 180}deg)`, transformOrigin: '100px 100px', transition: 'transform 0.5s cubic-bezier(0.3, 1.5, 0.5, 1)' }}>
            <line x1="100" y1="100" x2="100" y2="30" stroke="#fff" strokeWidth="5" strokeLinecap="round" />
          </g>
          <circle cx="100" cy="100" r="9" fill="#fff" />
        </svg>
      </div>
      <div className="min-w-0">
        <div className="text-[0.72rem] text-ink-dim">{title}</div>
        <div className="num text-[1.9rem] font-black leading-none" style={{ color: chanceColor(v) }}>
          {pct}
          <span className="text-[1rem]">%</span>
        </div>
        {thinking ? (
          <div className="mt-0.5 animate-pulse text-[0.82rem] font-black text-white">相手が考えている…</div>
        ) : (
          <div className="mt-0.5 text-[0.78rem] font-bold" style={{ color: chanceColor(v) }}>
            {oddsLabel(v)}
          </div>
        )}
      </div>
    </div>
  )
}

/**
 * 判定のバー: 緑の幅が見込み。針が左右に振れて、サイコロの目で止まる（緑の中なら成立）。
 * phase: idle（見込みだけ）/ spin（考え中）/ land（止まる）
 */
export function DiceBar({ chance, roll, phase }: { chance: number; roll?: number; phase: 'idle' | 'spin' | 'land' }) {
  const c = Math.max(0, Math.min(1, chance))
  return (
    <div className="relative h-4 overflow-hidden rounded-full bg-bad/25">
      <div className="absolute inset-y-0 left-0 rounded-full bg-good/60" style={{ width: `${c * 100}%`, transition: 'width 0.4s ease' }} />
      {phase !== 'idle' && (
        <div
          className={`absolute inset-y-[-0.1rem] w-1.5 -translate-x-1/2 rounded-full bg-white shadow-[0_0_0.5rem_rgba(255,255,255,0.9)] ${phase === 'spin' ? 'dice-sweep' : ''}`}
          style={phase === 'land' ? { left: `${Math.max(2, Math.min(98, (roll ?? 0) * 100))}%`, transition: 'left 0.6s cubic-bezier(0.2, 0.9, 0.3, 1)' } : undefined}
        />
      )}
    </div>
  )
}

/** 乗り気の決め手（＋は右へ緑、−は左へ赤） */
export function FactorList({ factors }: { factors: WillFactor[] }) {
  const max = Math.max(0.5, ...factors.map((f) => Math.abs(f.value)))
  const sorted = [...factors].sort((a, b) => Math.abs(b.value) - Math.abs(a.value))
  if (!sorted.length) return <div className="text-[0.74rem] text-ink-mute">目立った決め手はありません。</div>
  return (
    <div className="space-y-1">
      {sorted.map((f) => {
        const w = (Math.abs(f.value) / max) * 50
        const plus = f.value > 0
        return (
          <div key={f.key} className="text-[0.74rem]">
            <div className="flex items-center gap-1">
              <span className={`w-4 shrink-0 text-center font-black ${plus ? 'text-good' : 'text-bad'}`}>{plus ? '＋' : '−'}</span>
              <span className="min-w-0 flex-1 truncate">{f.label}</span>
              <span className={`num shrink-0 text-[0.7rem] font-bold ${plus ? 'text-good' : 'text-bad'}`}>{Math.abs(f.value) >= 0.3 ? '大' : Math.abs(f.value) >= 0.12 ? '中' : '小'}</span>
            </div>
            <div className="relative ml-5 h-1.5 rounded-full bg-white/[0.06]">
              <div className="absolute inset-y-0 left-1/2 w-px bg-white/25" />
              <div className={`absolute inset-y-0 rounded-full ${plus ? 'bg-good' : 'bg-bad'}`} style={plus ? { left: '50%', width: `${w}%` } : { right: '50%', width: `${w}%` }} />
            </div>
          </div>
        )
      })}
    </div>
  )
}

const TONE: Record<Signability['tone'], string> = {
  good: 'bg-good/20 text-good',
  info: 'bg-accent/20 text-accent',
  warn: 'bg-[#f59e42]/20 text-[#f8b26a]',
  bad: 'bg-bad/20 text-bad',
  mute: 'bg-white/10 text-ink-dim',
}

/** 獲得できそうかの札 */
export function SignChip({ s, className = '' }: { s: Signability; className?: string }) {
  return <span className={`inline-block whitespace-nowrap rounded px-1.5 text-[0.7rem] font-bold ${TONE[s.tone]} ${className}`}>{s.label}</span>
}

/** 外国人枠（日本のクラブ）: 在籍の外国籍の人数と、いっぱいかどうか */
export function ForeignQuota({ state, className = '' }: { state: GameState; className?: string }) {
  const me = state.clubs[state.playerClubId]
  const f = foreignRoster(state, me)
  if (f.limit === Infinity) return me.leagueId === 'WL' ? <div className={`rounded-lg bg-good/10 px-2 py-1 text-[0.72rem] text-good ${className}`}>外国人枠なし（ワールドリーグ）</div> : null
  return (
    <div className={`rounded-lg px-2 py-1 text-[0.72rem] ${f.full ? 'bg-bad/15 text-[#ffb3b0]' : 'bg-black/25 text-ink-dim'} ${className}`}>
      外国人枠 在籍 <b className="num">{f.roster}</b>/{f.limit}
      {f.full ? '・いっぱい（外国籍は大きな補強だけ）' : `・あと ${f.limit - f.roster} 人`}
    </div>
  )
}

/** 弱点補強の札（大きく、金色） */
export function UpgradeChip({ up, big = false, compact = false }: { up: Upgrade; big?: boolean; compact?: boolean }) {
  const strong = up.gain >= 8
  return (
    <span className={`inline-flex items-center gap-1 whitespace-nowrap rounded-md bg-gradient-to-b from-[#ffd968] to-[#e0a92a] font-black text-[#2a1a00] shadow-[0_0_0.6rem_rgba(245,197,66,0.35)] ${big ? 'px-2 py-0.5 text-[0.82rem]' : 'px-1.5 text-[0.72rem]'}`}>
      {compact ? '補強' : strong ? '大幅補強' : '弱点補強'} {up.pos}
      <span className="num font-bold opacity-80">
        {Math.round(up.from)}→{Math.round(up.to)}
      </span>
    </span>
  )
}
