/** 自動生成の顔（画像のない選手・スタッフ用）。未指定の項目は id から決定的に選ぶ。 */
export type BeardStyle = 'none' | 'stubble' | 'goatee' | 'full' | 'mustache'

export interface FaceSpec {
  skin?: number
  hair?: number
  hairColor?: string
  beard?: BeardStyle
  glasses?: boolean
  headband?: boolean
  /** 生成した写真の id（portraitManifest の gen）。あれば自動の顔の代わりに出す */
  photo?: string
}

export type Mood = 'happy' | 'normal' | 'flat' | 'sad' | 'hurt'

/** 調子（0-100）と怪我から表情を決める */
export function moodOf(condition: number, injured: boolean): Mood {
  if (injured) return 'hurt'
  if (condition >= 78) return 'happy'
  if (condition >= 50) return 'normal'
  if (condition >= 35) return 'flat'
  return 'sad'
}
