/**
 * 戦術: フォーメーションと先発の入れ替え、戦術のプリセットと細かい調整。
 * スロット → スロット、またはスロット → 控えの順にタップして入れ替える。
 */
import { useState } from 'react'
import {
  FORMATIONS,
  TACTIC_PRESETS,
  autoLineup,
  foreignCount,
  FOREIGN_LIMIT,
  closestPreset,
  isAvailable,
  ovr,
  playerClub,
  refitLineup,
  squadOf,
  type Lineup,
  type Tactics,
} from '../../engine'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { FormationPitch } from '../components/FormationPitch'
import { OvrBadge, PosBadge } from '../components/common'
import { PlayerFace } from '../components/PersonFace'
import { useGame, useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'

const LEVELS = [
  { v: 15, label: '低' },
  { v: 32, label: 'やや低' },
  { v: 50, label: '普通' },
  { v: 68, label: 'やや高' },
  { v: 85, label: '高' },
]

function LevelPicker({ label, value, onChange }: { label: string; value: number; onChange: (v: number) => void }) {
  const near = LEVELS.reduce((b, l) => (Math.abs(l.v - value) < Math.abs(b.v - value) ? l : b))
  return (
    <div className="flex items-center gap-2">
      <span className="w-[4.4rem] shrink-0 text-[0.75rem] text-ink-dim">{label}</span>
      <div className="seg flex-1 !p-0.5">
        {LEVELS.map((l) => (
          <button key={l.v} aria-selected={near.v === l.v} onClick={() => onChange(l.v)} className="!min-h-[2.1rem] flex-1 !px-0 !text-[0.74rem]">
            {l.label}
          </button>
        ))}
      </div>
    </div>
  )
}

export function TacticsScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const back = !!useCurrentScreen().params?.back
  const pop = useUi((s) => s.pop)
  const club = playerClub(state)
  const [sel, setSel] = useState<number | null>(null)
  const [tab, setTab] = useState<'members' | 'tactics'>('members')

  const save = (lineup: Lineup, tactics?: Tactics) =>
    mutate((st) => {
      const c = st.clubs[st.playerClubId]
      c.lineup = lineup
      if (tactics) c.tactics = tactics
    })
  const setTactics = (patch: Partial<Tactics>) => save(club.lineup, { ...club.tactics, ...patch })

  const tapSlot = (i: number) => {
    if (sel === null) return setSel(i)
    if (sel === i) return setSel(null)
    const st = [...club.lineup.starters]
    ;[st[sel], st[i]] = [st[i], st[sel]]
    save({ ...club.lineup, starters: st, manual: true })
    setSel(null)
  }
  const tapBench = (id: number) => {
    if (sel === null) return
    const st = [...club.lineup.starters]
    const out = st[sel]
    st[sel] = id
    const bench = club.lineup.bench.filter((b) => b !== id)
    if (out > 0) bench.unshift(out)
    save({ ...club.lineup, starters: st, bench: bench.slice(0, 9), manual: true })
    setSel(null)
  }

  const starters = new Set(club.lineup.starters)
  const others = squadOf(state, club.id)
    .filter((p) => !starters.has(p.id))
    .sort((a, b) => Number(club.lineup.bench.includes(b.id)) - Number(club.lineup.bench.includes(a.id)) || ovr(b) - ovr(a))
  const preset = closestPreset(club.tactics)

  return (
    <AppShell title="戦術・メンバー" current="tactics" back={back} right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="flex min-w-0 flex-[1.2] flex-col gap-2">
          <div className="min-h-0 flex-1">
            <FormationPitch state={state} formation={club.tactics.formation} lineup={club.lineup} kit={club.colors} selected={sel} onSlot={tapSlot} />
          </div>
          <div className="flex items-center gap-2">
            <span className="text-[0.78rem] text-ink-dim">{sel === null ? '入れ替える選手をタップ' : '入れ替え先（ピッチか控え）をタップ'}</span>
            <span className={`num rounded px-1.5 py-0.5 text-[0.74rem] font-bold ${foreignCount(state, club) > FOREIGN_LIMIT ? 'bg-bad/25 text-bad' : 'bg-black/30 text-ink-dim'}`}>
              外国籍 {foreignCount(state, club)}/{FOREIGN_LIMIT}
            </span>
            <button
              className="btn btn-ghost btn-sm ml-auto"
              onClick={() => {
                save({ ...autoLineup(state, club), manual: false })
                setSel(null)
              }}
            >
              おまかせで選ぶ
            </button>
            {back && (
              <button className="btn btn-gold btn-sm" onClick={pop}>
                決定
              </button>
            )}
          </div>
        </div>

        <div className="panel flex w-[40%] shrink-0 flex-col p-2.5">
          <div className="seg mb-2 self-start">
            <button aria-selected={tab === 'members'} onClick={() => setTab('members')}>
              控え・メンバー
            </button>
            <button aria-selected={tab === 'tactics'} onClick={() => setTab('tactics')}>
              戦術
            </button>
          </div>
          {tab === 'members' ? (
            <div className="scroll-y min-h-0 flex-1 space-y-1 pr-1">
              {others.map((p) => {
                const onBench = club.lineup.bench.includes(p.id)
                const ok = isAvailable(p)
                return (
                  <button key={p.id} disabled={!ok} onClick={() => tapBench(p.id)} className={`flex w-full items-center gap-2 rounded-lg px-1.5 py-1 text-left ${sel !== null && ok ? 'bg-gold/10 hover:bg-gold/20' : 'bg-white/[0.04]'} disabled:opacity-40`}>
                    <PlayerFace p={p} kit={club.colors} className="h-8 w-8 shrink-0" />
                    <PosBadge pos={p.pos} />
                    <span className="min-w-0 flex-1 truncate text-[0.8rem] font-bold">{p.name}</span>
                    {onBench && <span className="rounded bg-accent/20 px-1 text-[0.66rem] font-bold text-accent">控え</span>}
                    {p.injury && <span className="rounded bg-bad/20 px-1 text-[0.66rem] font-bold text-bad">負傷</span>}
                    {p.suspension > 0 && <span className="rounded bg-warn/20 px-1 text-[0.66rem] font-bold text-warn">停止</span>}
                    <OvrBadge value={ovr(p)} size="sm" />
                  </button>
                )
              })}
            </div>
          ) : (
            <div className="scroll-y min-h-0 flex-1 space-y-2.5 pr-1">
              <div>
                <div className="panel-head mb-1">フォーメーション</div>
                <div className="grid grid-cols-5 gap-1">
                  {FORMATIONS.map((f) => (
                    <button
                      key={f.id}
                      onClick={() => save(refitLineup(state, club, f.id), { ...club.tactics, formation: f.id })}
                      className={`rounded-md border py-1.5 text-[0.74rem] font-bold ${club.tactics.formation === f.id ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}
                    >
                      {f.name.replace(' ダイヤ', '◇')}
                    </button>
                  ))}
                </div>
              </div>
              <div>
                <div className="panel-head mb-1">作戦</div>
                <div className="grid grid-cols-4 gap-1">
                  {TACTIC_PRESETS.map((p) => (
                    <button key={p.id} title={p.desc} onClick={() => setTactics(p.values)} className={`rounded-md border px-0.5 py-1.5 text-[0.72rem] font-bold leading-tight ${preset?.id === p.id ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                      {p.name}
                    </button>
                  ))}
                </div>
                {preset && <p className="mt-1 text-[0.74rem] text-ink-dim">{preset.desc}</p>}
              </div>
              <div className="space-y-1.5">
                <div className="flex items-center gap-2">
                  <span className="w-[4.4rem] shrink-0 text-[0.75rem] text-ink-dim">攻撃意識</span>
                  <div className="seg flex-1 !p-0.5">
                    {[-2, -1, 0, 1, 2].map((v) => (
                      <button key={v} aria-selected={club.tactics.mentality === v} onClick={() => setTactics({ mentality: v })} className="!min-h-[2.1rem] flex-1 !px-0 !text-[0.74rem]">
                        {['守備的', 'やや守', '普通', 'やや攻', '攻撃的'][v + 2]}
                      </button>
                    ))}
                  </div>
                </div>
                <LevelPicker label="攻撃の速さ" value={club.tactics.tempo} onChange={(v) => setTactics({ tempo: v })} />
                <LevelPicker label="攻撃の幅" value={club.tactics.width} onChange={(v) => setTactics({ width: v })} />
                <LevelPicker label="最終ライン" value={club.tactics.lineHeight} onChange={(v) => setTactics({ lineHeight: v })} />
                <LevelPicker label="プレス" value={club.tactics.pressing} onChange={(v) => setTactics({ pressing: v })} />
              </div>
            </div>
          )}
        </div>
      </div>
    </AppShell>
  )
}
