/** クラブの記録: 歩み・タイトル・通算記録・殿堂・歴代優勝。 */
import { useState } from 'react'
import { playerClub, seasonLabel, type GameState, type Nation, type Player } from '../../engine'
import type { MatchRecord } from '../../engine/models/game'
import { clubCareer } from '../../engine/club/records'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Emblem } from '../components/ClubArt'
import { PlayerFace } from '../components/PersonFace'
import { Flag, PosBadge } from '../components/common'
import { Icon } from '../components/Icon'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen } from '../../stores/uiStore'
import { formatMoney } from '../format'

type Tab = 'history' | 'trophies' | 'alltime' | 'hof' | 'champions'
const TABS: [Tab, string][] = [
  ['history', 'クラブの歩み'],
  ['trophies', 'タイトル'],
  ['alltime', '通算記録'],
  ['hof', '殿堂'],
  ['champions', '歴代優勝'],
]

const COMP_SHORT: Record<string, string> = { NPL1: 'NPL1', NPL2: 'NPL2', NPL3: 'NPL3', CUP: 'カップ', ACC: 'アジア', WCC: '世界', EUC: '欧州' }
/** トロフィーの色（大会ごと） */
const TROPHY_COLOR: Record<string, string> = { WCC: '#f5c542', ACC: '#2dd4bf', EUC: '#93c5fd', CUP: '#f87171', NPL1: '#facc15', NPL2: '#cbd5e1', NPL3: '#d6a46a' }

function clubShort(state: GameState, id: number | undefined): string {
  return id !== undefined && id >= 0 ? (state.clubs[id]?.short ?? '―') : '―'
}

/** 自クラブにいたことのある選手（今いる選手と、履歴に残っている選手） */
function clubPlayers(state: GameState): Player[] {
  const me = state.playerClubId
  return Object.values(state.players).filter((p) => p.clubId === me || p.history.some((h) => h.clubId === me))
}

function HistoryTab({ state }: { state: GameState }) {
  const me = state.playerClubId
  const players = clubPlayers(state)
  const rows = [...state.seasons].reverse()
  return (
    <div className="panel scroll-y min-h-0 flex-1 p-2">
      <div className="sticky top-0 z-10 flex items-center gap-2 bg-panel/95 px-2 py-1 text-[0.72rem] font-bold text-ink-mute">
        <span className="w-[4.2rem]">シーズン</span>
        <span className="w-[6.5rem]">リーグ</span>
        <span className="w-[5.5rem]">カップ</span>
        <span className="w-[5.5rem]">アジア</span>
        <span className="w-[5rem]">世界</span>
        <span className="min-w-0 flex-1">チーム得点王</span>
      </div>
      {rows.length === 0 && <div className="p-2 text-[0.8rem] text-ink-mute">まだ終わったシーズンはありません。</div>}
      {rows.map((s) => {
        const acc = s.continental?.find((c) => c.compId === 'ACC')
        const wcc = s.continental?.find((c) => c.compId === 'WCC')
        let top: { p: Player; goals: number } | null = null
        for (const p of players) {
          const h = p.history.find((x) => x.season === s.season && x.clubId === me)
          if (h && h.goals > 0 && (!top || h.goals > top.goals)) top = { p, goals: h.goals }
        }
        const promoted = s.promoted.includes(me)
        const relegated = s.relegated.includes(me)
        return (
          <div key={s.season} className="flex items-center gap-2 border-b border-white/5 px-2 py-[0.35rem] text-[0.78rem]">
            <span className="num w-[4.2rem] text-ink-dim">{seasonLabel(state.startYear, s.season)}</span>
            <span className="w-[6.5rem]">
              <span className="font-bold">{COMP_SHORT[s.leagueId] ?? s.leagueId}</span>
              <span className={`num ml-1 font-black ${s.rank === 1 ? 'text-gold' : ''}`}>{s.rank}位</span>
              {promoted && <span className="ml-1 text-[0.72rem] text-good">昇格</span>}
              {relegated && <span className="ml-1 text-[0.72rem] text-bad">降格</span>}
            </span>
            <span className={`w-[5.5rem] truncate ${s.cup?.stage === '優勝' ? 'font-black text-gold' : 'text-ink-dim'}`}>{s.cup?.stage ?? '―'}</span>
            <span className={`w-[5.5rem] truncate ${acc?.stage === '優勝' ? 'font-black text-gold' : 'text-ink-dim'}`}>{acc?.stage ?? '―'}</span>
            <span className={`w-[5rem] truncate ${wcc?.stage === '優勝' ? 'font-black text-gold' : 'text-ink-dim'}`}>{wcc?.stage ?? '―'}</span>
            <span className="min-w-0 flex-1 truncate">{top ? `${top.p.name}（${top.goals}点）` : '―'}</span>
          </div>
        )
      })}
    </div>
  )
}

function TrophiesTab({ state }: { state: GameState }) {
  const groups = new Map<string, { name: string; seasons: number[] }>()
  for (const t of state.trophies ?? []) {
    const g = groups.get(t.compId) ?? { name: t.name, seasons: [] }
    g.seasons.push(t.season)
    groups.set(t.compId, g)
  }
  const order = ['WCC', 'ACC', 'NPL1', 'CUP', 'NPL2', 'NPL3']
  const list = [...groups.entries()].sort((a, b) => order.indexOf(a[0]) - order.indexOf(b[0]))
  return (
    <div className="panel scroll-y min-h-0 flex-1 p-3">
      {list.length === 0 && <div className="text-[0.85rem] text-ink-dim">まだタイトルはありません。最初のトロフィーを目指しましょう。</div>}
      <div className="grid grid-cols-3 gap-2">
        {list.map(([id, g]) => (
          <div key={id} className="flex items-center gap-3 rounded-xl border border-line/50 bg-black/25 p-3">
            <span className="shrink-0" style={{ color: TROPHY_COLOR[id] ?? '#f5c542' }}>
              <Icon name="trophy" className="h-10 w-10" />
            </span>
            <div className="min-w-0">
              <div className="truncate text-[0.85rem] font-black">{g.name}</div>
              <div className="num text-[1.3rem] font-black text-gold">×{g.seasons.length}</div>
              <div className="truncate text-[0.7rem] text-ink-dim">{g.seasons.map((s) => seasonLabel(state.startYear, s)).join('・')}</div>
            </div>
          </div>
        ))}
      </div>
    </div>
  )
}

function MatchRec({ state, label, m }: { state: GameState; label: string; m?: MatchRecord }) {
  return (
    <div className="flex items-center gap-2 py-0.5 text-[0.76rem]">
      <span className="w-[6.5rem] shrink-0 text-ink-dim">{label}</span>
      {m ? (
        <span className="min-w-0 truncate">
          <span className="num font-black">
            {m.gf}-{m.ga}
          </span>
          <span className="ml-1">vs {clubShort(state, m.opponent)}</span>
          <span className="ml-1 text-[0.72rem] text-ink-dim">
            （{seasonLabel(state.startYear, m.season)}・{COMP_SHORT[m.compId] ?? m.compId}）
          </span>
        </span>
      ) : (
        <span className="text-ink-mute">―</span>
      )}
    </div>
  )
}

type CareerRow = { p: Player; apps: number; goals: number }

/** 通算の上位（いまいる選手ははっきり、去った選手は薄く） */
function RankList({ list, field, myClub }: { list: CareerRow[]; field: 'goals' | 'apps'; myClub: number }) {
  return (
    <div className="space-y-0.5">
      {list.length === 0 && <div className="text-[0.75rem] text-ink-mute">まだ記録がありません</div>}
      {list.map((c, i) => (
        <div key={c.p.id} className={`flex items-center gap-1.5 rounded px-1 py-0.5 text-[0.75rem] ${c.p.clubId === myClub ? '' : 'opacity-75'}`}>
          <span className="num w-4 text-center font-black text-ink-dim">{i + 1}</span>
          <PosBadge pos={c.p.pos} />
          <span className="min-w-0 flex-1 truncate font-bold">{c.p.name}</span>
          <span className="num font-black">{c[field]}</span>
          <span className="w-6 text-[0.68rem] text-ink-dim">{field === 'goals' ? '点' : '試合'}</span>
        </div>
      ))}
    </div>
  )
}

function AllTimeTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const r = state.records
  const career = clubPlayers(state).map((p) => ({ p, ...clubCareer(state, p) }))
  const scorers = [...career].filter((c) => c.goals > 0).sort((a, b) => b.goals - a.goals || b.apps - a.apps).slice(0, 10)
  const apps = [...career].filter((c) => c.apps > 0).sort((a, b) => b.apps - a.apps).slice(0, 10)
  const t = r?.total
  return (
    <div className="flex min-h-0 flex-1 gap-3">
      <div className="panel scroll-y w-[40%] shrink-0 p-3">
        <div className="panel-head mb-1">公式戦の通算</div>
        {t && (
          <div className="num text-[0.85rem] font-bold">
            {t.played} 試合 {t.won} 勝 {t.drawn} 分 {t.lost} 敗<span className="ml-2 text-ink-dim">得点 {t.gf}・失点 {t.ga}</span>
          </div>
        )}
        <div className="panel-head mb-1 mt-2">クラブ記録</div>
        <MatchRec state={state} label="最大得点差の勝利" m={r?.biggestWin} />
        <MatchRec state={state} label="最大得点差の敗戦" m={r?.worstLoss} />
        <MatchRec state={state} label="1 試合の最多得点" m={r?.mostGoalsMatch} />
        <div className="flex items-center gap-2 py-0.5 text-[0.76rem]">
          <span className="w-[6.5rem] shrink-0 text-ink-dim">最多観客</span>
          <span className="truncate">{r?.topAttendance ? `${r.topAttendance.value.toLocaleString()} 人（vs ${clubShort(state, r.topAttendance.opponent)}）` : '―'}</span>
        </div>
        <div className="flex items-center gap-2 py-0.5 text-[0.76rem]">
          <span className="w-[6.5rem] shrink-0 text-ink-dim">シーズン最多得点</span>
          <span className="truncate">{r?.mostGoalsSeason ? `${r.mostGoalsSeason.name} ${r.mostGoalsSeason.goals} 点（${seasonLabel(state.startYear, r.mostGoalsSeason.season)}）` : '―'}</span>
        </div>
        <div className="flex items-center gap-2 py-0.5 text-[0.76rem]">
          <span className="w-[6.5rem] shrink-0 text-ink-dim">最高額の獲得</span>
          <span className="truncate">{r?.recordSigning ? `${r.recordSigning.name} ${formatMoney(r.recordSigning.fee)}` : '―'}</span>
        </div>
        <div className="flex items-center gap-2 py-0.5 text-[0.76rem]">
          <span className="w-[6.5rem] shrink-0 text-ink-dim">最高額の売却</span>
          <span className="truncate">{r?.recordSale ? `${r.recordSale.name} ${formatMoney(r.recordSale.fee)}` : '―'}</span>
        </div>
      </div>
      <div className="panel scroll-y min-w-0 flex-1 p-3">
        <div className="grid grid-cols-2 gap-3">
          <div>
            <div className="panel-head mb-1">通算得点</div>
            <RankList list={scorers} field="goals" myClub={me.id} />
          </div>
          <div>
            <div className="panel-head mb-1">通算出場</div>
            <RankList list={apps} field="apps" myClub={me.id} />
          </div>
        </div>
      </div>
    </div>
  )
}

function HofTab({ state }: { state: GameState }) {
  const me = playerClub(state)
  const list = [...(state.hallOfFame ?? [])].reverse()
  return (
    <div className="panel scroll-y min-h-0 flex-1 p-3">
      <p className="mb-2 text-[0.78rem] text-ink-dim">クラブで 120 試合以上に出場、50 得点以上、またはリーグ MVP・得点王に輝いた選手が、引退するときに殿堂入りします。</p>
      {list.length === 0 && <div className="text-[0.85rem] text-ink-mute">殿堂入りした選手はまだいません。</div>}
      <div className="grid grid-cols-2 gap-2">
        {list.map((h) => {
          const p = state.players[h.playerId]
          return (
            <div key={h.playerId} className="flex items-center gap-3 rounded-xl border border-gold/40 bg-gold/5 p-2">
              {p ? <PlayerFace p={p} kit={me.colors} className="h-14 w-14 shrink-0" /> : <div className="h-14 w-14 shrink-0 rounded-full bg-black/30" />}
              <div className="min-w-0 flex-1">
                <div className="flex items-center gap-1.5">
                  <Flag nation={h.nation as Nation} />
                  <span className="truncate text-[0.9rem] font-black">{h.name}</span>
                </div>
                <div className="num text-[0.78rem] text-ink-dim">
                  {h.pos}・{h.apps} 試合 {h.goals} 得点
                </div>
                <div className="text-[0.76rem] text-gold">
                  {h.reason}（{seasonLabel(state.startYear, h.season)} 殿堂入り）
                </div>
              </div>
            </div>
          )
        })}
      </div>
    </div>
  )
}

function ChampionsTab({ state }: { state: GameState }) {
  const me = state.playerClubId
  const cols = ['NPL1', 'NPL2', 'NPL3', 'CUP', 'ACC', 'WCC', 'EUC']
  const rows = [...state.seasons].reverse()
  return (
    <div className="panel scroll-y min-h-0 flex-1 p-2">
      <div className="sticky top-0 z-10 flex items-center gap-1 bg-panel/95 px-2 py-1 text-[0.72rem] font-bold text-ink-mute">
        <span className="w-[4.2rem]">シーズン</span>
        {cols.map((c) => (
          <span key={c} className="min-w-0 flex-1 truncate">
            {COMP_SHORT[c]}
          </span>
        ))}
      </div>
      {rows.length === 0 && <div className="p-2 text-[0.8rem] text-ink-mute">まだ終わったシーズンはありません。</div>}
      {rows.map((s) => (
        <div key={s.season} className="flex items-center gap-1 border-b border-white/5 px-2 py-[0.35rem] text-[0.74rem]">
          <span className="num w-[4.2rem] text-ink-dim">{seasonLabel(state.startYear, s.season)}</span>
          {cols.map((c) => {
            const id = s.champions.find((x) => x.compId === c)?.clubId
            const club = id !== undefined ? state.clubs[id] : undefined
            return (
              <span key={c} className={`flex min-w-0 flex-1 items-center gap-1 truncate ${id === me ? 'font-black text-gold' : ''}`}>
                {club && <Emblem id={`ch-${s.season}-${c}`} emblem={club.emblem} colors={club.colors} size="1rem" />}
                <span className="truncate">{club?.short ?? '―'}</span>
              </span>
            )
          })}
        </div>
      ))}
    </div>
  )
}

export function RecordsScreen() {
  const state = useGameState()
  const screen = useCurrentScreen()
  const [tab, setTab] = useState<Tab>((screen.params?.tab as Tab | undefined) ?? 'history')
  return (
    <AppShell title="クラブの記録" current="club" back right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className="seg shrink-0 self-start">
          {TABS.map(([id, label]) => (
            <button key={id} aria-selected={tab === id} onClick={() => setTab(id)}>
              {label}
            </button>
          ))}
        </div>
        {tab === 'history' && <HistoryTab state={state} />}
        {tab === 'trophies' && <TrophiesTab state={state} />}
        {tab === 'alltime' && <AllTimeTab state={state} />}
        {tab === 'hof' && <HofTab state={state} />}
        {tab === 'champions' && <ChampionsTab state={state} />}
      </div>
    </AppShell>
  )
}
