/**
 * 「1か月オート」のボタン（上部バーの日付の横と、右下の大きなボタンの下）。押すと確認を出す（押し間違えても進まない）。
 * 右下にも置くのは、折りたたみの内側の画面などで、上の端がシステムの表示に重なって押せないことがあるため。
 */
import { useState } from 'react'
import { Icon } from '../components/Icon'
import { ConfirmDialog } from '../components/ConfirmDialog'

export function MonthAutoButton({ onRun, label = '1か月オート', className = 'btn btn-ghost btn-sm !min-h-0 !px-2.5 !py-1 !text-[0.76rem]' }: { onRun: () => void; label?: string; className?: string }) {
  const [ask, setAsk] = useState(false)
  return (
    <>
      <button className={className} onClick={() => setAsk(true)}>
        {label}
        <Icon name="forward" className="h-3.5 w-3.5" />
      </button>
      <ConfirmDialog
        open={ask}
        title={`${label}で進めますか？`}
        text="4 週間を、試合も含めて自動で進めます。止まる出来事は設定で選べます。"
        ok="4 週間進める"
        onOk={() => {
          setAsk(false)
          onRun()
        }}
        onCancel={() => setAsk(false)}
      />
    </>
  )
}
