/** 新しいクラブを作る（ホームタウン・名前・カラー・エンブレム・ユニフォーム）。 */
import { useEffect, useMemo, useState } from 'react'
import { listSlots, SLOT_COUNT, type SaveSlotMeta } from '../../persistence/db'
import { CLUB_NICKNAMES, HOMETOWNS, type EmblemSpec, type KitPattern } from '../../engine'
import { TOWN_TRAITS } from '../../engine/data/clubs'
import { regionOf } from '../../engine/club/derby'
import { Emblem, Kit } from '../components/ClubArt'
import { Icon } from '../components/Icon'
import { Portrait } from '../components/Portrait'
import { useUi } from '../../stores/uiStore'
import { flushSave, useGame } from '../../stores/gameStore'

const COLOR_SETS: { primary: string; secondary: string; name: string }[] = [
  { primary: '#1d4ed8', secondary: '#ffffff', name: '青×白' },
  { primary: '#b91c1c', secondary: '#ffffff', name: '赤×白' },
  { primary: '#111827', secondary: '#f5c542', name: '黒×金' },
  { primary: '#047857', secondary: '#ffffff', name: '緑×白' },
  { primary: '#f97316', secondary: '#1e293b', name: '橙×紺' },
  { primary: '#7c3aed', secondary: '#f8fafc', name: '紫×白' },
  { primary: '#0ea5e9', secondary: '#1e3a8a', name: '空×紺' },
  { primary: '#facc15', secondary: '#1e3a8a', name: '黄×紺' },
  { primary: '#be123c', secondary: '#1e3a8a', name: '臙脂×紺' },
  { primary: '#ffffff', secondary: '#111827', name: '白×黒' },
  { primary: '#0f766e', secondary: '#fde047', name: '碧×黄' },
  { primary: '#e11d48', secondary: '#0f172a', name: '紅×黒' },
]
const KITS: { id: KitPattern; name: string }[] = [
  { id: 'solid', name: '無地' },
  { id: 'stripes', name: '縦じま' },
  { id: 'hoops', name: '横じま' },
  { id: 'sash', name: 'たすき' },
  { id: 'halves', name: 'ハーフ' },
]

function Bar({ label, value }: { label: string; value: number }) {
  return (
    <div className="flex items-center gap-2 text-[0.78rem]">
      <span className="w-[3.2rem] shrink-0 text-ink-dim">{label}</span>
      <div className="h-1.5 flex-1 overflow-hidden rounded-full bg-black/40">
        <div className="h-full rounded-full bg-gold" style={{ width: `${value}%` }} />
      </div>
    </div>
  )
}

/** ホームタウンを地方ごとに並べる（M19。47 都道府県） */
const AREAS: { name: string; regions: string[] }[] = [
  { name: '北海道・東北', regions: ['北海道', '東北'] },
  { name: '関東', regions: ['関東'] },
  { name: '中部', regions: ['中部'] },
  { name: '近畿', regions: ['近畿'] },
  { name: '中国・四国', regions: ['中国', '四国'] },
  { name: '九州・沖縄', regions: ['九州'] },
]
const areaOf = (pref: string) => AREAS.findIndex((a) => a.regions.includes(regionOf(pref) ?? ''))

function Section({ title, children }: { title: string; children: React.ReactNode }) {
  return (
    <section className="mb-3">
      <div className="panel-head mb-1.5">{title}</div>
      {children}
    </section>
  )
}

export function NewGameScreen() {
  const pop = useUi((s) => s.pop)
  const reset = useUi((s) => s.reset)
  const newGame = useGame((s) => s.newGame)
  const [town, setTown] = useState(9)
  const [area, setArea] = useState(() => areaOf(HOMETOWNS[9].pref))
  const [nick, setNick] = useState(6)
  const [customName, setCustomName] = useState('')
  const [color, setColor] = useState(0)
  const [kit, setKit] = useState<KitPattern>('solid')
  const [emblem, setEmblem] = useState<EmblemSpec>({ shape: 0, charge: 1, pattern: 0 })
  const [busy, setBusy] = useState(false)
  const [slots, setSlots] = useState<SaveSlotMeta[]>([])
  const [slot, setSlot] = useState(1)
  useEffect(() => {
    void flushSave()
      .then(() => listSlots())
      .then((list) => {
        setSlots(list)
        const used = new Set(list.map((x) => x.id))
        const free = Array.from({ length: SLOT_COUNT }, (_, i) => i + 1).find((i) => !used.has(i))
        setSlot(free ?? 1)
      })
      .catch(() => setSlots([]))
  }, [])

  const t = HOMETOWNS[town]
  const name = customName.trim() || `${t.city}${CLUB_NICKNAMES[nick]}`
  const colors = COLOR_SETS[color]
  const cycle = (k: keyof EmblemSpec, n: number) => setEmblem((e) => ({ ...e, [k]: (e[k] + 1) % n }))
  const popLabel = useMemo(() => `${t.population}万人`, [t])

  const start = () => {
    setBusy(true)
    // 描画を一度返してから重い生成を行う
    setTimeout(() => {
      newGame({ seed: (Date.now() ^ Math.floor(Math.random() * 1e9)) >>> 0, clubName: name, clubShort: t.city, hometownIndex: town, colors: { primary: colors.primary, secondary: colors.secondary }, emblem, kit }, slot)
      reset({ id: 'home' })
    }, 30)
  }

  return (
    <div className="absolute inset-0 flex flex-col">
      <header className="topbar safe-px flex shrink-0 items-center gap-2" style={{ boxSizing: 'content-box' }}>
        <button className="flex h-10 w-10 items-center justify-center rounded-lg text-ink-dim hover:bg-white/5" onClick={pop} aria-label="戻る">
          <Icon name="back" className="h-5 w-5" />
        </button>
        <h1 className="text-[1.05rem] font-extrabold">クラブ設立</h1>
        <span className="ml-2 text-[0.75rem] text-ink-dim">あなたはクラブの社長です。ホームタウンとクラブの顔を決めましょう。</span>
      </header>
      <div className="safe-px safe-pb flex min-h-0 flex-1 gap-3 pt-3">
        {/* 左: プレビュー */}
        <div className="panel relative flex w-[38%] shrink-0 flex-col items-center overflow-hidden p-3">
          <div className="absolute inset-x-0 top-0 h-1/2 opacity-30" style={{ background: `radial-gradient(80% 90% at 50% 0%, ${colors.primary}, transparent 70%)` }} />
          <div className="relative flex items-end gap-2">
            <Emblem id="ng" emblem={emblem} colors={colors} size="5.6rem" />
            <Kit id="ng" pattern={kit} colors={colors} size="4.6rem" number={10} />
          </div>
          <div className="relative mt-2 text-center text-[1.3rem] font-black leading-tight">{name}</div>
          <div className="relative text-[0.78rem] text-ink-dim">
            {t.pref}・{t.city}（人口 {popLabel}）
          </div>
          <div className="relative mt-1.5 rounded-lg border border-gold/40 bg-gold/10 px-2.5 py-1 text-center">
            <div className="text-[0.84rem] font-black text-gold">{TOWN_TRAITS[t.trait].name}</div>
            <div className="text-[0.72rem] leading-snug text-ink-dim">{TOWN_TRAITS[t.trait].desc}</div>
          </div>
          <div className="relative mt-2 w-full space-y-1 px-2">
            <Bar label="人口" value={Math.min(100, t.population * 1.2)} />
            <Bar label="経済力" value={t.economy} />
            <Bar label="サッカー熱" value={t.passion} />
          </div>
          <div className="relative mt-auto flex w-full items-end gap-2 pt-2">
            <Portrait id="kato_misaki" kind="face" className="face-round h-12 w-12 shrink-0" />
            <div className="rounded-xl rounded-bl-none bg-white/10 px-2.5 py-1.5 text-[0.75rem] leading-snug">
              秘書の加藤です。社長、まずは NPL ディビジョン3 からのスタートです。一緒にクラブを大きくしましょう！
            </div>
          </div>
        </div>

        {/* 右: 設定 */}
        <div className="scroll-y min-w-0 flex-1 pr-1">
          <Section title="ホームタウン">
            <div className="seg scroll-x mb-1.5 max-w-full">
              {AREAS.map((a, i) => (
                <button key={a.name} aria-selected={area === i} onClick={() => setArea(i)}>
                  {a.name}
                </button>
              ))}
            </div>
            <div className="grid grid-cols-4 gap-1.5">
              {HOMETOWNS.map((h, i) => ({ h, i }))
                .filter(({ h }) => areaOf(h.pref) === area)
                .map(({ h, i }) => (
                  <button key={h.city} onClick={() => setTown(i)} className={`rounded-lg border px-1 py-1 text-center ${i === town ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20 text-ink'}`}>
                    <div className="text-[0.84rem] font-bold">{h.city}</div>
                    <div className="text-[0.66rem] text-ink-dim">
                      {h.pref}・{TOWN_TRAITS[h.trait].name}
                    </div>
                  </button>
                ))}
            </div>
          </Section>
          <Section title="クラブ名">
            <div className="flex flex-wrap gap-1.5">
              {CLUB_NICKNAMES.map((n, i) => (
                <button key={n} onClick={() => { setNick(i); setCustomName('') }} className={`rounded-lg border px-2.5 py-1.5 text-[0.8rem] font-bold ${i === nick && !customName ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/20'}`}>
                  {t.city}
                  {n}
                </button>
              ))}
            </div>
            <input value={customName} onChange={(e) => setCustomName(e.target.value.slice(0, 16))} placeholder="自由に名前をつける（任意）" className="mt-1.5 h-10 w-full rounded-lg border border-line/60 bg-black/30 px-3 text-[0.85rem] outline-none focus:border-gold" />
          </Section>
          <Section title="クラブカラー">
            <div className="grid grid-cols-6 gap-1.5">
              {COLOR_SETS.map((c, i) => (
                <button key={c.name} onClick={() => setColor(i)} className={`flex h-10 items-center justify-center gap-1 rounded-lg border ${i === color ? 'border-gold ring-2 ring-gold/40' : 'border-line/60'}`} style={{ background: `linear-gradient(135deg, ${c.primary} 55%, ${c.secondary} 55%)` }} aria-label={c.name} />
              ))}
            </div>
          </Section>
          <div className="grid grid-cols-2 gap-3">
            <Section title="エンブレム">
              <div className="flex gap-1.5">
                <button className="btn btn-ghost btn-sm flex-1" onClick={() => cycle('shape', 5)}>
                  形
                </button>
                <button className="btn btn-ghost btn-sm flex-1" onClick={() => cycle('charge', 8)}>
                  紋章
                </button>
                <button className="btn btn-ghost btn-sm flex-1" onClick={() => cycle('pattern', 5)}>
                  模様
                </button>
              </div>
            </Section>
            <Section title="ユニフォーム">
              <div className="flex gap-1">
                {KITS.map((k) => (
                  <button key={k.id} onClick={() => setKit(k.id)} className={`flex flex-1 flex-col items-center rounded-lg border py-0.5 text-[0.7rem] ${k.id === kit ? 'border-gold bg-gold/15' : 'border-line/60'}`}>
                    <Kit id={`k-${k.id}`} pattern={k.id} colors={colors} size="1.8rem" />
                    {k.name}
                  </button>
                ))}
              </div>
            </Section>
          </div>
          <div className="sticky bottom-0 flex items-center justify-end gap-2 bg-gradient-to-t from-bg via-bg/90 to-transparent pt-3">
            <div className="flex items-center gap-1">
              <span className="text-[0.76rem] text-ink-dim">保存先</span>
              {Array.from({ length: SLOT_COUNT }, (_, i) => i + 1).map((n) => {
                const used = slots.find((x) => x.id === n)
                return (
                  <button key={n} onClick={() => setSlot(n)} title={used ? `${used.clubName}（上書き）` : '空き'} className={`flex h-[3.3rem] w-[3rem] flex-col items-center justify-center rounded-lg border text-[0.68rem] leading-tight ${slot === n ? 'border-gold bg-gold/15 text-gold' : 'border-line/60 bg-black/30'}`}>
                    <span className="num text-[0.95rem] font-black">{n}</span>
                    <span className="w-full truncate px-0.5">{used ? '上書き' : '空き'}</span>
                  </button>
                )
              })}
            </div>
            <button className="btn btn-gold h-[3.3rem] px-8 text-[1.05rem]" onClick={start} disabled={busy}>
              {busy ? '世界を作っています…' : 'このクラブで始める'}
            </button>
          </div>
        </div>
      </div>
    </div>
  )
}
