/** 表示用の整形。 */

/** 万円 → 「1億2,300万円」「4,500万円」 */
export function formatMoney(man: number): string {
  const neg = man < 0
  const v = Math.abs(Math.round(man))
  let s: string
  if (v >= 10000) {
    const oku = Math.floor(v / 10000)
    const rest = v % 10000
    s = rest ? `${oku}億${rest.toLocaleString()}万` : `${oku}億`
  } else s = `${v.toLocaleString()}万`
  return `${neg ? '-' : ''}${s}円`
}

/** 短い表記（「1.2億」「4,500万」） */
export function formatMoneyShort(man: number): string {
  const neg = man < 0
  const v = Math.abs(man)
  const s = v >= 10000 ? `${(v / 10000).toFixed(v >= 100000 ? 0 : 1)}億` : `${Math.round(v).toLocaleString()}万`
  return (neg ? '-' : '') + s
}

/** 能力値の色（ランクにそろえる: S 金・A 橙・B 緑・C 青・D 白・E 以下 灰） */
export function attrColor(v: number): string {
  if (v >= 90) return '#ffcf4a'
  if (v >= 80) return '#ff9a52'
  if (v >= 70) return '#3ddc84'
  if (v >= 60) return '#7dd3fc'
  if (v >= 50) return '#c7d2de'
  return '#8a97a8'
}

export function signed(v: number): string {
  return v > 0 ? `+${v}` : `${v}`
}
