import type { Personality } from '../data/personality'
import type { FaceSpec } from './face'

export type StaffRole = 'manager' | 'headCoach' | 'attackCoach' | 'defenseCoach' | 'physicalCoach' | 'gkCoach' | 'mentalCoach' | 'physio' | 'analyst' | 'scout' | 'youthCoach' | 'secretary' | 'interpreter' | 'owner'

export const STAFF_ROLE_LABEL: Record<StaffRole, string> = {
  manager: '監督',
  headCoach: 'ヘッドコーチ',
  attackCoach: '攻撃コーチ',
  defenseCoach: '守備コーチ',
  physicalCoach: 'フィジカルコーチ',
  gkCoach: 'GKコーチ',
  mentalCoach: 'メンタルコーチ',
  physio: 'トレーナー',
  analyst: 'アナリスト',
  scout: 'スカウト',
  youthCoach: 'ユースコーチ',
  secretary: '秘書',
  interpreter: '通訳',
  owner: 'オーナー',
}

/** 監督の戦術スタイル */
export type TacticalStyle = 'balance' | 'possession' | 'counter' | 'wing' | 'pressing' | 'defensive' | 'longball'

export const STYLE_LABEL: Record<TacticalStyle, string> = {
  balance: 'バランス',
  possession: 'ポゼッション',
  counter: 'カウンター',
  wing: 'サイドアタック',
  pressing: 'ハイプレス',
  defensive: '堅守速攻',
  longball: 'ロングボール',
}

export type StaffSkill = 'attack' | 'defense' | 'physical' | 'gk' | 'mental' | 'tactics' | 'youth' | 'medical' | 'judging' | 'network'

export interface Staff {
  id: number
  name: string
  nation: Nation
  birthAbsWeek: number
  role: StaffRole
  /** 総合力 1-99 */
  ability: number
  sub: Partial<Record<StaffSkill, number>>
  /** 監督: フォーメーション id ごとの熟練度 0-100 */
  formations?: Record<string, number>
  style?: TacticalStyle
  personality: Personality
  /** 年俸（万円/年） */
  wage: number
  until: number
  clubId: number
  starId?: string
  face?: FaceSpec
  female?: boolean
  /** キャリアモードから来たレジェンド（書き出しの key） */
  legend?: string
  /** 世界のスタッフ（M24 の 2 回目。ワールドリーグのクラブとしか契約しない） */
  world?: boolean
}
