/** リーグ: 順位表と日程・結果。 */
import { useState } from 'react'
import { FLAGS, dateLabel, playerClub, sortTable, teamStrength, type Competition, type GameState, type Nation } from '../../engine'
import { Flag } from '../components/common'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Emblem } from '../components/ClubArt'
import { useGameState } from '../../stores/gameStore'
import { useCurrentScreen, useUi } from '../../stores/uiStore'
import { winnerOf } from '../../engine/competition/playoff'
import { GROUP_LETTERS, groupStandings, roundName } from '../../engine/competition/continental'

function zoneColor(comp: Competition, rank: number): string | undefined {
  const n = comp.table.length
  if (comp.promotion && rank <= comp.promotion) return '#3ddc84'
  if (comp.playoff && rank > comp.promotion && rank <= comp.promotion + 4) return '#3aa0ff'
  if (comp.relegation && rank > n - comp.relegation) return '#ff5a5f'
  if (comp.tier === 1 && comp.country === 'JP' && rank === 1) return '#f5c542'
  return undefined
}

function Table({ state, comp }: { state: GameState; comp: Competition }) {
  sortTable(comp)
  const me = state.playerClubId
  return (
    <div className="scroll-y h-full pr-1">
      <div className="sticky top-0 z-10 flex items-center gap-2 bg-panel/95 px-2 py-1 text-[0.72rem] font-bold text-ink-mute">
        <span className="w-5 text-center">#</span>
        <span className="min-w-0 flex-1">クラブ</span>
        {['試', '勝', '分', '敗', '得', '失', '差'].map((h) => (
          <span key={h} className="w-6 text-center">
            {h}
          </span>
        ))}
        <span className="w-8 text-center">勝点</span>
        <span className="w-[4.6rem] text-center">直近</span>
        <span className="w-8 text-center">戦力</span>
      </div>
      {comp.table.map((r, i) => {
        const c = state.clubs[r.clubId]
        const zc = zoneColor(comp, i + 1)
        return (
          <div key={r.clubId} className={`flex items-center gap-2 border-b border-white/5 px-2 py-[0.3rem] text-[0.8rem] ${r.clubId === me ? 'bg-gold/15' : ''}`}>
            <span className="num w-5 text-center font-extrabold" style={{ color: zc }}>
              {i + 1}
            </span>
            <span className="flex min-w-0 flex-1 items-center gap-1.5">
              <Emblem id={`t-${c.id}`} emblem={c.emblem} colors={c.colors} size="1.4rem" />
              <span className={`truncate ${r.clubId === me ? 'font-black text-gold' : 'font-bold'}`}>{c.name}</span>
              {comp.id === 'WL' && (FLAGS as Record<string, unknown>)[c.country] !== undefined && <Flag nation={c.country as Nation} className="h-[0.75rem] w-[1.1rem]" />}
            </span>
            {[r.played, r.won, r.drawn, r.lost, r.gf, r.ga, r.gf - r.ga].map((v, k) => (
              <span key={k} className="num w-6 text-center text-ink-dim">
                {v}
              </span>
            ))}
            <span className="num w-8 text-center font-black">{r.points}</span>
            <span className="flex w-[4.6rem] justify-center gap-0.5">
              {r.form.split('').map((ch, k) => (
                <span key={k} className={`h-3 w-3 rounded-sm text-center text-[0.6rem] font-black leading-3 text-bg ${ch === 'W' ? 'bg-good' : ch === 'D' ? 'bg-ink-dim' : 'bg-bad'}`}>
                  {ch === 'W' ? '勝' : ch === 'D' ? '分' : '敗'}
                </span>
              ))}
            </span>
            <span className="num w-8 text-center text-[0.78rem] text-ink-dim">{Math.round(teamStrength(state, c))}</span>
          </div>
        )
      })}
      <div className="mt-2 flex flex-wrap gap-3 px-2 text-[0.72rem] text-ink-dim">
        {comp.promotion > 0 && <span><span className="text-good">■</span> 自動昇格</span>}
        {comp.playoff && <span><span className="text-accent">■</span> 昇格プレーオフ</span>}
        {comp.relegation > 0 && <span><span className="text-bad">■</span> {comp.id === 'WL' ? '自分の国のリーグへ戻る' : '降格'}</span>}
      </div>
    </div>
  )
}

function Fixtures({ state, comp }: { state: GameState; comp: Competition }) {
  const rounds = Math.max(...comp.fixtures.map((f) => f.round)) + 1
  const me = state.playerClubId
  const firstOpen = comp.fixtures.filter((f) => !f.result).reduce((m, f) => Math.min(m, f.round), rounds - 1)
  const [round, setRound] = useState(firstOpen)
  const list = comp.fixtures.filter((f) => f.round === round)
  return (
    <div className="flex h-full flex-col">
      <div className="flex shrink-0 items-center justify-center gap-2 pb-2">
        <button className="btn btn-ghost btn-sm w-10 !px-0" onClick={() => setRound((r) => Math.max(0, r - 1))}>
          ◀
        </button>
        <div className="num min-w-[9rem] text-center text-[0.9rem] font-extrabold">
          第{round + 1}節
          <span className="ml-1 text-[0.76rem] font-normal text-ink-dim">{list[0] && dateLabel(state.startYear, comp.season, list[0].absWeek % 48).replace(/^\d+年/, '')}</span>
        </div>
        <button className="btn btn-ghost btn-sm w-10 !px-0" onClick={() => setRound((r) => Math.min(rounds - 1, r + 1))}>
          ▶
        </button>
      </div>
      <div className="scroll-y grid min-h-0 flex-1 grid-cols-2 content-start gap-1.5 pr-1">
        {list.map((f) => {
          const h = state.clubs[f.home]
          const a = state.clubs[f.away]
          const mine = f.home === me || f.away === me
          return (
            <div key={f.id} className={`flex items-center gap-1.5 rounded-lg px-2 py-1.5 text-[0.78rem] ${mine ? 'bg-gold/15' : 'bg-black/20'}`}>
              <span className="min-w-0 flex-1 truncate text-right font-bold">{h.short}</span>
              <Emblem id={`fh-${f.id}`} emblem={h.emblem} colors={h.colors} size="1.3rem" />
              <span className="num w-12 shrink-0 text-center font-black">{f.result ? `${f.result.hg} - ${f.result.ag}` : 'vs'}</span>
              <Emblem id={`fa-${f.id}`} emblem={a.emblem} colors={a.colors} size="1.3rem" />
              <span className="min-w-0 flex-1 truncate font-bold">{a.short}</span>
            </div>
          )
        })}
      </div>
    </div>
  )
}

/** 大陸大会のグループ（4 組の順位表） */
function GroupTables({ state, comp }: { state: GameState; comp: Competition }) {
  const me = state.playerClubId
  return (
    <div className="grid grid-cols-2 gap-2">
      {GROUP_LETTERS.map((letter, g) => (
        <div key={letter} className="rounded-lg bg-black/20 p-1.5">
          <div className="mb-0.5 flex items-center gap-2 px-1 text-[0.72rem] font-bold text-ink-mute">
            <span className="flex-1 text-[0.75rem] text-gold">{letter} 組</span>
            {['試', '勝', '分', '敗', '差'].map((h) => (
              <span key={h} className="w-5 text-center">
                {h}
              </span>
            ))}
            <span className="w-6 text-center">点</span>
          </div>
          {groupStandings(comp, g).map((r, i) => {
            const c = state.clubs[r.clubId]
            return (
              <div key={r.clubId} className={`flex items-center gap-2 rounded px-1 py-[0.2rem] text-[0.74rem] ${r.clubId === me ? 'bg-gold/15' : ''}`}>
                <span className="num w-3 text-center font-extrabold" style={{ color: i < 2 ? '#3ddc84' : undefined }}>
                  {i + 1}
                </span>
                <Emblem id={`g-${c.id}`} emblem={c.emblem} colors={c.colors} size="1.2rem" />
                <span className={`min-w-0 flex-1 truncate ${r.clubId === me ? 'font-black text-gold' : 'font-bold'}`}>{c.short}</span>
                {[r.played, r.won, r.drawn, r.lost, r.gf - r.ga].map((v, k) => (
                  <span key={k} className="num w-5 text-center text-ink-dim">
                    {v}
                  </span>
                ))}
                <span className="num w-6 text-center font-black">{r.points}</span>
              </div>
            )
          })}
        </div>
      ))}
    </div>
  )
}

function CupView({ state, comp }: { state: GameState; comp: Competition }) {
  const me = state.playerClubId
  const ko = comp.fixtures.filter((f) => f.group === undefined)
  const rounds = [...new Set(ko.map((f) => f.round))].sort((a, b) => b - a)
  const hasGroups = comp.fixtures.some((f) => f.group !== undefined)
  return (
    <div className="scroll-y h-full space-y-2 pr-1">
      {rounds.map((r) => {
        const list = ko.filter((f) => f.round === r).sort((a, b) => Number(b.home === me || b.away === me) - Number(a.home === me || a.away === me))
        return (
          <div key={r}>
            <div className="panel-head mb-1">
              {roundName(comp, r)}
              <span className="ml-1 text-[0.72rem] font-normal">{list[0] && dateLabel(state.startYear, comp.season, list[0].absWeek % 48).replace(/^\d+年/, '')}</span>
            </div>
            <div className="grid grid-cols-2 gap-1">
              {list.map((f) => {
                const h = state.clubs[f.home]
                const a = state.clubs[f.away]
                const w = winnerOf(f)
                const mine = f.home === me || f.away === me
                return (
                  <div key={f.id} className={`flex items-center gap-1.5 rounded-lg px-2 py-1 text-[0.78rem] ${mine ? 'bg-gold/15' : 'bg-black/20'}`}>
                    <span className={`min-w-0 flex-1 truncate text-right ${w === f.home ? 'font-black' : 'text-ink-dim'}`}>{h.short}</span>
                    <span className="num w-14 shrink-0 text-center font-bold">
                      {f.result ? `${f.result.hg}-${f.result.ag}` : 'vs'}
                      {f.result?.pens && <span className="block text-[0.66rem] text-ink-dim">PK {f.result.pens[0]}-{f.result.pens[1]}</span>}
                    </span>
                    <span className={`min-w-0 flex-1 truncate ${w === f.away ? 'font-black' : 'text-ink-dim'}`}>{a.short}</span>
                  </div>
                )
              })}
            </div>
          </div>
        )
      })}
      {hasGroups && (
        <div>
          <div className="panel-head mb-1">グループステージ（各組 2 位まで準々決勝へ）</div>
          <GroupTables state={state} comp={comp} />
        </div>
      )}
    </div>
  )
}

const CUP_LABEL: Record<string, string> = { CUP: 'カップ', ACC: 'アジア', EUC: '欧州', WCC: '世界' }

export function LeagueScreen() {
  const state = useGameState()
  const me = playerClub(state)
  const screen = useCurrentScreen()
  const push = useUi((s) => s.push)
  const [compId, setCompId] = useState((screen.params?.comp as string | undefined) ?? me.leagueId)
  const [tab, setTab] = useState<'table' | 'fixtures'>('table')
  const comp = state.competitions.find((c) => c.id === compId) ?? state.competitions.find((c) => c.id === me.leagueId)!
  // ワールドリーグ（M24）を先頭に、国内、海外
  const domestic = [...state.competitions.filter((c) => c.id === 'WL'), ...state.competitions.filter((c) => c.country === 'JP' && c.kind === 'league' && !c.hidden)]
  const foreign = state.competitions.filter((c) => c.country !== 'JP' && c.id !== 'WL' && c.kind === 'league' && !c.hidden)
  const cups = ['CUP', 'ACC', 'EUC', 'WCC'].flatMap((id) => state.competitions.filter((c) => c.id === id))
  return (
    <AppShell title="リーグ" current="schedule" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex flex-col gap-2 p-3">
        <div className="flex shrink-0 items-center gap-2">
          <div className="seg shrink-0">
            {domestic.map((c) => (
              <button key={c.id} aria-selected={comp.id === c.id} onClick={() => setCompId(c.id)}>
                {c.short}
              </button>
            ))}
          </div>
          {cups.length > 0 && (
            <div className="seg shrink-0">
              {cups.map((c) => (
                <button key={c.id} aria-selected={comp.id === c.id} onClick={() => setCompId(c.id)}>
                  {CUP_LABEL[c.id] ?? c.short}
                </button>
              ))}
            </div>
          )}
          <div className="seg scroll-x min-w-0 flex-1">
            {foreign.map((c) => (
              <button key={c.id} aria-selected={comp.id === c.id} onClick={() => setCompId(c.id)}>
                {c.short}
              </button>
            ))}
          </div>
          <div className={`seg ml-auto ${comp.kind !== 'league' ? 'invisible' : ''}`}>
            <button aria-selected={tab === 'table'} onClick={() => setTab('table')}>
              順位表
            </button>
            <button aria-selected={tab === 'fixtures'} onClick={() => setTab('fixtures')}>
              日程
            </button>
          </div>
          <button className="btn btn-ghost btn-sm shrink-0" onClick={() => push({ id: 'national' })}>
            代表
          </button>
          <button className="btn btn-ghost btn-sm shrink-0" onClick={() => push({ id: 'records' })}>
            記録
          </button>
        </div>
        <div className="panel min-h-0 flex-1 p-2">
          <div className="mb-1 px-2 text-[0.85rem] font-extrabold">{comp.name}</div>
          <div className="h-[calc(100%-1.6rem)]">{comp.kind !== 'league' ? <CupView state={state} comp={comp} /> : tab === 'table' ? <Table state={state} comp={comp} /> : <Fixtures key={comp.id} state={state} comp={comp} />}</div>
        </div>
      </div>
    </AppShell>
  )
}
