/**
 * ステージの寸法を React から読むフック。
 * 画面幅のブレークポイント（Tailwind の sm/md など）は端末のビューポートで判定されるため、
 * 縦持ちで回転表示しているときに狂う。レイアウトの出し分けはこのフックで行う。
 */
import { useSyncExternalStore } from 'react'
import { getStageInfo, onStageChange, stageRem, type StageInfo } from './stageInfo'

export function useStage(): StageInfo {
  return useSyncExternalStore(onStageChange, getStageInfo, getStageInfo)
}

/** ステージの幅（rem。画面の大きさの設定で変わる） */
export function useStageRem(): number {
  return useSyncExternalStore(onStageChange, stageRem, stageRem)
}

/** ステージの幅が w 以上か（CSS px） */
export function useStageWide(w: number): boolean {
  return useSyncExternalStore(
    onStageChange,
    () => getStageInfo().w >= w,
    () => getStageInfo().w >= w,
  )
}
