/** 国際ユースカップ（M25）の自クラブの試合: 試合前（先発）→ 観戦か結果だけ → 結果。 */
import { useState } from 'react'
import { NATION_NAME } from '../../engine/data/nations'
import { YC_ROUND, ourCupMatch, ourLevel, playOurCupMatch, playYouthCupWatched, youthCupSetup } from '../../engine/club/youthCup'
import type { MatchSummary } from '../../engine/match/live/types'
import { MatchView } from '../match/MatchView'
import { AppShell } from '../layout/AppShell'
import { GameTopInfo } from '../layout/GameTopInfo'
import { Flag, PosBadge } from '../components/common'
import { Icon } from '../components/Icon'
import { useGame, useGameState } from '../../stores/gameStore'
import { useUi } from '../../stores/uiStore'

export function YouthCupScreen() {
  const state = useGameState()
  const mutate = useGame((s) => s.mutate)
  const reset = useUi((s) => s.reset)
  const push = useUi((s) => s.push)
  // 開いた時点の試合と設定を固定する（観戦の結果をこの設定で入れる）
  const [cur] = useState(() => ourCupMatch(state))
  const [setup] = useState(() => youthCupSetup(state))
  const [phase, setPhase] = useState<'pre' | 'live' | 'done'>('pre')
  const [score, setScore] = useState<string | null>(null)
  const cup = state.youthCup
  const finish = (s: MatchSummary | null) => {
    let text = ''
    mutate((st) => {
      const sum = s && setup ? (playYouthCupWatched(st, setup, s), s) : playOurCupMatch(st)
      if (sum) text = `${sum.score[0]} - ${sum.score[1]}${sum.pens ? `
PK ${sum.pens[0]}-${sum.pens[1]}` : ''}`
    })
    setScore(text)
    setPhase('done')
  }
  if (phase === 'live' && setup) return <MatchView setup={setup} onExit={finish} />
  if (!cup || !cur || !setup) {
    if (phase !== 'done') {
      return (
        <AppShell title="国際ユースカップ" current="squad" right={<GameTopInfo />}>
          <div className="absolute inset-0 flex items-center justify-center">
            <button className="btn btn-gold" onClick={() => reset({ id: 'home' })}>
              ホームへ
            </button>
          </div>
        </AppShell>
      )
    }
  }
  const opp = cur?.opp
  const m = cur ? cup?.rounds[cur.round]?.find((x) => x.a === 0 || x.b === 0) : undefined
  const won = m?.winner === 0
  return (
    <AppShell title={`国際ユースカップ ${cur ? YC_ROUND[cur.round] : ''}`} current="squad" right={<GameTopInfo />}>
      <div className="absolute inset-0 flex gap-3 p-3">
        <div className="panel flex min-w-0 flex-1 flex-col justify-center p-4">
          <div className="text-center text-[0.75rem] font-bold tracking-widest text-gold">
            {cup && `${NATION_NAME[cup.host.nation]}・${cup.host.city}`} {cur && YC_ROUND[cur.round]}
          </div>
          <div className="mt-2 flex items-center justify-center gap-4">
            <div className="w-[38%] text-center text-[1.05rem] font-black">{cup?.teams[0].name}</div>
            <div className="num shrink-0 whitespace-pre text-center text-[1.4rem] font-black leading-tight text-ink-dim">{phase === 'done' ? score : 'VS'}</div>
            <div className="flex w-[38%] items-center justify-center gap-1.5 text-center text-[1.05rem] font-black">
              {opp && <Flag nation={opp.nation} />}
              {opp?.name}
            </div>
          </div>
          {phase === 'done' ? (
            <div className={`mx-auto mt-4 rounded-lg px-4 py-2 text-center text-[0.95rem] font-black ${won ? 'bg-good/20 text-good' : 'bg-white/10 text-ink-dim'}`}>
              {won ? (cur?.round === 2 ? '優勝！ 世界の強豪を破った！' : '勝ち上がり！') : '敗退。この経験を次へ。'}
            </div>
          ) : (
            <div className="mt-3 flex gap-4">
              <div className="min-w-0 flex-1">
                <div className="mb-0.5 text-[0.7rem] font-bold text-ink-dim">うちの先発（力 {Math.round(cup?.teams[0].level || ourLevel(state))}）</div>
                <div className="grid grid-cols-2 gap-x-3 gap-y-0.5 text-[0.72rem]">
                  {setup?.home.starters.map((p) => (
                    <div key={p.id} className="flex min-w-0 items-center gap-1">
                      <PosBadge pos={p.pos} />
                      <span className={`truncate ${p.id < 0 ? 'text-ink-mute' : 'font-bold'}`}>{p.name}</span>
                    </div>
                  ))}
                </div>
                {setup?.home.starters.some((p) => p.id < 0) && <div className="mt-0.5 text-[0.64rem] text-ink-mute">灰色はポジションの合う選手がいないので入った控えの子</div>}
              </div>
              <div className="w-[34%] shrink-0 rounded-lg bg-black/25 px-2.5 py-2 text-[0.74rem]">
                <div className="text-[0.7rem] font-bold text-ink-dim">相手</div>
                {opp && (
                  <>
                    <div className="mt-0.5 flex items-center gap-1 font-bold">
                      <Flag nation={opp.nation} className="h-[0.75rem] w-[1.1rem]" />
                      {NATION_NAME[opp.nation]}
                    </div>
                    <div className="mt-0.5">
                      力 <b className="num">{Math.round(opp.level)}</b>
                    </div>
                  </>
                )}
              </div>
            </div>
          )}
        </div>
        <div className="flex w-[11rem] shrink-0 flex-col justify-end gap-2">
          {phase === 'pre' ? (
            <>
              <button className="btn btn-gold h-[3.6rem] text-[1.05rem]" onClick={() => setPhase('live')}>
                <Icon name="play" className="h-5 w-5" />
                観戦する
              </button>
              <button className="btn btn-ghost" onClick={() => finish(null)}>
                結果だけ見る
              </button>
            </>
          ) : (
            <>
              <button className="btn btn-ghost" onClick={() => push({ id: 'youth', params: { tab: 'cup' } })}>
                大会を見る
              </button>
              <button className="btn btn-gold" onClick={() => reset({ id: 'home' })}>
                ホームへ
              </button>
            </>
          )}
        </div>
      </div>
    </AppShell>
  )
}
